insert into public.questions (
  id,
  question_number,
  question,
  choices,
  answers,
  content_domain,
  content_task,
  aws_services,
  explanation,
  choice_evaluations
)
select
  record.id,
  record.question_number,
  record.question,
  record.choices,
  record.answers,
  record.content_domain,
  record.content_task,
  record.aws_services,
  record.explanation,
  record.choice_evaluations
from jsonb_to_recordset('[{"id":"Q0001","question_number":1,"question":"회사는 여러 대륙에 걸쳐 도시의 온도, 습도 및 대기압에 대한 데이터를 수집합니다. 회사가 매일 각 사이트에서 수집하는 데이터의 평균 볼륨은 500GB 입니다. 각 사이트에는 고속 인터넷 연결이 있습니다. 이 회사는 이러한 모든 글로벌 사이트의 데이터를 단일 Amazon S3 버킷에 최대한 빨리 집계하려고 합니다. 솔루션은 운영 복잡성을 최소화해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"대상 S3 버킷에서 S3 Transfer Acceleration 을 켭니다. 멀티파트 업로드를 사용하여 사이트 데이터를 대상 S3 버킷에 직접 업로드합니다.","B":"각 사이트의 데이터를 가장 가까운 리전의 S3 버킷에 업로드합니다. S3 교차 리전 복제를 사용하여 대상 S3 버킷에 객체를 복사합니다. 그런 다음 원본 S3 버킷에서 데이터를 제거합니다.","C":"AWS Snowball Edge Storage Optimized 디바이스 작업을 매일 예약하여 각 사이트에서 가장 가까운 리전으로 데이터를 전송합니다. S3 교차 리전 복제를 사용하여 대상 S3 버킷에 객체를 복사합니다.","D":"각 사이트의 데이터를 가장 가까운 리전의 Amazon EC2 인스턴스로 업로드합니다. Amazon Elastic Block Store(Amazon EBS) 볼륨에 데이터를 저장합니다. 정기적으로 EBS 스냅샷을 만들어 대상 S3 버킷이 포함된 리전에 복사합니다. 해당 리전에서 EBS 볼륨을 복원합니다."},"answers":["A"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터 수집 및 변환 솔루션 결정","aws_services":["Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 여러 대륙의 사이트에서 매일 평균 500GB를 단일 Amazon S3 버킷으로 최대한 신속하게 집계해야 합니다. 각 사이트에 고속 인터넷 연결이 있으므로 네트워크 기반 전송을 활용할 수 있습니다. 또한 중간 저장소나 별도 컴퓨팅/스토리지 계층을 추가하지 않아야 운영 복잡성을 낮출 수 있습니다. 장거리 전송 성능과 대용량 업로드 효율을 높이면서 대상 버킷으로 직접 전송할 수 있어야 합니다.","awsServicesAnalysis":"Amazon S3 Transfer Acceleration은 전 세계 클라이언트와 S3 범용 버킷 간 장거리 파일 전송을 가속하는 버킷 수준 기능입니다. 데이터는 가까운 엣지 로케이션으로 전송된 뒤 AWS의 최적화된 네트워크 경로를 사용합니다. S3 멀티파트 업로드는 하나의 객체를 여러 파트로 나누어 병렬 업로드하고 실패한 파트만 재전송할 수 있게 합니다. S3 교차 리전 복제는 S3 객체를 다른 리전 버킷으로 비동기 복제합니다. AWS Snowball Edge는 물리적 장치를 이용한 오프라인 전송 서비스이지만 2025년 11월 7일부터 신규 고객은 주문할 수 없습니다. Amazon EBS 스냅샷은 EBS 볼륨의 백업이며 S3 객체 집계 수단이 아닙니다.","choicesAnalysis":"고속 인터넷을 사용할 수 있고 매일 대용량 데이터를 전송해야 하므로 원격 사이트에서 최종 S3 버킷으로 직접 연결되는 경로가 요구사항에 부합합니다. 전송 가속과 멀티파트 업로드를 함께 사용하면 장거리 전송과 대용량 객체 처리의 효율을 높일 수 있습니다. 중간 버킷, 물리적 장비 또는 EC2/EBS 처리 계층을 도입하면 전송 단계와 관리 대상이 늘어납니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"대상 S3 버킷으로 직접 업로드하며 S3 Transfer Acceleration으로 장거리 전송을 가속하고 멀티파트 업로드로 대용량 데이터를 병렬 처리할 수 있으므로 적합합니다."},"B":{"isCorrect":false,"explanation":"최종 버킷으로 데이터를 집계할 수 있지만 사이트별 중간 S3 버킷과 교차 리전 복제를 구성하고 관리해야 합니다. 직접 업로드보다 처리 단계와 운영 부담이 증가하므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"물리적 장비의 주문, 데이터 적재, 배송 및 반환 절차가 필요하므로 매일 신속히 집계하는 요구에 맞지 않습니다. 또한 AWS Snowball Edge는 현재 신규 고객이 주문할 수 없으므로 새로운 설계로도 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"각 사이트에 EC2 및 EBS를 운영하고 스냅샷 복사와 볼륨 복원을 수행해야 합니다. 복원된 EBS 데이터가 지정한 S3 버킷에 객체로 직접 집계되는 구조도 아니므로 적합하지 않습니다."}}},{"id":"Q0002","question_number":2,"question":"회사는 독점 애플리케이션의 로그 파일을 분석할 수 있는 능력이 필요합니다. 로그는 Amazon S3 버킷에 JSON 형식으로 저장됩니다. 쿼리는 간단하고 주문형으로 실행됩니다. 솔루션 설계자는 기존 아키텍처에 대한 최소한의 변경으로 분석을 수행해야 합니다. 솔루션 설계자는 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"Amazon Redshift 를 사용하여 모든 콘텐츠를 한 곳에 로드하고 필요에 따라 SQL 쿼리를 실행합니다.","B":"Amazon CloudWatch Logs 를 사용하여 로그를 저장합니다. Amazon CloudWatch 콘솔에서 필요에 따라 SQL 쿼리를 실행합니다.","C":"Amazon S3 와 함께 Amazon Athena 를 직접 사용하여 필요에 따라 쿼리를 실행합니다.","D":"AWS Glue 를 사용하여 로그를 분류합니다. Amazon EMR 에서 임시 Apache Spark 클러스터를 사용하여 필요에 따라 SQL 쿼리를 실행합니다."},"answers":["C"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터 수집 및 변환 솔루션 결정","aws_services":["Amazon Athena","Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 Amazon S3에 이미 저장된 JSON 로그를 간단한 주문형 쿼리로 분석해야 합니다. JSON은 반정형 데이터이므로 이를 조회할 수 있어야 합니다. 기존 아키텍처의 변경과 운영 오버헤드를 최소화하려면 데이터를 다른 분석 저장소로 적재하거나 별도 클러스터를 운영하지 않는 방식이 필요합니다. 따라서 기존 S3 데이터를 직접 대상으로 서버리스 분석을 수행하는지가 핵심입니다.","awsServicesAnalysis":"Amazon Athena는 Amazon S3의 데이터를 대상으로 서버리스 대화형 SQL 쿼리를 실행하며 JSON 같은 반정형 데이터를 조회할 수 있습니다. 쿼리를 위해서는 테이블 메타데이터가 필요하고, AWS Glue Data Catalog 또는 Athena 데이터 카탈로그로 이를 관리할 수 있습니다. Amazon Redshift는 데이터 웨어하우스 서비스이며, 적재된 데이터에 SQL을 실행할 수 있습니다. Amazon CloudWatch Logs Insights는 여러 쿼리 언어를 지원하지만 S3의 기존 로그를 분석 대상으로 사용하려면 CloudWatch Logs로 수집하는 흐름이 필요합니다. AWS Glue는 데이터 카탈로그 및 ETL 작업에, Amazon EMR은 Spark 같은 분산 처리 프레임워크 실행에 사용됩니다.","choicesAnalysis":"요구사항은 기존 S3 로그를 별도 적재 없이 필요할 때 분석하는 것입니다. S3 직접 쿼리 방식은 클러스터 관리와 데이터 복제 단계를 없애므로 변경 범위와 운영 부담을 낮춥니다. 반면 다른 로그 저장소, 데이터 웨어하우스 또는 분산 처리 클러스터를 추가하면 불필요한 구성 요소가 생깁니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 모든 콘텐츠를 Amazon Redshift로 적재하는 과정을 추가해야 합니다. 기존 S3 로그를 직접 활용하는 방식보다 아키텍처 변경과 운영 오버헤드가 크므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 CloudWatch Logs Insights가 SQL 쿼리를 지원하지만, S3에 이미 저장된 로그를 CloudWatch Logs로 수집하도록 흐름을 추가해야 합니다. 따라서 요구된 최소 변경에 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 Amazon Athena로 S3의 JSON 로그를 직접 대상으로 주문형 SQL 쿼리를 실행할 수 있습니다. 별도 데이터 적재나 분석 클러스터 운영이 필요하지 않으므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 AWS Glue 작업과 임시 Amazon EMR Spark 클러스터를 추가로 구성하고 운영해야 합니다. 간단한 주문형 분석에는 Athena 직접 쿼리보다 복잡하므로 적합하지 않습니다."}}},{"id":"Q0003","question_number":3,"question":"회사는 AWS Organizations 를 사용하여 여러 부서의 여러 AWS 계정을 관리합니다. 관리 계정에는 프로젝트 보고서가 포함된 Amazon S3 버킷이 있습니다. 회사는 이 S3 버킷에 대한 액세스를 AWS Organizations 의 조직 내 계정 사용자로만 제한하려고 합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"조직 ID 에 대한 참조와 함께 aws PrincipalOrgID 전역 조건 키를 S3 버킷 정책에 추가합니다.","B":"각 부서에 대한 조직 단위(OU)를 만듭니다. aws:PrincipalOrgPaths 전역 조건 키를 S3 버킷 정책에 추가합니다.","C":"AWS CloudTrail 을 사용하여 CreateAccount, InviteAccountToOrganization, LeaveOrganization 및 RemoveAccountFromOrganization 이벤트를 모니터링합니다. 그에 따라 S3 버킷 정책을 업데이트합니다.","D":"S3 버킷에 액세스해야 하는 각 사용자에 태그를 지정합니다. aws:PrincipalTag 전역 조건 키를 S3 버킷 정책에 추가합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"AWS 리소스에 대한 보안 액세스 설계","aws_services":["AWS Organizations","Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 AWS Organizations로 여러 AWS 계정을 관리하며, 관리 계정의 Amazon S3 버킷 접근을 조직에 속한 계정의 사용자로 제한해야 합니다. 계정이 추가되거나 제거될 때마다 버킷 정책을 수동으로 갱신하지 않아야 운영 오버헤드를 줄일 수 있습니다. 따라서 요청 주체의 조직 소속 여부를 정책에서 직접 확인하고 조직 변경에 자동으로 대응하는 방식이 필요합니다.","awsServicesAnalysis":"aws:PrincipalOrgID는 요청 주체가 속한 AWS Organizations의 조직 ID를 조건으로 비교하는 전역 조건 키입니다. 리소스 기반 정책에서 사용하면 개별 계정 ID를 나열하지 않고 조직 구성원을 조건으로 지정할 수 있습니다. aws:PrincipalOrgPaths는 요청 주체의 조직 루트 및 OU 경로를 비교하는 다중 값 조건 키로, 특정 OU 범위를 지정할 때 사용할 수 있습니다. AWS CloudTrail은 AWS API 활동을 기록합니다. aws:PrincipalTag는 IAM 사용자, 역할 또는 세션에 연결된 보안 주체 태그를 정책 조건으로 비교합니다.","choicesAnalysis":"접근 대상은 조직 전체의 모든 계정 사용자이므로 OU별 경로 또는 사용자별 태그를 별도로 관리할 필요가 없습니다. 조직 ID 조건을 사용하면 계정 변동 시에도 정책에서 해당 조직의 구성원을 자동으로 포함할 수 있습니다. 이벤트 감시 후 정책을 수정하는 방식은 동일한 목표를 더 복잡하게 구현합니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 버킷 정책에서 aws:PrincipalOrgID와 조직 ID를 비교하여 조직 구성원의 요청을 제어할 수 있습니다. 계정 추가 및 제거에 따라 수동으로 계정 목록을 갱신할 필요가 없으므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 aws:PrincipalOrgPaths로 특정 OU 또는 경로를 지정할 수 있습니다. 그러나 모든 조직 계정이 대상인 요구사항에는 OU 구조를 별도로 만들고 유지할 필요가 있어 최소 운영 오버헤드에 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 계정 관련 CloudTrail 이벤트를 감시한 뒤 버킷 정책을 수정해야 합니다. 정책 갱신 자동화를 별도로 구현하고 운영해야 하므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 사용자 또는 역할마다 태그를 부여하고 일관되게 관리해야 합니다. 조직 소속 여부를 직접 확인하는 조건보다 관리 부담이 크므로 적합하지 않습니다."}}},{"id":"Q0004","question_number":4,"question":"애플리케이션은 VPC 의 Amazon EC2 인스턴스에서 실행됩니다. 애플리케이션은 Amazon S3 버킷에 저장된 로그를 처리합니다. EC2 인스턴스는 인터넷 연결 없이 S3 버킷에 액세스해야 합니다. Amazon S3 에 대한 프라이빗 네트워크 연결을 제공하는 솔루션은 무엇입니까?","choices":{"A":"S3 버킷에 대한 게이트웨이 VPC 엔드포인트를 생성합니다.","B":"Amazon CloudWatch Logs 로 로그를 스트리밍합니다. 로그를 S3 버킷으로 내보냅니다.","C":"Amazon EC2 에 인스턴스 프로파일을 생성하여 S3 액세스를 허용합니다.","D":"S3 엔드포인트에 액세스하기 위한 프라이빗 링크가 있는 Amazon API Gateway API 를 생성합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["Amazon VPC","Amazon S3"],"explanation":{"requirementsAnalysis":"애플리케이션은 VPC 내부의 Amazon EC2 인스턴스에서 실행되며 Amazon S3 버킷의 로그를 처리해야 합니다. 인스턴스에는 인터넷 연결이 없으므로 S3 API 호출이 인터넷 게이트웨이 또는 NAT 디바이스를 통과하지 않는 사설 네트워크 경로가 필요합니다. 따라서 VPC에서 S3 서비스로 직접 라우팅할 수 있는 연결 방식을 선택해야 합니다.","awsServicesAnalysis":"Amazon S3용 게이트웨이 VPC 엔드포인트는 VPC 라우팅 테이블의 대상으로 추가되어 VPC와 S3 간 트래픽을 AWS 네트워크로 전달합니다. 이 방식에는 인터넷 게이트웨이나 NAT 디바이스가 필요하지 않습니다. Amazon EC2 인스턴스 프로파일은 인스턴스에 IAM 권한을 제공하지만 네트워크 경로를 만들지는 않습니다. Amazon CloudWatch Logs는 로그 수집 및 분석 서비스입니다. Amazon API Gateway는 API를 게시하고 백엔드 서비스와 통합하는 관리형 서비스입니다.","choicesAnalysis":"핵심 제약은 S3 권한이 아니라 인터넷 연결 없이 S3에 도달하는 네트워크 경로입니다. S3용 게이트웨이 엔드포인트는 해당 VPC 트래픽을 라우팅 테이블 수준에서 사설 경로로 처리합니다. 로그 전달, IAM 권한 설정 또는 API 프록시 구성은 이 연결 요구사항을 직접 충족하지 않습니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 VPC의 라우팅 테이블을 통해 Amazon S3로 향하는 트래픽을 게이트웨이 엔드포인트로 보낼 수 있습니다. 인터넷 게이트웨이 또는 NAT 없이 S3에 접근할 수 있으므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 로그 처리 경로를 CloudWatch Logs로 바꾸며 EC2에서 S3로 가는 사설 네트워크 연결을 제공하지 않습니다. 따라서 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 인스턴스에 S3 API 호출 권한을 부여할 수 있지만, 인터넷 연결 없이 S3에 도달하는 네트워크 경로를 구성하지 않습니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 API Gateway와 PrivateLink 관련 구성을 추가하지만, EC2 인스턴스의 S3 접근에는 S3 VPC 엔드포인트가 직접적인 해결책입니다. 불필요한 구성 요소가 추가되므로 적합하지 않습니다."}}},{"id":"Q0005","question_number":5,"question":"회사는 사용자 업로드 문서를 Amazon EBS 볼륨에 저장하는 단일 Amazon EC2 인스턴스를 사용하여 AWS 에서 웹 애플리케이션을 호스팅하고 있습니다. 더 나은 확장성과 가용성을 위해 이 회사는 아키텍처를 복제하고 다른 가용 영역에 두 번째 EC2 인스턴스와 EBS 볼륨을 생성하여 Application Load Balancer 뒤에 배치했습니다. 이 변경을 완료한 후 사용자는 웹 사이트를 새로 고칠 때마다 문서의 일부 또는 다른 하위 집합을 볼 수 있지만 모든 문서를 동시에 볼 수는 없다고 보고했습니다. 솔루션 설계자는 사용자가 모든 문서를 한 번에 볼 수 있도록 무엇을 제안해야 합니까?","choices":{"A":"두 EBS 볼륨에 모든 문서가 포함되도록 데이터를 복사합니다.","B":"문서가 있는 서버로 사용자를 안내하도록 Application Load Balancer 를 구성합니다.","C":"두 EBS 볼륨의 데이터를 Amazon EFS 로 복사합니다. 새 문서를 Amazon EFS 에 저장하도록 애플리케이션을 수정합니다.","D":"두 서버 모두에 요청을 보내도록 Application Load Balancer 를 구성합니다. 올바른 서버에서 각 문서를 반환합니다."},"answers":["C"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"고가용성 및/또는 내결함성 아키텍처 설계","aws_services":["Amazon EBS","Amazon EFS"],"explanation":{"requirementsAnalysis":"웹 애플리케이션은 서로 다른 가용 영역의 두 EC2 인스턴스에서 실행되고 Application Load Balancer가 요청을 분산합니다. 문서가 각 인스턴스의 Amazon EBS 볼륨에 분리되어 있어 요청 대상에 따라 보이는 문서가 달라집니다. 모든 사용자가 항상 같은 문서 집합을 보려면 두 인스턴스가 동시에 접근할 수 있는 공유 파일 스토리지가 필요합니다. 또한 가용 영역 분산 구조와 함께 사용할 수 있어야 합니다.","awsServicesAnalysis":"Amazon EBS는 일반적으로 단일 EC2 인스턴스에 연결하는 블록 스토리지이며, 볼륨의 데이터는 다른 볼륨과 자동으로 동기화되지 않습니다. Amazon EFS는 NFS 기반의 완전관리형 공유 파일 시스템으로, 같은 리전의 여러 가용 영역에서 실행되는 EC2 인스턴스가 동시에 마운트할 수 있습니다. Application Load Balancer는 대상 그룹의 정상 대상에 HTTP/HTTPS 요청을 분산합니다. 데이터 복사는 초기 또는 지속적인 동기화 작업을 별도로 필요로 합니다.","choicesAnalysis":"문제의 원인은 로드 밸런서가 아니라 인스턴스별 로컬 스토리지에 서로 다른 데이터가 있다는 점입니다. 공통 파일 시스템을 사용하고 모든 새 문서를 그곳에 저장하면 어느 인스턴스가 요청을 처리하더라도 동일한 문서를 제공합니다. 단순 복제나 라우팅 변경은 동시 접근 가능한 단일 데이터 원본을 보장하지 않습니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 두 EBS 볼륨을 한 시점에 동일하게 만들 수 있어도 새 문서와 변경 사항을 지속적으로 동기화해야 합니다. 공유 저장소를 제공하지 않으므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 Application Load Balancer가 문서가 있는 서버를 자동으로 식별하도록 구성할 수 없습니다. 데이터 분산 문제를 해결하지 못하므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 두 EBS 볼륨의 문서를 Amazon EFS로 통합하고 두 애플리케이션 인스턴스가 동일한 파일 시스템을 사용하게 합니다. 모든 사용자가 같은 문서 집합을 볼 수 있으므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 Application Load Balancer가 하나의 요청을 두 서버에 보내고 응답을 조합하는 방식으로 동작하지 않습니다. 또한 데이터 불일치를 해결하지 못하므로 적합하지 않습니다."}}},{"id":"Q0006","question_number":6,"question":"회사는 NFS 를 사용하여 온프레미스 네트워크 연결 스토리지에 대용량 비디오 파일을 저장합니다. 각 비디오 파일의 크기 범위는 1MB 에서 500GB 입니다. 총 스토리지는 70TB 이며 더 이상 증가하지 않습니다. 회사는 비디오 파일을 Amazon S3 로 마이그레이션하기로 결정합니다. 회사는 가능한 한 최소한의 네트워크 대역폭을 사용하면서 가능한 한 빨리 비디오 파일을 마이그레이션해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"S3 버킷을 생성합니다. S3 버킷에 대한 쓰기 권한이 있는 IAM 역할을 생성합니다. AWS CLI 를 사용하여 모든 파일을 S3 버킷에 로컬로 복사합니다.","B":"AWS Snowball Edge 작업을 생성합니다. 온프레미스에서 Snowball Edge 장치를 받습니다. Snowball Edge 클라이언트를 사용하여 장치로 데이터를 전송합니다. AWS 가 데이터를 Amazon S3 로 가져올 수 있도록 디바이스를 반환합니다.","C":"온프레미스에 S3 파일 게이트웨이를 배포합니다. S3 파일 게이트웨이에 연결할 퍼블릭 서비스 엔드포인트를 생성합니다. S3 버킷을 생성합니다. S3 파일 게이트웨이에서 새 NFS 파일 공유를 생성합니다. 새 파일 공유가 S3 버킷을 가리키도록 합니다. 기존 NFS 파일 공유에서 S3 파일 게이트웨이로 데이터를 전송합니다.","D":"온프레미스 네트워크와 AWS 간에 AWS Direct Connect 연결을 설정합니다. 온프레미스에 S3 파일 게이트웨이를 배포합니다. S3 파일 게이트웨이에 연결할 공용 VIF(가상 인터페이스)를 생성합니다. S3 버킷을 생성합니다. S3 파일 게이트웨이에서 새 NFS 파일 공유를 생성합니다. 새 파일 공유가 S3 버킷을 가리키도록 합니다. 기존 NFS 파일 공유에서 S3 파일 게이트웨이로 데이터를 전송합니다."},"answers":["B"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터 수집 및 변환 솔루션 결정","aws_services":["AWS Snow Family","Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 온프레미스 NFS 스토리지의 70TB 비디오 파일을 Amazon S3로 이전해야 합니다. 파일은 최대 500GB이고, 가능한 한 적은 네트워크 대역폭을 사용하면서 신속한 마이그레이션이 요구됩니다. 따라서 대용량 데이터를 WAN으로 전송하지 않고 반입할 수 있으며 해당 파일 크기를 처리하는 전송 방식이 필요합니다.","awsServicesAnalysis":"AWS Snowball Edge는 물리적 디바이스에 대용량 데이터를 적재한 뒤 AWS로 반송하여 S3로 가져오는 오프라인 전송 서비스입니다. 다만 2025년 11월 7일부터 신규 고객은 Snowball Edge 디바이스를 주문할 수 없고, 기존 고객만 계속 사용할 수 있습니다. 현재 신규 고객은 온라인 전송에는 AWS DataSync, 물리적 전송에는 AWS Data Transfer Terminal 또는 AWS 파트너 솔루션을 검토해야 합니다. AWS CLI, S3 File Gateway 및 AWS Direct Connect를 통한 전송은 모두 네트워크 대역폭을 사용합니다.","choicesAnalysis":"이 문항의 출제 시점에는 70TB를 WAN으로 전송하지 않는 Snowball Edge가 네트워크 대역폭 최소화와 대규모 초기 이전에 가장 직접적으로 부합했습니다. AWS CLI, File Gateway 및 Direct Connect 선택지는 모두 데이터 본문을 네트워크로 전송합니다. 따라서 출제 맥락에서는 B가 정답입니다. 현재 신규 고객에게는 Snowball Edge 주문이 제공되지 않으므로 실제 신규 설계에서는 Data Transfer Terminal이나 파트너의 오프라인 전송 서비스를 별도로 검토해야 합니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"AWS CLI로 70TB 데이터를 인터넷 또는 네트워크 연결을 통해 업로드해야 하므로 네트워크 대역폭 사용을 최소화하는 요구사항에 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"출제 당시에는 Snowball Edge에 데이터를 적재하고 디바이스를 반환하여 S3로 가져오는 방식이 WAN 대역폭을 최소화하므로 가장 적합했습니다. 다만 현재는 신규 고객이 Snowball Edge를 주문할 수 없으며 기존 고객에게만 적용 가능한 선택지입니다."},"C":{"isCorrect":false,"explanation":"S3 File Gateway를 통해 기존 데이터를 S3로 이동할 수 있지만 데이터가 온프레미스 네트워크를 거쳐 AWS로 전송됩니다. 네트워크 사용 최소화 요구사항에 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"Direct Connect로 더 예측 가능한 전송 경로를 제공할 수 있지만 70TB 데이터를 네트워크로 전송해야 합니다. 네트워크 대역폭 사용을 최소화하는 조건에는 적합하지 않습니다."}}},{"id":"Q0007","question_number":7,"question":"회사에 들어오는 메시지를 수집하는 응용 프로그램이 있습니다. 그러면 수십 개의 다른 애플리케이션과 마이크로서비스가 이러한 메시지를 빠르게 소비합니다. 메시지 수는 급격하게 변하며 때로는 초당 100,000 개로 갑자기 증가하기도 합니다. 이 회사는 솔루션을 분리하고 확장성을 높이고자 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"Amazon Kinesis Data Analytics 에 대한 메시지를 유지합니다. 메시지를 읽고 처리하도록 소비자 애플리케이션을 구성합니다.","B":"Auto Scaling 그룹의 Amazon EC2 인스턴스에 수집 애플리케이션을 배포하여 CPU 지표를 기반으로 EC2 인스턴스 수를 확장합니다.","C":"단일 샤드를 사용하여 Amazon Kinesis Data Streams 에 메시지를 씁니다. AWS Lambda 함수를 사용하여 메시지를 사전 처리하고 Amazon DynamoDB 에 저장합니다. 메시지를 처리하기 위해 DynamoDB 에서 읽도록 소비자 애플리케이션을 구성합니다.","D":"여러 Amazon Simple Queue Service(Amazon SOS) 구독이 있는 Amazon Simple Notification Service(Amazon SNS) 주제에 메시지를 게시합니다. 대기열의 메시지를 처리하도록 소비자 애플리케이션을 구성합니다."},"answers":["D"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon SNS","Amazon SQS"],"explanation":{"requirementsAnalysis":"회사는 급격히 변동하는 대량의 메시지를 수집한 뒤 수십 개의 애플리케이션과 마이크로서비스가 빠르게 소비하도록 해야 합니다. 생산자와 다수의 소비자가 서로의 가용성 및 처리 속도에 직접 의존하지 않아야 하며, 급증하는 트래픽을 흡수할 수 있어야 합니다. 따라서 단일 게시로 여러 소비 경로에 메시지를 전달하고 각 소비자가 독립적으로 처리하도록 분리하는 메시징 구조가 필요합니다.","awsServicesAnalysis":"Amazon SNS는 게시/구독 모델로 하나의 주제에 게시된 메시지를 여러 구독자에게 팬아웃할 수 있습니다. Amazon SQS는 생산자와 소비자를 분리하는 내구성 있는 메시지 큐이며 소비자 그룹별로 별도 큐를 둘 수 있습니다. Amazon Kinesis Data Streams는 샤드 또는 온디맨드 용량 모드를 사용하는 스트리밍 데이터 서비스입니다. 보기의 Amazon Kinesis Data Analytics는 스트림 분석 서비스이지 메시지 보존 및 팬아웃 서비스가 아닙니다. 종전의 SQL 애플리케이션 기능은 2026년 1월 27일 지원이 종료되었고, 현재 실시간 스트림 처리는 Amazon Managed Service for Apache Flink를 사용합니다. Amazon DynamoDB는 관리형 NoSQL 데이터베이스입니다.","choicesAnalysis":"서로 다른 소비자가 같은 메시지를 각각 받아야 하므로 소비자별 독립 버퍼와 처리 속도를 제공하는 팬아웃 구성이 적합합니다. SNS 주제와 여러 SQS 구독을 결합하면 게시자는 한 번 전송하고 소비자는 각자의 큐에서 비동기로 처리할 수 있습니다. 컴퓨팅 자동 확장이나 단일 스트림과 데이터베이스를 잇는 경로는 다수 소비자의 독립 처리 요구를 완전하게 제공하지 않습니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"Kinesis Data Analytics를 메시지 보존과 다수 소비자 배포에 사용하려는 구성입니다. 이 서비스는 스트림 분석용이며 요구된 팬아웃 소비 구조를 제공하지 않으므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"수집 애플리케이션의 컴퓨팅 용량은 조정할 수 있지만 생산자와 수십 개 소비자의 메시지 전달 및 독립 처리를 분리하지 못하므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"단일 Kinesis Data Streams 샤드는 초당 100,000개로 급증하는 트래픽에 부족할 수 있으며, DynamoDB 저장 경로도 소비자별 독립 큐를 제공하지 않습니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"SNS 주제가 메시지를 여러 SQS 큐로 팬아웃하고 각 애플리케이션이 자기 큐를 독립적으로 처리하게 합니다. 생산자와 소비자를 분리하고 다수 소비자 구성을 지원하므로 적합합니다."}}},{"id":"Q0008","question_number":8,"question":"회사에서 분산 애플리케이션을 AWS 로 마이그레이션하고 있습니다. 애플리케이션은 다양한 워크로드를 처리합니다. 레거시 플랫폼은 여러 컴퓨팅 노드에서 작업을 조정하는 기본 서버로 구성됩니다. 이 회사는 탄력성과 확장성을 극대화하는 솔루션으로 애플리케이션을 현대화하려고 합니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 아키텍처를 어떻게 설계해야 합니까?","choices":{"A":"작업의 대상으로 Amazon Simple Queue Service(Amazon SQS) 대기열을 구성합니다. Auto Scaling 그룹에서 관리되는 Amazon EC2 인스턴스로 컴퓨팅 노드를 구현합니다. 예약된 조정을 사용하도록 EC2 Auto Scaling 을 구성합니다.","B":"작업의 대상으로 Amazon Simple Queue Service(Amazon SQS) 대기열을 구성합니다. Auto Scaling 그룹에서 관리되는 Amazon EC2 인스턴스로 컴퓨팅 노드를 구현합니다. 대기열 크기에 따라 EC2 Auto Scaling 을 구성합니다.","C":"Auto Scaling 그룹에서 관리되는 Amazon EC2 인스턴스로 기본 서버와 컴퓨팅 노드를 구현합니다. 작업의 대상으로 AWS CloudTrail 을 구성합니다. 기본 서버의 부하를 기반으로 EC2 Auto Scaling 을 구성합니다.","D":"Auto Scaling 그룹에서 관리되는 Amazon EC2 인스턴스로 기본 서버와 컴퓨팅 노드를 구현합니다. 작업의 대상으로 Amazon EventBridge(Amazon CloudWatch Events)를 구성합니다. 컴퓨팅 노드의 부하를 기반으로 EC2 Auto Scaling 을 구성합니다."},"answers":["B"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon SQS","Amazon EC2","Amazon EC2 Auto Scaling"],"explanation":{"requirementsAnalysis":"회사는 여러 컴퓨팅 노드에서 작업을 조정하는 기본 서버 기반의 분산 애플리케이션을 현대화해야 합니다. 탄력성과 확장성을 높이려면 작업 생성과 처리를 분리하고, 처리 용량이 실제 대기 작업량에 따라 변해야 합니다. 따라서 작업을 버퍼링할 수 있는 내구성 있는 큐와 큐 부하에 맞춰 조정되는 컴퓨팅 계층이 필요합니다.","awsServicesAnalysis":"Amazon SQS는 생산자와 소비자 사이에 메시지를 보관하는 관리형 큐 서비스로 비동기 작업 처리를 분리할 수 있습니다. Amazon EC2 Auto Scaling은 Auto Scaling 그룹의 EC2 용량을 지표 기반 정책으로 조정합니다. SQS 기반 처리 시스템에서는 메시지 백로그와 인스턴스 수를 결합한 지표를 사용하여 처리 용량을 조정할 수 있습니다. AWS CloudTrail은 AWS API 활동을 기록하는 감사 서비스입니다. Amazon EventBridge는 이벤트를 규칙에 따라 대상에 전달하는 서버리스 이벤트 버스입니다.","choicesAnalysis":"작업 큐는 기본 서버가 작업을 직접 조정하는 결합을 줄이고, 처리 노드는 큐의 백로그에 맞춰 독립적으로 확장할 수 있어야 합니다. 예약된 확장은 실제 작업량의 급격한 변화에 즉시 대응하지 못합니다. CloudTrail이나 EventBridge를 작업 저장소로 사용하면 내구성 있는 작업 큐와 큐 기반 처리량 조정이라는 목표와 맞지 않습니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 SQS와 Auto Scaling 그룹을 사용하지만 예약된 조정은 실제 큐 백로그의 변동에 따라 용량을 자동으로 조절하지 못합니다. 탄력성 및 확장성 극대화 요구사항에 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 SQS가 작업을 버퍼링하고 Auto Scaling 그룹의 EC2 노드가 이를 처리하게 합니다. 큐 백로그에 맞춰 용량을 조정할 수 있으므로 작업과 처리 노드를 분리하면서 탄력적으로 확장할 수 있어 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 AWS CloudTrail을 작업 대상으로 사용하지만 CloudTrail은 API 활동 기록 서비스입니다. 작업 큐를 제공하지 않으며 기본 서버의 부하 기준 확장도 대기 작업량을 직접 반영하지 않으므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 EventBridge가 이벤트를 대상에 전달할 수 있으나, 보기의 구성은 기본 서버를 계속 중심에 두고 컴퓨팅 노드 부하만 기준으로 확장합니다. SQS 백로그 기반 작업 분리 및 확장 방식보다 요구사항에 적합하지 않습니다."}}},{"id":"Q0009","question_number":9,"question":"회사는 데이터 센터에서 SMB 파일 서버를 실행하고 있습니다. 파일 서버는 파일이 생성된 후 처음 며칠 동안 자주 액세스하는 대용량 파일을 저장합니다. 7 일이 지나면 파일에 거의 액세스하지 않습니다. 총 데이터 크기가 증가하고 있으며 회사의 총 저장 용량에 가깝습니다. 솔루션 설계자는 가장 최근에 액세스한 파일에 대한 저지연 액세스를 잃지 않으면서 회사의 사용 가능한 저장 공간을 늘려야 합니다. 솔루션 설계자는 향후 스토리지 문제를 방지하기 위해 파일 수명 주기 관리도 제공해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"AWS DataSync 를 사용하여 SMB 파일 서버에서 AWS 로 7 일이 지난 데이터를 복사합니다.","B":"Amazon S3 파일 게이트웨이를 생성하여 회사의 스토리지 공간을 확장합니다. S3 수명 주기 정책을 생성하여 7 일 후에 데이터를 S3 Glacier Deep Archive 로 전환합니다.","C":"Windows 파일 서버용 Amazon FSx 파일 시스템을 생성하여 회사의 저장 공간을 확장합니다.","D":"각 사용자의 컴퓨터에 유틸리티를 설치하여 Amazon S3 에 액세스합니다. S3 수명 주기 정책을 생성하여 7 일 후 데이터를 S3 Glacier Flexible Retrieval 로 전환합니다."},"answers":["B"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 스토리지 솔루션 설계","aws_services":["Amazon S3","Amazon S3 Glacier","AWS Storage Gateway"],"explanation":{"requirementsAnalysis":"회사는 온프레미스 SMB 파일 서버의 저장 공간을 확장해야 합니다. 새 파일은 처음 며칠 동안 자주 사용하므로 낮은 지연 시간으로 접근할 수 있어야 하고, 7일 이후에는 거의 접근하지 않아 저비용 장기 저장소로 전환할 수 있어야 합니다. 온프레미스 파일 인터페이스를 유지하면서 로컬 캐시와 S3 수명 주기 관리를 함께 제공하는 솔루션이 필요합니다.","awsServicesAnalysis":"Amazon S3 File Gateway는 온프레미스 애플리케이션에 SMB 및 NFS 파일 공유를 제공하고, 파일을 S3 객체로 저장하며 자주 액세스하는 데이터를 로컬에 캐시할 수 있습니다. Amazon S3 Lifecycle은 객체를 정의한 기간 후 다른 S3 스토리지 클래스로 전환할 수 있습니다. S3 Glacier Deep Archive는 장기 보관에 적합한 저비용 아카이브 스토리지 클래스입니다. AWS DataSync는 온프레미스와 AWS 스토리지 서비스 간 데이터 전송을 자동화합니다. Amazon FSx for Windows File Server는 관리형 Windows 파일 시스템입니다.","choicesAnalysis":"활성 파일에 대한 SMB 기반 저지연 접근을 유지하면서 온프레미스 용량을 확장하려면 S3를 백엔드로 사용하고 로컬 캐시를 제공하는 파일 게이트웨이가 필요합니다. 이후 파일을 S3 수명 주기 정책으로 아카이브 계층으로 이동하면 접근 빈도 감소에 맞춰 저장 비용을 줄일 수 있습니다. 단순 일회성 복사나 별도 파일 시스템 추가는 두 요구사항을 함께 해결하지 못합니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 7일이 지난 데이터를 AWS로 한 번 복사할 수 있지만, 온프레미스 SMB 접근을 확장하는 파일 인터페이스와 지속적인 수명 주기 관리를 제공하지 않으므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 S3 File Gateway로 SMB 파일 서버의 저장 공간을 S3로 확장하고 자주 쓰는 데이터를 로컬 캐시에서 제공할 수 있습니다. S3 Lifecycle로 7일 후 Glacier Deep Archive로 전환할 수 있으므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 Amazon FSx for Windows File Server로 파일 시스템을 제공할 수 있지만, 제시된 구성에는 온프레미스 용량 확장용 캐시 계층과 7일 기준 아카이브 수명 주기 관리가 없습니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 각 사용자 컴퓨터에 별도 유틸리티를 배포해야 하며 기존 SMB 파일 서버 인터페이스를 유지하지 못합니다. 중앙 캐시 및 파일 공유 방식도 제공하지 않으므로 적합하지 않습니다."}}},{"id":"Q0010","question_number":10,"question":"회사는 AWS 에서 전자 상거래 웹 애플리케이션을 구축하고 있습니다. 애플리케이션은 처리할 Amazon API Gateway REST API 에 새 주문에 대한 정보를 보냅니다. 회사는 주문이 접수된 순서대로 처리되기를 원합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"API Gateway 통합을 사용하여 애플리케이션이 주문을 수신할 때 Amazon Simple Notification Service(Amazon SNS) 주제에 메시지를 게시합니다. AWS Lambda 함수를 주제에 구독하여 처리를 수행합니다.","B":"API Gateway 통합을 사용하여 애플리케이션이 주문을 수신할 때 Amazon Simple Queue Service(Amazon SQS) FIFO 대기열에 메시지를 보냅니다. 처리를 위해 AWS Lambda 함수를 호출하도록 SQS FIFO 대기열을 구성합니다.","C":"API Gateway 권한 부여자를 사용하여 애플리케이션이 주문을 처리하는 동안 모든 요청을 차단합니다.","D":"API Gateway 통합을 사용하여 애플리케이션이 주문을 수신할 때 Amazon Simple Queue Service(Amazon SQS) 표준 대기열에 메시지를 보냅니다. 처리를 위해 AWS Lambda 함수를 호출하도록 SQS 표준 대기열을 구성합니다."},"answers":["B"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon API Gateway","Amazon SQS","AWS Lambda"],"explanation":{"requirementsAnalysis":"웹 애플리케이션은 Amazon API Gateway REST API로 새 주문 정보를 전송하며, 주문은 접수된 순서대로 처리되어야 합니다. 따라서 API 수신과 비동기 처리를 분리하면서 메시지 순서를 보장하는 내구성 있는 대기열과 소비자 통합이 필요합니다. 단순한 비동기 전송만으로는 순서 보장 요구사항을 충족할 수 없습니다.","awsServicesAnalysis":"Amazon API Gateway는 REST API 요청을 AWS 서비스 또는 백엔드와 통합할 수 있습니다. Amazon SQS FIFO 큐는 메시지 그룹 ID와 중복 제거를 사용하여 순서 있는 메시지 처리를 지원합니다. FIFO 큐를 Lambda 이벤트 소스로 구성하면 Lambda는 동일한 메시지 그룹의 메시지를 동시에 처리하지 않아 순서 보장을 유지합니다. Amazon SQS 표준 큐는 높은 처리량의 최소 1회 전달을 제공하지만 메시지 순서를 보장하지 않습니다. Amazon SNS는 게시/구독 메시징 서비스이며, Lambda 함수는 이벤트에 따라 코드를 실행합니다.","choicesAnalysis":"주문 처리에는 내구성 있는 버퍼와 수신 순서 보장이 모두 필요합니다. API Gateway에서 FIFO 큐로 주문을 전달하고 Lambda가 큐를 소비하게 하면 요청 수신과 처리를 분리하면서 동일한 메시지 그룹의 순서를 유지할 수 있습니다. 표준 큐나 일반 알림 주제 기반 구성은 이 순서 제약을 충족하지 않습니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 SNS 주제와 Lambda 구독으로 비동기 처리를 구성할 수 있지만, 제시된 일반 SNS 주제는 주문 메시지의 처리 순서를 보장하지 않습니다. 따라서 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 API Gateway가 주문을 SQS FIFO 큐에 보내고 Lambda가 이를 처리하게 합니다. FIFO 큐의 메시지 그룹을 사용하면 주문 접수 순서를 유지할 수 있으므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 요청을 차단하여 순차성을 구현하는 방식이 아니며, 주문을 내구성 있게 저장하고 비동기로 처리하는 경로를 제공하지 않습니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 SQS 표준 큐가 메시지를 비동기로 버퍼링할 수 있지만, 표준 큐는 메시지 순서를 보장하지 않습니다. 따라서 적합하지 않습니다."}}},{"id":"Q0011","question_number":11,"question":"회사에 Amazon EC2 인스턴스에서 실행되고 Amazon Aurora 데이터베이스를 사용하는 애플리케이션이 있습니다. EC2 인스턴스는 파일에 로컬로 저장된 사용자 이름과 암호를 사용하여 데이터베이스에 연결합니다. 회사는 자격 증명 관리의 운영 오버헤드를 최소화하려고 합니다. 솔루션 설계자는 이 목표를 달성하기 위해 무엇을 해야 합니까?","choices":{"A":"AWS Secrets Manager 를 사용합니다. 자동 회전을 켭니다.","B":"AWS Systems Manager Parameter Store 를 사용합니다. 자동 회전을 켭니다.","C":"AWS Key Management Service(AWS KMS) 암호화 키로 암호화된 객체를 저장할 Amazon S3 버킷을 생성합니다. 자격 증명 파일을 S3 버킷으로 마이그레이션합니다. 애플리케이션이 S3 버킷을 가리키도록 합니다.","D":"각 EC2 인스턴스에 대해 암호화된 Amazon Elastic Block Store(Amazon EBS) 볼륨을 생성합니다. 새 EBS 볼륨을 각 EC2 인스턴스에 연결합니다. 자격 증명 파일을 새 EBS 볼륨으로 마이그레이션합니다. 애플리케이션이 새 EBS 볼륨을 가리키도록 합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["AWS Secrets Manager"],"explanation":{"requirementsAnalysis":"애플리케이션은 Amazon EC2 인스턴스에서 Amazon Aurora 데이터베이스에 연결하며, 현재 사용자 이름과 암호가 로컬 파일에 저장되어 있습니다. 회사는 데이터베이스 자격 증명을 안전하게 보관하고 교체하는 과정의 운영 부담을 줄여야 합니다. 따라서 애플리케이션이 필요할 때 자격 증명을 안전하게 조회할 수 있고, 암호 교체를 관리형 기능으로 자동화할 수 있어야 합니다.","awsServicesAnalysis":"AWS Secrets Manager는 데이터베이스 자격 증명과 같은 비밀을 암호화하여 저장하고, 애플리케이션이 IAM 권한을 사용해 비밀 값을 조회하도록 지원합니다. Amazon RDS 및 Amazon Aurora용 비밀은 Secrets Manager의 회전 기능을 사용해 일정에 따라 자동으로 교체할 수 있습니다. AWS Systems Manager Parameter Store는 보안 문자열 파라미터를 저장할 수 있지만, Parameter Store 자체에는 Secrets Manager와 같은 관리형 데이터베이스 자격 증명 회전 기능이 없습니다. Amazon S3와 Amazon EBS의 암호화는 저장 데이터 보호에 사용되지만, 애플리케이션 자격 증명의 수명 주기와 자동 교체를 관리하는 서비스는 아닙니다.","choicesAnalysis":"요구사항의 핵심은 자격 증명 파일의 저장 위치만 변경하는 것이 아니라 비밀의 안전한 조회와 주기적 교체를 관리형으로 처리하는 것입니다. 저장소 암호화만 적용한 구성은 암호 교체 절차를 별도로 운영해야 하며, Parameter Store만으로는 관리형 데이터베이스 비밀 회전이 제공되지 않습니다. 따라서 Aurora 자격 증명 관리와 자동 회전을 함께 제공하는 AWS Secrets Manager를 사용하는 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"적합합니다. AWS Secrets Manager에 Aurora 자격 증명을 저장하고 자동 회전을 활성화하면, 비밀 저장과 암호 교체를 관리형 기능으로 처리할 수 있습니다. 애플리케이션은 로컬 파일 대신 권한이 부여된 방식으로 최신 자격 증명을 조회할 수 있으므로 운영 오버헤드가 낮습니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Systems Manager Parameter Store는 보안 문자열을 저장할 수 있지만, Parameter Store 자체에는 Amazon Aurora 자격 증명을 자동으로 회전하는 관리형 기능이 없습니다. 따라서 회전 로직과 운영 절차를 별도로 구현해야 합니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. Amazon S3에 암호화된 자격 증명 파일을 저장하면 로컬 파일을 중앙화할 수는 있지만, 애플리케이션이 파일을 관리하고 자격 증명을 교체하는 절차를 계속 운영해야 합니다. 자동 회전 요구사항을 충족하지 못합니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. 암호화된 Amazon EBS 볼륨은 저장된 파일을 보호하지만, 자격 증명의 자동 교체나 애플리케이션의 안전한 비밀 조회를 제공하지 않습니다. 인스턴스별 볼륨 관리까지 필요하므로 운영 부담도 줄지 않습니다."}}},{"id":"Q0012","question_number":12,"question":"글로벌 회사는 ALB(Application Load Balancer) 뒤의 Amazon EC2 인스턴스에서 웹 애플리케이션을 호스팅합니다. 웹 애플리케이션에는 정적 데이터와 동적 데이터가 있습니다. 회사는 정적 데이터를 Amazon S3 버킷에 저장합니다. 회사는 정적 데이터 및 동적 데이터의 성능을 개선하고 대기 시간을 줄이기를 원합니다. 회사는 Amazon Route 53 에 등록된 자체 도메인 이름을 사용하고 있습니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"S3 버킷과 ALB 를 오리진으로 포함하는 Amazon CloudFront 배포를 생성합니다. CloudFront 배포로 트래픽을 라우팅하도록 Route 53 을 구성합니다.","B":"ALB 가 오리진인 Amazon CloudFront 배포를 생성합니다. S3 버킷을 엔드포인트로 포함하는 AWS Global Accelerator 표준 액셀러레이터를 생성합니다. CloudFront 배포로 트래픽을 라우팅하도록 Route 53 을 구성합니다.","C":"S3 버킷을 오리진으로 포함하는 Amazon CloudFront 배포를 생성합니다. ALB 및 CloudFront 배포를 엔드포인트로 포함하는 AWS Global Accelerator 표준 액셀러레이터를 생성합니다. 가속기 DNS 이름을 가리키는 사용자 지정 도메인 이름을 만듭니다. 사용자 지정 도메인 이름을 웹 애플리케이션의 끝점으로 사용합니다.","D":"ALB 가 오리진인 Amazon CloudFront 배포를 생성합니다. S3 버킷을 엔드포인트로 포함하는 AWS Global Accelerator 표준 액셀러레이터를 생성합니다. 두 개의 도메인 이름을 만듭니다. 하나의 도메인 이름이 동적 콘텐츠의 CloudFront DNS 이름을 가리키도록 합니다. 다른 도메인 이름이 정적 콘텐츠에 대한 가속기 DNS 이름을 가리키도록 합니다. 도메인 이름을 웹 애플리케이션의 끝점으로 사용합니다."},"answers":["A"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 네트워크 아키텍처 결정","aws_services":["Amazon CloudFront","Amazon S3","Elastic Load Balancing(ELB)","Amazon Route 53"],"explanation":{"requirementsAnalysis":"회사는 Amazon S3에 저장된 정적 콘텐츠와 Application Load Balancer 뒤에서 제공되는 동적 콘텐츠의 성능을 함께 개선하고 지연 시간을 줄여야 합니다. 자체 도메인은 Amazon Route 53에서 관리하고 있으므로, 사용자가 하나의 도메인으로 두 유형의 콘텐츠에 효율적으로 접근할 수 있어야 합니다. 따라서 전 세계 엣지에서 정적 콘텐츠를 캐시하고 동적 요청도 적절한 원본으로 전달하면서, DNS 구성을 단순하게 유지하는 것이 핵심입니다.","awsServicesAnalysis":"Amazon CloudFront는 전 세계 엣지 로케이션에서 콘텐츠를 전송하는 CDN이며, 배포 하나에 여러 원본과 경로별 캐시 동작을 구성할 수 있습니다. Amazon S3 버킷은 정적 콘텐츠의 원본으로 사용할 수 있고, Application Load Balancer는 동적 HTTP 및 HTTPS 콘텐츠의 원본으로 사용할 수 있습니다. Amazon Route 53은 별칭 레코드를 통해 사용자 지정 도메인을 CloudFront 배포에 연결할 수 있습니다. AWS Global Accelerator는 고정 IP 주소와 AWS 글로벌 네트워크를 사용해 지원되는 엔드포인트로 트래픽을 전달하지만, S3 버킷과 CloudFront 배포를 표준 액셀러레이터의 엔드포인트로 사용하는 구성은 제공되지 않습니다.","choicesAnalysis":"정적 콘텐츠와 동적 콘텐츠를 모두 전 세계 사용자에게 낮은 지연 시간으로 제공하려면, 두 원본을 하나의 CloudFront 배포에 연결하고 경로에 따라 원본을 선택하는 구성이 적합합니다. Route 53은 사용자 지정 도메인의 트래픽을 해당 배포로 직접 라우팅할 수 있습니다. Global Accelerator를 포함한 다른 구성은 제시된 엔드포인트 조합을 지원하지 않거나 도메인과 전송 경로를 불필요하게 분리합니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"적합합니다. 하나의 CloudFront 배포에 S3 버킷과 ALB를 원본으로 구성하면 정적 콘텐츠는 엣지에서 캐시하고 동적 요청은 ALB로 전달할 수 있습니다. Route 53 별칭 레코드로 자체 도메인을 배포에 연결하므로 성능과 지연 시간 요구사항을 단순하게 충족합니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Global Accelerator 표준 액셀러레이터는 Amazon S3 버킷을 엔드포인트로 포함할 수 없습니다. 또한 CloudFront 배포와 S3 원본을 한 배포에서 처리할 수 있으므로 이 구성은 요구사항에 필요한 방식이 아닙니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Global Accelerator 표준 액셀러레이터는 S3 버킷이나 CloudFront 배포를 엔드포인트로 지원하지 않습니다. 따라서 제시된 가속기 구성 자체가 성립하지 않습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Global Accelerator 표준 액셀러레이터에 S3 버킷을 엔드포인트로 추가할 수 없습니다. 또한 정적 및 동적 콘텐츠를 별도 도메인으로 나누는 방식은 하나의 CloudFront 배포에서 여러 원본을 사용하는 구성보다 복잡합니다."}}},{"id":"Q0013","question_number":13,"question":"회사는 AWS 인프라에 대한 월별 유지 관리를 수행합니다. 이러한 유지 관리 활동 중에 회사는 여러 AWS 리전에서 MySQL 용 Amazon RDS 데이터베이스에 대한 자격 증명을 교체해야 합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"자격 증명을 AWS Secrets Manager 에 암호로 저장합니다. 필요한 리전에 대해 다중 리전 비밀 복제를 사용합니다. 일정에 따라 보안 암호를 교체하도록 Secrets Manager 를 구성합니다.","B":"보안 문자열 파라미터를 생성하여 AWS Systems Manager 에 자격 증명을 보안 암호로 저장합니다. 필요한 리전에 대해 다중 리전 비밀 복제를 사용합니다. 일정에 따라 암호를 교체하도록 Systems Manager 를 구성합니다.","C":"서버 측 암호화(SSE)가 활성화된 Amazon S3 버킷에 자격 증명을 저장합니다. Amazon EventBridge(Amazon CloudWatch Events)를 사용하여 AWS Lambda 함수를 호출하여 자격 증명을 교체합니다.","D":"AWS Key Management Service(AWS KMS) 다중 리전 고객 관리형 키를 사용하여 자격 증명을 비밀로 암호화합니다. Amazon DynamoDB 전역 테이블에 암호를 저장합니다. AWS Lambda 함수를 사용하여 DynamoDB 에서 암호를 검색합니다. RDS API 를 사용하여 비밀을 교체합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["AWS Secrets Manager","Amazon RDS"],"explanation":{"requirementsAnalysis":"회사는 여러 AWS 리전의 MySQL용 Amazon RDS 데이터베이스 자격 증명을 월별 유지 관리 중 교체해야 합니다. 같은 자격 증명 관리 방식을 필요한 리전에 일관되게 제공하고, 암호 교체를 수작업이나 자체 구현으로 운영하지 않아야 합니다. 따라서 다중 리전 배포와 일정 기반 데이터베이스 자격 증명 회전을 관리형으로 지원하는 서비스가 필요합니다.","awsServicesAnalysis":"AWS Secrets Manager는 비밀을 저장하고 Amazon RDS 데이터베이스 자격 증명을 일정에 따라 자동 회전할 수 있습니다. 다중 리전 비밀 복제를 사용하면 원본 비밀을 다른 리전에 복제하여 리전별 워크로드가 가까운 복제본을 사용할 수 있습니다. AWS Systems Manager Parameter Store는 보안 문자열을 저장하지만, 다중 리전 비밀 복제와 관리형 데이터베이스 자격 증명 회전 기능을 제공하지 않습니다. Amazon S3, Amazon DynamoDB 및 AWS Lambda를 조합하면 값을 저장하고 사용자 지정 회전 로직을 구현할 수 있으나, 운영해야 할 구성 요소와 코드가 늘어납니다. AWS KMS 다중 리전 키는 암호화 키를 리전 간에 복제하는 기능입니다.","choicesAnalysis":"여러 리전에서 데이터베이스 자격 증명을 사용하고 정기 교체를 최소 운영 오버헤드로 수행해야 하므로, 비밀 복제와 RDS용 자동 회전을 함께 제공하는 관리형 기능이 필요합니다. 저장소와 Lambda를 조합한 방식은 회전과 동기화를 직접 구현해야 합니다. 따라서 AWS Secrets Manager의 다중 리전 비밀 복제 및 일정 기반 회전을 사용하는 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"적합합니다. AWS Secrets Manager는 MySQL용 Amazon RDS 자격 증명을 저장하고 일정에 따라 자동으로 회전할 수 있습니다. 필요한 리전에 비밀을 복제하면 각 리전의 데이터베이스와 애플리케이션에 맞게 비밀을 제공할 수 있어 운영 오버헤드를 최소화합니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Systems Manager Parameter Store는 보안 문자열 파라미터를 저장하지만, 다중 리전 비밀 복제와 Amazon RDS 자격 증명의 관리형 자동 회전을 제공하지 않습니다. 제시된 기능을 그대로 구성할 수 없습니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. Amazon S3와 EventBridge 및 Lambda를 사용하면 회전 자동화를 직접 만들 수 있지만, 자격 증명 저장, 권한, 회전 로직 및 오류 처리를 운영해야 합니다. 관리형 Secrets Manager 방식보다 운영 부담이 큽니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. DynamoDB 전역 테이블과 Lambda, RDS API를 조합하면 사용자 지정 자격 증명 관리 체계를 만들 수 있지만, 비밀 회전 로직과 운영을 직접 책임져야 합니다. 최소 운영 오버헤드 요구사항에 맞지 않습니다."}}},{"id":"Q0014","question_number":14,"question":"회사는 Application Load Balancer 뒤의 Amazon EC2 인스턴스에서 전자 상거래 애플리케이션을 실행합니다. 인스턴스는 여러 가용 영역에 걸쳐 Amazon EC2 Auto Scaling 그룹에서 실행됩니다. Auto Scaling 그룹은 CPU 사용률 메트릭을 기반으로 확장됩니다. 전자 상거래 애플리케이션은 대규모 EC2 인스턴스에서 호스팅되는 MySQL 8.0 데이터베이스에 트랜잭션 데이터를 저장합니다. 애플리케이션 로드가 증가하면 데이터베이스의 성능이 빠르게 저하됩니다. 애플리케이션은 쓰기 트랜잭션보다 더 많은 읽기 요청을 처리합니다. 이 회사는 고가용성을 유지하면서 예측할 수 없는 읽기 워크로드의 수요를 충족하도록 데이터베이스를 자동으로 확장하는 솔루션을 원합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"리더 및 컴퓨팅 기능을 위해 단일 노드와 함께 Amazon Redshift 를 사용하십시오.","B":"단일 AZ 배포와 함께 Amazon RDS 사용 다른 가용 영역에 리더 인스턴스를 추가하도록 Amazon RDS 를 구성합니다.","C":"다중 AZ 배포와 함께 Amazon Aurora 를 사용합니다. Aurora 복제본을 사용하여 Aurora Auto Scaling 을 구성합니다.","D":"EC2 스팟 인스턴스와 함께 Memcached 용 Amazon ElastiCache 를 사용합니다."},"answers":["C"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터베이스 솔루션 결정","aws_services":["Amazon Aurora"],"explanation":{"requirementsAnalysis":"애플리케이션은 읽기 요청이 쓰기 트랜잭션보다 많고, 현재 단일 대형 EC2 인스턴스에서 실행되는 MySQL 데이터베이스의 성능이 부하 증가 시 저하됩니다. 회사는 고가용성을 유지하면서 예측하기 어려운 읽기 수요에 맞춰 데이터베이스 읽기 용량을 자동으로 확장해야 합니다. 따라서 읽기 복제본을 여러 가용 영역에 배치하고 수요에 따라 복제본 수를 자동 조절할 수 있는 관계형 데이터베이스 구성이 필요합니다.","awsServicesAnalysis":"Amazon Aurora는 MySQL 호환 관계형 데이터베이스 서비스이며, 클러스터 볼륨을 여러 가용 영역에 복제하여 고가용성을 제공합니다. Aurora 복제본은 읽기 전용 엔드포인트를 통해 읽기 트래픽을 분산할 수 있고, Aurora Auto Scaling은 지정한 지표에 따라 Aurora 복제본을 추가하거나 제거합니다. Amazon RDS Multi-AZ 배포의 대기 인스턴스는 장애 조치용이며 읽기 트래픽을 확장하는 용도가 아닙니다. Amazon Redshift는 분석 워크로드용 데이터 웨어하우스입니다. Amazon ElastiCache for Memcached는 인메모리 캐시 서비스로서 데이터베이스의 트랜잭션 데이터와 고가용 관계형 데이터베이스 기능을 대체하지 않습니다.","choicesAnalysis":"읽기 중심의 예측 불가능한 워크로드에는 읽기 전용 복제본을 자동으로 늘리고 줄일 수 있어야 하며, 동시에 데이터베이스 계층의 고가용성도 유지해야 합니다. Aurora는 이 요구사항에 맞는 복제본과 Auto Scaling 기능을 제공합니다. 단일 AZ RDS, 단일 노드 Redshift, 스팟 인스턴스 기반 캐시는 이 조건을 함께 충족하지 못합니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. Amazon Redshift는 대규모 분석을 위한 데이터 웨어하우스이며, 단일 노드 구성은 운영 데이터베이스의 고가용성과 자동 읽기 확장 요구사항을 충족하지 못합니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. 단일 AZ Amazon RDS 배포는 고가용성을 제공하지 않습니다. 또한 RDS Multi-AZ의 대기 인스턴스는 읽기 확장을 위한 리더 인스턴스로 사용할 수 없으므로 제시된 요구사항에 맞지 않습니다."},"C":{"isCorrect":true,"explanation":"적합합니다. Amazon Aurora Multi-AZ 클러스터는 고가용성을 제공하고, Aurora 복제본은 읽기 요청을 분산합니다. Aurora Auto Scaling은 수요에 맞춰 복제본 수를 자동 조절하므로 예측할 수 없는 읽기 워크로드를 처리할 수 있습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. Amazon ElastiCache for Memcached는 읽기 부하를 완화하는 캐시로 사용할 수 있지만, EC2 스팟 인스턴스는 Memcached 노드를 구성하는 방식이 아니며 데이터베이스의 고가용성과 자동 읽기 확장을 제공하지 않습니다."}}},{"id":"Q0015","question_number":15,"question":"최근에 AWS 로 마이그레이션한 회사가 프로덕션 VPC 로 들어오고 나가는 트래픽을 보호하는 솔루션을 구현하려고 합니다. 이 회사는 사내 데이터 센터에 검사 서버를 가지고 있었습니다. 검사 서버는 트래픽 흐름 검사 및 트래픽 필터링과 같은 특정 작업을 수행했습니다. 회사는 AWS 클라우드에서 동일한 기능을 갖기를 원합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"프로덕션 VPC 에서 트래픽 검사 및 트래픽 필터링에 Amazon GuardDuty 를 사용합니다.","B":"트래픽 미러링을 사용하여 트래픽 검사 및 필터링을 위해 프로덕션 VPC 의 트래픽을 미러링합니다.","C":"AWS 네트워크 방화벽을 사용하여 프로덕션 VPC 에 대한 트래픽 검사 및 트래픽 필터링에 필요한 규칙을 생성합니다.","D":"AWS Firewall Manager 를 사용하여 프로덕션 VPC 에 대한 트래픽 검사 및 트래픽 필터링에 필요한 규칙을 생성합니다."},"answers":["C"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["AWS Network Firewall"],"explanation":{"requirementsAnalysis":"회사는 프로덕션 VPC로 들어오고 나가는 트래픽을 검사하고 필터링해야 합니다. 온프레미스 환경에서 검사 서버가 수행하던 네트워크 보안 기능을 AWS에서 구현하려는 상황이므로, 양방향 네트워크 트래픽에 규칙을 적용하고 정책에 따라 허용 또는 차단할 수 있어야 합니다. 따라서 관리형 네트워크 방화벽 기능을 사용해 VPC 트래픽 경로에 검사와 필터링을 적용하는 것이 필요합니다.","awsServicesAnalysis":"AWS Network Firewall은 VPC에 배포하는 관리형 네트워크 방화벽 및 침입 방지 서비스입니다. 상태 저장 또는 상태 비저장 규칙과 도메인 기반 규칙을 사용해 네트워크 트래픽을 검사하고 필터링할 수 있습니다. Amazon GuardDuty는 로그와 이벤트를 분석하여 잠재적인 위협을 탐지하는 서비스이며, 트래픽을 인라인으로 차단하거나 필터링하지 않습니다. VPC Traffic Mirroring은 네트워크 인터페이스의 트래픽 사본을 분석 도구로 보내지만, 원래 트래픽 흐름을 필터링하지 않습니다. AWS Firewall Manager는 여러 계정과 리소스에 방화벽 정책을 중앙 배포하고 관리하는 서비스입니다.","choicesAnalysis":"요구사항은 위협을 탐지하거나 트래픽 사본을 분석하는 것이 아니라, 프로덕션 VPC의 실제 인바운드 및 아웃바운드 트래픽을 검사하고 규칙에 따라 필터링하는 것입니다. AWS Network Firewall은 이 기능을 직접 제공합니다. GuardDuty, Traffic Mirroring 및 Firewall Manager는 각각 탐지, 복제 또는 중앙 정책 관리 역할이므로 인라인 검사 엔진을 대체하지 않습니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. Amazon GuardDuty는 잠재적인 악의적 활동을 탐지하고 경고하지만, VPC 트래픽을 인라인으로 검사하여 규칙에 따라 허용하거나 차단하는 방화벽 기능은 제공하지 않습니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. VPC Traffic Mirroring은 패킷 사본을 보안 분석 도구로 전달하는 기능입니다. 원본 트래픽은 계속 흐르므로 트래픽 필터링을 수행하지 못합니다."},"C":{"isCorrect":true,"explanation":"적합합니다. AWS Network Firewall은 VPC 트래픽에 상태 저장 및 상태 비저장 규칙을 적용하여 검사와 필터링을 수행합니다. 이를 통해 온프레미스 검사 서버와 같은 네트워크 보안 기능을 관리형 서비스로 구현할 수 있습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Firewall Manager는 AWS WAF, AWS Network Firewall 등 보안 정책을 중앙에서 배포하고 관리하는 서비스입니다. 자체적으로 VPC 트래픽을 검사하고 필터링하는 방화벽 엔진은 아닙니다."}}},{"id":"Q0016","question_number":16,"question":"회사는 AWS 에서 데이터 레이크를 호스팅합니다. 데이터 레이크는 Amazon S3 및 PostgreSQL 용 Amazon RDS 의 데이터로 구성됩니다. 이 회사는 데이터 시각화를 제공하고 데이터 레이크 내의 모든 데이터 소스를 포함하는 보고 솔루션이 필요합니다. 회사의 관리 팀만 모든 시각화에 대한 전체 액세스 권한을 가져야 합니다. 나머지 회사는 제한된 액세스 권한만 가져야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"Amazon QuickSight 에서 분석을 생성합니다. 모든 데이터 소스를 연결하고 새 데이터 세트를 만듭니다. 대시보드를 게시하여 데이터를 시각화합니다. 적절한 IAM 역할과 대시보드를 공유합니다.","B":"Amazon QuickSight 에서 분석을 생성합니다. 모든 데이터 소스를 연결하고 새 데이터 세트를 만듭니다. 대시보드를 게시하여 데이터를 시각화합니다. 적절한 사용자 및 그룹과 대시보드를 공유합니다.","C":"Amazon S3 의 데이터에 대한 AWS Glue 테이블 및 크롤러를 생성합니다. AWS Glue 추출, 변환 및 로드(ETL) 작업을 생성하여 보고서를 생성합니다. 보고서를 Amazon S3 에 게시합니다. S3 버킷 정책을 사용하여 보고서에 대한 액세스를 제한합니다.","D":"Amazon S3 의 데이터에 대한 AWS Glue 테이블과 크롤러를 생성합니다. Amazon Athena 연합 쿼리를 사용하여 PostgreSQL 용 Amazon RDS 내의 데이터에 액세스합니다. Amazon Athena 를 사용하여 보고서를 생성합니다. 보고서를 Amazon S3 에 게시합니다. S3 버킷 정책을 사용하여 보고서에 대한 액세스를 제한합니다."},"answers":["B"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터 수집 및 변환 솔루션 결정","aws_services":["Amazon Quick","Amazon S3","Amazon RDS"],"explanation":{"requirementsAnalysis":"데이터 레이크는 Amazon S3와 PostgreSQL용 Amazon RDS의 데이터를 포함하며, 회사는 두 데이터 원본을 아우르는 시각화와 보고 기능이 필요합니다. 관리 팀은 모든 시각화에 완전한 액세스 권한을 가져야 하고, 다른 직원은 제한된 범위만 볼 수 있어야 합니다. 따라서 여러 데이터 원본을 연결해 대시보드를 만들고, 사용자와 그룹 단위로 대시보드 접근을 세분화할 수 있는 관리형 BI 서비스가 필요합니다.","awsServicesAnalysis":"Amazon QuickSight는 여러 데이터 원본을 연결해 데이터 세트, 분석 및 대시보드를 만드는 서버리스 BI 서비스입니다. QuickSight 대시보드는 사용자 및 그룹과 공유할 수 있으며, 사용자 또는 그룹에 따라 접근 권한을 관리할 수 있습니다. IAM 역할은 AWS 서비스가 AWS 리소스에 접근할 때 사용하는 권한 위임 방식으로, QuickSight 최종 사용자에게 대시보드를 공유하는 주체가 아닙니다. AWS Glue는 데이터 카탈로그와 ETL 작업을 제공하고, Amazon Athena는 S3 데이터를 SQL로 분석하거나 연합 쿼리를 통해 지원되는 외부 데이터 원본을 조회할 수 있습니다. Amazon S3 버킷 정책은 S3 객체에 대한 접근을 제어합니다.","choicesAnalysis":"이 문제는 여러 데이터 원본의 보고서를 생성하는 기능뿐 아니라, 관리 팀과 일반 직원에게 서로 다른 대시보드 접근 권한을 제공해야 합니다. Amazon QuickSight는 데이터 원본 연결, 시각화, 대시보드 게시, 사용자 및 그룹별 공유를 하나의 서비스에서 지원합니다. S3에 정적 보고서를 게시하는 방식은 대화형 시각화와 세분화된 BI 사용자 공유 요구사항을 직접 충족하지 못합니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. Amazon QuickSight로 분석과 대시보드를 만들 수는 있지만, 대시보드 공유는 적절한 QuickSight 사용자 및 그룹을 대상으로 수행합니다. IAM 역할은 최종 사용자에게 대시보드 접근을 부여하는 공유 방식이 아닙니다."},"B":{"isCorrect":true,"explanation":"적합합니다. Amazon QuickSight는 Amazon S3와 Amazon RDS를 데이터 원본으로 연결하여 대시보드를 만들 수 있습니다. 관리 팀과 일반 직원을 서로 다른 사용자 및 그룹으로 구성해 대시보드 접근 권한을 구분할 수 있습니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Glue ETL 작업과 Amazon S3 보고서는 데이터 처리와 파일 배포에는 사용할 수 있지만, 여러 사용자와 그룹에 대화형 시각화를 세분화해 제공하는 관리형 BI 기능을 제공하지 않습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Glue와 Amazon Athena 연합 쿼리로 데이터를 조회하고 보고서 파일을 만들 수는 있지만, Amazon S3 버킷 정책만으로는 관리 팀과 다른 직원에게 대화형 시각화의 전체 및 제한된 접근을 효과적으로 제공할 수 없습니다."}}},{"id":"Q0017","question_number":17,"question":"회사에서 새로운 비즈니스 애플리케이션을 구현하고 있습니다. 이 애플리케이션은 두 개의 Amazon EC2 인스턴스에서 실행되며 문서 저장을 위해 Amazon S3 버킷을 사용합니다. 솔루션 설계자는 EC2 인스턴스가 S3 버킷에 액세스할 수 있는지 확인해야 합니다. 솔루션 설계자는 이 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"S3 버킷에 대한 액세스 권한을 부여하는 IAM 역할을 생성합니다. 역할을 EC2 인스턴스에 연결합니다.","B":"S3 버킷에 대한 액세스 권한을 부여하는 IAM 정책을 생성합니다. 정책을 EC2 인스턴스에 연결합니다.","C":"S3 버킷에 대한 액세스 권한을 부여하는 IAM 그룹을 생성합니다. 그룹을 EC2 인스턴스에 연결합니다.","D":"S3 버킷에 대한 액세스 권한을 부여하는 IAM 사용자를 생성합니다. 사용자 계정을 EC2 인스턴스에 연결합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"AWS 리소스에 대한 보안 액세스 설계","aws_services":["IAM","Amazon EC2","Amazon S3"],"explanation":{"requirementsAnalysis":"두 Amazon EC2 인스턴스에서 실행되는 애플리케이션이 Amazon S3 버킷의 문서에 접근해야 합니다. 장기 액세스 키를 인스턴스에 저장하지 않고, EC2 워크로드에 필요한 최소 권한을 부여할 수 있어야 합니다. 따라서 인스턴스가 임시 자격 증명을 받아 S3 접근 권한을 사용할 수 있도록 AWS IAM의 워크로드 권한 위임 방식을 구성해야 합니다.","awsServicesAnalysis":"AWS IAM 역할은 신뢰할 수 있는 주체가 역할을 수임해 임시 보안 자격 증명을 받도록 하는 권한 위임 기능입니다. EC2 인스턴스 프로파일을 통해 IAM 역할을 인스턴스에 연결하면, 인스턴스의 애플리케이션은 역할 정책에 부여된 Amazon S3 권한을 사용할 수 있습니다. IAM 정책은 권한을 정의하는 문서이며 EC2 인스턴스 자체에 직접 연결하는 리소스가 아닙니다. IAM 그룹은 IAM 사용자를 관리하기 위한 집합이고, IAM 사용자는 장기 자격 증명을 발급받을 수 있는 사람 또는 워크로드 주체입니다.","choicesAnalysis":"EC2 인스턴스에 AWS 리소스 접근 권한을 부여하는 표준 방식은 필요한 권한 정책을 포함한 IAM 역할을 인스턴스 프로파일로 연결하는 것입니다. 정책은 역할에 연결해 권한을 정의하지만 인스턴스에 직접 연결하지 않으며, 그룹과 사용자는 EC2 워크로드에 권한을 위임하는 방식이 아닙니다. 따라서 S3 접근 권한이 있는 IAM 역할을 EC2 인스턴스에 연결하는 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"적합합니다. S3 버킷 접근을 허용하는 IAM 정책을 IAM 역할에 연결하고, 해당 역할을 EC2 인스턴스 프로파일로 인스턴스에 연결할 수 있습니다. 애플리케이션은 임시 자격 증명을 사용하므로 액세스 키를 인스턴스에 저장할 필요가 없습니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. IAM 정책은 권한을 정의하는 문서이며 Amazon EC2 인스턴스에 직접 연결할 수 없습니다. 정책을 IAM 역할에 연결한 후 역할을 인스턴스 프로파일로 연결해야 합니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. IAM 그룹은 IAM 사용자를 묶어 공통 권한을 관리하는 기능입니다. EC2 인스턴스는 IAM 그룹에 연결할 수 없으며, 워크로드 권한 위임에는 IAM 역할을 사용해야 합니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. IAM 사용자는 장기 자격 증명을 사용할 수 있어 키 관리와 노출 위험이 커집니다. 또한 사용자 계정을 EC2 인스턴스에 연결하는 방식은 인스턴스 워크로드에 권한을 부여하는 표준 구성이 아닙니다."}}},{"id":"Q0018","question_number":18,"question":"애플리케이션 개발 팀은 큰 이미지를 더 작은 압축 이미지로 변환하는 마이크로서비스를 설계하고 있습니다. 사용자가 웹 인터페이스를 통해 이미지를 업로드하면 마이크로 서비스는 이미지를 Amazon S3 버킷에 저장하고, AWS Lambda 함수로 이미지를 처리 및 압축하고, 다른 S3 버킷에 압축된 형태로 이미지를 저장해야 합니다. 솔루션 설계자는 내구성이 있는 상태 비저장 구성 요소를 사용하여 이미지를 자동으로 처리하는 솔루션을 설계해야 합니다. 이러한 요구 사항을 충족하는 작업 조합은 무엇입니까? (2 개를 선택하세요.)","choices":{"A":"Amazon Simple Queue Service(Amazon SQS) 대기열을 생성합니다. 이미지가 S3 버킷에 업로드될 때 SQS 대기열에 알림을 보내도록 S3 버킷을 구성합니다.","B":"Amazon Simple Queue Service(Amazon SQS) 대기열을 호출 소스로 사용하도록 Lambda 함수를 구성합니다. SQS 메시지가 성공적으로 처리되면 대기열에서 메시지를 삭제합니다.","C":"새 업로드에 대해 S3 버킷을 모니터링하도록 Lambda 함수를 구성합니다. 업로드된 이미지가 감지되면 메모리의 텍스트 파일에 파일 이름을 쓰고 텍스트 파일을 사용하여 처리된 이미지를 추적합니다.","D":"Amazon EC2 인스턴스를 시작하여 Amazon Simple Queue Service(Amazon SQS) 대기열을 모니터링합니다. 항목이 대기열에 추가되면 EC2 인스턴스의 텍스트 파일에 파일 이름을 기록하고 Lambda 함수를 호출합니다.","E":"Amazon EventBridge(Amazon CloudWatch Events) 이벤트를 구성하여 S3 버킷을 모니터링합니다. 이미지가 업로드되면 추가 처리를 위해 애플리케이션 소유자의 이메일 주소와 함께 Amazon ample Notification Service(Amazon SNS) 주제에 알림을 보냅니다."},"answers":["A","B"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon S3","Amazon SQS","AWS Lambda"],"explanation":{"requirementsAnalysis":"사용자가 업로드한 큰 이미지는 Amazon S3에 저장된 뒤 AWS Lambda로 비동기 처리되어 다른 S3 버킷에 압축본으로 저장되어야 합니다. 처리 구성 요소는 상태 비저장이면서 내구성이 있어야 하므로, 업로드 이벤트와 처리 작업을 분리하고 일시적인 처리 실패에도 메시지를 보존할 수 있어야 합니다. 따라서 S3 이벤트를 내구성 있는 대기열로 전달하고 Lambda가 대기열을 이벤트 소스로 소비하는 구조가 필요합니다.","awsServicesAnalysis":"Amazon S3 이벤트 알림은 객체 생성 같은 이벤트를 Amazon SQS 대기열, Amazon SNS 주제, AWS Lambda 또는 Amazon EventBridge로 전달할 수 있습니다. Amazon SQS는 메시지를 내구성 있게 저장해 생산자와 소비자를 분리하며, Lambda는 SQS를 이벤트 소스 매핑으로 사용해 메시지 배치를 처리할 수 있습니다. Lambda가 성공적으로 처리한 메시지는 Lambda와 SQS의 통합 동작에 따라 대기열에서 삭제됩니다. Lambda 함수의 메모리는 호출 간 지속 상태 저장소가 아니며, Amazon EC2 인스턴스의 로컬 텍스트 파일도 내구성 있는 분산 작업 상태 저장소가 아닙니다. Amazon SNS는 메시지 배포 서비스이지만 이메일 알림만으로 이미지 처리 작업을 안정적으로 전달하고 실행하지는 않습니다.","choicesAnalysis":"내구성과 상태 비저장 처리를 함께 만족하려면 업로드 이벤트를 SQS에 저장해 처리 작업을 버퍼링하고, Lambda가 SQS 이벤트를 소비해 이미지를 처리해야 합니다. 이 조합은 처리량 변동과 일시적 실패를 분리해 다룰 수 있으며 별도의 서버 상태에 의존하지 않습니다. 로컬 파일 추적, EC2 폴링, 이메일 알림은 내구성 있는 자동 이미지 처리 경로를 제공하지 않습니다. 따라서 A와 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"적합합니다. S3 객체 생성 이벤트를 Amazon SQS 대기열로 전달하면 업로드와 이미지 처리 작업을 분리하고 이벤트를 내구성 있게 보관할 수 있습니다. Lambda가 처리할 작업을 안정적으로 전달하는 기반이 됩니다."},"B":{"isCorrect":true,"explanation":"적합합니다. Lambda를 Amazon SQS의 이벤트 소스로 구성하면 대기열 메시지에 따라 함수를 자동 호출할 수 있습니다. 이미지 처리가 성공하면 메시지가 삭제되므로 재처리와 실패 처리를 SQS/Lambda 통합 방식으로 관리할 수 있습니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. Lambda 함수가 S3 버킷을 지속적으로 모니터링하는 방식은 이벤트 기반 설계가 아니며, 함수 메모리에 저장한 파일 이름은 호출 간에 지속되지 않습니다. 따라서 내구성 있는 처리 상태를 제공하지 못합니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. EC2 인스턴스가 SQS를 폴링하고 로컬 텍스트 파일로 상태를 관리하면 서버 운영과 상태 관리가 필요합니다. 인스턴스 로컬 파일은 내구성 있는 상태 저장소도 아니므로 상태 비저장 요구사항에 맞지 않습니다."},"E":{"isCorrect":false,"explanation":"적합하지 않습니다. EventBridge로 S3 이벤트를 수신할 수는 있지만, 이메일 주소와 Amazon SNS 주제에 알리는 구성만으로는 Lambda 이미지 처리 작업을 내구성 있게 큐잉하고 실행하지 않습니다."}}},{"id":"Q0019","question_number":19,"question":"회사에 AWS 에 배포된 3 계층 웹 애플리케이션이 있습니다. 웹 서버는 VPC 의 퍼블릭 서브넷에 배포됩니다. 애플리케이션 서버와 데이터베이스 서버는 동일한 VPC 의 프라이빗 서브넷에 배포됩니다. 이 회사는 AWS Marketplace 의 타사 가상 방화벽 어플라이언스를 검사 VPC 에 배포했습니다. 어플라이언스는 IP 패킷을 수락할 수 있는 IP 인터페이스로 구성됩니다. 솔루션 설계자는 트래픽이 웹 서버에 도달하기 전에 애플리케이션에 대한 모든 트래픽을 검사하기 위해 웹 애플리케이션을 어플라이언스와 통합해야 합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"애플리케이션 VPC 의 퍼블릭 서브넷에 Network Load Balancer 를 생성하여 패킷 검사를 위해 어플라이언스로 트래픽을 라우팅합니다.","B":"애플리케이션 VPC 의 퍼블릭 서브넷에 Application Load Balancer 를 생성하여 패킷 검사를 위해 어플라이언스로 트래픽을 라우팅합니다.","C":"전송 게이트웨이를 통해 들어오는 패킷을 라우팅하도록 라우팅 테이블을 구성하는 검사 VPC 에 전송 게이트웨이를 배포합니다.","D":"검사 VPC 에 게이트웨이 로드 밸런서를 배포합니다. 게이트웨이 로드 밸런서 엔드포인트를 생성하여 수신 패킷을 수신하고 패킷을 어플라이언스로 전달합니다."},"answers":["D"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["Elastic Load Balancing(ELB)","Amazon VPC"],"explanation":{"requirementsAnalysis":"웹 서버가 있는 애플리케이션 VPC로 들어오는 모든 트래픽은 웹 서버에 도달하기 전에 별도의 검사 VPC에 배포된 타사 가상 방화벽 어플라이언스를 통과해야 합니다. 어플라이언스는 IP 패킷을 처리하는 인터페이스를 제공하므로, 트래픽을 투명하게 가로채 여러 어플라이언스로 분산하고 흐름 대칭성을 유지할 수 있어야 합니다. 또한 별도의 프록시나 자체 라우팅 관리 부담을 최소화하는 것이 필요합니다.","awsServicesAnalysis":"Gateway Load Balancer는 타사 가상 어플라이언스를 배포, 확장 및 관리하기 위한 로드 밸런서입니다. GENEVE 프로토콜을 사용해 IP 트래픽을 어플라이언스에 투명하게 전달하며, Gateway Load Balancer 엔드포인트를 VPC 라우팅 테이블의 다음 홉으로 사용할 수 있습니다. Network Load Balancer는 L4 연결을 대상으로 하고, Application Load Balancer는 HTTP 및 HTTPS 요청을 대상으로 합니다. 두 서비스는 인라인 네트워크 보안 어플라이언스에 대한 투명한 패킷 서비스 체이닝을 제공하는 Gateway Load Balancer의 역할을 대체하지 않습니다. AWS Transit Gateway는 VPC와 온프레미스 네트워크를 연결하는 라우팅 허브이지만, 자체적으로 어플라이언스 트래픽을 로드 밸런싱하거나 검사하지 않습니다.","choicesAnalysis":"이 환경에는 웹 트래픽이 방화벽 어플라이언스를 우회하지 않도록 라우팅 경로에 투명하게 삽입하고, IP 패킷을 여러 어플라이언스에 전달하는 기능이 필요합니다. Gateway Load Balancer와 그 엔드포인트는 이러한 서비스 삽입을 위해 설계된 관리형 구성입니다. 일반 L4/L7 로드 밸런서나 Transit Gateway만으로는 어플라이언스 검사 경로를 동일하게 구현할 수 없습니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. Network Load Balancer는 L4 연결을 로드 밸런싱하지만, 애플리케이션 VPC 트래픽을 검사 VPC의 가상 방화벽 어플라이언스로 투명하게 서비스 체이닝하는 Gateway Load Balancer 기능을 제공하지 않습니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. Application Load Balancer는 HTTP 및 HTTPS 애플리케이션 요청을 처리하는 L7 로드 밸런서입니다. 모든 IP 패킷을 가상 방화벽 어플라이언스에 투명하게 전달하는 용도에는 맞지 않습니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Transit Gateway는 네트워크 간 연결과 라우팅을 제공하지만, 패킷을 가상 방화벽 어플라이언스에 로드 밸런싱하고 서비스 체이닝하는 기능은 제공하지 않습니다."},"D":{"isCorrect":true,"explanation":"적합합니다. 검사 VPC의 Gateway Load Balancer와 애플리케이션 VPC의 Gateway Load Balancer 엔드포인트를 사용하면 수신 트래픽을 방화벽 어플라이언스로 투명하게 전달할 수 있습니다. 라우팅을 통해 검사 경로를 강제하면서 어플라이언스의 확장과 가용성도 관리형으로 처리할 수 있습니다."}}},{"id":"Q0020","question_number":20,"question":"회사에서 동일한 AWS 리전의 테스트 환경에 대량의 프로덕션 데이터를 복제하는 기능을 개선하려고 합니다. 데이터는 Amazon Elastic Block Store(Amazon EBS) 볼륨의 Amazon EC2 인스턴스에 저장됩니다. 복제된 데이터를 수정해도 프로덕션 환경에 영향을 주지 않아야 합니다. 이 데이터에 액세스하는 소프트웨어는 일관되게 높은 I/O 성능을 요구합니다. 솔루션 설계자는 프로덕션 데이터를 테스트 환경에 복제하는 데 필요한 시간을 최소화해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"프로덕션 EBS 볼륨의 EBS 스냅샷을 만듭니다. 테스트 환경의 EC2 인스턴스 스토어 볼륨에 스냅샷을 복원합니다.","B":"EBS 다중 연결 기능을 사용하도록 프로덕션 EBS 볼륨을 구성합니다. 프로덕션 EBS 볼륨의 EBS 스냅샷을 만듭니다. 테스트 환경의 EC2 인스턴스에 프로덕션 EBS 볼륨을 연결합니다.","C":"프로덕션 EBS 볼륨의 EBS 스냅샷을 만듭니다. 새 EBS 볼륨을 생성하고 초기화합니다. 프로덕션 EBS 스냅샷에서 볼륨을 복원하기 전에 테스트 환경의 EC2 인스턴스에 새 EBS 볼륨을 연결합니다.","D":"프로덕션 EBS 볼륨의 EBS 스냅샷을 만듭니다. EBS 스냅샷에서 EBS 빠른 스냅샷 복원 기능을 켭니다. 스냅샷을 새 EBS 볼륨으로 복원합니다. 테스트 환경의 EC2 인스턴스에 새 EBS 볼륨을 연결합니다."},"answers":["D"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 스토리지 솔루션 결정","aws_services":["Amazon EBS"],"explanation":{"requirementsAnalysis":"회사는 같은 AWS 리전에 있는 테스트 환경에서 대량의 프로덕션 EBS 데이터를 빠르게 복제해야 합니다. 테스트 데이터는 프로덕션과 독립적이어야 하므로 별도 볼륨에서 수정할 수 있어야 하며, 이 데이터를 사용하는 소프트웨어는 일관되게 높은 I/O 성능을 요구합니다. 따라서 스냅샷 기반의 독립 볼륨을 만들되, 스냅샷에서 복원된 블록을 처음 읽을 때 발생할 수 있는 지연을 줄여 복제 후 즉시 높은 성능을 제공해야 합니다.","awsServicesAnalysis":"Amazon EBS 스냅샷은 EBS 볼륨의 특정 시점 데이터를 백업하며, 스냅샷에서 새 EBS 볼륨을 생성하면 원본과 독립된 볼륨을 얻을 수 있습니다. 일반 스냅샷에서 생성한 볼륨은 블록을 처음 읽을 때 Amazon S3에서 데이터를 가져오는 초기화 지연이 발생할 수 있습니다. EBS Fast Snapshot Restore는 지정한 가용 영역에서 스냅샷 블록을 미리 초기화하여, 해당 스냅샷으로 생성한 볼륨이 생성 직후 완전한 성능을 제공하도록 합니다. EC2 인스턴스 스토어는 스냅샷에서 복원하는 EBS 볼륨 대상이 아니며 인스턴스 수명에 종속됩니다. EBS Multi-Attach는 지원되는 io1/io2 볼륨을 같은 가용 영역의 여러 인스턴스에 연결하는 기능으로, 독립된 테스트 복제본을 만드는 기능이 아닙니다.","choicesAnalysis":"테스트 환경이 프로덕션에 영향을 주지 않으려면 프로덕션 볼륨을 테스트 인스턴스와 공유하는 대신 스냅샷에서 독립된 새 EBS 볼륨을 만들어야 합니다. 또한 일관되게 높은 I/O 성능과 빠른 준비 시간을 위해서는 스냅샷 블록 초기화 지연을 제거해야 합니다. EBS Fast Snapshot Restore는 이 목적을 직접 지원하며, 인스턴스 스토어와 Multi-Attach는 요구사항에 맞지 않습니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. EBS 스냅샷을 EC2 인스턴스 스토어 볼륨에 복원할 수 없습니다. 또한 인스턴스 스토어는 인스턴스에 종속되는 임시 블록 스토리지이므로 독립적인 테스트 데이터 복제 요구사항에 맞지 않습니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. EBS Multi-Attach는 지원되는 EBS 볼륨을 여러 인스턴스에 연결하는 기능일 뿐, 프로덕션 데이터를 수정 가능한 독립 테스트 복제본으로 만들지 않습니다. 같은 볼륨을 공유하면 테스트 변경이 프로덕션 데이터에 영향을 줄 수 있습니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. 스냅샷에서 새 EBS 볼륨을 만들면 독립성은 확보할 수 있지만, Fast Snapshot Restore 또는 사전 초기화가 없으면 최초 블록 읽기 시 초기화 지연이 발생할 수 있습니다. 따라서 빠른 복제와 일관된 높은 I/O 성능 요구사항을 완전히 충족하지 못합니다."},"D":{"isCorrect":true,"explanation":"적합합니다. 프로덕션 EBS 볼륨의 스냅샷에서 새 볼륨을 만들면 테스트 환경은 프로덕션과 독립적으로 데이터를 수정할 수 있습니다. EBS Fast Snapshot Restore를 활성화하면 스냅샷 블록이 미리 초기화되어 새 볼륨이 생성 직후 일관된 높은 I/O 성능을 제공할 수 있습니다."}}},{"id":"Q0021","question_number":21,"question":"전자 상거래 회사는 AWS 에서 하루 1 회 웹 사이트를 시작하려고 합니다. 매일 24 시간 동안 정확히 하나의 제품을 판매합니다. 회사는 피크 시간 동안 밀리초 지연 시간으로 시간당 수백만 개의 요청을 처리할 수 있기를 원합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"Amazon S3 를 사용하여 다른 S3 버킷에 전체 웹 사이트를 호스팅합니다. Amazon CloudFront 배포를 추가합니다. S3 버킷을 배포의 오리진으로 설정합니다. Amazon S3 에 주문 데이터를 저장합니다.","B":"여러 가용 영역의 Auto Scaling 그룹에서 실행되는 Amazon EC2 인스턴스에 전체 웹 사이트를 배포합니다. ALB(Application Load Balancer)를 추가하여 웹 사이트 트래픽을 분산합니다. 백엔드 API 에 대해 다른 ALB 를 추가하십시오. MySQL 용 Amazon RDS 에 데이터를 저장합니다.","C":"컨테이너에서 실행되도록 전체 애플리케이션을 마이그레이션합니다. Amazon Elastic Kubernetes Service(Amazon EKS)에서 컨테이너를 호스팅합니다. Kubernetes 클러스터 자동 확장 처리를 사용하여 트래픽 버스트를 처리할 포드 수를 늘리거나 줄입니다. MySQL 용 Amazon RDS 에 데이터를 저장합니다.","D":"Amazon S3 버킷을 사용하여 웹 사이트의 정적 콘텐츠를 호스팅합니다. Amazon CloudFront 배포를 배포합니다. S3 버킷을 오리진으로 설정합니다. 백엔드 API 에 Amazon API Gateway 및 AWS Lambda 함수를 사용합니다. Amazon DynamoDB 에 데이터를 저장합니다."},"answers":["D"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능의 탄력적인 컴퓨팅 솔루션 설계","aws_services":["Amazon S3","Amazon CloudFront","Amazon API Gateway","AWS Lambda","Amazon DynamoDB"],"explanation":{"requirementsAnalysis":"회사는 하루에 하나의 제품을 24시간 동안 판매하는 웹 사이트를 운영하면서 피크 시간에는 시간당 수백만 건의 요청을 밀리초 지연 시간으로 처리해야 합니다. 정적 웹 콘텐츠는 전 세계 사용자에게 빠르게 제공되어야 하며, 주문 처리와 데이터 저장은 급격한 트래픽 증가에 맞춰 확장되어야 합니다. 또한 매일 반복되는 대규모 트래픽을 위해 서버와 데이터베이스 용량을 직접 계획하거나 운영하는 부담을 최소화해야 합니다. 따라서 정적 콘텐츠의 엣지 전송, 서버리스 요청 처리, 고확장성 데이터 저장을 함께 제공하는 구성이 필요합니다.","awsServicesAnalysis":"Amazon S3는 정적 웹 사이트 콘텐츠를 저장할 수 있고, Amazon CloudFront는 엣지 로케이션에서 콘텐츠를 캐시하여 사용자에게 낮은 지연 시간으로 제공합니다. Amazon API Gateway는 HTTP API의 수신과 관리 기능을 제공하며 AWS Lambda는 요청에 따라 코드를 실행하고 동시 실행 수요에 맞춰 확장됩니다. Amazon DynamoDB는 서버리스 NoSQL 데이터베이스로 짧은 지연 시간의 대규모 워크로드에 맞게 처리 용량을 확장할 수 있습니다. Amazon EC2 Auto Scaling, Application Load Balancer, Amazon EKS 및 Amazon RDS도 확장 가능한 웹 애플리케이션에 사용할 수 있지만, 인스턴스/클러스터 또는 관계형 데이터베이스 용량에 관한 운영 결정을 요구합니다.","choicesAnalysis":"대량의 전 세계 웹 요청을 처리하면서 운영 부담을 최소화하려면 정적 콘텐츠와 동적 주문 처리를 분리하고 각 계층이 독립적으로 확장되어야 합니다. CDN을 통한 정적 콘텐츠 제공만으로는 주문을 처리하고 저장할 수 없으며, EC2나 Kubernetes 기반 구성은 필요한 기능을 제공할 수 있어도 관리 대상이 늘어납니다. 서버리스 API와 컴퓨팅, 자동 확장되는 데이터 저장소를 조합하면 짧은 지연 시간과 탄력성을 함께 달성할 수 있습니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. S3와 CloudFront는 정적 콘텐츠를 빠르게 제공할 수 있지만, 주문을 처리할 동적 백엔드가 없습니다. 또한 S3 객체 저장소를 주문 데이터의 트랜잭션 처리 저장소로 사용하는 구성은 요구사항에 맞지 않습니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. 다중 AZ의 EC2 Auto Scaling 그룹과 ALB는 확장할 수 있지만, 인스턴스와 RDS 용량을 운영해야 합니다. 최소 운영 오버헤드 조건에서는 서버리스 구성보다 부담이 큽니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. EKS의 오토스케일링은 트래픽을 처리할 수 있지만 Kubernetes 클러스터와 컨테이너 워크로드를 관리해야 합니다. 이 운영 부담은 요구사항의 최소화 조건에 부합하지 않습니다."},"D":{"isCorrect":true,"explanation":"적합합니다. S3와 CloudFront가 정적 콘텐츠를 전 세계에 낮은 지연 시간으로 제공하고, API Gateway와 Lambda가 주문 요청을 서버리스 방식으로 처리합니다. DynamoDB는 대규모 요청에 맞춰 확장할 수 있으므로 성능과 운영 단순성 요구사항을 충족합니다."}}},{"id":"Q0022","question_number":22,"question":"솔루션 설계자는 Amazon S3 를 사용하여 새로운 디지털 미디어 애플리케이션의 스토리지 아키텍처를 설계하고 있습니다. 미디어 파일은 가용 영역 손실에 대한 복원력이 있어야 합니다. 일부 파일은 자주 액세스되는 반면 다른 파일은 예측할 수 없는 패턴으로 거의 액세스되지 않습니다. 솔루션 설계자는 미디어 파일을 저장하고 검색하는 비용을 최소화해야 합니다. 이러한 요구 사항을 충족하는 스토리지 옵션은 무엇입니까?","choices":{"A":"S3 Standard (S3 표준)","B":"S3 Intelligent-Tiering (S3 지능형 계층화)","C":"S3 Standard-Infrequent Access(S3 Standard-IA)","D":"S3 One Zone-Infrequent Access(S3 One Zone-IA)"},"answers":["B"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 스토리지 솔루션 설계","aws_services":["Amazon S3"],"explanation":{"requirementsAnalysis":"미디어 파일은 가용 영역 손실에도 복원력을 가져야 하므로 여러 가용 영역에 데이터를 저장하는 스토리지 클래스가 필요합니다. 파일의 일부는 자주 액세스되지만 다른 일부는 액세스 빈도를 예측하기 어렵고 드물게 사용됩니다. 따라서 두 유형의 파일을 모두 수용하면서 액세스 패턴 변화에 따른 스토리지 비용과 검색 비용을 최소화해야 합니다. 예측 불가능한 사용 패턴에 맞춰 자동으로 계층을 조정하는지가 핵심 판단 기준입니다.","awsServicesAnalysis":"S3 Standard는 여러 가용 영역에 데이터를 저장하며 자주 액세스하는 데이터에 적합합니다. S3 Standard-IA도 여러 가용 영역에 저장되지만 장기간 드물게 액세스하는 데이터를 위한 클래스이며 검색 요금이 부과됩니다. S3 Intelligent-Tiering은 객체별 액세스 패턴을 모니터링하여 빈번한 액세스, 드문 액세스 및 아카이브 계층 사이에서 자동으로 이동시켜 비용을 최적화합니다. S3 One Zone-IA는 단일 가용 영역에 저장되므로 가용 영역 손실에 대한 복원력을 제공하지 않습니다.","choicesAnalysis":"여러 가용 영역에 대한 복원력은 반드시 충족해야 하므로 단일 가용 영역 클래스는 제외됩니다. 모든 데이터를 자주 액세스하는 클래스로 저장하면 드물게 사용되는 파일의 비용을 줄이지 못하고, 정해진 IA 클래스를 일괄 적용하면 자주 액세스되는 파일에서 검색 비용이 발생할 수 있습니다. 액세스 패턴이 예측되지 않는 파일을 객체 단위로 자동 계층화하는 방식이 비용을 가장 잘 최적화합니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. S3 Standard는 여러 가용 영역에 저장되어 복원력은 충족하지만, 드물게 액세스되는 파일에도 빈번한 액세스용 비용이 적용됩니다. 예측하기 어려운 접근 패턴에 따른 비용 최적화가 부족합니다."},"B":{"isCorrect":true,"explanation":"적합합니다. S3 Intelligent-Tiering은 여러 가용 영역에 데이터를 저장하고 객체별 액세스 패턴에 따라 적절한 비용 계층으로 자동 이동합니다. 자주 또는 예측하기 어렵게 액세스되는 파일을 함께 저장하면서 스토리지와 검색 비용을 최소화할 수 있습니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. S3 Standard-IA는 여러 가용 영역 복원력을 제공하지만, 자주 액세스되는 파일에는 검색 요금이 발생합니다. 파일별로 달라지는 접근 패턴을 자동으로 최적화하지도 않습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. S3 One Zone-IA는 비용은 낮지만 데이터를 단일 가용 영역에 저장합니다. 따라서 가용 영역 손실에 대한 복원력 요구사항을 충족하지 못합니다."}}},{"id":"Q0023","question_number":23,"question":"회사에서 Amazon S3 Standard 스토리지를 사용하여 백업 파일을 저장하고 있습니다. 1 개월 동안 파일에 자주 액세스합니다. 단, 1 개월 이후에는 파일에 접근하지 않습니다. 회사는 파일을 무기한 보관해야 합니다. 이러한 요구 사항을 가장 비용 효율적으로 충족하는 스토리지 솔루션은 무엇입니까?","choices":{"A":"객체를 자동으로 마이그레이션하도록 S3 Intelligent-Tiering 을 구성합니다.","B":"S3 수명 주기 구성을 생성하여 1 개월 후에 S3 Standard 에서 S3 Glacier Deep Archive 로 객체를 전환합니다.","C":"S3 수명 주기 구성을 생성하여 1 개월 후에 객체를 S3 Standard 에서 S3 Standard-Infrequent Access(S3 Standard-IA)로 전환합니다.","D":"S3 수명 주기 구성을 생성하여 1 개월 후에 객체를 S3 Standard 에서 S3 One Zone-Infrequent Access(S3 One Zone-IA)로 전환합니다."},"answers":["B"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 스토리지 솔루션 설계","aws_services":["Amazon S3","Amazon S3 Glacier"],"explanation":{"requirementsAnalysis":"회사는 백업 파일을 처음 1개월 동안에는 자주 읽고, 그 이후에는 접근하지 않지만 무기한 보존해야 합니다. 따라서 최초 1개월에는 즉시 접근 가능한 스토리지에서 파일을 유지하고, 이후에는 장기 보관 비용을 가장 낮출 수 있는 계층으로 자동 전환해야 합니다. 삭제가 아니라 보존이 요구되므로 수명 주기 규칙은 만료가 아닌 스토리지 클래스 전환을 수행해야 합니다. 알려진 접근 시점 이후의 장기 아카이브 비용이 핵심 판단 기준입니다.","awsServicesAnalysis":"S3 수명 주기 구성은 객체의 생성 후 경과 일수에 따라 스토리지 클래스를 전환할 수 있습니다. S3 Glacier Deep Archive는 장기간 거의 접근하지 않는 데이터를 위한 가장 저렴한 S3 아카이브 계층 중 하나이며, 객체를 읽으려면 복원 요청과 긴 검색 시간이 필요합니다. S3 Intelligent-Tiering은 변하는 접근 패턴을 자동으로 계층화하지만 객체 모니터링/자동화 요금이 있습니다. S3 Standard-IA와 S3 One Zone-IA는 밀리초 검색이 가능한 드문 액세스용 클래스이며, One Zone-IA는 단일 가용 영역에 데이터를 저장합니다.","choicesAnalysis":"접근 패턴과 전환 시점이 명확하므로 자동 패턴 분석보다 1개월 후의 명시적 수명 주기 전환이 적합합니다. 파일을 무기한 보관하면서 이후 접근하지 않는 조건에서는 즉시 검색 가능한 IA 계층보다 장기 아카이브 계층이 더 비용 효율적입니다. 또한 백업 파일은 내구성 있게 보존되어야 하므로 단일 가용 영역 저장소를 선택할 이유가 없습니다. 따라서 S3 Glacier Deep Archive로 전환하는 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. S3 Intelligent-Tiering은 액세스 패턴을 알 수 없을 때 유용하지만, 이 경우에는 1개월 후 접근하지 않는다는 정책이 명확합니다. 장기 보관만을 위해서는 명시적으로 Deep Archive로 전환하는 방식이 더 비용 효율적입니다."},"B":{"isCorrect":true,"explanation":"적합합니다. S3 수명 주기 규칙으로 처음 1개월은 S3 Standard에서 자주 접근하고, 이후에는 S3 Glacier Deep Archive에 무기한 보관할 수 있습니다. 알려진 장기 미접근 기간의 스토리지 비용을 최소화하는 구성입니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. S3 Standard-IA는 드물지만 즉시 접근해야 하는 데이터를 위한 계층입니다. 1개월 이후 접근하지 않는 파일을 무기한 보관하는 요구사항에는 S3 Glacier Deep Archive보다 스토리지 비용이 높습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. S3 One Zone-IA는 단일 가용 영역에 데이터를 저장하므로 장기 백업 보존에 적절하지 않습니다. 또한 장기 미접근 데이터의 비용 측면에서도 S3 Glacier Deep Archive보다 유리하지 않습니다."}}},{"id":"Q0024","question_number":24,"question":"회사는 가장 최근 청구서에서 Amazon EC2 비용 증가를 관찰했습니다. 청구 팀은 몇 개의 EC2 인스턴스에 대한 인스턴스 유형의 원치 않는 수직적 확장을 발견했습니다. 솔루션 설계자는 지난 2 개월간의 EC2 비용을 비교하는 그래프를 생성하고 심층 분석을 수행하여 수직적 확장의 근본 원인을 식별해야 합니다. 솔루션 설계자는 운영 오버헤드가 가장 적은 정보를 어떻게 생성해야 합니까?","choices":{"A":"AWS 예산을 사용하여 예산 보고서를 생성하고 인스턴스 유형에 따라 EC2 비용을 비교합니다.","B":"Cost Explorer 의 세분화된 필터링 기능을 사용하여 인스턴스 유형을 기반으로 EC2 비용에 대한 심층 분석을 수행합니다.","C":"AWS Billing and Cost Management 대시보드의 그래프를 사용하여 지난 2 개월 동안의 인스턴스 유형을 기준으로 EC2 비용을 비교합니다.","D":"AWS 비용 및 사용 보고서를 사용하여 보고서를 생성하고 Amazon S3 버킷으로 보냅니다. Amazon S3 와 함께 Amazon QuickSight 를 소스로 사용하여 인스턴스 유형을 기반으로 대화형 그래프를 생성합니다."},"answers":["B"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 컴퓨팅 솔루션 설계","aws_services":["Amazon EC2","AWS Cost Explorer"],"explanation":{"requirementsAnalysis":"솔루션 설계자는 최근 2개월의 Amazon EC2 비용을 인스턴스 유형별로 비교하는 그래프를 만들고, 원치 않는 인스턴스 유형 상향 변경의 원인을 심층 분석해야 합니다. 별도의 데이터 수집, 저장 또는 BI 시각화 환경을 구축하지 않고 필요한 기간과 비용 차원을 세분화하여 조사할 수 있어야 합니다. 따라서 내장 비용 분석 도구에서 기간, 서비스 및 인스턴스 유형을 필터링하고 그래프로 확인하는 것이 핵심입니다.","awsServicesAnalysis":"AWS Cost Explorer는 AWS 비용과 사용량을 시간대별 차트로 분석하고 서비스, 인스턴스 유형, 사용 유형, 리전 등의 차원으로 필터링하거나 그룹화할 수 있습니다. AWS Budgets는 예산 임계값과 비용/사용량 추적을 위한 예산 및 알림 기능을 제공합니다. AWS Billing and Cost Management 대시보드는 청구 정보를 요약해 보여 줍니다. AWS Cost and Usage Report는 상세 사용량 데이터를 S3로 전달할 수 있으며, Amazon QuickSight는 데이터 원본을 분석하고 대시보드를 만들 수 있습니다.","choicesAnalysis":"필요한 정보는 EC2 비용을 인스턴스 유형 기준으로 특정 기간에 분석하는 것이므로, 해당 차원에 대한 필터와 그래프를 기본 제공하는 도구가 가장 적합합니다. 예산 알림이나 청구 요약 그래프는 원인 분석을 위한 세분화 기능이 제한적이며, 비용 및 사용 보고서와 별도 시각화 도구를 구축하면 불필요한 운영 작업이 추가됩니다. 따라서 Cost Explorer에서 인스턴스 유형으로 필터링해 분석하는 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Budgets는 예산 설정과 임계값 알림에 적합하지만, 인스턴스 유형별 비용 증감의 근본 원인을 심층 분석하는 기본 도구는 아닙니다."},"B":{"isCorrect":true,"explanation":"적합합니다. Cost Explorer는 기간과 Amazon EC2 서비스를 지정하고 인스턴스 유형을 기준으로 비용을 필터링하거나 그룹화하여 차트를 만들 수 있습니다. 별도의 보고서 파이프라인 없이 비용 증가 원인을 분석할 수 있습니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. Billing and Cost Management 대시보드는 청구 요약을 제공하지만, 인스턴스 유형별로 비용을 세분화해 원인을 분석하는 Cost Explorer 수준의 기능을 제공하지 않습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. 비용 및 사용 보고서와 S3, QuickSight를 사용하면 맞춤형 분석은 가능하지만 보고서 전달, 데이터 원본 구성 및 시각화 작업이 필요합니다. Cost Explorer보다 운영 오버헤드가 큽니다."}}},{"id":"Q0025","question_number":25,"question":"회사에서 응용 프로그램을 설계하고 있습니다. 애플리케이션은 AWS Lambda 함수를 사용하여 Amazon API Gateway 를 통해 정보를 수신하고 Amazon Aurora PostgreSQL 데이터베이스에 정보를 저장합니다. 개념 증명 단계에서 회사는 데이터베이스에 로드해야 하는 대용량 데이터를 처리하기 위해 Lambda 할당량을 크게 늘려야 합니다. 솔루션 설계자는 확장성을 개선하고 구성 노력을 최소화하기 위해 새로운 설계를 권장해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"Lambda 함수 코드를 Amazon EC2 인스턴스에서 실행되는 Apache Tomcat 코드로 리팩터링합니다. 네이티브 JDBC(Java Database Connectivity) 드라이버를 사용하여 데이터베이스를 연결합니다.","B":"플랫폼을 Aurora 에서 Amazon DynamoDProvision a DynamoDB Accelerator(DAX) 클러스터로 변경합니다. DAX 클라이언트 SDK 를 사용하여 DAX 클러스터에서 기존 DynamoDB API 호출을 가리킵니다.","C":"두 개의 Lambda 함수를 설정합니다. 정보를 수신할 하나의 기능을 구성하십시오. 정보를 데이터베이스에 로드하도록 다른 기능을 구성하십시오. Amazon Simple Notification Service(Amazon SNS)를 사용하여 Lambda 함수를 통합합니다.","D":"두 개의 Lambda 함수를 설정합니다. 정보를 수신할 하나의 기능을 구성하십시오. 정보를 데이터베이스에 로드하도록 다른 기능을 구성하십시오. Amazon Simple Queue Service(Amazon SQS) 대기열을 사용하여 Lambda 함수를 통합합니다."},"answers":["D"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon API Gateway","AWS Lambda","Amazon Aurora","Amazon SQS"],"explanation":{"requirementsAnalysis":"애플리케이션은 API Gateway와 Lambda를 통해 정보를 수신한 뒤 Aurora PostgreSQL에 저장합니다. 대용량 데이터를 처리할 때 데이터베이스로의 동시 요청이 Lambda 할당량 증가를 요구할 만큼 급증하므로, 수신과 데이터베이스 쓰기를 분리하여 부하를 흡수하고 처리량에 맞춰 확장해야 합니다. 새 설계는 확장성을 높이되 애플리케이션과 인프라의 재구성 노력을 최소화해야 합니다. 따라서 내구성 있는 버퍼를 두고 비동기적으로 데이터베이스 적재를 수행하는 구성이 필요합니다.","awsServicesAnalysis":"Amazon SQS는 메시지를 내구성 있게 보관하는 관리형 대기열로 생산자와 소비자를 분리합니다. Lambda는 SQS 이벤트 소스 매핑을 통해 대기열을 폴링하고 메시지 배치로 함수를 호출하며, 메시지량에 따라 처리 작업을 확장합니다. Amazon SNS는 메시지를 구독자에게 푸시하는 게시/구독 서비스입니다. Amazon EC2에서 Tomcat을 실행하면 서버와 확장 구성을 직접 관리해야 합니다. Amazon DynamoDB Accelerator는 DynamoDB 읽기 성능을 위한 캐시이므로 Aurora PostgreSQL의 쓰기 부하를 처리하는 대체 수단이 아닙니다.","choicesAnalysis":"수신 단계와 데이터베이스 적재 단계를 비동기로 분리하면 요청 급증이 데이터베이스 쓰기 동시성으로 바로 전파되는 것을 막을 수 있습니다. 대기열 기반 소비자는 백로그를 흡수하고 Lambda가 배치 단위로 확장해 처리할 수 있습니다. 동기식 푸시 방식이나 EC2 리팩터링은 이 완충과 최소 구성 변경이라는 목표를 달성하지 못합니다. 따라서 SQS로 두 Lambda 함수를 연결하는 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. Lambda 코드를 EC2의 Tomcat으로 리팩터링하면 서버, 확장 및 JDBC 연결 관리를 새로 수행해야 합니다. 이는 구성 노력을 최소화하는 요구사항과 맞지 않으며 부하 완충도 제공하지 않습니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. DAX는 DynamoDB용 읽기 캐시이고, 현재 데이터베이스는 Aurora PostgreSQL입니다. Aurora 쓰기 부하와 Lambda 동시 실행 급증을 완화하는 구성도 아닙니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. SNS는 구독 Lambda에 메시지를 즉시 푸시하므로 데이터베이스 적재 속도를 조절할 내구성 있는 대기열 완충 계층을 제공하지 않습니다. 대용량 입력의 백프레셔 처리에는 SQS가 더 적합합니다."},"D":{"isCorrect":true,"explanation":"적합합니다. 수신 Lambda가 SQS에 메시지를 넣고 적재 Lambda가 이벤트 소스 매핑으로 배치 처리하면 수신과 데이터베이스 쓰기가 느슨하게 결합됩니다. SQS가 급증한 데이터를 보관하고 Lambda가 처리량에 맞춰 확장하므로 확장성과 구성 단순성을 함께 충족합니다."}}},{"id":"Q0026","question_number":26,"question":"회사는 AWS 클라우드 배포를 검토하여 Amazon S3 버킷에 무단 구성 변경이 없는지 확인해야 합니다. 솔루션 설계자는 이 목표를 달성하기 위해 무엇을 해야 합니까?","choices":{"A":"적절한 규칙으로 AWS Config 를 켭니다.","B":"적절한 검사를 통해 AWS Trusted Advisor 를 켭니다.","C":"적절한 평가 템플릿으로 Amazon Inspector 를 켭니다.","D":"Amazon S3 서버 액세스 로깅을 켭니다. Amazon EventBridge(Amazon Cloud Watch Events)를 구성합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["AWS Config","Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 Amazon S3 버킷의 구성이 무단으로 변경되지 않았는지 지속적으로 확인해야 합니다. 따라서 버킷의 구성 변경을 기록하고, 정의한 보안 기준에 대한 준수 여부를 자동으로 평가해 변경 사항을 식별할 수 있어야 합니다. 단순 권고나 액세스 기록이 아니라 리소스 구성과 정책 상태를 검사하는 통제 수단이 필요합니다.","awsServicesAnalysis":"AWS Config는 AWS 리소스의 구성 변경을 기록하고, Config 규칙으로 원하는 구성 기준의 준수 여부를 지속적으로 평가합니다. 관리형 규칙이나 사용자 지정 규칙은 S3 버킷의 공개 액세스 차단, 암호화, 버전 관리 등 구체적인 속성을 검사할 수 있습니다. AWS Trusted Advisor는 비용 최적화, 성능, 보안 등의 모범 사례 권장 사항을 제공합니다. Amazon Inspector는 주로 워크로드의 소프트웨어 취약성과 노출을 평가합니다. S3 서버 액세스 로깅은 버킷 요청 기록을 제공하며, Amazon EventBridge는 이벤트에 반응하는 규칙과 대상을 구성합니다.","choicesAnalysis":"무단 구성 변경을 확인하려면 S3 버킷의 현재 및 변경된 구성을 기준과 비교해 비준수를 식별해야 합니다. AWS Config는 구성 기록과 규칙 기반 준수 평가를 함께 제공하므로 이 목적에 직접 부합합니다. 권고 도구, 취약성 평가 도구 또는 접근 로그와 이벤트 라우팅만으로는 구성 정책을 지속 평가하지 못합니다. 따라서 적절한 AWS Config 규칙을 활성화하는 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"적합합니다. AWS Config는 S3 버킷 구성 변경을 기록하고 규칙으로 지정한 보안 설정의 준수 여부를 평가합니다. 무단 변경으로 인한 비준수 상태를 식별하는 데 직접 사용할 수 있습니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Trusted Advisor는 모범 사례에 관한 권장 사항을 제공하지만, S3 버킷의 구성 변경을 기록하고 사용자 기준에 따라 지속적으로 준수 여부를 평가하는 서비스는 아닙니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. Amazon Inspector는 EC2, 컨테이너 이미지 및 Lambda 등의 취약성 관리에 사용됩니다. S3 버킷 구성의 무단 변경을 추적하고 정책 준수를 평가하는 목적에 맞지 않습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. S3 서버 액세스 로그는 버킷에 대한 요청을 기록하고 EventBridge는 이벤트를 전달할 수 있지만, 이 조합만으로는 버킷 구성의 기준 준수 여부를 자동 평가하지 못합니다."}}},{"id":"Q0027","question_number":27,"question":"회사에서 새 애플리케이션을 시작하고 Amazon CloudWatch 대시보드에 애플리케이션 지표를 표시합니다. 회사의 제품 관리자는 이 대시보드에 주기적으로 액세스해야 합니다. 제품 관리자에게 AWS 계정이 없습니다. 솔루션 설계자는 최소 권한 원칙에 따라 제품 관리자에 대한 액세스를 제공해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"CloudWatch 콘솔에서 대시보드를 공유합니다. 제품 관리자의 이메일 주소를 입력하고 공유 단계를 완료합니다. 대시보드에 대한 공유 가능한 링크를 제품 관리자에게 제공하십시오.","B":"특히 제품 관리자를 위한 IAM 사용자를 생성합니다. CloudWatchReadOnlyAccess AWS 관리형 정책을 사용자에게 연결합니다. 새 로그인 자격 증명을 제품 관리자와 공유하십시오. 올바른 대시보드의 브라우저 URL 을 제품 관리자와 공유하십시오.","C":"회사 직원을 위한 IAM 사용자를 생성합니다. ViewOnlyAccess AWS 관리형 정책을 IAM 사용자에게 연결합니다. 새 로그인 자격 증명을 제품 관리자와 공유하십시오. 제품 관리자에게 CloudWatch 콘솔로 이동하여 대시보드 섹션에서 이름으로 대시보드를 찾으라고 요청합니다.","D":"퍼블릭 서브넷에 배스천 서버를 배포합니다. 제품 관리자가 대시보드에 액세스해야 하는 경우 서버를 시작하고 RDP 자격 증명을 공유합니다. 배스천 서버에서 대시보드를 볼 수 있는 적절한 권한이 있는 캐시된 AWS 자격 증명으로 대시보드 URL 을 열도록 브라우저가 구성되어 있는지 확인합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"AWS 리소스에 대한 보안 액세스 설계","aws_services":["Amazon CloudWatch"],"explanation":{"requirementsAnalysis":"제품 관리자는 AWS 계정이 없지만 Amazon CloudWatch 대시보드를 주기적으로 확인해야 합니다. 필요한 권한은 특정 대시보드의 조회에 한정되어야 하므로, AWS 콘솔 전체에 대한 로그인 자격 증명이나 광범위한 읽기 권한을 부여하지 않아야 합니다. 따라서 AWS 계정 없이도 필요한 대시보드만 볼 수 있도록 최소한의 접근 범위를 제공해야 합니다.","awsServicesAnalysis":"Amazon CloudWatch는 대시보드를 공개 공유 링크로 제공할 수 있으며, 링크를 받은 사용자는 AWS 자격 증명 없이 대시보드를 볼 수 있습니다. 공개 공유 링크는 링크를 가진 모든 사람이 인증 없이 접근할 수 있으므로 민감한 정보가 없는 대시보드에 사용해야 합니다. IAM 사용자는 AWS 계정 내 콘솔 로그인 자격 증명을 제공하며 CloudWatchReadOnlyAccess 또는 ViewOnlyAccess 정책은 여러 AWS 리소스에 대한 읽기 권한을 포함합니다. 배스천 호스트는 원격 접속 환경을 운영해야 하는 컴퓨팅 인프라입니다.","choicesAnalysis":"요구사항은 AWS 계정이 없는 외부 사용자에게 특정 대시보드의 보기 권한만 제공하는 것입니다. 대시보드 공유 링크는 별도 계정을 만들지 않고 해당 대시보드에 접근하도록 하므로 권한 범위가 가장 작습니다. IAM 사용자와 관리형 읽기 정책은 콘솔 및 더 넓은 AWS 리소스 접근을 제공하며, 배스천 호스트는 불필요한 운영 복잡성을 도입합니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"적합합니다. CloudWatch 대시보드의 공유 가능한 링크를 제공하면 제품 관리자는 AWS 계정이나 콘솔 자격 증명 없이 해당 대시보드를 볼 수 있습니다. 공개 공유 전에 대시보드에 민감한 정보가 없는지 확인해야 합니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. IAM 사용자와 CloudWatchReadOnlyAccess는 제품 관리자에게 AWS 콘솔 로그인과 CloudWatch 전반의 읽기 권한을 부여합니다. 특정 대시보드만 공유하는 것보다 권한 범위가 넓습니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. ViewOnlyAccess는 CloudWatch에만 한정되지 않은 광범위한 읽기 권한을 포함하고, IAM 사용자 계정도 새로 관리해야 합니다. 최소 권한 원칙에 맞지 않습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. 배스천 서버와 RDP 자격 증명을 운영하는 방식은 대시보드 조회에 불필요한 컴퓨팅 및 보안 관리 부담을 추가합니다. 또한 공유된 자격 증명은 최소 권한 접근 방식이 아닙니다."}}},{"id":"Q0028","question_number":28,"question":"회사에서 애플리케이션을 AWS 로 마이그레이션하고 있습니다. 응용 프로그램은 다른 계정에 배포됩니다. 회사는 AWS Organizations 를 사용하여 중앙에서 계정을 관리합니다. 회사의 보안 팀은 회사의 모든 계정에 SSO(Single Sign-On) 솔루션이 필요합니다. 회사는 사내 자체 관리 Microsoft Active Directory 에서 사용자 및 그룹을 계속 관리해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"AWS SSO 콘솔에서 AWS Single Sign-On(AWS SSO)을 활성화합니다. 단방향 포리스트 트러스트 또는 단방향 도메인 트러스트를 생성하여 Microsoft Active Directory 용 AWS Directory Service 를 사용하여 회사의 자체 관리형 Microsoft Active Directory 를 AWS SSO 와 연결합니다.","B":"AWS SSO 콘솔에서 AWS Single Sign-On(AWS SSO)을 활성화합니다. Microsoft Active Directory 용 AWS Directory Service 를 사용하여 회사의 자체 관리형 Microsoft Active Directory 를 AWS SSO 와 연결하는 양방향 포리스트 트러스트를 생성합니다.","C":"AWS 디렉터리 서비스를 사용합니다. 회사의 자체 관리 Microsoft Active Directory 와 양방향 신뢰 관계를 만드십시오.","D":"온프레미스에 ID 공급자(IdP)를 배포합니다. AWS SSO 콘솔에서 AWS Single Sign-On(AWS SSO)을 활성화합니다."},"answers":["B"],"content_domain":"보안 아키텍처 설계","content_task":"AWS 리소스에 대한 보안 액세스 설계","aws_services":["AWS Organizations","AWS IAM Identity Center","AWS Directory Service"],"explanation":{"requirementsAnalysis":"회사는 AWS Organizations로 여러 AWS 계정을 중앙 관리하고 있으며, 모든 계정에 단일 로그인 경험을 제공해야 합니다. 사용 및 그룹 관리는 사내 자체 관리 Microsoft Active Directory에서 계속 수행해야 하므로 사용자 정보를 AWS에 별도로 다시 만들거나 이전하지 않아야 합니다. 따라서 기존 AD를 IAM Identity Center의 자격 증명 원본으로 연결하고 여러 계정에 권한을 할당할 수 있는 신뢰 구성이 필요합니다.","awsServicesAnalysis":"AWS IAM Identity Center는 AWS Organizations의 여러 AWS 계정과 애플리케이션에 대한 중앙 액세스를 관리하는 서비스이며, 이전 명칭은 AWS Single Sign-On입니다. IAM Identity Center는 AWS Directory Service for Microsoft Active Directory와 자체 관리 Active Directory 사이의 양방향 신뢰를 통해 기존 도메인의 사용자와 그룹을 사용할 수 있습니다. 양방향 신뢰는 인증과 사용자/그룹 메타데이터 동기화에 필요한 권한을 제공합니다. 단방향 신뢰는 IAM Identity Center와 자체 관리 AD의 연결에 사용할 수 없습니다. AWS Directory Service만 구성하거나 온프레미스 IdP만 배포하는 것은 IAM Identity Center에 대한 필요한 디렉터리 통합 구성을 완성하지 않습니다.","choicesAnalysis":"여러 계정의 SSO와 기존 사내 AD 사용자/그룹 관리를 동시에 충족하려면 IAM Identity Center를 활성화하고 자체 관리 AD와 연결해야 합니다. 이 연결은 사용자 인증뿐 아니라 권한 할당에 필요한 디렉터리 메타데이터도 읽어야 하므로 양방향 신뢰가 요구됩니다. 단방향 신뢰나 디렉터리 서비스만의 구성은 이 조건을 충족하지 못합니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"적합하지 않습니다. IAM Identity Center를 자체 관리 Active Directory와 연결하는 데 단방향 포리스트 또는 도메인 신뢰는 사용할 수 없습니다. 사용자와 그룹 메타데이터 동기화를 위해 양방향 신뢰가 필요합니다."},"B":{"isCorrect":true,"explanation":"적합합니다. IAM Identity Center를 활성화하고 AWS Directory Service for Microsoft Active Directory와 자체 관리 AD 간에 양방향 포리스트 신뢰를 구성하면 기존 사용자와 그룹으로 여러 AWS 계정에 SSO를 제공할 수 있습니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Directory Service와 자체 관리 AD의 양방향 신뢰만으로는 AWS Organizations 전체 계정에 SSO와 권한 세트를 제공하는 IAM Identity Center 구성이 없습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. 온프레미스 IdP를 배포하고 IAM Identity Center를 활성화하는 것만으로는 기존 자체 관리 Active Directory의 사용자와 그룹을 사용할 구체적인 자격 증명 원본 및 통합 구성이 제시되지 않았습니다."}}},{"id":"Q0029","question_number":29,"question":"회사는 UDP 연결을 사용하는 VoIP(Voice over Internet Protocol) 서비스를 제공합니다. 이 서비스는 Auto Scaling 그룹에서 실행되는 Amazon EC2 인스턴스로 구성됩니다. 회사는 여러 AWS 리전에 배포하고 있습니다. 회사는 지연 시간이 가장 짧은 리전으로 사용자를 라우팅해야 합니다. 이 회사는 또한 지역 간 자동 장애 조치가 필요합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"NLB(Network Load Balancer) 및 연결된 대상 그룹을 배포합니다. 대상 그룹을 Auto Scaling 그룹과 연결합니다. 각 리전에서 NLB 를 AWS Global Accelerator 엔드포인트로 사용합니다.","B":"ALB(Application Load Balancer) 및 연결된 대상 그룹을 배포합니다. 대상 그룹을 Auto Scaling 그룹과 연결합니다. 각 리전에서 ALB 를 AWS Global Accelerator 엔드포인트로 사용합니다.","C":"NLB(Network Load Balancer) 및 연결된 대상 그룹을 배포합니다. 대상 그룹을 Auto Scaling 그룹과 연결합니다. 각 NLB 의 별칭을 가리키는 Amazon Route 53 지연 시간 레코드를 생성합니다. 지연 시간 레코드를 오리진으로 사용하는 Amazon CloudFront 배포를 생성합니다.","D":"ALB(Application Load Balancer) 및 연결된 대상 그룹을 배포합니다. 대상 그룹을 Auto Scaling 그룹과 연결합니다. 각 ALB 의 별칭을 가리키는 Amazon Route 53 가중치 레코드를 생성합니다. 가중 레코드를 오리진으로 사용하는 Amazon CloudFront 배포를 배포합니다."},"answers":["A"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 네트워크 아키텍처 결정","aws_services":["Amazon EC2","Amazon EC2 Auto Scaling","Elastic Load Balancing(ELB)","AWS Global Accelerator"],"explanation":{"requirementsAnalysis":"VoIP 서비스는 UDP 연결을 사용하며 여러 AWS 리전의 Auto Scaling EC2 인스턴스에서 실행됩니다. 사용자는 네트워크 지연 시간이 가장 낮은 리전으로 라우팅되어야 하고, 한 리전이나 엔드포인트에 장애가 발생하면 다른 리전으로 자동 장애 조치되어야 합니다. 따라서 UDP를 지원하는 리전별 로드 밸런싱과 글로벌 네트워크 기반의 지연 시간 최적화 및 상태 기반 장애 조치가 필요합니다.","awsServicesAnalysis":"Network Load Balancer는 TCP, UDP 및 TLS 트래픽을 대상 그룹의 인스턴스로 분산할 수 있고 Auto Scaling 그룹의 인스턴스를 대상으로 등록할 수 있습니다. Application Load Balancer는 HTTP와 HTTPS 같은 애플리케이션 계층 트래픽을 처리하며 UDP를 지원하지 않습니다. AWS Global Accelerator 표준 가속기는 정적 IP 주소를 진입점으로 제공하고 AWS 글로벌 네트워크를 통해 사용자 위치와 엔드포인트 상태 등을 고려해 정상 리전 엔드포인트로 트래픽을 라우팅합니다. Global Accelerator의 엔드포인트로 NLB를 지정할 수 있습니다. Amazon CloudFront는 주로 HTTP/HTTPS 콘텐츠 전송에 사용되며 UDP VoIP 트래픽의 프록시가 아닙니다. Route 53 지연 시간 기반 라우팅은 DNS 응답을 선택할 수 있습니다.","choicesAnalysis":"UDP 기반 VoIP 트래픽은 UDP를 지원하는 로드 밸런서를 거쳐야 하므로 ALB와 CloudFront 기반 구성은 제외됩니다. 글로벌 사용자에게 가장 낮은 지연 시간의 정상 리전으로 라우팅하고 리전 간 장애 조치를 제공하려면 DNS 응답만 선택하는 방식보다 Global Accelerator의 글로벌 애니캐스트 진입점과 상태 모니터링이 적합합니다. NLB를 각 리전 엔드포인트로 연결하면 프로토콜 요구사항도 충족합니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"적합합니다. 각 리전의 NLB는 UDP VoIP 트래픽을 Auto Scaling EC2 대상에 분산할 수 있습니다. AWS Global Accelerator는 정상 상태의 적절한 리전 엔드포인트로 글로벌 트래픽을 라우팅하므로 낮은 지연 시간과 리전 간 자동 장애 조치를 제공합니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. AWS Global Accelerator는 ALB를 엔드포인트로 사용할 수 있지만 ALB는 UDP 트래픽을 지원하지 않습니다. 따라서 VoIP의 UDP 연결 요구사항을 충족하지 못합니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. NLB와 Route 53 지연 시간 레코드는 일부 라우팅 요구사항에 도움이 될 수 있지만 CloudFront는 UDP VoIP 트래픽을 처리하지 않습니다. 또한 Global Accelerator가 제공하는 글로벌 정적 진입점과 상태 기반 전환 구성이 없습니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. ALB와 CloudFront는 UDP를 지원하지 않으며, Route 53 가중치 기반 라우팅은 사용자별 최저 지연 시간 리전을 자동으로 선택하는 정책이 아닙니다."}}},{"id":"Q0030","question_number":30,"question":"개발 팀은 성능 개선 도우미가 활성화된 MySQL DB 인스턴스용 범용 Amazon RDS 에서 매월 리소스 집약적 테스트를 실행합니다. 테스트는 한 달에 한 번 48 시간 동안 지속되며 데이터베이스를 사용하는 유일한 프로세스입니다. 팀은 DB 인스턴스의 컴퓨팅 및 메모리 속성을 줄이지 않고 테스트 실행 비용을 줄이려고 합니다. 어떤 솔루션이 이러한 요구 사항을 가장 비용 효율적으로 충족합니까?","choices":{"A":"테스트가 완료되면 DB 인스턴스를 중지합니다. 필요한 경우 DB 인스턴스를 다시 시작합니다.","B":"DB 인스턴스와 함께 Auto Scaling 정책을 사용하여 테스트가 완료되면 자동으로 확장합니다.","C":"테스트가 완료되면 스냅샷을 만듭니다. DB 인스턴스를 종료하고 필요한 경우 스냅샷을 복원합니다.","D":"테스트가 완료되면 DB 인스턴스를 저용량 인스턴스로 수정합니다. 필요한 경우 DB 인스턴스를 다시 수정합니다."},"answers":["A"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 컴퓨팅 솔루션 설계","aws_services":["Amazon RDS"],"explanation":{"requirementsAnalysis":"개발 팀은 월 1회 48시간 동안만 리소스 집약적 테스트를 실행하고, 나머지 기간에는 데이터베이스를 사용하지 않습니다. 테스트 중에는 현재 DB 인스턴스의 컴퓨팅 및 메모리 성능을 유지해야 하지만, 유휴 기간의 인스턴스 실행 비용은 줄여야 합니다. 데이터와 기존 구성은 유지하면서 다음 테스트 전에 신속히 같은 성능으로 재개할 수 있는지가 핵심입니다.","awsServicesAnalysis":"Amazon RDS는 지원되는 DB 인스턴스를 일시 중지했다가 다시 시작할 수 있습니다. 중지된 동안에는 DB 인스턴스의 컴퓨팅 비용이 발생하지 않지만 프로비저닝된 스토리지와 백업 스토리지는 계속 과금됩니다. 중지한 DB 인스턴스는 최대 7일 후 자동으로 다시 시작되므로 월별 테스트 일정에서는 필요할 때 재중지해야 할 수 있습니다. RDS는 DB 인스턴스에 대한 Auto Scaling 정책으로 컴퓨팅과 메모리 인스턴스 클래스를 자동 조정하지 않습니다. 스냅샷은 복원을 통해 새 DB 인스턴스를 만들 수 있고, 인스턴스 클래스 변경은 재시작/수정 작업을 요구할 수 있습니다.","choicesAnalysis":"테스트가 없는 장기간에는 데이터베이스를 중지하면 컴퓨팅 비용을 절감하면서 인스턴스 식별자, 구성 및 데이터를 유지할 수 있습니다. 재시작하면 기존 인스턴스 클래스가 유지되므로 테스트의 컴퓨팅/메모리 조건도 충족됩니다. 종료 후 스냅샷 복원이나 인스턴스 클래스를 반복 변경하는 방식은 재구성과 복구 시간이 추가되고, Auto Scaling 정책은 이 목적의 기능이 아닙니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"적합합니다. 테스트가 끝난 후 RDS DB 인스턴스를 중지하면 유휴 기간의 컴퓨팅 비용을 줄이고, 필요할 때 같은 인스턴스 구성으로 다시 시작할 수 있습니다. 중지 상태는 최대 7일이므로 월별 일정에서는 자동 재시작 후 다시 중지하는 운영이 필요할 수 있습니다."},"B":{"isCorrect":false,"explanation":"적합하지 않습니다. Amazon RDS DB 인스턴스는 Auto Scaling 정책으로 컴퓨팅 및 메모리 인스턴스 클래스를 자동 확장하는 방식이 아닙니다. 또한 테스트가 없는 기간에는 인스턴스를 중지하는 방식이 실행 비용 절감에 더 직접적입니다."},"C":{"isCorrect":false,"explanation":"적합하지 않습니다. 스냅샷 후 인스턴스를 종료하고 복원하면 새 DB 인스턴스 생성, 복원 대기 및 구성 확인이 필요합니다. 기존 인스턴스를 중지/시작하는 방식보다 운영 작업과 재개 시간이 늘어납니다."},"D":{"isCorrect":false,"explanation":"적합하지 않습니다. 저용량 인스턴스로 변경하면 테스트가 없을 때 비용은 줄일 수 있지만, 매월 두 차례 인스턴스 클래스 변경과 재시작을 관리해야 합니다. 중지/시작보다 운영 부담이 크고 성능 구성 변경도 발생합니다."}}},{"id":"Q0031","question_number":31,"question":"AWS 에서 웹 애플리케이션을 호스팅하는 회사는 모든 Amazon EC2 인스턴스를 보장하기를 원합니다. Amazon RDS DB 인스턴스. Amazon Redshift 클러스터는 태그로 구성됩니다. 회사는 이 검사를 구성하고 운영하는 노력을 최소화하기를 원합니다. 솔루션 설계자는 이를 달성하기 위해 무엇을 해야 합니까?","choices":{"A":"AWS Config 규칙을 사용하여 적절하게 태그가 지정되지 않은 리소스를 정의하고 감지합니다.","B":"비용 탐색기를 사용하여 제대로 태그가 지정되지 않은 리소스를 표시합니다. 해당 리소스에 수동으로 태그를 지정합니다.","C":"적절한 태그 할당을 위해 모든 리소스를 확인하는 API 호출을 작성합니다. EC2 인스턴스에서 주기적으로 코드를 실행합니다.","D":"적절한 태그 할당을 위해 모든 리소스를 확인하는 API 호출을 작성합니다. Amazon CloudWatch 를 통해 AWS Lambda 함수를 예약하여 코드를 주기적으로 실행합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["AWS Config"],"explanation":{"requirementsAnalysis":"회사는 모든 Amazon EC2 인스턴스, Amazon RDS DB 인스턴스 및 Amazon Redshift 클러스터에 필요한 태그가 구성되었는지 지속적으로 확인해야 합니다. 확인 대상은 여러 AWS 리소스 유형이며, 미준수 리소스를 식별할 수 있어야 합니다. 또한 검사 로직을 직접 작성하거나 실행 인프라를 운영하는 부담을 최소화해야 합니다.","awsServicesAnalysis":"AWS Config는 AWS 리소스 구성의 변경 사항과 구성 이력을 기록하고, Config 규칙으로 리소스 구성의 준수 여부를 평가합니다. 태그 키와 값을 기준으로 구성 항목을 평가하는 관리형 규칙 및 사용자 지정 규칙을 사용할 수 있습니다. AWS Cost Explorer는 비용과 사용량을 분석하는 서비스입니다. Amazon EC2에서 실행하는 스크립트와 AWS Lambda 함수는 API를 호출하는 사용자 지정 검사 로직을 실행할 수 있으며, Lambda는 예약 실행을 지원합니다.","choicesAnalysis":"태그 정책의 준수 여부를 여러 리소스 유형에서 계속 평가하면서 운영 부담을 낮추려면 구성 추적 및 규칙 평가 기능을 사용하는 방식이 적합합니다. 별도 API 검사 코드를 작성하면 구현과 유지 관리가 필요하고, 비용 분석 도구는 구성 준수 검사의 중심 기능이 아닙니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 AWS Config 규칙으로 필요한 태그 조건을 정의하고, 구성된 리소스의 미준수 상태를 식별할 수 있으므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 비용 분석 도구에서 확인한 뒤 수동으로 태그를 지정해야 하므로 지속적인 구성 검사와 운영 노력 최소화 요구사항에 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 API 검사 코드와 이를 실행할 EC2 인스턴스를 직접 관리해야 하므로 AWS Config 규칙보다 운영 오버헤드가 큽니다."},"D":{"isCorrect":false,"explanation":"D는 EC2를 관리하지는 않지만 태그 검사 API 코드와 예약 실행을 구현하고 유지해야 하므로 관리형 Config 규칙보다 적합하지 않습니다."}}},{"id":"Q0032","question_number":32,"question":"개발 팀은 다른 팀이 액세스할 웹사이트를 호스팅해야 합니다. 웹사이트 콘텐츠는 HTML, CSS, 클라이언트 측 JavaScript 및 이미지로 구성됩니다. 웹 사이트 호스팅에 가장 비용 효율적인 방법은 무엇입니까?","choices":{"A":"웹 사이트를 컨테이너화하고 AWS Fargate 에서 호스팅합니다.","B":"Amazon S3 버킷을 생성하고 거기에서 웹 사이트를 호스팅합니다.","C":"Amazon EC2 인스턴스에 웹 서버를 배포하여 웹 사이트를 호스팅합니다.","D":"Express.js 프레임워크를 사용하는 AWS Lambda 대상으로 Application Load Balancer 를 구성합니다."},"answers":["B"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 스토리지 솔루션 설계","aws_services":["Amazon S3"],"explanation":{"requirementsAnalysis":"웹사이트는 HTML, CSS, 클라이언트 측 JavaScript 및 이미지로만 구성된 정적 콘텐츠입니다. 다른 팀이 웹사이트에 접속할 수 있도록 호스팅해야 하며, 서버 측 애플리케이션 처리 요구사항은 제시되지 않았습니다. 따라서 필요한 기능을 제공하면서 컴퓨팅 리소스 비용과 관리 부담을 최소화하는 호스팅 방식이 필요합니다.","awsServicesAnalysis":"Amazon S3는 객체를 저장하고 정적 웹사이트 호스팅을 제공할 수 있습니다. AWS Fargate는 컨테이너화된 애플리케이션을 실행하는 서버리스 컴퓨팅 엔진입니다. Amazon EC2는 가상 서버에서 웹 서버 소프트웨어를 실행할 수 있습니다. Application Load Balancer는 HTTP 요청을 Lambda 대상으로 라우팅할 수 있고, Lambda는 요청 처리 코드를 실행합니다.","choicesAnalysis":"정적 파일만 제공하는 웹사이트에는 웹 서버 프로세스나 애플리케이션 실행 환경이 필요하지 않습니다. 객체 스토리지 기반 정적 호스팅은 이러한 컴퓨팅 계층을 제거하므로 비용과 운영 부담을 낮춥니다. 컨테이너, EC2 또는 Lambda와 로드 밸런서는 동적 처리 계층을 추가합니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 정적 파일을 제공하기 위해 컨테이너 실행 환경을 구성해야 하므로 필요한 기능보다 많은 컴퓨팅 비용과 운영 구성이 발생합니다."},"B":{"isCorrect":true,"explanation":"B는 Amazon S3의 정적 웹사이트 호스팅으로 HTML, CSS, JavaScript 및 이미지를 직접 제공할 수 있으므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 웹 서버가 설치된 EC2 인스턴스를 운영해야 하므로 정적 콘텐츠 호스팅에 비해 비용과 관리 부담이 증가합니다."},"D":{"isCorrect":false,"explanation":"D는 Application Load Balancer, Lambda 및 Express.js 요청 처리 계층을 구성하므로 서버 측 처리가 없는 정적 웹사이트에 적합하지 않습니다."}}},{"id":"Q0033","question_number":33,"question":"회사는 AWS 에서 온라인 마켓플레이스 웹 애플리케이션을 실행합니다. 이 애플리케이션은 피크 시간에 수십만 명의 사용자에게 서비스를 제공합니다. 이 회사는 수백만 건의 금융 거래 세부 정보를 다른 여러 내부 애플리케이션과 공유할 수 있는 확장 가능한 거의 실시간 솔루션이 필요합니다. 또한 지연 시간이 짧은 검색을 위해 문서 데이터베이스에 저장하기 전에 민감한 데이터를 제거하기 위해 트랜잭션을 처리해야 합니다. 이러한 요구 사항을 충족하기 위해 솔루션 설계자는 무엇을 권장해야 합니까?","choices":{"A":"트랜잭션 데이터를 Amazon DynamoDB 에 저장합니다. 쓰기 시 모든 트랜잭션에서 민감한 데이터를 제거하도록 DynamoDB 에서 규칙을 설정합니다. DynamoDB 스트림을 사용하여 다른 애플리케이션과 트랜잭션 데이터를 공유합니다.","B":"트랜잭션 데이터를 Amazon Kinesis Data Firehose 로 스트리밍하여 Amazon DynamoDB 및 Amazon S3 에 데이터를 저장합니다. Kinesis Data Firehose 와 AWS Lambda 통합을 사용하여 민감한 데이터를 제거하십시오. 다른 애플리케이션은 Amazon S3 에 저장된 데이터를 사용할 수 있습니다.","C":"트랜잭션 데이터를 Amazon Kinesis Data Streams 로 스트리밍합니다. AWS Lambda 통합을 사용하여 모든 트랜잭션에서 민감한 데이터를 제거한 다음 Amazon DynamoDB 에 트랜잭션 데이터를 저장합니다. 다른 애플리케이션은 Kinesis 데이터 스트림의 트랜잭션 데이터를 사용할 수 있습니다.","D":"일괄 처리된 트랜잭션 데이터를 Amazon S3 에 파일로 저장합니다. Amazon S3 에서 파일을 업데이트하기 전에 AWS Lambda 를 사용하여 모든 파일을 처리하고 민감한 데이터를 제거하십시오. 그러면 Lambda 함수가 Amazon DynamoDB 에 데이터를 저장합니다. 다른 애플리케이션은 Amazon S3 에 저장된 트랜잭션 파일을 사용할 수 있습니다."},"answers":["C"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터 수집 및 변환 솔루션 결정","aws_services":["Amazon Kinesis","AWS Lambda","Amazon DynamoDB"],"explanation":{"requirementsAnalysis":"온라인 마켓플레이스는 피크 시간의 대규모 사용자 트래픽에서 발생하는 수백만 건의 금융 거래를 여러 내부 애플리케이션에 거의 실시간으로 공유해야 합니다. 트랜잭션의 민감한 데이터는 지연 시간이 낮은 문서 데이터베이스에 저장하기 전에 제거되어야 합니다. 따라서 높은 처리량의 스트리밍 수집, 변환 처리, 다수 소비자에 대한 데이터 제공 및 빠른 데이터 저장을 함께 지원해야 합니다.","awsServicesAnalysis":"Amazon Kinesis Data Streams는 실시간 데이터 레코드를 수집하고 여러 애플리케이션이 독립적으로 소비할 수 있는 데이터 스트리밍 서비스입니다. AWS Lambda는 Kinesis Data Streams의 레코드로 함수를 호출하여 변환 로직을 실행할 수 있습니다. Amazon DynamoDB는 낮은 지연 시간의 키-값 및 문서 데이터베이스입니다. Amazon Data Firehose는 스트리밍 데이터를 지정한 대상으로 전달하는 완전관리형 전송 서비스이며, Amazon S3는 객체를 저장합니다.","choicesAnalysis":"대량 거래를 여러 소비자에게 거의 실시간으로 전달하려면 독립적 소비를 지원하는 스트림이 필요합니다. 민감한 데이터 제거는 스트림 처리 단계에서 수행한 뒤 지연 시간이 낮은 문서 데이터베이스로 저장할 수 있습니다. 파일 단위 일괄 처리나 S3만을 소비 경로로 쓰는 방식은 이 실시간 처리 흐름과 맞지 않습니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 DynamoDB Streams는 테이블 변경 사항을 전달할 수 있지만, DynamoDB에는 쓰기 시 민감한 데이터를 제거하는 규칙을 설정하는 기능이 없으므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 Amazon Data Firehose의 전송 대상으로 Amazon DynamoDB를 직접 지정할 수 없으며, 다른 애플리케이션도 S3에 전달된 데이터를 사용해야 하므로 거의 실시간 공유 요구사항에 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 Kinesis Data Streams로 트랜잭션을 여러 소비자에게 제공하고 Lambda로 민감한 데이터를 제거한 뒤 DynamoDB에 저장할 수 있으므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 파일을 S3에 일괄 저장하고 처리하므로 대규모 거래를 여러 애플리케이션에 거의 실시간으로 공유하는 요구사항에 적합하지 않습니다."}}},{"id":"Q0034","question_number":34,"question":"회사는 AWS 에서 다중 계층 애플리케이션을 호스팅합니다. 규정 준수, 거버넌스, 감사 및 보안을 위해 회사는 AWS 리소스의 구성 변경 사항을 추적하고 이러한 리소스에 대한 API 호출 기록을 기록해야 합니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"AWS CloudTrail 을 사용하여 구성 변경을 추적하고 AWS Config 를 사용하여 API 호출을 기록하십시오.","B":"AWS Config 를 사용하여 구성 변경을 추적하고 AWS CloudTrail 을 사용하여 API 호출을 기록합니다.","C":"AWS Config 를 사용하여 구성 변경을 추적하고 Amazon CloudWatch 를 사용하여 API 호출을 기록합니다.","D":"AWS CloudTrail 을 사용하여 구성 변경을 추적하고 Amazon CloudWatch 를 사용하여 API 호출을 기록합니다."},"answers":["B"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["AWS Config","AWS CloudTrail"],"explanation":{"requirementsAnalysis":"회사는 규정 준수, 거버넌스, 감사 및 보안을 위해 AWS 리소스 구성의 변경 이력을 추적해야 합니다. 또한 이러한 리소스에 대해 수행된 API 호출의 기록도 보존해야 합니다. 두 종류의 감사 정보를 각각 지속적으로 수집할 수 있는 구성이 필요합니다.","awsServicesAnalysis":"AWS Config는 지원되는 AWS 리소스의 구성, 구성 변경 및 구성 이력을 기록합니다. AWS CloudTrail은 AWS 계정에서 이루어진 관리 이벤트와 데이터 이벤트 등 API 활동을 이벤트로 기록할 수 있습니다. Amazon CloudWatch는 지표, 로그 및 경보를 수집하고 모니터링하는 서비스입니다.","choicesAnalysis":"리소스 자체의 구성 변경과 AWS API 호출은 서로 다른 감사 데이터입니다. 구성 변경 기록에는 AWS Config를 사용하고, 누가 언제 어떤 API를 호출했는지 추적하려면 AWS CloudTrail을 사용해야 합니다. CloudWatch는 이 요구사항의 API 호출 감사 기록을 대체하지 않습니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 구성 변경 추적과 API 호출 기록에 사용하는 서비스를 서로 바꾸어 적용하므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 AWS Config로 리소스 구성 변경을 추적하고 AWS CloudTrail로 API 호출을 기록하므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 AWS Config로 구성 변경을 추적할 수 있지만, Amazon CloudWatch는 AWS API 호출 감사 기록을 위한 서비스가 아니므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 AWS CloudTrail로 API 활동을 기록할 수 있지만, 구성 변경 추적에는 AWS Config가 필요하므로 적합하지 않습니다."}}},{"id":"Q0035","question_number":35,"question":"한 회사가 AWS 클라우드에서 공개 웹 애플리케이션 출시를 준비하고 있습니다. 아키텍처는 Elastic Load Balancer(ELB) 뒤의 VPC 내 Amazon EC2 인스턴스로 구성됩니다. DNS 에는 타사 서비스가 사용됩니다. 회사의 솔루션 설계자는 대규모 DDoS 공격을 감지하고 보호하기 위한 솔루션을 권장해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"계정에서 Amazon GuardDuty 를 활성화합니다.","B":"EC2 인스턴스에서 Amazon Inspector 를 활성화합니다.","C":"AWS Shield 를 활성화하고 여기에 Amazon Route 53 을 할당합니다.","D":"AWS Shield Advanced 를 활성화하고 ELB 를 할당합니다."},"answers":["D"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["AWS Shield","Elastic Load Balancing(ELB)"],"explanation":{"requirementsAnalysis":"공개 웹 애플리케이션은 Elastic Load Balancer 뒤의 Amazon EC2 인스턴스에서 실행되며, DNS에는 타사 서비스를 사용합니다. 회사는 대규모 DDoS 공격을 탐지하고 애플리케이션 진입 지점에 대한 보호를 받아야 합니다. 따라서 사용 중인 DNS 서비스와 독립적으로 로드 밸런서를 보호 대상으로 지정할 수 있는 DDoS 방어 기능이 필요합니다.","awsServicesAnalysis":"AWS Shield는 AWS 리소스에 대한 DDoS 보호 서비스이며, AWS Shield Advanced는 향상된 DDoS 탐지와 완화 기능을 제공합니다. Shield Advanced의 보호 대상에는 Application Load Balancer와 Classic Load Balancer가 포함됩니다. Amazon GuardDuty는 계정과 워크로드의 위협 탐지 서비스이고, Amazon Inspector는 워크로드의 취약성 관리 서비스입니다. Amazon Route 53은 AWS의 권한 있는 DNS 서비스입니다.","choicesAnalysis":"보호해야 할 공개 진입 지점은 ELB이며, DNS는 Route 53이 아닌 타사 서비스에서 관리됩니다. 따라서 Route 53 연결을 전제로 하는 구성보다 ELB를 직접 보호 대상으로 등록하는 Shield Advanced 구성이 요구사항에 부합합니다. GuardDuty와 Inspector는 DDoS 완화 서비스가 아닙니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 Amazon GuardDuty는 잠재적 보안 위협을 탐지하지만 ELB에 대한 대규모 DDoS 공격을 완화하는 서비스가 아니므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B의 Amazon Inspector는 EC2 워크로드의 소프트웨어 취약성을 평가하므로 DDoS 공격 탐지 및 보호 요구사항에 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 Route 53을 보호 대상으로 사용하지만 회사는 타사 DNS를 사용하므로 현재 공개 진입 지점의 요구사항에 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"D는 AWS Shield Advanced에서 ELB를 보호 대상으로 지정하여 대규모 DDoS 공격의 탐지와 완화 기능을 제공하므로 적합합니다."}}},{"id":"Q0036","question_number":36,"question":"회사는 AWS 클라우드에서 애플리케이션을 구축하고 있습니다. 애플리케이션은 두 AWS 리전의 Amazon S3 버킷에 데이터를 저장합니다. 회사는 AWS Key Management Service(AWS KMS) 고객 관리형 키를 사용하여 S3 버킷에 저장된 모든 데이터를 암호화해야 합니다. 두 S3 버킷의 데이터는 동일한 KMS 키로 암호화 및 복호화해야 합니다. 데이터와 키는 두 지역 각각에 저장되어야 합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"각 리전에서 S3 버킷을 생성합니다. Amazon S3 관리형 암호화 키(SSE-S3)와 함께 서버 측 암호화를 사용하도록 S3 버킷을 구성합니다. S3 버킷 간의 복제를 구성합니다.","B":"고객 관리형 다중 지역 KMS 키를 생성합니다. 각 리전에서 S3 버킷을 생성합니다. S3 버킷 간의 복제를 구성합니다. 클라이언트 측 암호화와 함께 KMS 키를 사용하도록 애플리케이션을 구성합니다.","C":"각 리전에서 고객 관리형 KMS 키와 S3 버킷을 생성합니다. Amazon S3 관리형 암호화 키(SSE-S3)와 함께 서버 측 암호화를 사용하도록 S3 버킷을 구성합니다. S3 버킷 간의 복제를 구성합니다.","D":"각 리전에서 고객 관리형 KMS 키와 S3 버킷을 생성합니다. AWS KMS 키(SSE-KMS)로 서버 측 암호화를 사용하도록 S3 버킷을 구성합니다. S3 버킷 간의 복제를 구성합니다."},"answers":["B"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["AWS KMS","Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 두 AWS 리전의 S3 버킷에 저장되는 모든 데이터를 고객 관리형 AWS KMS 키로 암호화해야 합니다. 두 리전의 데이터는 동일한 키 계열로 암호화 및 복호화할 수 있어야 하며, 데이터와 키가 각 리전에 존재해야 합니다. 리전 간 복제를 구성하면서 키 관리와 애플리케이션 운영 부담을 최소화하는 방식이 필요합니다.","awsServicesAnalysis":"AWS KMS 다중 리전 키는 한 리전의 기본 키와 다른 리전의 복제 키로 구성되며, 관련 키는 동일한 키 ID와 키 자료를 공유합니다. 각 관련 키는 해당 리전에서 암호화 및 복호화 작업에 사용할 수 있습니다. 클라이언트 측 암호화는 애플리케이션이 데이터를 S3에 업로드하기 전에 암호화합니다. Amazon S3 교차 리전 복제는 한 버킷의 객체를 다른 리전 버킷으로 비동기 복제합니다. SSE-S3는 Amazon S3 관리형 키를 사용하고, SSE-KMS는 AWS KMS 키를 사용하여 S3에서 서버 측 암호화를 수행합니다.","choicesAnalysis":"동일한 키 자료를 두 리전에 배치해 리전별로 암호화와 복호화를 수행하려면 관련된 다중 리전 키가 필요합니다. 클라이언트 측에서 이를 사용하면 객체가 S3에 저장되기 전부터 암호화되며, 교차 리전 복제는 두 리전에 데이터를 유지합니다. S3 관리형 키는 고객 관리형 키 요구사항을 충족하지 않고, 각 리전에 독립된 단일 리전 키를 만드는 방식은 동일 키 계열 요구사항을 충족하지 않습니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 SSE-S3를 사용하므로 고객 관리형 AWS KMS 키로 데이터를 암호화해야 하는 요구사항에 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 고객 관리형 다중 리전 KMS 키와 클라이언트 측 암호화를 사용하고 S3 교차 리전 복제로 데이터를 두 리전에 유지하므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 고객 관리형 KMS 키를 만들지만 실제 S3 암호화에는 SSE-S3를 사용하므로 요구사항에 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 각 리전에 독립적인 고객 관리형 KMS 키를 사용하므로 두 리전의 데이터를 동일한 키 계열로 암호화 및 복호화하는 요구사항에 적합하지 않습니다."}}},{"id":"Q0037","question_number":37,"question":"한 회사는 최근 AWS 계정의 Amazon EC2 인스턴스에서 다양한 새로운 워크로드를 출시했습니다. 회사는 인스턴스에 원격으로 안전하게 액세스하고 관리하는 전략을 수립해야 합니다. 회사는 기본 AWS 서비스와 함께 작동하고 AWS Well-Architected 프레임워크를 따르는 반복 가능한 프로세스를 구현해야 합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"EC2 직렬 콘솔을 사용하여 관리를 위해 각 인스턴스의 터미널 인터페이스에 직접 액세스합니다.","B":"각 기존 인스턴스와 새 인스턴스에 적절한 IAM 역할을 연결합니다. AWS Systems Manager Session Manager 를 사용하여 원격 SSH 세션을 설정합니다.","C":"관리 SSH 키 쌍을 만듭니다. 공개 키를 각 EC2 인스턴스에 로드합니다. 퍼블릭 서브넷에 배스천 호스트를 배포하여 각 인스턴스의 관리를 위한 터널을 제공합니다.","D":"AWS Site-to-Site VPN 연결을 설정합니다. 관리자에게 로컬 온프레미스 머신을 사용하여 VPN 터널에서 SSH 키를 사용하여 인스턴스에 직접 연결하도록 지시합니다."},"answers":["B"],"content_domain":"보안 아키텍처 설계","content_task":"AWS 리소스에 대한 보안 액세스 설계","aws_services":["IAM","AWS Systems Manager"],"explanation":{"requirementsAnalysis":"회사는 새로 배포한 여러 Amazon EC2 인스턴스에 원격으로 안전하게 접근하고 관리할 반복 가능한 절차를 마련해야 합니다. 이 절차는 기본 AWS 서비스와 연동되고 AWS Well-Architected 프레임워크의 보안 원칙을 따라야 합니다. 인바운드 관리 경로와 별도 관리 인프라를 최소화해 운영 부담을 낮추는 구성이 필요합니다.","awsServicesAnalysis":"AWS Systems Manager Session Manager는 관리형 노드에 대해 콘솔 또는 AWS CLI 기반의 보안 대화형 세션을 제공합니다. Session Manager를 사용하려면 인스턴스에 Systems Manager Agent가 설치되어 있고, 인스턴스 프로파일의 IAM 역할 및 Systems Manager 서비스 연결이 구성되어야 합니다. Session Manager는 인바운드 포트를 열거나 배스천 호스트를 운영하지 않고도 세션을 제공할 수 있습니다. EC2 직렬 콘솔은 인스턴스의 직렬 포트 연결을 제공하며, AWS Site-to-Site VPN은 온프레미스 네트워크와 VPC 간의 암호화된 네트워크 연결을 제공합니다.","choicesAnalysis":"여러 인스턴스에 일관되게 적용하면서 인바운드 SSH 노출과 관리 서버를 줄이려면 IAM 역할과 Systems Manager의 관리형 세션 기능을 사용해야 합니다. 배스천 호스트, SSH 키 배포 또는 온프레미스 VPN을 중심으로 한 방식은 추가 인프라와 키 관리 절차를 만듭니다. 직렬 콘솔은 일반적인 반복 원격 관리 방식이 아닙니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 EC2 직렬 콘솔은 특정 인스턴스의 콘솔 수준 문제 해결에 사용할 수 있지만, 여러 인스턴스의 반복적인 원격 관리 전략으로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 인스턴스 역할과 AWS Systems Manager Session Manager를 사용하여 인바운드 SSH 포트나 배스천 호스트 없이 안전한 원격 세션을 제공하므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 관리 SSH 키와 배스천 호스트를 배포하고 유지해야 하므로 Session Manager 기반 방식보다 운영 부담과 공격 표면이 큽니다."},"D":{"isCorrect":false,"explanation":"D는 Site-to-Site VPN, 온프레미스 연결 및 SSH 키 관리가 필요하므로 기본 AWS 관리 서비스만으로 운영 부담을 최소화하는 요구사항에 적합하지 않습니다."}}},{"id":"Q0038","question_number":38,"question":"회사는 Amazon S3 에서 정적 웹 사이트를 호스팅하고 DNS 에 Amazon Route 53 을 사용하고 있습니다. 웹 사이트는 전 세계적으로 수요가 증가하고 있습니다. 회사는 웹 사이트에 액세스하는 사용자의 대기 시간을 줄여야 합니다. 어떤 솔루션이 이러한 요구 사항을 가장 비용 효율적으로 충족합니까?","choices":{"A":"웹 사이트가 포함된 S3 버킷을 모든 AWS 리전에 복제합니다. Route 53 지리적 위치 라우팅 항목을 추가합니다.","B":"AWS Global Accelerator 에서 액셀러레이터를 프로비저닝합니다. 제공된 IP 주소를 S3 버킷과 연결합니다. 액셀러레이터의 IP 주소를 가리키도록 Route 53 항목을 편집합니다.","C":"S3 버킷 앞에 Amazon CloudFront 배포를 추가합니다. CloudFront 배포를 가리키도록 Route 53 항목을 편집합니다.","D":"버킷에서 S3 Transfer Acceleration 을 활성화합니다. 새 엔드포인트를 가리키도록 Route 53 항목을 편집합니다."},"answers":["C"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 네트워크 아키텍처 결정","aws_services":["Amazon CloudFront","Amazon Route 53","Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 Amazon S3에서 정적 웹사이트를 제공하고 Amazon Route 53으로 DNS를 관리하고 있습니다. 전 세계 사용자가 증가하므로 각 사용자가 콘텐츠를 받는 대기 시간을 낮춰야 합니다. 솔루션은 정적 콘텐츠를 효율적으로 전 세계에 배포하면서 비용을 합리적으로 유지해야 합니다.","awsServicesAnalysis":"Amazon CloudFront는 콘텐츠를 전 세계 엣지 로케이션에서 캐시하고 제공하는 콘텐츠 전송 네트워크입니다. Amazon S3 버킷은 CloudFront 배포의 오리진으로 사용할 수 있습니다. Amazon Route 53은 CloudFront 배포를 가리키는 DNS 레코드를 구성할 수 있습니다. AWS Global Accelerator는 정적 Anycast IP 주소를 제공하고 지원되는 엔드포인트로 트래픽을 라우팅합니다. S3 Transfer Acceleration은 S3 버킷으로 또는 버킷에서 장거리 객체 전송을 가속하는 기능입니다.","choicesAnalysis":"전 세계 정적 웹사이트의 읽기 지연 시간을 줄이려면 사용자와 가까운 위치에서 콘텐츠를 캐시해 제공하는 CDN이 필요합니다. CloudFront는 기존 S3 오리진을 유지한 채 이 기능을 제공하므로 리전별 버킷 복제보다 구성과 비용 측면에서 효율적입니다. 전송 가속은 웹 콘텐츠 캐싱 기능이 아니며, Global Accelerator는 S3 정적 웹사이트의 적절한 엔드포인트 방식이 아닙니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 모든 리전에 S3 버킷을 복제하고 라우팅 정책을 운영해야 하므로 CloudFront 캐시 배포보다 비용과 관리 부담이 큽니다."},"B":{"isCorrect":false,"explanation":"B는 AWS Global Accelerator의 IP 주소를 S3 버킷에 직접 연결할 수 없으므로 정적 웹사이트의 대기 시간 개선 방식으로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 CloudFront가 S3 콘텐츠를 전 세계 엣지 로케이션에 캐시하고 Route 53이 배포를 가리키도록 구성하므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D의 S3 Transfer Acceleration은 S3 객체 전송 경로를 가속할 수 있지만 정적 웹사이트 콘텐츠를 엣지에서 캐시하여 제공하지 않으므로 적합하지 않습니다."}}},{"id":"Q0039","question_number":39,"question":"회사는 웹 사이트에서 검색 가능한 항목 저장소를 유지 관리합니다. 데이터는 천만 개 이상의 행이 포함된 Amazon RDS for MySQL 데이터베이스 테이블에 저장됩니다. 데이터베이스에는 2TB 의 범용 SSD 스토리지가 있습니다. 회사 웹 사이트를 통해 이 데이터에 대한 수백만 건의 업데이트가 매일 있습니다. 이 회사는 일부 삽입 작업이 10 초 이상 걸리는 것을 확인했습니다. 회사는 데이터베이스 스토리지 성능이 문제라고 판단했습니다. 이 성능 문제를 해결하는 솔루션은 무엇입니까?","choices":{"A":"스토리지 유형을 프로비저닝된 IOPS SSD 로 변경합니다.","B":"DB 인스턴스를 메모리 최적화 인스턴스 클래스로 변경합니다.","C":"DB 인스턴스를 버스트 가능한 성능 인스턴스 클래스로 변경합니다.","D":"MySQL 기본 비동기 복제로 다중 AZ RDS 읽기 전용 복제본을 활성화합니다."},"answers":["A"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터베이스 솔루션 결정","aws_services":["Amazon RDS"],"explanation":{"requirementsAnalysis":"회사는 Amazon RDS for MySQL의 대규모 테이블에 대해 매일 수백만 건의 업데이트를 처리합니다. 일부 삽입 작업이 10초 이상 걸리며, 원인은 데이터베이스 스토리지 성능으로 확인되었습니다. 따라서 높은 쓰기 I/O 수요에서 예측 가능한 스토리지 성능을 제공하는 구성이 필요합니다.","awsServicesAnalysis":"Amazon RDS는 범용 SSD 스토리지와 프로비저닝된 IOPS SSD 스토리지를 제공합니다. 프로비저닝된 IOPS SSD는 I/O 집약적 데이터베이스 워크로드에 대해 지정한 IOPS 성능을 제공합니다. 메모리 최적화 인스턴스 클래스는 더 많은 메모리를 제공하고, 버스트 가능 인스턴스 클래스는 CPU 크레딧 모델을 사용합니다. RDS 읽기 전용 복제본은 읽기 트래픽을 분산할 수 있으며 MySQL 복제본은 비동기 복제를 사용할 수 있습니다.","choicesAnalysis":"확인된 병목은 스토리지 성능이며, 대량 업데이트와 삽입은 지속적인 쓰기 I/O를 생성합니다. 이 경우 데이터베이스의 스토리지 IOPS를 명시적으로 확보하는 구성이 병목 원인을 직접 해결합니다. 인스턴스 메모리나 CPU 특성을 바꾸거나 읽기 복제본을 추가하는 것은 스토리지 쓰기 I/O 성능을 보장하지 않습니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 프로비저닝된 IOPS SSD로 변경하여 I/O 집약적인 쓰기 워크로드에 필요한 예측 가능한 스토리지 성능을 제공하므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 메모리 용량을 늘릴 수 있지만 확인된 스토리지 I/O 병목을 직접 해결하지 않으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 CPU 버스트 요구에 대응하는 인스턴스 클래스이므로 지속적인 데이터베이스 스토리지 성능 문제에 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 읽기 작업을 복제본으로 분산할 수 있지만 기본 DB 인스턴스의 삽입과 업데이트에 대한 스토리지 I/O 병목을 해결하지 못합니다."}}},{"id":"Q0040","question_number":40,"question":"회사에는 매일 1TB 의 상태 알림을 집합적으로 생성하는 수천 개의 에지 장치가 있습니다. 각 경고의 크기는 약 2KB 입니다. 솔루션 설계자는 향후 분석을 위해 경고를 수집하고 저장하는 솔루션을 구현해야 합니다. 회사는 고가용성 솔루션을 원합니다. 그러나 회사는 비용을 최소화해야 하며 추가 인프라 관리를 원하지 않습니다. 또한 회사는 즉각적인 분석을 위해 14 일 동안의 데이터를 유지하고 14 일이 지난 데이터를 보관하기를 원합니다. 이러한 요구 사항을 충족하는 가장 운영 효율성이 높은 솔루션은 무엇입니까?","choices":{"A":"Amazon Kinesis Data Firehose 전송 스트림을 생성하여 알림을 수집합니다. Amazon S3 버킷에 알림을 전달하도록 Kinesis Data Firehose 스트림을 구성합니다. 14 일 후에 데이터를 Amazon S3 Glacier 로 전환하도록 S3 수명 주기 구성을 설정합니다.","B":"두 가용 영역에서 Amazon EC2 인스턴스를 시작하고 Elastic Load Balancer 뒤에 배치하여 알림을 수집합니다. Amazon S3 버킷에 경고를 저장할 EC2 인스턴스에 대한 스크립트를 생성합니다. 14 일 후에 데이터를 Amazon S3 Glacier 로 전환하도록 S3 수명 주기 구성을 설정합니다.","C":"Amazon Kinesis Data Firehose 전송 스트림을 생성하여 알림을 수집합니다. Amazon OpenSearch Service(Amazon Elasticsearch Service) 클러스터에 알림을 전달하도록 Kinesis Data Firehose 스트림을 구성합니다. Amazon OpenSearch Service(Amazon Elasticsearch Service) 클러스터를 설정하여 매일 수동 스냅샷을 만들고 클러스터에서 14 일이 지난 데이터를 삭제합니다.","D":"Amazon Simple Queue Service(Amazon SQS) 표준 대기열을 생성하여 알림을 수집하고 메시지 보존 기간을 14 일로 설정합니다. SQS 대기열을 폴링하고, 메시지의 수명을 확인하고, 필요에 따라 메시지 데이터를 분석하도록 소비자를 구성합니다. 메시지가 14 일이 지난 경우 소비자는 메시지를 Amazon S3 버킷에 복사하고 SQS 대기열에서 메시지를 삭제해야 합니다."},"answers":["A"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 스토리지 솔루션 설계","aws_services":["Amazon Data Firehose","Amazon S3","Amazon S3 Glacier"],"explanation":{"requirementsAnalysis":"수천 개의 에지 장치는 하루 총 1TB의 약 2KB 상태 알림을 생성합니다. 회사는 이 알림을 고가용성으로 수집하고 향후 분석을 위해 저장해야 하며, 별도 인프라를 관리하지 않으면서 비용을 최소화해야 합니다. 최근 14일 데이터는 즉시 분석할 수 있어야 하고, 그 이후 데이터는 장기 보관해야 합니다. 따라서 대량 스트리밍 수집, 내구성 있는 저장소 및 기간 기반 스토리지 전환이 필요합니다.","awsServicesAnalysis":"Amazon Data Firehose는 스트리밍 데이터를 수집해 지정된 대상으로 전달하는 완전관리형 서비스입니다. Amazon S3는 높은 내구성의 객체 스토리지이며, S3 수명 주기 구성은 객체를 정의된 기간 후 다른 스토리지 클래스로 전환할 수 있습니다. S3 Glacier 스토리지 클래스는 장기 아카이브에 사용됩니다. Amazon EC2와 Elastic Load Balancing은 애플리케이션 수집 계층을 구성할 수 있고, Amazon OpenSearch Service는 검색과 분석을 위한 관리형 클러스터 서비스입니다. Amazon SQS 표준 대기열의 메시지 보존 기간은 최대 14일입니다.","choicesAnalysis":"관리형 스트리밍 전송 서비스로 알림을 S3에 지속적으로 적재하면 서버나 클러스터를 운영하지 않고 대량 데이터를 수집할 수 있습니다. S3에 저장된 최근 데이터는 분석에 사용할 수 있고, 수명 주기 규칙으로 14일 뒤 Glacier 스토리지 클래스로 자동 전환할 수 있습니다. EC2 소비자, OpenSearch 클러스터 또는 SQS 폴링 로직은 관리 대상이나 추가 처리 코드를 늘립니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 Amazon Data Firehose로 알림을 S3에 전달하고 S3 수명 주기 규칙으로 14일 후 Glacier로 자동 전환하므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 고가용성 EC2 수집 계층과 스크립트를 직접 운영해야 하므로 추가 인프라 관리가 필요해 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 Amazon OpenSearch Service 클러스터와 수동 스냅샷 운영이 필요하며, 비용 최소화와 운영 효율성 요구사항에 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 SQS 메시지가 최대 14일까지만 보존되고, 소비자가 수명과 분석 및 S3 복사를 직접 처리해야 하므로 적합하지 않습니다."}}},{"id":"Q0041","question_number":41,"question":"회사의 애플리케이션은 데이터 수집을 위해 여러 SaaS(Software-as-a-Service) 소스와 통합됩니다. 이 회사는 Amazon EC2 인스턴스를 실행하여 데이터를 수신하고 분석을 위해 데이터를 Amazon S3 버킷에 업로드합니다. 데이터를 수신하고 업로드하는 동일한 EC2 인스턴스도 업로드가 완료되면 사용자에게 알림을 보냅니다. 회사는 느린 응용 프로그램 성능을 발견했으며 가능한 한 성능을 개선하려고 합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"EC2 인스턴스가 확장할 수 있도록 Auto Scaling 그룹을 생성합니다. S3 버킷에 업로드가 완료되면 Amazon Simple Notification Service(Amazon SNS) 주제에 이벤트를 보내도록 S3 이벤트 알림을 구성합니다.","B":"Amazon AppFlow 흐름을 생성하여 각 SaaS 소스와 S3 버킷 간에 데이터를 전송합니다. S3 버킷에 업로드가 완료되면 Amazon Simple Notification Service(Amazon SNS) 주제에 이벤트를 보내도록 S3 이벤트 알림을 구성합니다.","C":"각 SaaS 소스에 대해 Amazon EventBridge(Amazon CloudWatch Events) 규칙을 생성하여 출력 데이터를 보냅니다. S3 버킷을 규칙의 대상으로 구성합니다. S3 버킷에 업로드가 완료되면 이벤트를 전송하는 두 번째 EventBridge(Cloud Watch Events) 규칙을 생성합니다. Amazon Simple Notification Service(Amazon SNS) 주제를 두 번째 규칙의 대상으로 구성합니다.","D":"EC2 인스턴스 대신 사용할 Docker 컨테이너를 생성합니다. Amazon Elastic Container Service(Amazon ECS)에서 컨테이너화된 애플리케이션을 호스팅합니다. S3 버킷에 업로드가 완료되면 Amazon Simple Notification Service(Amazon SNS) 주제에 이벤트를 보내도록 Amazon CloudWatch Container Insights 를 구성합니다."},"answers":["B"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터 수집 및 변환 솔루션 결정","aws_services":["Amazon AppFlow","Amazon S3","Amazon SNS"],"explanation":{"requirementsAnalysis":"회사는 여러 SaaS 소스에서 데이터를 수신하여 Amazon S3에 저장하고, 업로드 완료 시 사용자에게 알려야 합니다. 현재 EC2 인스턴스가 수신, 업로드, 알림까지 함께 처리하므로 애플리케이션 성능 저하를 줄여야 합니다. 따라서 SaaS 데이터 전송과 완료 알림을 관리형 서비스로 분리하여 컴퓨팅 부담과 운영 작업을 최소화하는 구성이 필요합니다.","awsServicesAnalysis":"Amazon AppFlow는 지원되는 SaaS 애플리케이션과 AWS 서비스 간 데이터를 관리형으로 전송하는 통합 서비스이며 Amazon S3를 대상으로 흐름을 구성할 수 있습니다. Amazon S3 이벤트 알림은 객체 생성 같은 이벤트를 Amazon SNS 주제로 게시할 수 있습니다. Amazon SNS는 주제 구독자에게 알림을 팬아웃합니다. Auto Scaling은 EC2 용량을 조정하며, Amazon EventBridge는 이벤트를 규칙과 대상으로 라우팅합니다. Amazon ECS는 컨테이너를 실행하고 CloudWatch Container Insights는 컨테이너 환경의 모니터링 데이터를 수집합니다.","choicesAnalysis":"핵심은 기존 EC2에서 수행하던 SaaS 통합과 파일 전송 작업을 제거하면서, S3 업로드 완료를 기준으로 알림을 계속 제공하는 것입니다. SaaS별 연결과 S3 전송을 관리형 흐름으로 처리하면 인스턴스의 처리 부담과 통합 코드의 운영 부담을 함께 줄일 수 있습니다. S3 이벤트 알림과 SNS를 결합하면 업로드 완료 후 알림 경로도 분리됩니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 EC2 용량을 확장하고 S3 완료 알림을 분리할 수 있습니다. 그러나 SaaS 데이터 수신과 S3 업로드는 계속 EC2에서 처리하므로 애플리케이션의 처리 부담과 통합 운영을 근본적으로 줄이지 못합니다."},"B":{"isCorrect":true,"explanation":"B는 Amazon AppFlow가 지원 SaaS 소스에서 S3로의 데이터 전송을 관리형으로 수행하고, S3 이벤트 알림과 SNS로 완료 알림을 분리합니다. EC2에서 데이터 수신과 업로드를 제거하여 성능과 운영 오버헤드 요구사항에 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 이벤트를 대상으로 라우팅하는 구조를 만들 수 있지만, 모든 SaaS 소스의 대용량 데이터 전송을 일반 EventBridge 규칙으로 처리하는 방식은 지원되는 SaaS 데이터 통합을 관리형으로 제공하는 AppFlow보다 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 EC2 대신 컨테이너를 사용하지만 SaaS 수신과 S3 업로드 로직을 계속 운영해야 합니다. 또한 Container Insights는 관찰성 기능이지 S3 객체 업로드 완료 알림을 SNS로 보내는 기능이 아니므로 적합하지 않습니다."}}},{"id":"Q0042","question_number":42,"question":"회사는 단일 VPC 의 Amazon EC2 인스턴스에서 고가용성 이미지 처리 애플리케이션을 실행합니다. EC2 인스턴스는 여러 가용 영역의 여러 서브넷 내에서 실행됩니다. EC2 인스턴스는 서로 통신하지 않습니다. 그러나 EC2 인스턴스는 Amazon S3 에서 이미지를 다운로드하고 단일 NAT 게이트웨이를 통해 Amazon S3 에 이미지를 업로드합니다. 회사는 데이터 전송 요금에 대해 우려하고 있습니다. 회사가 지역 데이터 전송 요금을 피할 수 있는 가장 비용 효율적인 방법은 무엇입니까?","choices":{"A":"각 가용 영역에서 NAT 게이트웨이를 시작합니다.","B":"NAT 게이트웨이를 NAT 인스턴스로 교체합니다.","C":"Amazon S3 용 게이트웨이 VPC 엔드포인트를 배포합니다.","D":"EC2 인스턴스를 실행할 EC2 전용 호스트를 프로비저닝합니다."},"answers":["C"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 네트워크 아키텍처 설계","aws_services":["Amazon VPC","Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 여러 가용 영역의 EC2 인스턴스가 Amazon S3와 데이터를 주고받는 환경에서 지역 데이터 전송 요금을 줄여야 합니다. 현재 단일 NAT 게이트웨이를 거치므로 다른 가용 영역의 인스턴스 트래픽에는 교차 가용 영역 경로가 생길 수 있습니다. 가장 비용 효율적인 방법은 인터넷 또는 NAT 경로를 사용하지 않고 VPC에서 S3로 직접 연결하는 것입니다.","awsServicesAnalysis":"Amazon S3용 게이트웨이 VPC 엔드포인트는 VPC 라우팅 테이블에 S3 서비스 접두사 목록 경로를 추가하여 S3 트래픽을 AWS 네트워크로 사설 연결합니다. 게이트웨이 엔드포인트 자체에는 시간당 요금이나 데이터 처리 요금이 없습니다. NAT 게이트웨이는 프라이빗 서브넷의 아웃바운드 연결을 제공하며 시간당 및 처리 데이터 요금이 발생합니다. NAT 인스턴스는 사용자가 가용성, 확장성, 패치 및 장애 조치를 관리해야 합니다. EC2 전용 호스트는 전용 물리 서버 옵션입니다.","choicesAnalysis":"S3는 게이트웨이 엔드포인트를 지원하므로 EC2 인스턴스가 NAT 게이트웨이를 거치지 않고 S3에 접근하도록 라우팅할 수 있습니다. 이 방식은 단일 NAT로 발생할 수 있는 교차 가용 영역 데이터 전송과 NAT 처리 비용을 모두 피하면서 추가 관리 부담도 적습니다. NAT 구성 변경이나 전용 호스트는 S3 접근 경로의 비용 문제를 직접 해결하지 못합니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 각 가용 영역에서 NAT 게이트웨이를 사용하여 교차 가용 영역 NAT 경로를 줄일 수 있습니다. 그러나 S3 트래픽에 NAT 게이트웨이와 그 처리 요금을 계속 사용하므로 게이트웨이 엔드포인트보다 비용 효율적이지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 NAT 게이트웨이 비용을 일부 줄일 수 있으나 NAT 인스턴스의 가용성, 확장, 패치 및 처리량을 관리해야 합니다. 또한 S3 트래픽을 NAT 경로로 처리하는 구조 자체를 제거하지 못합니다."},"C":{"isCorrect":true,"explanation":"C는 S3용 게이트웨이 VPC 엔드포인트를 통해 EC2와 S3 간 트래픽을 VPC에서 직접 라우팅합니다. NAT 게이트웨이와 교차 가용 영역 경로를 피할 수 있고 엔드포인트 추가 요금도 없으므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D의 EC2 전용 호스트는 규정 준수나 소프트웨어 라이선스 요구에 사용하는 전용 물리 서버입니다. S3 데이터 전송 경로나 NAT 비용에는 영향을 주지 않으므로 적합하지 않습니다."}}},{"id":"Q0043","question_number":43,"question":"회사에 Amazon S3 에 백업되는 시간에 민감한 대량의 데이터를 생성하는 온프레미스 애플리케이션이 있습니다. 애플리케이션이 성장했고 인터넷 대역폭 제한에 대한 사용자 불만이 있습니다. 솔루션 설계자는 Amazon S3 에 대한 적시 백업을 허용하고 내부 사용자의 인터넷 연결에 미치는 영향을 최소화하는 장기 솔루션을 설계해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"AWS VPN 연결을 설정하고 VPC 게이트웨이 엔드포인트를 통해 모든 트래픽을 프록시합니다.","B":"새 AWS Direct Connect 연결을 설정하고 이 새 연결을 통해 백업 트래픽을 직접 연결합니다.","C":"매일 AWS Snowball 디바이스를 주문합니다. Snowball 디바이스에 데이터를 로드하고 디바이스를 매일 AWS 로 반환합니다.","D":"AWS Management 콘솔을 통해 지원 티켓을 제출합니다. 계정에서 S3 서비스 제한 제거를 요청합니다."},"answers":["B"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 네트워크 아키텍처 결정","aws_services":["AWS Direct Connect","Amazon S3"],"explanation":{"requirementsAnalysis":"온프레미스 애플리케이션은 시간에 민감한 대량 데이터를 Amazon S3에 백업해야 하며, 인터넷 대역폭 제한으로 내부 사용자의 연결이 영향을 받고 있습니다. 장기적으로 적시에 전송하려면 인터넷과 분리된 예측 가능한 전용 네트워크 대역폭이 필요합니다. 물리적 전송 장비를 반복 운영하지 않으면서 S3에 지속적으로 연결할 수 있어야 합니다.","awsServicesAnalysis":"AWS Direct Connect는 온프레미스 환경과 AWS 간 전용 네트워크 연결을 제공하며, 퍼블릭 가상 인터페이스를 사용해 Amazon S3 같은 AWS 퍼블릭 서비스에 접근할 수 있습니다. AWS Site-to-Site VPN은 인터넷을 통해 암호화된 연결을 제공합니다. S3 게이트웨이 VPC 엔드포인트는 VPC 내부 리소스의 S3 접근에 사용하는 라우팅 기능입니다. AWS Snowball Edge는 물리 장치를 이용한 오프라인 데이터 전송 서비스이지만 2025년 11월 7일부터 신규 고객은 주문할 수 없습니다.","choicesAnalysis":"요구사항은 반복적인 대용량 백업을 인터넷 대역폭과 분리해 장기적으로 처리하는 것입니다. Direct Connect는 전용 연결을 통해 일관된 전송 경로를 제공하므로 인터넷 병목과 내부 사용자의 영향을 줄일 수 있습니다. VPN은 여전히 인터넷 연결에 의존하고 물리 장치를 매일 배송하는 방식은 시간에 민감한 지속 백업에 맞지 않습니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"VPN은 인터넷을 통과하므로 인터넷 대역폭 제한과 내부 사용자 영향이라는 문제를 해소하지 못합니다. S3 게이트웨이 엔드포인트도 온프레미스 백업에 전용 회선을 제공하지 않으므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"AWS Direct Connect로 온프레미스와 AWS 사이에 전용 네트워크 경로를 구성하고 해당 경로로 S3 백업 트래픽을 전송합니다. 대량의 시간 민감한 백업을 지속 처리하면서 인터넷 연결 영향을 줄일 수 있으므로 적합합니다."},"C":{"isCorrect":false,"explanation":"물리 장치를 매일 주문, 적재 및 반송하는 절차는 시간에 민감한 지속 백업에 적합하지 않습니다. 현재 신규 고객은 Snowball Edge를 주문할 수도 없으므로 장기 솔루션이 될 수 없습니다."},"D":{"isCorrect":false,"explanation":"S3 서비스 한도 조정은 온프레미스 인터넷 회선의 대역폭 제약을 해결하지 못하므로 적합하지 않습니다."}}},{"id":"Q0044","question_number":44,"question":"회사에 중요한 데이터가 포함된 Amazon S3 버킷이 있습니다. 회사는 우발적인 삭제로부터 데이터를 보호해야 합니다. 이러한 요구 사항을 충족하기 위해 솔루션 설계자는 어떤 단계 조합을 취해야 합니까? (2 개를 선택하세요.)","choices":{"A":"S3 버킷에서 버전 관리를 활성화합니다.","B":"S3 버킷에서 MFA 삭제를 활성화합니다.","C":"S3 버킷에 버킷 정책을 생성합니다.","D":"S3 버킷에서 기본 암호화를 활성화합니다.","E":"S3 버킷의 객체에 대한 수명 주기 정책을 생성합니다."},"answers":["A","B"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 Amazon S3 버킷의 중요 데이터를 우발적인 삭제로부터 보호해야 합니다. 삭제된 객체를 복구할 수 있어야 하며, 버전이나 버전 관리 상태를 영구적으로 삭제·변경하는 민감한 작업도 강하게 통제해야 합니다. 따라서 복구 기능과 삭제 방지 제어를 함께 적용해야 합니다.","awsServicesAnalysis":"S3 버전 관리는 동일한 객체 키의 여러 버전을 유지하여 삭제 마커가 생성되거나 객체가 덮어써져도 이전 버전을 복원할 수 있게 합니다. S3 MFA 삭제는 영구 객체 버전 삭제와 버전 관리 상태 변경에 MFA 인증 코드를 요구하는 추가 제어입니다. MFA 삭제의 구성·해제에는 루트 사용자 자격 증명이 필요합니다. 버킷 정책은 접근 권한을 제어하고, 기본 암호화는 저장 데이터 암호화를 적용하며, 수명 주기 규칙은 객체 전환 또는 만료를 자동화합니다.","choicesAnalysis":"우발적 삭제 후 복구하려면 객체의 이전 버전을 남겨야 하므로 버전 관리가 필요합니다. 여기에 MFA 삭제를 적용하면 영구 삭제와 버전 관리 비활성화 같은 작업에 별도 인증을 요구해 실수나 권한 오용의 위험을 줄일 수 있습니다. 접근 제어 또는 암호화만으로는 삭제된 객체의 복구를 보장하지 않습니다. 따라서 A와 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 S3 버전 관리를 활성화하여 삭제 마커가 생성되거나 객체가 덮어써진 경우에도 이전 객체 버전을 보존합니다. 우발적으로 삭제된 데이터를 복구할 수 있으므로 적합합니다."},"B":{"isCorrect":true,"explanation":"B는 MFA 삭제로 영구 객체 버전 삭제와 버전 관리 상태 변경에 MFA를 요구합니다. 버전 관리와 함께 사용하면 중요 데이터의 우발적 또는 무단 영구 삭제를 줄일 수 있으므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C의 버킷 정책은 삭제 권한을 제한할 수 있지만, 단독으로는 허용된 사용자의 실수로 삭제된 객체를 복구하지 못합니다. 복구와 삭제 방지를 함께 요구하는 이 문제의 완전한 해법은 아닙니다."},"D":{"isCorrect":false,"explanation":"D의 기본 암호화는 S3에 저장되는 객체를 암호화하지만 객체 삭제 방지나 삭제 후 복구 기능을 제공하지 않습니다. 따라서 요구사항에 적합하지 않습니다."},"E":{"isCorrect":false,"explanation":"E의 수명 주기 정책은 객체의 스토리지 클래스 전환이나 만료 삭제를 자동화합니다. 우발적인 삭제를 복구하거나 영구 삭제를 방지하는 제어가 아니므로 적합하지 않습니다."}}},{"id":"Q0045","question_number":45,"question":"회사에는 다음으로 구성된 데이터 수집 워크플로가 있습니다. • 새로운 데이터 전송에 대한 알림을 위한 Amazon Simple Notification Service(Amazon SNS) 주제 • 데이터를 처리하고 메타데이터를 기록하는 AWS Lambda 함수 회사는 네트워크 연결 문제로 인해 수집 워크플로가 때때로 실패하는 것을 관찰했습니다. 이러한 장애가 발생하면 회사에서 수동으로 작업을 다시 실행하지 않는 한 Lambda 함수는 해당 데이터를 수집하지 않습니다. Lambda 함수가 향후 모든 데이터를 수집하도록 하려면 솔루션 설계자가 취해야 하는 작업 조합은 무엇입니까? (2 개를 선택하세요.)","choices":{"A":"여러 가용 영역에 Lambda 함수를 배포합니다.","B":"Amazon Simple Queue Service(Amazon SQS) 대기열을 생성하고 SNS 주제를 구독합니다.","C":"Lambda 함수에 할당된 CPU 와 메모리를 늘립니다.","D":"Lambda 함수에 대해 프로비저닝된 처리량을 늘립니다.","E":"Amazon Simple Queue Service(Amazon SQS) 대기열에서 읽도록 Lambda 함수를 수정합니다."},"answers":["B","E"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon SNS","Amazon SQS","AWS Lambda"],"explanation":{"requirementsAnalysis":"회사는 SNS 알림으로 시작되는 데이터 수집 워크플로에서 일시적인 네트워크 문제에도 모든 데이터를 결국 처리해야 합니다. 현재 Lambda 함수가 실패하면 수동 재실행 전에는 데이터를 수집하지 못하므로, 이벤트를 내구성 있게 보관하고 Lambda가 실패 후 다시 처리할 수 있는 분리 계층이 필요합니다. 생산자와 소비자를 느슨하게 결합하여 일시 장애를 흡수해야 합니다.","awsServicesAnalysis":"Amazon SNS는 메시지를 여러 구독 대상으로 게시하는 관리형 게시/구독 서비스입니다. Amazon SQS는 메시지를 보존하는 관리형 대기열이며, SNS 주제를 SQS 대기열에 구독시킬 수 있습니다. AWS Lambda는 SQS를 이벤트 소스로 사용하여 대기열 메시지를 배치로 폴링하고 처리 성공 후 삭제합니다. 처리 실패한 메시지는 가시성 제한 시간과 재시도 정책에 따라 다시 처리될 수 있습니다. Lambda는 여러 가용 영역에 걸쳐 관리형으로 실행됩니다.","choicesAnalysis":"SNS와 Lambda 사이에 SQS를 두면 SNS 메시지가 대기열에 보존되고, 네트워크 장애나 Lambda 처리 실패 동안 소비가 지연되어도 데이터가 유실되지 않습니다. 이어서 Lambda가 SQS에서 읽도록 구성해야 대기열 기반 재시도와 비동기 처리가 완성됩니다. 컴퓨팅 용량을 늘리거나 가용 영역을 지정하는 것은 메시지 내구성 문제를 해결하지 못합니다. 따라서 B와 E가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 Lambda의 배포 가용 영역을 사용자가 지정하는 방식이 아니며, Lambda는 서비스가 여러 가용 영역에서 관리합니다. 메시지를 보존하거나 실패한 데이터를 재처리하는 구성을 제공하지 못하므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 SNS 주제의 메시지를 SQS 대기열에 내구성 있게 전달하여 소비자 장애 동안에도 데이터를 보존합니다. Lambda와 생산자를 분리하는 데 필요하므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 Lambda의 처리 성능에 영향을 줄 수 있지만 네트워크 장애로 전달 또는 처리하지 못한 메시지를 보존하지 않습니다. 따라서 모든 데이터를 결국 수집해야 하는 요구사항에 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 Lambda에 직접 설정하는 처리량 옵션이 아니며, 처리량 증가만으로는 실패한 메시지를 저장하거나 재시도할 수 없습니다. 따라서 적합하지 않습니다."},"E":{"isCorrect":true,"explanation":"E는 Lambda가 SQS 이벤트 소스에서 메시지를 처리하도록 하여 실패한 메시지의 재시도와 비동기 소비를 가능하게 합니다. B의 대기열 구독과 결합하면 데이터 수집의 복원력이 높아지므로 적합합니다."}}},{"id":"Q0046","question_number":46,"question":"회사에 매장에 마케팅 서비스를 제공하는 애플리케이션이 있습니다. 서비스는 매장 고객의 이전 구매를 기반으로 합니다. 상점은 SFTP 를 통해 거래 데이터를 회사에 업로드하고 데이터를 처리 및 분석하여 새로운 마케팅 제안을 생성합니다. 일부 파일의 크기는 200GB 를 초과할 수 있습니다. 최근에 회사는 일부 상점에서 포함되어서는 안 되는 개인 식별 정보(PII)가 포함된 파일을 업로드했음을 발견했습니다. 회사는 PII 가 다시 공유될 경우 관리자에게 경고를 주기를 원합니다. 회사는 또한 문제 해결을 자동화하기를 원합니다. 최소한의 개발 노력으로 이러한 요구 사항을 충족하기 위해 솔루션 설계자는 무엇을 해야 합니까?","choices":{"A":"Amazon S3 버킷을 보안 전송 지점으로 사용하십시오. Amazon Inspector 를 사용하여 버킷의 객체를 스캔합니다. 객체에 PII 가 포함된 경우 S3 수명 주기 정책을 트리거하여 PII 가 포함된 객체를 제거합니다.","B":"Amazon S3 버킷을 보안 전송 지점으로 사용합니다. Amazon Macie 를 사용하여 버킷의 객체를 스캔합니다. 객체에 PII 가 포함된 경우 Amazon Simple Notification Service(Amazon SNS)를 사용하여 관리자에게 PII 가 포함된 객체를 제거하라는 알림을 트리거합니다.","C":"AWS Lambda 함수에서 사용자 지정 스캔 알고리즘을 구현합니다. 객체가 버킷에 로드될 때 함수를 트리거합니다. 객체에 PII 가 포함된 경우 Amazon Simple Notification Service(Amazon SNS)를 사용하여 관리자에게 PII 가 포함된 객체를 제거하라는 알림을 트리거합니다.","D":"AWS Lambda 함수에서 사용자 지정 스캔 알고리즘을 구현합니다. 객체가 버킷에 로드될 때 함수를 트리거합니다. 객체에 PII 가 포함된 경우 Amazon Simple Email Service(Amazon SES)를 사용하여 관리자에게 알림을 트리거하고 S3 수명 주기 정책을 트리거하여 PII 가 포함된 고기를 제거합니다."},"answers":["B"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["Amazon S3","Amazon Macie","Amazon SNS"],"explanation":{"requirementsAnalysis":"회사는 SFTP로 수신하는 거래 파일에서 개인 식별 정보가 포함된 파일을 탐지하고 관리자에게 경고해야 합니다. 일부 파일은 200GB를 넘으므로 대용량 객체를 저장할 수 있어야 하며, 민감 데이터 탐지와 후속 대응의 자동화 범위도 고려해야 합니다. 최소 개발 노력이 요구되므로 사용자 지정 탐지 알고리즘보다 관리형 민감 데이터 검색 기능이 우선됩니다.","awsServicesAnalysis":"Amazon S3는 대용량 객체를 저장할 수 있습니다. Amazon Macie는 S3 객체에서 PII 같은 민감 데이터를 관리형으로 발견하고 결과를 생성합니다. 다만 분석 가능한 객체의 형식과 크기에 제한이 있으며, 예를 들어 비이진 텍스트는 객체당 최대 20GB이고 PDF는 최대 1GB이므로 200GB가 넘는 파일 전체를 직접 검사할 수 없습니다. Macie 결과는 Amazon EventBridge를 통해 SNS 알림이나 Lambda 기반 격리·삭제 워크플로로 연결할 수 있습니다. Amazon Inspector는 S3 객체의 PII 탐지 서비스가 아니며, S3 수명 주기 규칙은 탐지 결과에 따라 개별 객체를 즉시 삭제하도록 호출하는 기능이 아닙니다.","choicesAnalysis":"제시된 선택지 중 PII를 관리형으로 탐지하고 관리자 알림으로 연결하는 구성은 Macie와 SNS를 사용하는 B뿐입니다. 사용자 지정 Lambda 검사보다 개발 노력이 작으므로 출제 의도에서는 B가 가장 적합합니다. 다만 B는 관리자에게 삭제를 요청할 뿐 사람의 개입 없는 조치를 구현하지 않으며, Macie 크기 한도를 넘는 객체도 분석하지 못합니다. 실제로 모든 요구를 충족하려면 큰 파일을 지원되는 크기로 분할하거나 별도 검사 경로를 두고, Macie 결과를 EventBridge와 Lambda 등의 자동 격리·삭제 워크플로에 연결해야 합니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"S3를 수신 지점으로 사용할 수 있지만 Amazon Inspector는 S3 객체의 PII를 탐지하지 않습니다. 수명 주기 규칙도 탐지 결과에 따라 개별 객체를 즉시 제거하도록 호출할 수 없으므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"보기 중에서는 Amazon Macie로 S3 객체의 PII를 관리형으로 탐지하고 SNS로 관리자에게 알리는 이 구성이 가장 적합합니다. 다만 200GB 초과 객체는 Macie의 분석 크기 한도를 넘을 수 있고, 알림만으로 자동 삭제가 완성되지는 않으므로 실제 설계에는 추가 처리가 필요합니다."},"C":{"isCorrect":false,"explanation":"Lambda로 사용자 지정 PII 검사 알고리즘을 직접 구현하고 운영해야 합니다. 관리형 민감 데이터 탐지 서비스를 사용하는 방식보다 개발 및 유지 관리 부담이 크므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"사용자 지정 Lambda 검사 로직이 필요해 개발 노력이 크며, S3 수명 주기 규칙은 객체 내용 검사 결과에 따라 즉시 실행되는 개별 객체 제거 워크플로가 아닙니다. 따라서 적합하지 않습니다."}}},{"id":"Q0047","question_number":47,"question":"회사는 1 주일 동안 진행될 예정된 이벤트를 위해 특정 AWS 리전의 3 개의 특정 가용 영역에서 보장된 Amazon EC2 용량이 필요합니다. EC2 용량을 보장하기 위해 회사는 무엇을 해야 합니까?","choices":{"A":"필요한 리전을 지정하는 예약 인스턴스를 구매합니다.","B":"필요한 지역을 지정하는 온디맨드 용량 예약을 생성합니다.","C":"필요한 리전과 3 개의 가용 영역을 지정하는 예약 인스턴스를 구매합니다.","D":"필요한 지역과 3 개의 가용 영역을 지정하는 온디맨드 용량 예약을 생성합니다."},"answers":["D"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능의 탄력적인 컴퓨팅 솔루션 설계","aws_services":["Amazon EC2"],"explanation":{"requirementsAnalysis":"회사는 예정된 1주일 이벤트 동안 특정 리전의 세 가용 영역에서 필요한 EC2 용량을 보장해야 합니다. 비용 할인 자체보다 지정한 가용 영역별 컴퓨팅 용량 확보가 핵심이며, 짧은 이벤트 기간이 끝나면 장기 약정 없이 예약을 종료할 수 있어야 합니다.","awsServicesAnalysis":"EC2 온디맨드 용량 예약은 특정 가용 영역에서 지정한 인스턴스 속성의 용량을 확보하며, 즉시 시작하는 예약은 필요한 때 취소할 수 있습니다. 여러 가용 영역에서 용량이 필요하면 각 가용 영역에 별도의 용량 예약을 생성합니다. 리전 범위 예약 인스턴스는 특정 가용 영역의 용량을 확보하지 않습니다. 가용 영역 범위 예약 인스턴스는 해당 영역과 연결되지만 1년 또는 3년의 요금 약정이 필요하므로 1주일 이벤트에는 비용 효율적이지 않습니다.","choicesAnalysis":"세 가용 영역에서 1주일 동안 용량을 확보하려면 각 가용 영역을 대상으로 온디맨드 용량 예약을 생성해야 합니다. 이 방식은 단기 용량 보장에 맞고 장기 예약 인스턴스 약정을 만들지 않습니다. 리전만 지정한 예약은 특정 가용 영역의 용량 요구를 충족하지 못합니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"리전 범위 예약 인스턴스는 특정 가용 영역의 EC2 용량을 확보하지 않으며 장기 요금 약정을 수반하므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"온디맨드 용량 예약은 리전 전체가 아니라 특정 가용 영역을 대상으로 생성합니다. 세 가용 영역 각각의 용량을 보장하는 구성이 제시되지 않았으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"가용 영역 범위 예약 인스턴스는 영역별 속성을 가질 수 있지만 1년 또는 3년 약정이 필요합니다. 1주일 이벤트의 단기 용량 확보에는 취소 가능한 온디맨드 용량 예약보다 비용 효율적이지 않습니다."},"D":{"isCorrect":true,"explanation":"필요한 리전의 세 가용 영역 각각에 온디맨드 용량 예약을 생성하면 이벤트 기간의 EC2 용량을 확보하고 이후 예약을 종료할 수 있으므로 적합합니다."}}},{"id":"Q0048","question_number":48,"question":"회사 웹 사이트는 항목 카탈로그에 Amazon EC2 인스턴스 스토어를 사용합니다. 회사는 카탈로그의 가용성이 높고 카탈로그가 내구성 있는 위치에 저장되기를 원합니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"카탈로그를 Redis 용 Amazon ElastiCache 로 이동합니다.","B":"더 큰 인스턴스 스토어로 더 큰 EC2 인스턴스를 배포합니다.","C":"인스턴스 스토어에서 Amazon S3 Glacier Deep Archive 로 카탈로그를 이동합니다.","D":"카탈로그를 Amazon Elastic File System(Amazon EFS) 파일 시스템으로 이동합니다."},"answers":["D"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"고가용성 및/또는 내결함성 아키텍처 설계","aws_services":["Amazon EFS"],"explanation":{"requirementsAnalysis":"웹 사이트의 항목 카탈로그는 현재 EC2 인스턴스 스토어에 있으나, 인스턴스 스토어 데이터는 인스턴스 수명에 종속됩니다. 회사는 카탈로그를 고가용하고 내구성 있는 위치에 저장해야 하므로, 여러 가용 영역에서 접근할 수 있고 인스턴스 장애에도 데이터를 유지하는 관리형 스토리지가 필요합니다.","awsServicesAnalysis":"EC2 인스턴스 스토어는 호스트에 연결된 임시 블록 스토리지로 인스턴스 중지, 종료 또는 호스트 장애 시 데이터가 손실될 수 있습니다. Amazon EFS는 여러 가용 영역에 걸쳐 데이터를 저장하는 리전 파일 시스템이며 여러 EC2 인스턴스가 동시에 마운트할 수 있습니다. Amazon ElastiCache for Redis는 주로 인메모리 캐시 및 데이터 저장소에 사용됩니다. S3 Glacier Deep Archive는 장기 아카이브 스토리지 클래스로 검색 지연이 길 수 있습니다.","choicesAnalysis":"카탈로그는 내구성과 고가용성이 필요한 운영 데이터이므로 인스턴스 수명에 의존하지 않는 공유 파일 시스템에 옮겨야 합니다. EFS는 다중 가용 영역 내구성과 여러 EC2 인스턴스의 동시 접근을 제공하므로 이 요구에 맞습니다. 인스턴스 스토어 확장은 임시 스토리지의 한계를 해소하지 못하고, 캐시 또는 장기 아카이브는 이 저장 요구에 직접 맞지 않습니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 ElastiCache for Redis는 빠른 인메모리 캐시 용도에 적합하지만 카탈로그의 영구 기본 저장소로 사용하는 선택지는 아닙니다. 내구성 있는 공유 파일 저장 요구사항에 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 더 큰 인스턴스 스토어 용량을 제공할 수 있지만 인스턴스 스토어의 임시적 특성은 그대로입니다. 인스턴스 또는 호스트 장애 시 데이터 내구성을 보장하지 못하므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C의 S3 Glacier Deep Archive는 매우 낮은 비용의 장기 아카이브 클래스이며 검색에 상당한 지연이 발생할 수 있습니다. 고가용 웹 사이트 카탈로그의 운영 스토리지로 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"D는 Amazon EFS의 다중 가용 영역 내구성과 공유 파일 시스템 접근을 사용합니다. 여러 EC2 인스턴스가 카탈로그를 사용할 수 있고 인스턴스 스토어 장애 위험을 제거하므로 적합합니다."}}},{"id":"Q0049","question_number":49,"question":"회사는 매월 통화 기록 파일을 저장합니다. 사용자는 통화 후 1 년 이내에 파일에 무작위로 액세스하지만 1 년 이후에는 파일에 자주 액세스하지 않습니다. 이 회사는 사용자에게 1 년 미만의 파일을 가능한 한 빨리 쿼리하고 검색할 수 있는 기능을 제공하여 솔루션을 최적화하려고 합니다. 오래된 파일을 검색하는 데 있어 지연은 허용됩니다. 어떤 솔루션이 이러한 요구 사항을 가장 비용 효율적으로 충족합니까?","choices":{"A":"Amazon S3 Glacier Instant Retrieval 에 태그가 있는 개별 파일을 저장합니다. 태그를 쿼리하여 S3 Glacier Instant Retrieval 에서 파일을 검색합니다.","B":"Amazon S3 Intelligent-Tiering 에 개별 파일을 저장합니다. S3 수명 주기 정책을 사용하여 1 년 후 파일을 S3 Glacier Flexible Retrieval 로 이동합니다. Amazon Athena 를 사용하여 Amazon S3 에 있는 파일을 쿼리하고 검색합니다. S3 Glacier Select 를 사용하여 S3 Glacier 에 있는 파일을 쿼리하고 검색합니다.","C":"Amazon S3 Standard 스토리지에 태그가 있는 개별 파일을 저장합니다. Amazon S3 Standard 스토리지의 각 아카이브에 대한 검색 메타데이터를 저장합니다. S3 수명 주기 정책을 사용하여 1 년 후에 파일을 S3 Glacier Instant Retrieval 로 이동합니다. Amazon S3 에서 메타데이터를 검색하여 파일을 쿼리하고 검색합니다.","D":"Amazon S3 Standard 스토리지에 개별 파일을 저장합니다. S3 수명 주기 정책을 사용하여 1 년 후에 파일을 S3 Glacier Deep Archive 로 이동합니다. Amazon RDS 에 검색 메타데이터를 저장합니다. Amazon RDS 에서 파일을 쿼리합니다. S3 Glacier Deep Archive 에서 파일을 검색합니다."},"answers":["B"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 스토리지 솔루션 설계","aws_services":["Amazon S3","Amazon S3 Glacier","Amazon Athena"],"explanation":{"requirementsAnalysis":"회사는 통화 기록 파일을 1년 동안 무작위로 접근하며 이 기간에는 빠르게 쿼리하고 검색해야 합니다. 1년 이후에는 접근 빈도가 낮고 검색 지연을 허용하므로 더 저렴한 아카이브 계층으로 전환할 수 있습니다. 따라서 최근 파일의 빠른 분석과 오래된 파일의 저비용 보관을 결합해야 합니다.","awsServicesAnalysis":"Amazon S3 Intelligent-Tiering은 객체의 접근 패턴에 따라 액세스 계층을 자동 조정합니다. S3 Glacier Flexible Retrieval은 저비용 아카이브 스토리지 클래스로, 일반적으로 객체를 복원한 뒤 접근해야 합니다. Amazon Athena는 접근 가능한 S3 객체에 서버리스 SQL 쿼리를 실행할 수 있습니다. 선택지에 언급된 Glacier Select 계열 기능은 출제 당시 아카이브 일부를 선택적으로 검색하는 방식이었지만, 현재 Amazon S3 Select는 신규 고객에게 제공되지 않으며 S3 Glacier Flexible Retrieval 객체를 직접 쿼리할 수도 없습니다. 현재는 아카이브 객체를 복원한 뒤 Athena 등으로 조회하는 흐름이 필요합니다.","choicesAnalysis":"출제 당시 서비스 기능을 기준으로 하면 최근 1년 파일은 Intelligent-Tiering과 Athena로 빠르게 분석하고, 이후에는 Flexible Retrieval로 전환해 장기 비용을 줄이는 B의 계층화가 가장 적합합니다. 다른 선택지는 최근 데이터의 내용 쿼리 기능이 부족하거나 더 비싼 계층과 별도 데이터베이스를 사용합니다. 따라서 출제 맥락에서는 B가 정답입니다. 현재 신규 설계에서는 B의 Glacier Select 단계를 그대로 구현할 수 없으므로 아카이브를 복원한 뒤 조회하도록 변경해야 합니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"Glacier Instant Retrieval은 즉시 객체 검색을 지원하지만 태그만으로 파일 내용에 대한 쿼리를 제공하지 않으며, 1년 이후 지연을 허용하는 데이터에 더 저렴한 아카이브 계층을 적용하지도 않으므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"출제 맥락에서는 최근 파일을 Intelligent-Tiering에 두고 Athena로 조회한 뒤 1년 후 Flexible Retrieval로 전환하는 구성이 비용과 접근 요구를 가장 잘 충족합니다. 다만 현재 신규 고객은 선택지의 Glacier Select 단계를 사용할 수 없으므로 복원 후 조회 방식으로 대체해야 합니다."},"C":{"isCorrect":false,"explanation":"최근 1년 동안 모든 파일을 S3 Standard에 저장하므로 접근 패턴 기반 비용 최적화가 제한됩니다. 1년 후의 Instant Retrieval도 검색 지연을 허용하는 데이터에는 Flexible Retrieval보다 비용 효율성이 낮을 수 있으므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"S3 Standard와 Amazon RDS를 함께 운영해야 하므로 비용과 관리 대상이 늘어납니다. 최근 파일의 서버리스 직접 분석과 접근 패턴 기반 자동 계층화가 없어 적합하지 않습니다."}}},{"id":"Q0050","question_number":50,"question":"회사에 1,000 개의 Amazon EC2 Linux 인스턴스에서 실행되는 프로덕션 워크로드가 있습니다. 워크로드는 타사 소프트웨어에 의해 구동됩니다. 회사는 중요한 보안 취약성을 수정하기 위해 가능한 한 빨리 모든 EC2 인스턴스에서 타사 소프트웨어를 패치해야 합니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"AWS Lambda 함수를 생성하여 모든 EC2 인스턴스에 패치를 적용합니다.","B":"모든 EC2 인스턴스에 패치를 적용하도록 AWS Systems Manager Patch Manager 를 구성합니다.","C":"AWS Systems Manager 유지 관리 기간을 예약하여 모든 EC2 인스턴스에 패치를 적용합니다.","D":"AWS Systems Manager Run Command 를 사용하여 모든 EC2 인스턴스에 패치를 적용하는 사용자 지정 명령을 실행합니다."},"answers":["B"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["Amazon EC2","AWS Systems Manager"],"explanation":{"requirementsAnalysis":"회사는 1,000개의 Linux EC2 인스턴스에서 실행되는 타사 소프트웨어의 중요 보안 취약성을 가능한 한 빨리 패치해야 합니다. 대규모 인스턴스 집합에 일관된 패치 정책을 적용하고 실행 결과를 추적할 수 있어야 합니다. 따라서 사용자 지정 원격 실행 코드를 만들기보다 관리형 패치 오케스트레이션 기능을 사용해야 합니다.","awsServicesAnalysis":"AWS Systems Manager Patch Manager는 관리형 노드에 패치 기준선을 적용하고 인스턴스 전체의 패치 작업 및 준수 상태를 관리하는 기능입니다. 패치 작업을 수행하려면 대상 EC2 인스턴스가 Systems Manager 관리형 노드로 등록되어 있고 필요한 IAM 권한과 SSM Agent 구성이 필요합니다. Patch Manager는 운영 체제 패키지 관리자와 지원되는 패치 저장소를 사용합니다. Systems Manager 유지 관리 기간은 작업 실행 시간을 예약하는 기능이고, Run Command는 여러 관리형 노드에서 명령 또는 문서를 실행하는 기능입니다. AWS Lambda는 이벤트 기반 코드를 실행하는 서버리스 컴퓨팅 서비스입니다.","choicesAnalysis":"요구사항은 대규모 인스턴스에 대해 긴급 패치를 일관되게 배포하고 관리하는 것입니다. Patch Manager는 패치 기준선, 대상 지정, 실행 및 준수 확인을 제공하므로 이 목적에 맞는 관리형 기능입니다. 유지 관리 기간은 향후 예약에 유용하지만 긴급 패치의 핵심 기능이 아니며, Run Command나 Lambda로 별도 패치 로직을 구성하면 관리 부담이 커집니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 Lambda 함수에 원격 패치 배포 로직, 권한 처리 및 실패 관리를 직접 구현해야 합니다. 1,000개 인스턴스의 표준 패치 관리에는 Patch Manager보다 운영 부담이 크므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 AWS Systems Manager Patch Manager로 대상 EC2 인스턴스에 패치 기준선을 적용하고 실행 상태와 준수 여부를 관리합니다. 관리형 노드 전제하에 대규모 Linux 인스턴스의 긴급 패치 배포 요구사항에 적합합니다."},"C":{"isCorrect":false,"explanation":"C의 Systems Manager 유지 관리 기간은 패치 실행 작업을 예약하는 데 사용할 수 있지만, 가능한 한 빨리 적용해야 하는 긴급 취약성 대응에는 예약 자체가 해법이 아닙니다. Patch Manager의 패치 관리 기능을 구성하는 선택지가 더 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 Systems Manager Run Command로 사용자 지정 명령을 대규모 인스턴스에 실행할 수 있습니다. 그러나 패치 기준선, 준수 추적 및 패치 수명 주기 관리를 Patch Manager보다 더 많이 직접 구성해야 하므로 적합하지 않습니다."}}},{"id":"Q0051","question_number":51,"question":"회사는 REST API 로 검색하기 위해 주문 배송 통계를 제공하는 애플리케이션을 개발 중입니다. 이 회사는 배송 통계를 추출하고 데이터를 읽기 쉬운 HTML 형식으로 구성하고 매일 아침 여러 이메일 주소로 보고서를 보내려고 합니다. 이러한 요구 사항을 충족하기 위해 솔루션 설계자는 어떤 단계 조합을 취해야 합니까? (2 개를 선택하세요.)","choices":{"A":"데이터를 Amazon Kinesis Data Firehose 로 보내도록 애플리케이션을 구성합니다.","B":"Amazon Simple Email Service(Amazon SES)를 사용하여 데이터 형식을 지정하고 보고서를 이메일로 보냅니다.","C":"AWS Glue 작업을 호출하여 데이터에 대한 애플리케이션의 API 를 쿼리하는 Amazon EventBridge(Amazon CloudWatch Events) 예약 이벤트를 생성합니다.","D":"AWS Lambda 함수를 호출하여 데이터에 대한 애플리케이션의 API 를 쿼리하는 Amazon EventBridge(Amazon CloudWatch Events) 예약 이벤트를 생성합니다.","E":"Amazon S3 에 애플리케이션 데이터를 저장합니다. 보고서를 이메일로 보낼 S3 이벤트 대상으로 Amazon Simple Notification Service(Amazon SNS) 주제를 생성합니다."},"answers":["B","D"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터 수집 및 변환 솔루션 결정","aws_services":["Amazon EventBridge","AWS Lambda"],"explanation":{"requirementsAnalysis":"회사는 REST API에서 배송 통계를 매일 아침 가져와 읽기 쉬운 HTML 보고서로 구성하고 여러 수신자에게 이메일로 전송해야 합니다. 따라서 정해진 시각에 작업을 시작하고, API 응답을 보고서 본문으로 변환하며, HTML 형식의 이메일을 발송하는 자동화 흐름이 필요합니다.","awsServicesAnalysis":"Amazon EventBridge는 예약 규칙을 통해 지정된 시각에 대상 서비스를 호출할 수 있습니다. AWS Lambda는 REST API를 호출하고 응답 데이터를 변환하는 코드를 서버 관리 없이 실행할 수 있습니다. Amazon Simple Email Service(Amazon SES)는 여러 수신자에게 HTML 본문을 포함한 이메일을 보낼 수 있습니다. Amazon Kinesis Data Firehose는 스트리밍 데이터를 대상으로 전송하는 서비스이며, AWS Glue는 데이터 통합 및 ETL 작업에 사용됩니다. Amazon S3 이벤트 알림은 객체 생성과 같은 S3 이벤트를 대상으로 Amazon SNS 등의 대상으로 전달할 수 있습니다.","choicesAnalysis":"매일 정해진 시각에 API를 호출하고 보고서를 생성하려면 EventBridge 예약 규칙과 Lambda 실행을 연결해야 합니다. Lambda가 생성한 HTML 보고서는 SES로 여러 이메일 주소에 발송할 수 있습니다. 이 조합은 필요한 조회, 변환 및 전송 단계를 모두 자동화하므로 B와 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 Amazon Kinesis Data Firehose는 스트리밍 레코드를 전송하는 용도입니다. 예약된 REST API 조회, HTML 보고서 생성 및 이메일 발송을 수행하지 않으므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B의 Amazon SES는 HTML 형식의 보고서를 여러 수신자에게 이메일로 발송할 수 있으므로 요구된 전송 기능에 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 예약 이벤트로 AWS Glue 작업을 호출할 수 있지만, Glue는 단순한 일일 REST API 호출과 보고서 발송에 비해 과도한 ETL 서비스입니다. 또한 이메일 발송을 위한 구성 요소가 없으므로 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"D는 EventBridge 예약 규칙으로 Lambda를 호출하여 매일 API를 조회하고 응답을 HTML 보고서로 변환할 수 있으므로 적합합니다."},"E":{"isCorrect":false,"explanation":"E는 S3 객체 생성에 반응하여 SNS 알림을 보내는 구성입니다. 일일 REST API 조회와 HTML 보고서 생성이 포함되지 않으므로 적합하지 않습니다."}}},{"id":"Q0052","question_number":52,"question":"회사에서 온프레미스 애플리케이션을 AWS 로 마이그레이션하려고 합니다. 애플리케이션은 수십 기가바이트에서 수백 테라바이트까지 다양한 크기의 출력 파일을 생성합니다. 애플리케이션 데이터는 표준 파일 시스템 구조로 저장되어야 합니다. 회사는 자동으로 확장되는 솔루션을 원합니다. 고가용성이며 최소한의 운영 오버헤드가 필요합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"Amazon Elastic Container Service(Amazon ECS)에서 컨테이너로 실행되도록 애플리케이션을 마이그레이션합니다. 스토리지에 Amazon S3 를 사용합니다.","B":"Amazon Elastic Kubernetes Service(Amazon EKS)에서 컨테이너로 실행되도록 애플리케이션을 마이그레이션합니다. 스토리지에 Amazon Elastic Block Store(Amazon EBS)를 사용합니다.","C":"다중 AZ Auto Scaling 그룹의 Amazon EC2 인스턴스로 애플리케이션을 마이그레이션합니다. 스토리지에 Amazon Elastic File System(Amazon EFS)을 사용합니다.","D":"다중 AZ Auto Scaling 그룹의 Amazon EC2 인스턴스로 애플리케이션을 마이그레이션합니다. 스토리지에 Amazon Elastic Block Store(Amazon EBS)를 사용합니다."},"answers":["C"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"고가용성 및/또는 내결함성 아키텍처 설계","aws_services":["Amazon EC2","Amazon EC2 Auto Scaling","Amazon EFS"],"explanation":{"requirementsAnalysis":"애플리케이션은 수십 기가바이트부터 수백 테라바이트까지의 출력 파일을 표준 파일 시스템 구조로 저장해야 합니다. 스토리지는 용량 요구에 맞춰 자동으로 확장되고, 고가용성을 제공하면서 운영 관리 부담이 낮아야 합니다. 따라서 여러 컴퓨팅 인스턴스가 공유할 수 있는 관리형 파일 스토리지가 필요합니다.","awsServicesAnalysis":"Amazon EFS는 여러 가용 영역에 걸쳐 데이터를 저장하는 완전관리형 탄력적 파일 시스템이며, 파일 시스템 용량을 자동으로 확장 및 축소합니다. Amazon EBS는 특정 가용 영역에 연결하는 블록 스토리지입니다. Amazon S3는 객체 스토리지이며 일반 파일 시스템 인터페이스를 직접 제공하지 않습니다. Amazon EC2 Auto Scaling은 수요에 따라 EC2 인스턴스 수를 조정하고, Amazon ECS 및 Amazon EKS는 컨테이너화된 워크로드를 오케스트레이션합니다.","choicesAnalysis":"표준 파일 시스템 구조와 자동 용량 확장, 다중 가용 영역 고가용성을 함께 충족하려면 공유 파일 시스템을 사용해야 합니다. EFS는 해당 스토리지를 관리형으로 제공하며 EC2 Auto Scaling 그룹의 인스턴스가 같은 파일 시스템을 사용할 수 있습니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 Amazon S3를 스토리지로 사용합니다. S3는 객체 스토리지이므로 애플리케이션이 요구하는 표준 파일 시스템 구조를 직접 제공하지 않아 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B의 Amazon EBS는 특정 가용 영역의 블록 스토리지이며, 다수 노드가 공유하는 자동 확장 파일 시스템을 제공하지 않습니다. EKS 및 EBS 운영도 최소 운영 오버헤드 요구에 부합하지 않으므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 다중 AZ Auto Scaling 그룹과 Amazon EFS를 사용합니다. EFS는 자동 확장되는 관리형 공유 파일 시스템이며 다중 가용 영역에 데이터를 저장하므로 고가용성과 낮은 운영 부담 요구에 적합합니다."},"D":{"isCorrect":false,"explanation":"D의 Amazon EBS는 가용 영역 단위의 블록 스토리지입니다. Auto Scaling 그룹의 여러 인스턴스가 공유하는 탄력적 파일 시스템을 구성하려면 추가 설계와 관리가 필요하므로 적합하지 않습니다."}}},{"id":"Q0053","question_number":53,"question":"회사는 Amazon S3 에 회계 기록을 저장해야 합니다. 기록은 1 년 동안 즉시 액세스할 수 있어야 하며 그 후 추가로 9 년 동안 보관해야 합니다. 관리자 및 루트 사용자를 포함하여 회사의 그 누구도 전체 10 년 동안 기록을 삭제할 수 없습니다. 기록은 최대한의 복원력으로 저장해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"전체 10 년 동안 S3 Glacier 에 기록을 저장합니다. 접근통제 정책을 사용하여 10 년 동안 기록 삭제를 거부합니다.","B":"S3 Intelligent-Tiering 을 사용하여 레코드를 저장합니다. IAM 정책을 사용하여 레코드 삭제를 거부합니다. 10 년 후 삭제를 허용하도록 IAM 정책을 변경합니다.","C":"S3 수명 주기 정책을 사용하여 1 년 후에 S3 Standard 에서 S3 Glacier Deep Archive 로 레코드를 전환합니다. 10 년 동안 규정 준수 모드에서 S3 Object Lock 을 사용합니다.","D":"S3 수명 주기 정책을 사용하여 1 년 후 레코드를 S3 Standard 에서 S3 One Zone-Infrequent Access(S3 One Zone-IA)로 전환합니다. 10 년 동안 거버넌스 모드에서 S3 Object Lock 을 사용합니다."},"answers":["C"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["Amazon S3","Amazon S3 Glacier"],"explanation":{"requirementsAnalysis":"회계 기록은 처음 1년 동안 즉시 액세스할 수 있어야 하고, 이후 9년을 더 보관해야 합니다. 전체 10년 동안 관리자와 루트 사용자를 포함한 누구도 기록을 삭제할 수 없어야 하며, 저장소는 최대한 높은 복원력을 제공해야 합니다. 따라서 액세스 기간에 맞는 수명 주기와 변경 불가능한 보존 제어가 모두 필요합니다.","awsServicesAnalysis":"Amazon S3 Lifecycle은 객체를 정의한 시점에 다른 S3 스토리지 클래스로 전환할 수 있습니다. S3 Glacier Deep Archive에 보관된 객체는 복원 절차 없이 실시간으로 액세스할 수 없습니다. S3 Object Lock의 규정 준수 모드는 보존 기간 중 어떤 사용자도, 계정 루트 사용자를 포함하여 객체 버전을 삭제하거나 덮어쓸 수 없게 합니다. 거버넌스 모드는 필요한 권한이 있는 사용자가 보존을 우회할 수 있습니다. S3 One Zone-IA는 단일 가용 영역에 데이터를 저장합니다.","choicesAnalysis":"즉시 액세스가 필요한 첫해에는 S3 Standard에 기록을 유지하고, 이후에는 장기 아카이브 스토리지로 전환할 수 있습니다. 삭제 불가 보존은 루트 사용자도 우회할 수 없는 규정 준수 모드여야 하며, 단일 가용 영역 스토리지는 최대 복원력 조건에 맞지 않습니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 S3 Glacier 스토리지는 아카이브 데이터를 복원해야 액세스할 수 있으므로 첫 1년간의 즉시 액세스 요구를 충족하지 못합니다. 또한 접근 제어 정책은 변경될 수 있어 절대 삭제 불가 보존을 보장하지 못합니다."},"B":{"isCorrect":false,"explanation":"B의 IAM 정책은 권한 있는 주체가 변경할 수 있습니다. 따라서 관리자와 루트 사용자를 포함해 누구도 10년 동안 삭제할 수 없어야 하는 요구를 보장하지 못하므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 첫 1년 동안 S3 Standard의 즉시 액세스를 제공하고 이후 S3 Glacier Deep Archive로 전환합니다. 또한 10년 규정 준수 모드의 S3 Object Lock은 루트 사용자를 포함한 모든 사용자의 조기 삭제 또는 덮어쓰기를 차단하므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D의 S3 One Zone-IA는 단일 가용 영역 스토리지이므로 최대 복원력 요구에 맞지 않습니다. 또한 거버넌스 모드는 권한이 있는 사용자가 보존을 우회할 수 있으므로 적합하지 않습니다."}}},{"id":"Q0054","question_number":54,"question":"회사는 AWS 에서 여러 Windows 워크로드를 실행합니다. 회사 직원은 두 개의 Amazon EC2 인스턴스에서 호스팅되는 Windows 파일 공유를 사용합니다. 파일 공유는 서로 간에 데이터를 동기화하고 중복 복사본을 유지합니다. 이 회사는 사용자가 현재 파일에 액세스하는 방식을 보존하는 고가용성 및 내구성 스토리지 솔루션을 원합니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"모든 데이터를 Amazon S3 로 마이그레이션합니다. 사용자가 파일에 액세스할 수 있도록 IAM 인증을 설정합니다.","B":"Amazon S3 파일 게이트웨이를 설정합니다. 기존 EC2 인스턴스에 S3 파일 게이트웨이를 탑재합니다.","C":"다중 AZ 구성을 사용하여 파일 공유 환경을 Windows 파일 서버용 Amazon FSx 로 확장합니다. 모든 데이터를 Windows 파일 서버용 FSx 로 마이그레이션합니다.","D":"다중 AZ 구성을 사용하여 파일 공유 환경을 Amazon Elastic File System(Amazon EFS)으로 확장합니다. 모든 데이터를 Amazon EFS 로 마이그레이션합니다."},"answers":["C"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"고가용성 및/또는 내결함성 아키텍처 설계","aws_services":["Amazon FSx(모든 유형)"],"explanation":{"requirementsAnalysis":"회사는 두 EC2 인스턴스에서 제공하던 Windows 파일 공유의 동기화와 중복 복사본 운영을 대체해야 합니다. 사용자가 현재와 같은 방식으로 파일에 액세스하면서도, 파일 공유 스토리지는 고가용성과 내구성을 제공해야 합니다. 따라서 Windows 파일 공유 프로토콜을 지원하는 관리형 다중 가용 영역 파일 시스템이 필요합니다.","awsServicesAnalysis":"Amazon FSx for Windows File Server는 Windows 파일 공유에 사용하는 SMB 프로토콜과 Windows ACL, Microsoft Active Directory 통합을 지원하는 완전관리형 파일 시스템입니다. Multi-AZ 배포는 가용 영역 간 파일 서버와 스토리지 복제를 사용하고 장애 시 자동 장애 조치를 제공합니다. Amazon EFS는 NFS 파일 시스템입니다. Amazon S3는 객체 스토리지이고, S3 File Gateway는 SMB 또는 NFS 인터페이스로 S3 객체에 액세스할 수 있는 하이브리드 스토리지 게이트웨이입니다.","choicesAnalysis":"Windows 파일 공유 접근 방식을 유지하면서 기존 인스턴스 간 동기화와 중복 복사본을 관리형 스토리지로 대체하려면 SMB 기반의 고가용성 파일 시스템이 필요합니다. FSx for Windows File Server의 Multi-AZ 구성이 이 프로토콜 호환성과 장애 조치 기능을 제공합니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 Amazon S3는 객체 스토리지이며 사용자가 기존 Windows 파일 공유 방식으로 접근하는 SMB 파일 시스템을 제공하지 않습니다. IAM 인증만으로는 해당 접근 방식이 보존되지 않으므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B의 S3 File Gateway는 S3 객체를 SMB 또는 NFS로 노출할 수 있지만, 기존 EC2 파일 서버의 공유 스토리지를 고가용성 Windows 파일 시스템으로 대체하는 구성은 아닙니다. 게이트웨이와 백엔드 S3를 별도로 운영해야 하므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 데이터를 Multi-AZ Amazon FSx for Windows File Server로 이전합니다. FSx는 Windows SMB 파일 공유를 지원하고 다중 가용 영역 장애 조치를 제공하므로 기존 사용자 접근 방식과 고가용성 요구에 적합합니다."},"D":{"isCorrect":false,"explanation":"D의 Amazon EFS는 NFS 파일 시스템입니다. Windows 파일 공유에서 사용하는 SMB 접근 방식을 그대로 제공하지 않으므로 적합하지 않습니다."}}},{"id":"Q0055","question_number":55,"question":"솔루션 설계자는 여러 서브넷을 포함하는 VPC 아키텍처를 개발 중입니다. 아키텍처는 Amazon EC2 인스턴스 및 Amazon RDS DB 인스턴스를 사용하는 애플리케이션을 호스팅합니다. 아키텍처는 2 개의 가용 영역에 있는 6 개의 서브넷으로 구성됩니다. 각 가용 영역에는 퍼블릭 서브넷, 프라이빗 서브넷 및 데이터베이스용 전용 서브넷이 포함됩니다. 프라이빗 서브넷에서 실행되는 EC2 인스턴스만 RDS 데이터베이스에 액세스할 수 있습니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"퍼블릭 서브넷의 CIDR 블록에 대한 경로를 제외하는 새 라우팅 테이블을 생성합니다. 라우팅 테이블을 데이터베이스 서브넷과 연결합니다.","B":"퍼블릭 서브넷의 인스턴스에 할당된 보안 그룹의 인바운드 트래픽을 거부하는 보안 그룹을 생성합니다. 보안 그룹을 DB 인스턴스에 연결합니다.","C":"프라이빗 서브넷의 인스턴스에 할당된 보안 그룹의 인바운드 트래픽을 허용하는 보안 그룹을 생성합니다. 보안 그룹을 DB 인스턴스에 연결합니다.","D":"퍼블릭 서브넷과 프라이빗 서브넷 사이에 새로운 피어링 연결을 생성합니다. 프라이빗 서브넷과 데이터베이스 서브넷 간에 다른 피어링 연결을 만듭니다."},"answers":["C"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["Amazon VPC","Amazon RDS"],"explanation":{"requirementsAnalysis":"두 가용 영역에 걸친 VPC에서 퍼블릭, 프라이빗 및 데이터베이스 전용 서브넷을 분리합니다. RDS DB 인스턴스에는 프라이빗 서브넷의 EC2 인스턴스만 연결할 수 있어야 합니다. 따라서 DB 인스턴스에 대한 인바운드 연결을 워크로드의 네트워크 위치가 아니라 허용된 EC2 집합으로 제한하는 제어가 필요합니다.","awsServicesAnalysis":"보안 그룹은 상태 저장 가상 방화벽으로, 인바운드 규칙의 소스로 CIDR 범위 또는 다른 보안 그룹을 지정할 수 있습니다. Amazon RDS DB 인스턴스에는 VPC 보안 그룹을 연결할 수 있습니다. 네트워크 ACL은 서브넷 수준의 상태 비저장 필터이며 보안 그룹처럼 보안 그룹을 소스로 참조하지 않습니다. 같은 VPC의 서브넷은 기본 local 경로를 통해 통신하며 VPC 피어링 연결이 필요하지 않습니다.","choicesAnalysis":"DB 인스턴스의 인바운드 규칙에서 프라이빗 EC2 인스턴스에 연결된 보안 그룹만 소스로 허용하면, 해당 인스턴스만 DB 포트에 접속할 수 있습니다. 이 방식은 인스턴스 IP 변경에도 그룹 멤버십을 기준으로 적용됩니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 라우팅 테이블은 패킷의 다음 홉을 결정하며, RDS에 대한 인바운드 접근을 EC2 보안 그룹 기준으로 제한하지 않습니다. 따라서 요구사항을 충족하지 못합니다."},"B":{"isCorrect":false,"explanation":"B는 보안 그룹 인바운드 규칙으로 거부 규칙을 만들려고 합니다. 보안 그룹은 허용 규칙만 지원하며, 퍼블릭 인스턴스를 거부하는 방식은 프라이빗 인스턴스만 허용해야 하는 요구를 정확히 구현하지 못합니다."},"C":{"isCorrect":true,"explanation":"C는 DB 인스턴스 보안 그룹의 인바운드 규칙 소스로 프라이빗 EC2 인스턴스의 보안 그룹을 지정합니다. 따라서 해당 보안 그룹이 연결된 인스턴스만 RDS DB 인스턴스에 연결할 수 있으므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 동일한 VPC의 서브넷 사이에 피어링 연결을 만들려는 구성입니다. VPC 피어링은 서로 다른 VPC를 연결하는 기능이며, 접근 제어도 제공하지 않으므로 적합하지 않습니다."}}},{"id":"Q0056","question_number":56,"question":"회사는 Amazon Route 53 에 도메인 이름을 등록했습니다. 이 회사는 ca-central-1 리전의 Amazon API Gateway 를 백엔드 마이크로서비스 API 의 공용 인터페이스로 사용합니다. 타사 서비스는 API 를 안전하게 사용합니다. 회사는 타사 서비스에서 HTTPS 를 사용할 수 있도록 회사의 도메인 이름 및 해당 인증서로 API 게이트웨이 URL 을 설계하려고 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"API Gateway 에서 Name=\"Endpoint-URL\" 및 Value=\"Company Domain Name\"으로 단계 변수를 생성하여 기본 URL 을 덮어씁니다. 회사의 도메인 이름과 연결된 공인 인증서를 AWS Certificate Manager(ACM)로 가져옵니다.","B":"회사의 도메인 이름으로 Route 53 DNS 레코드를 생성합니다. 별칭 레코드가 리전 API 게이트웨이 단계 엔드포인트를 가리키도록 합니다. 회사의 도메인 이름과 연결된 공인 인증서를 us-east-1 리전의 AWS Certificate Manager(ACM)로 가져옵니다.","C":"리전 API 게이트웨이 엔드포인트를 생성합니다. API Gateway 엔드포인트를 회사의 도메인 이름과 연결합니다. 회사의 도메인 이름과 연결된 공인 인증서를 동일한 리전의 AWS Certificate Manager(ACM)로 가져옵니다. API Gateway 엔드포인트에 인증서를 연결합니다. API Gateway 엔드포인트로 트래픽을 라우팅하도록 Route 53 을 구성합니다.","D":"리전 API 게이트웨이 엔드포인트를 생성합니다. API Gateway 엔드포인트를 회사의 도메인 이름과 연결합니다. 회사의 도메인 이름과 연결된 공인 인증서를 us-east-1 리전의 AWS Certificate Manager(ACM)로 가져옵니다. API Gateway API 에 인증서를 연결합니다. 회사의 도메인 이름으로 Route 53 DNS 레코드를 생성합니다. A 레코드가 회사의 도메인 이름을 가리키도록 합니다."},"answers":["C"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["Amazon API Gateway","AWS Certificate Manager(ACM)","Amazon Route 53"],"explanation":{"requirementsAnalysis":"회사는 ca-central-1 리전의 API Gateway를 백엔드 마이크로서비스 API의 공용 인터페이스로 사용합니다. 타사 서비스가 회사 도메인 이름으로 HTTPS를 통해 안전하게 API를 호출할 수 있어야 합니다. 따라서 리전 API에 사용자 지정 도메인과 유효한 TLS 인증서를 연결하고, 해당 도메인으로의 DNS 요청을 API Gateway에 라우팅해야 합니다.","awsServicesAnalysis":"API Gateway의 리전 사용자 지정 도메인 이름은 API와 같은 리전에 있는 AWS Certificate Manager(ACM) 인증서를 사용해야 합니다. 사용자 지정 도메인에 API 매핑을 구성하면 도메인의 경로를 API 스테이지에 연결할 수 있습니다. Amazon Route 53은 리전 API Gateway 사용자 지정 도메인 이름을 대상으로 하는 별칭 A 레코드를 생성할 수 있습니다. us-east-1의 ACM 인증서는 엣지 최적화 API Gateway 사용자 지정 도메인에 필요합니다.","choicesAnalysis":"리전 엔드포인트에는 ca-central-1에서 발급하거나 가져온 ACM 인증서를 사용자 지정 도메인에 연결해야 합니다. 이어서 API 매핑과 Route 53 별칭 레코드로 회사 도메인의 HTTPS 요청을 리전 API Gateway로 보낼 수 있습니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 API Gateway 단계 변수는 기본 API URL을 사용자 지정 도메인으로 대체하지 않습니다. 또한 ACM 인증서를 가져오는 것만으로 사용자 지정 도메인, API 매핑 및 DNS 라우팅이 구성되지 않으므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 리전 API Gateway에 사용할 인증서를 us-east-1에 가져옵니다. 리전 사용자 지정 도메인의 ACM 인증서는 API와 같은 ca-central-1 리전에 있어야 하므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 리전 API Gateway에 사용자 지정 도메인을 연결하고 같은 리전의 ACM 인증서를 사용합니다. 이후 Route 53을 API Gateway 엔드포인트로 라우팅하도록 구성하므로 HTTPS와 사용자 지정 도메인 요구에 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 리전 API Gateway에 필요한 인증서를 us-east-1에 가져오므로 리전 요구와 맞지 않습니다. 또한 Route 53 레코드는 사용자 지정 도메인을 API Gateway의 사용자 지정 도메인 대상으로 해석해야 하므로 적합하지 않습니다."}}},{"id":"Q0057","question_number":57,"question":"한 회사에서 인기 있는 소셜 미디어 웹사이트를 운영하고 있습니다. 웹사이트는 사용자에게 이미지를 업로드하여 다른 사용자와 공유할 수 있는 기능을 제공합니다. 회사는 이미지에 부적절한 콘텐츠가 포함되지 않았는지 확인하고 싶습니다. 회사는 개발 노력을 최소화하는 솔루션이 필요합니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"Amazon Comprehend 를 사용하여 부적절한 콘텐츠를 감지합니다. 신뢰도가 낮은 예측에는 인적 검토를 사용합니다.","B":"Amazon Rekognition 을 사용하여 부적절한 콘텐츠를 감지합니다. 신뢰도가 낮은 예측에는 인적 검토를 사용합니다.","C":"Amazon SageMaker 를 사용하여 부적절한 콘텐츠를 감지합니다. 신뢰도가 낮은 예측에 레이블을 지정하려면 정답을 사용합니다.","D":"AWS Fargate 를 사용하여 사용자 지정 기계 학습 모델을 배포하여 부적절한 콘텐츠를 감지합니다. 신뢰도가 낮은 예측에 레이블을 지정하려면 정답을 사용합니다."},"answers":["B"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["Amazon Rekognition"],"explanation":{"requirementsAnalysis":"소셜 미디어 웹사이트는 사용자가 업로드한 이미지에 부적절한 콘텐츠가 있는지 확인해야 합니다. 개발 노력은 최소화해야 하며 자동 분류의 신뢰도가 낮은 경우에는 사람이 검토할 수 있어야 합니다. 따라서 이미지 콘텐츠 조정을 위한 사전 구축 기능과 신뢰도 기반 검토 흐름이 필요합니다.","awsServicesAnalysis":"Amazon Rekognition의 DetectModerationLabels API는 이미지에서 부적절하거나 불쾌감을 줄 수 있는 콘텐츠의 조정 레이블과 신뢰도 점수를 반환합니다. 출제 당시에는 Amazon Augmented AI와 직접 통합해 신뢰도 조건에 따른 인적 검토 워크플로를 구성할 수 있었습니다. Amazon A2I는 2026년 7월 30일부터 신규 고객에게 제공되지 않지만 기존 고객은 계속 사용할 수 있습니다. Amazon Comprehend는 자연어 텍스트 분석 서비스이고, Amazon SageMaker와 AWS Fargate를 사용한 사용자 지정 모델은 별도의 모델 개발 및 운영이 필요합니다.","choicesAnalysis":"사전 학습된 이미지 조정 기능을 사용하면 사용자 지정 모델을 구축하지 않고 부적절한 콘텐츠와 신뢰도 점수를 얻을 수 있습니다. 출제 당시에는 낮은 신뢰도 결과를 Amazon A2I 인적 검토로 연결할 수 있었으므로 B가 정답입니다. 현재 신규 고객도 Rekognition의 이미지 조정 API는 사용할 수 있지만 A2I 신규 접근은 종료되었으므로 인적 검토 단계에는 자체 워크플로 또는 다른 검토 솔루션이 필요합니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"Amazon Comprehend는 텍스트를 분석하는 서비스이며 업로드된 이미지의 부적절한 콘텐츠를 직접 감지하지 않으므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"Amazon Rekognition은 이미지 조정 레이블과 신뢰도 점수를 제공하므로 출제 맥락에서 가장 적합합니다. 기존 Amazon A2I 고객은 낮은 신뢰도 결과를 인적 검토로 연결할 수 있지만, 현재 신규 고객은 A2I 대신 별도 검토 워크플로를 구성해야 합니다."},"C":{"isCorrect":false,"explanation":"Amazon SageMaker에서 사용자 지정 모델을 구축하고 운영해야 합니다. 이미지 조정에 사용할 사전 구축 Rekognition 기능보다 개발 및 운영 노력이 크므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"사용자 지정 모델을 컨테이너로 배포하고 운영해야 합니다. Fargate가 서버 관리를 줄이더라도 모델 개발과 검토 흐름 구현이 필요하므로 적합하지 않습니다."}}},{"id":"Q0058","question_number":58,"question":"회사는 확장성 및 가용성에 대한 요구 사항을 충족하기 위해 컨테이너에서 중요한 응용 프로그램을 실행하려고 합니다. 회사는 중요한 응용 프로그램의 유지 관리에 집중하는 것을 선호합니다. 회사는 컨테이너화된 워크로드를 실행하는 기본 인프라의 프로비저닝 및 관리에 대한 책임을 원하지 않습니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"Amazon EC2 인스턴스를 사용하고 인스턴스에 Docker 를 설치합니다.","B":"Amazon EC2 작업자 노드에서 Amazon Elastic Container Service(Amazon ECS)를 사용합니다.","C":"AWS Fargate 에서 Amazon Elastic Container Service(Amazon ECS)를 사용합니다.","D":"Amazon Elastic Container Service(Amazon ECS)에 최적화된 Amazon 머신 이미지(AMI)의 Amazon EC2 인스턴스를 사용합니다."},"answers":["C"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능의 탄력적인 컴퓨팅 솔루션 설계","aws_services":["Amazon ECS","AWS Fargate"],"explanation":{"requirementsAnalysis":"회사는 중요한 컨테이너 애플리케이션의 확장성과 가용성을 확보해야 하지만, 워크로드를 실행하는 기본 인프라의 프로비저닝과 관리는 담당하지 않으려 합니다. 따라서 컨테이너 오케스트레이션과 서버리스 컴퓨팅을 결합하여 애플리케이션 운영에 집중할 수 있는 방식이 필요합니다.","awsServicesAnalysis":"Amazon ECS는 컨테이너를 배포하고 관리하는 완전관리형 컨테이너 오케스트레이션 서비스입니다. AWS Fargate는 ECS 태스크와 EKS 포드를 위한 서버리스 컴퓨팅 엔진으로, 고객이 EC2 인스턴스를 프로비저닝하거나 패치하고 관리할 필요가 없습니다. ECS의 EC2 시작 유형과 Docker를 설치한 EC2 인스턴스는 고객이 인스턴스 용량과 운영 체제를 관리해야 합니다. ECS 최적화 AMI는 ECS 컨테이너 인스턴스를 실행하기 위한 Amazon EC2 이미지입니다.","choicesAnalysis":"기본 인프라를 관리하지 않으면서 컨테이너 워크로드를 실행하려면 서버리스 컴퓨팅 엔진을 사용해야 합니다. ECS와 Fargate를 함께 사용하면 태스크 실행을 위해 EC2 인스턴스를 직접 관리하지 않아도 됩니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 EC2 인스턴스를 프로비저닝하고 Docker를 설치 및 관리해야 합니다. 기본 인프라 관리 책임을 원하지 않는 요구에 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B의 ECS EC2 작업자 노드는 컨테이너 인스턴스의 용량, 패치 및 운영을 관리해야 합니다. 따라서 기본 인프라 관리가 불필요한 서버리스 방식이 아니므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 Amazon ECS에서 AWS Fargate를 사용합니다. Fargate는 태스크 실행 인프라를 서버리스로 제공하므로 EC2 인스턴스의 프로비저닝 및 관리를 수행하지 않아도 되어 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 ECS 최적화 AMI가 설치된 EC2 인스턴스를 사용합니다. 인스턴스의 용량과 수명 주기를 관리해야 하므로 적합하지 않습니다."}}},{"id":"Q0059","question_number":59,"question":"회사는 300 개 이상의 글로벌 웹사이트 및 애플리케이션을 호스팅합니다. 이 회사는 매일 30TB 이상의 클릭스트림 데이터를 분석할 플랫폼이 필요합니다. 솔루션 설계자는 클릭스트림 데이터를 전송하고 처리하기 위해 무엇을 해야 합니까?","choices":{"A":"AWS Data Pipeline 을 설계하여 데이터를 Amazon S3 버킷에 보관하고 데이터로 Amazon EMR 클러스터를 실행하여 분석을 생성합니다.","B":"Amazon EC2 인스턴스의 Auto Scaling 그룹을 생성하여 데이터를 처리하고 Amazon Redshift 가 분석에 사용할 수 있도록 Amazon S3 데이터 레이크로 보냅니다.","C":"데이터를 Amazon CloudFront 에 캐시합니다. Amazon S3 버킷에 데이터를 저장합니다. 객체가 S3 버킷에 추가될 때. AWS Lambda 함수를 실행하여 분석용 데이터를 처리합니다.","D":"Amazon Kinesis Data Streams 에서 데이터를 수집합니다. Amazon Kinesis Data Firehose 를 사용하여 Amazon S3 데이터 레이크로 데이터를 전송합니다. 분석을 위해 Amazon Redshift 에 데이터를 로드합니다."},"answers":["D"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터 수집 및 변환 솔루션 결정","aws_services":["Amazon Kinesis","Amazon Data Firehose","Amazon S3","Amazon Redshift"],"explanation":{"requirementsAnalysis":"회사는 300개가 넘는 글로벌 웹사이트와 애플리케이션에서 매일 30TB 이상의 클릭스트림 데이터를 분석해야 합니다. 데이터는 대규모로 지속 유입되므로 수집 계층은 높은 처리량으로 스트림을 받아야 하며, 장기 분석을 위한 데이터 레이크와 분석 저장소로 전달할 수 있어야 합니다. 따라서 확장 가능한 스트리밍 수집, 관리형 전송 및 분석 적재 흐름이 필요합니다.","awsServicesAnalysis":"Amazon Kinesis Data Streams는 대량의 실시간 데이터 레코드를 수집하고 처리하는 스트리밍 서비스입니다. Amazon Data Firehose는 스트리밍 데이터를 Amazon S3, Amazon Redshift 등을 비롯한 대상으로 전송하는 완전관리형 전송 서비스입니다. Amazon S3는 데이터 레이크에 사용할 수 있는 내구성 있는 객체 스토리지입니다. Amazon Redshift는 대규모 분석 쿼리를 위한 데이터 웨어하우스 서비스입니다. AWS Lambda는 이벤트 기반 코드를 실행하며, Amazon EC2 Auto Scaling은 EC2 용량을 조정합니다.","choicesAnalysis":"대규모 클릭스트림은 스트리밍 방식으로 수집한 뒤 관리형 전송 서비스를 통해 S3 데이터 레이크에 저장하고 분석용 데이터 웨어하우스로 적재하는 흐름이 필요합니다. Kinesis Data Streams, Data Firehose, S3 및 Redshift를 연결하면 이 단계를 확장 가능하게 구현할 수 있습니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 Amazon EMR 클러스터를 실행하여 분석할 수 있지만, 대규모 클릭스트림의 지속 수집을 위한 스트리밍 수집 계층이 없습니다. AWS Data Pipeline과 EMR 운영도 관리 부담을 늘리므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 EC2 Auto Scaling 그룹으로 데이터 처리를 직접 구현해야 합니다. 스트림 수집과 전송을 위한 관리형 서비스를 사용하지 않으며, 대규모 처리 인프라 운영 부담이 있으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C의 Amazon CloudFront 캐시는 클릭스트림 수집 서비스가 아니며, S3 객체 생성마다 Lambda로 분석을 수행하는 방식은 일일 30TB 이상의 지속적인 데이터 처리 흐름에 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"D는 Amazon Kinesis Data Streams로 클릭스트림을 수집하고, Amazon Data Firehose로 S3 데이터 레이크에 전송한 뒤 Amazon Redshift에 적재하여 분석할 수 있으므로 적합합니다."}}},{"id":"Q0060","question_number":60,"question":"회사에 AWS 에서 호스팅되는 웹 사이트가 있습니다. 웹 사이트는 HTTP 와 HTTPS 를 별도로 처리하도록 구성된 ALB(Application Load Balancer) 뒤에 있습니다. 회사는 요청이 HTTPS 를 사용하도록 모든 요청을 웹사이트로 전달하려고 합니다. 솔루션 설계자는 이 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"HTTPS 트래픽만 허용하도록 ALB 의 네트워크 ACL 을 업데이트합니다.","B":"URL 의 HTTP 를 HTTPS 로 바꾸는 규칙을 만듭니다.","C":"ALB 에서 리스너 규칙을 생성하여 HTTP 트래픽을 HTTPS 로 리디렉션합니다.","D":"ALB 를 SNI(서버 이름 표시)를 사용하도록 구성된 Network Load Balancer 로 교체합니다."},"answers":["C"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["Elastic Load Balancing(ELB)"],"explanation":{"requirementsAnalysis":"웹사이트는 HTTP와 HTTPS를 각각 처리하는 Application Load Balancer 뒤에 있으며, 모든 웹 요청이 HTTPS를 사용하도록 강제해야 합니다. 따라서 HTTP 요청을 차단하는 것만이 아니라 클라이언트가 HTTPS 주소로 다시 요청할 수 있도록 리디렉션 응답을 제공해야 합니다.","awsServicesAnalysis":"Application Load Balancer의 리스너 규칙은 요청 조건에 따라 전달, 리디렉션 및 고정 응답 등의 작업을 수행할 수 있습니다. HTTP 리스너의 리디렉션 작업은 프로토콜을 HTTPS로 바꾸고 적절한 리디렉션 응답을 클라이언트에 반환할 수 있습니다. 네트워크 ACL은 서브넷 수준에서 트래픽을 허용하거나 거부하는 상태 비저장 제어입니다. Network Load Balancer는 전송 계층 로드 밸런서이며 SNI를 사용해 TLS 리스너에서 여러 인증서를 선택할 수 있습니다.","choicesAnalysis":"HTTP를 HTTPS로 전환하려면 HTTP 리스너가 요청을 HTTPS URL로 리디렉션해야 합니다. ALB 리스너 규칙은 이 동작을 기본 기능으로 제공하며, 단순 차단이나 로드 밸런서 교체는 클라이언트를 HTTPS로 안내하지 않습니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 네트워크 ACL로 HTTPS 외 트래픽을 차단하려는 방식입니다. HTTP 요청에 HTTPS 위치를 알려 주는 리디렉션 응답을 제공하지 않으므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 URL을 바꾸는 규칙을 언급하지만, 웹사이트 외부에서 URL을 변환하는 일반 규칙만으로는 ALB의 HTTP 요청을 HTTPS로 리디렉션하는 구성이 명확하지 않습니다. ALB 리스너 리디렉션을 지정한 C가 요구를 직접 충족합니다."},"C":{"isCorrect":true,"explanation":"C는 ALB의 HTTP 리스너 규칙에서 HTTPS URL로 리디렉션을 반환합니다. 따라서 HTTP로 시작한 요청도 클라이언트가 HTTPS로 다시 연결하게 하므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 Application Load Balancer를 Network Load Balancer로 교체합니다. SNI는 TLS 인증서 선택 기능이며 HTTP에서 HTTPS로의 리디렉션을 제공하지 않으므로 적합하지 않습니다."}}},{"id":"Q0061","question_number":61,"question":"한 회사가 AWS 에서 2 계층 웹 애플리케이션을 개발하고 있습니다. 회사 개발자는 백엔드 Amazon RDS 데이터베이스에 직접 연결되는 Amazon EC2 인스턴스에 애플리케이션을 배포했습니다. 회사는 애플리케이션에 데이터베이스 자격 증명을 하드코딩해서는 안 됩니다. 또한 회사는 정기적으로 데이터베이스 자격 증명을 자동으로 교체하는 솔루션을 구현해야 합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"인스턴스 메타데이터에 데이터베이스 자격 증명을 저장합니다. Amazon EventBridge(Amazon CloudWatch Events) 규칙을 사용하여 RDS 자격 증명과 인스턴스 메타데이터를 동시에 업데이트하는 예약된 AWS Lambda 함수를 실행합니다.","B":"암호화된 Amazon S3 버킷의 구성 파일에 데이터베이스 자격 증명을 저장합니다. Amazon EventBridge(Amazon CloudWatch Events) 규칙을 사용하여 RDS 자격 증명과 구성 파일의 자격 증명을 동시에 업데이트하는 예약된 AWS Lambda 함수를 실행합니다. S3 버전 관리를 사용하여 이전 값으로 폴백하는 기능을 보장합니다.","C":"데이터베이스 자격 증명을 AWS Secrets Manager 에 암호로 저장합니다. 보안 비밀에 대한 자동 순환을 켭니다. EC2 역할에 필요한 권한을 연결하여 보안 암호에 대한 액세스 권한을 부여합니다.","D":"데이터베이스 자격 증명을 AWS Systems Manager Parameter Store 에 암호화된 파라미터로 저장합니다. 암호화된 매개변수에 대해 자동 회전을 켭니다. EC2 역할에 필요한 권한을 연결하여 암호화된 파라미터에 대한 액세스 권한을 부여합니다."},"answers":["C"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["AWS Secrets Manager","IAM","Amazon EC2","Amazon RDS"],"explanation":{"requirementsAnalysis":"애플리케이션은 Amazon EC2에서 Amazon RDS에 연결하지만 데이터베이스 자격 증명을 코드에 포함해서는 안 됩니다. 또한 자격 증명은 정기적으로 자동 교체되어야 하며, 애플리케이션에는 필요한 권한만 부여해야 합니다. 직접 교체 로직과 자격 증명 배포 과정을 운영하면 부담이 커지므로, RDS 자격 증명 관리와 자동 교체를 관리형으로 제공하는 서비스가 필요합니다.","awsServicesAnalysis":"AWS Secrets Manager는 데이터베이스 자격 증명과 같은 보안 비밀을 암호화하여 저장하고, Amazon RDS용 관리형 교체 기능을 제공할 수 있습니다. EC2 인스턴스 프로파일의 IAM 역할에는 해당 보안 비밀을 읽는 최소 권한을 부여할 수 있습니다. AWS Systems Manager Parameter Store의 SecureString은 값을 암호화해 저장하지만 RDS 자격 증명의 관리형 자동 교체 기능을 제공하지 않습니다. 인스턴스 메타데이터와 Amazon S3는 애플리케이션 비밀을 저장하고 순환하기 위한 전용 관리형 솔루션이 아닙니다.","choicesAnalysis":"요구사항의 핵심은 코드에서 분리한 보안 비밀 저장, RDS 자격 증명의 자동 순환, IAM 기반 접근 제어와 낮은 운영 부담입니다. Secrets Manager를 사용하면 애플리케이션이 실행 시점에 자격 증명을 조회하고 서비스가 교체 과정을 관리할 수 있습니다. 다른 선택지는 직접 Lambda 교체 워크플로를 개발하거나 관리형 순환 기능이 없는 저장소를 사용하므로 요구사항을 덜 충족합니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 자격 증명을 인스턴스 메타데이터에 두고 Lambda로 RDS와 값을 함께 갱신해야 합니다. 비밀 관리와 교체 로직을 직접 구현하고 운영해야 하므로 최소 운영 오버헤드 요구사항에 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 암호화와 버전 관리를 제공할 수 있지만, S3 구성 파일과 Lambda를 사용해 교체 절차를 직접 구현해야 합니다. RDS 자격 증명의 관리형 자동 순환을 제공하지 않으므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 AWS Secrets Manager에 RDS 자격 증명을 저장하고 관리형 자동 순환을 사용할 수 있습니다. EC2 IAM 역할로 보안 비밀 조회 권한을 부여하면 하드코딩 없이 최소 권한 접근을 구현할 수 있으므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D의 SecureString 파라미터는 암호화 저장에 사용할 수 있지만, Parameter Store는 RDS 자격 증명의 관리형 자동 순환을 제공하지 않습니다. 별도 자동화가 필요하므로 적합하지 않습니다."}}},{"id":"Q0062","question_number":62,"question":"회사에서 AWS 에 새로운 공개 웹 애플리케이션을 배포하고 있습니다. 애플리케이션은 ALB(Application Load Balancer) 뒤에서 실행됩니다. 애플리케이션은 외부 CA(인증 기관)에서 발급한 SSL/TLS 인증서를 사용하여 에지에서 암호화해야 합니다. 인증서가 만료되기 전에 매년 인증서를 교체해야 합니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"AWS Certificate Manager(ACM)를 사용하여 SSL/TLS 인증서를 발급합니다. 인증서를 ALB 에 적용합니다. 관리형 갱신 기능을 사용하여 인증서를 자동으로 교체합니다.","B":"AWS Certificate Manager(ACM)를 사용하여 SSL/TLS 인증서를 발급합니다. 인증서에서 키 자료를 가져옵니다. AL 에 인증서 적용 관리되는 갱신 기능을 사용하여 인증서를 자동으로 교체합니다.","C":"AWS Certificate Manager(ACM) 사설 인증 기관을 사용하여 루트 CA 에서 SSL/TLS 인증서를 발급합니다. 인증서를 ALB 에 적용합니다. 관리형 갱신 기능을 사용하여 인증서를 자동으로 교체합니다.","D":"AWS Certificate Manager(ACM)를 사용하여 SSL/TLS 인증서를 가져옵니다. 인증서를 ALB 에 적용합니다. Amazon EventBridge(Amazon CloudWatch Events)를 사용하여 인증서가 만료될 때 알림을 보냅니다. 인증서를 수동으로 교체합니다."},"answers":["D"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["AWS Certificate Manager(ACM)","Elastic Load Balancing(ELB)","Amazon EventBridge"],"explanation":{"requirementsAnalysis":"공개 웹 애플리케이션은 ALB에서 외부 인증 기관이 발급한 SSL/TLS 인증서로 TLS를 종료해야 합니다. 인증서가 만료되기 전에 매년 교체해야 하므로 외부 인증서의 갱신 주기를 관리하고 ALB에 새 인증서를 적용하는 절차가 필요합니다. 외부 CA가 발급한 인증서라는 조건 때문에 ACM이 발급하고 자동 갱신하는 퍼블릭 인증서와는 구분해야 합니다.","awsServicesAnalysis":"AWS Certificate Manager는 ACM이 발급한 퍼블릭 인증서를 관리형으로 갱신할 수 있고, 사설 CA 인증서 발급도 지원합니다. 그러나 외부 CA에서 발급한 인증서를 ACM으로 가져온 경우 ACM은 인증서의 갱신이나 교체를 자동으로 수행하지 않습니다. 가져온 인증서는 ALB 리스너에 연결할 수 있으며, Amazon EventBridge는 ACM 인증서 만료 이벤트에 대응하는 알림 또는 자동화에 사용할 수 있습니다.","choicesAnalysis":"외부 CA 인증서는 갱신 시 새 인증서를 외부 CA에서 받아 ACM으로 다시 가져와야 합니다. 만료 알림을 받아 수동 교체하는 방식은 이 조건을 직접 충족합니다. ACM 발급 또는 ACM Private CA 발급을 전제한 선택지는 외부 CA 인증서 요구사항과 맞지 않으며, 가져온 인증서에 관리형 갱신을 적용하는 것도 불가능합니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 ACM이 발급한 퍼블릭 인증서를 전제로 하므로 외부 CA가 발급한 인증서 요구사항을 충족하지 않습니다. ACM 발급 인증서의 관리형 갱신은 가능하지만 이 사례의 인증서에는 적용되지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 ACM에서 발급한 인증서와 키 자료 추출을 전제하며, 외부 CA 인증서 사용 요구사항에 맞지 않습니다. 또한 ACM 발급 퍼블릭 인증서의 프라이빗 키는 내보낼 수 없으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 ACM Private CA가 발급한 사설 인증서를 사용하므로 외부 CA 인증서 조건과 맞지 않습니다. 공개 인터넷 클라이언트가 신뢰할 수 있는 외부 CA 인증서의 교체 방식으로도 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"D는 외부 CA 인증서를 ACM으로 가져와 ALB에 적용하고, 만료 알림에 따라 갱신된 인증서를 수동으로 교체합니다. 가져온 인증서는 ACM이 자동 갱신하지 않으므로 이 방식이 요구사항에 적합합니다."}}},{"id":"Q0063","question_number":63,"question":"회사는 AWS 에서 인프라를 실행하고 문서 관리 애플리케이션에 대해 700,000 명의 등록 기반을 보유하고 있습니다. 회사는 큰 .pdf 파일을 .jpg 이미지 파일로 변환하는 제품을 만들려고 합니다. .pdf 파일의 크기는 평균 5MB 입니다. 회사는 원본 파일과 변환 파일을 보관해야 합니다. 솔루션 설계자는 시간이 지남에 따라 빠르게 증가할 수요를 수용할 수 있는 확장 가능한 솔루션을 설계해야 합니다. 어떤 솔루션이 이러한 요구 사항을 가장 비용 효율적으로 충족합니까?","choices":{"A":".pdf 파일을 Amazon S3 에 저장합니다. AWS Lambda 함수를 호출하여 파일을 .jpg 형식으로 변환하고 Amazon S3 에 다시 저장하도록 S3 PUT 이벤트를 구성합니다.","B":".pdf 파일을 Amazon DynamoD 에 저장 DynamoDB 스트림 기능을 사용하여 AWS Lambda 함수를 호출하여 파일을 .jpg 형식으로 변환하고 DynamoDB 에 다시 저장합니다.","C":"Amazon EC2 인스턴스, Amazon Elastic Block Store(Amazon EBS) 스토리지 및 Auto Scaling 그룹이 포함된 AWS Elastic Beanstalk 애플리케이션에 .pdf 파일을 업로드합니다. EC2 인스턴스의 프로그램을 사용하여 파일을 .jpg 형식으로 변환합니다. .pdf 파일과 .jpg 파일을 EBS 스토어에 저장합니다.","D":".pdf 파일을 Amazon EC2 인스턴스, Amazon Elastic File System(Amazon EFS) 스토리지 및 Auto Scaling 그룹이 포함된 AWS Elastic Beanstalk 애플리케이션에 업로드합니다. EC2 인스턴스의 프로그램을 사용하여 파일을 .jpg 형식으로 변환합니다. .pdf 파일과 .jpg 파일을 EBS 스토어에 저장합니다."},"answers":["A"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 스토리지 솔루션 결정","aws_services":["Amazon S3","AWS Lambda"],"explanation":{"requirementsAnalysis":"회사는 평균 5MB PDF와 변환된 JPG를 모두 보관해야 하며, 등록 사용자 증가에 따라 급격히 늘어나는 변환 수요를 처리해야 합니다. 비용 효율성을 위해 유휴 서버를 상시 운영하지 않고, 파일 저장소는 높은 내구성과 사실상 무제한 확장성을 제공해야 합니다. 파일 업로드를 계기로 자동 변환을 시작하는 이벤트 기반 서버리스 구성이 요구사항에 부합합니다.","awsServicesAnalysis":"Amazon S3는 객체를 내구성 있게 저장하고 PUT 이벤트 알림으로 후속 처리를 시작할 수 있습니다. AWS Lambda는 이벤트에 따라 실행되고 요청량에 맞춰 확장되므로 서버 관리 비용이 없습니다. DynamoDB는 대용량 이진 파일의 일반적인 객체 저장소가 아니며 항목 크기 제한이 있습니다. Elastic Beanstalk, Amazon EC2, Amazon EBS 및 Amazon EFS는 인스턴스, 용량 또는 스토리지 운영을 수반합니다.","choicesAnalysis":"S3에 원본과 결과 파일을 저장하고 업로드 이벤트로 Lambda 변환을 호출하면 수요 증가에 따라 처리 용량이 자동 확장됩니다. 이 방식은 서버와 파일 시스템을 미리 프로비저닝하지 않아 사용량 기반 비용 모델에도 부합합니다. DynamoDB 저장은 파일 크기와 용도에 맞지 않고, Elastic Beanstalk 기반 선택지는 운영 구성 요소가 더 많습니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 S3에 원본과 변환 파일을 저장하고 S3 PUT 이벤트로 Lambda 변환을 시작합니다. 저장소와 처리 계층이 모두 관리형으로 확장되므로 비용 효율적이며 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 평균 5MB 파일을 DynamoDB에 저장하려 하지만 DynamoDB 항목의 최대 크기는 400KB입니다. 파일 저장 요구사항을 충족할 수 없으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 Auto Scaling을 사용해 확장할 수 있지만 EC2, EBS 및 Elastic Beanstalk 환경을 구성하고 관리해야 합니다. 이벤트 기반 S3/Lambda보다 운영 부담과 유휴 비용 가능성이 크므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 EC2와 EFS를 포함한 Elastic Beanstalk 환경을 운영해야 하며, 설명의 EFS 사용과 EBS 저장도 일관되지 않습니다. 서버리스 S3/Lambda 방식보다 비용과 운영 측면에서 적합하지 않습니다."}}},{"id":"Q0064","question_number":64,"question":"회사는 온프레미스에서 실행되는 Windows 파일 서버에 5TB 이상의 파일 데이터를 가지고 있습니다. 사용자와 애플리케이션은 매일 데이터와 상호 작용합니다. 이 회사는 Windows 워크로드를 AWS 로 이전하고 있습니다. 회사가 이 프로세스를 계속함에 따라 회사는 최소 지연 시간으로 AWS 및 온프레미스 파일 스토리지에 액세스할 수 있어야 합니다. 회사는 운영 오버헤드를 최소화하고 기존 파일 액세스 패턴을 크게 변경할 필요가 없는 솔루션이 필요합니다. 회사는 AWS 연결을 위해 AWS Site-to-Site VPN 연결을 사용합니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"AWS 에서 Windows 파일 서버용 Amazon FSx 를 배포 및 구성합니다. 온-프레미스 파일 데이터를 Windows 파일 서버용 FSx 로 이동합니다. AWS 에서 Windows 파일 서버용 FSx 를 사용하도록 워크로드를 재구성합니다.","B":"온프레미스에 Amazon S3 파일 게이트웨이를 배포하고 구성합니다. 온프레미스 파일 데이터를 S3 파일 게이트웨이로 이동합니다. S3 파일 게이트웨이를 사용하도록 온프레미스 워크로드 및 클라우드 워크로드를 재구성합니다.","C":"온프레미스에 Amazon S3 파일 게이트웨이를 배포하고 구성합니다. 온프레미스 파일 데이터를 Amazon S3 로 이동합니다. Amazon S3 를 직접 사용하거나 S3 파일 게이트웨이를 사용하도록 워크로드를 재구성합니다. 각 워크로드의 위치에 따라 다릅니다.","D":"AWS 에서 Windows 파일 서버용 Amazon FSx 를 배포 및 구성합니다. 온프레미스에 Amazon FSx 파일 게이트웨이를 배포하고 구성합니다. 온프레미스 파일 데이터를 FSx 파일 게이트웨이로 이동합니다. AWS 의 Windows 파일 서버용 FSx 를 사용하도록 클라우드 워크로드를 구성합니다. FSx 파일 게이트웨이를 사용하도록 온프레미스 워크로드를 구성합니다."},"answers":["D"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 스토리지 솔루션 결정","aws_services":["Amazon FSx(모든 유형)","AWS Storage Gateway"],"explanation":{"requirementsAnalysis":"회사는 온프레미스 Windows 파일 서버의 5TB 이상 데이터를 AWS로 이전하면서 온프레미스와 AWS 워크로드가 낮은 지연 시간으로 파일에 접근할 수 있어야 합니다. 기존 SMB 기반 Windows 파일 액세스 패턴을 크게 바꾸지 않고 Site-to-Site VPN을 사용하며 운영 부담도 낮춰야 합니다. 출제 시점에는 AWS의 관리형 Windows 파일 시스템과 온프레미스 로컬 캐시를 결합하는 하이브리드 구성이 이 요구에 부합했습니다.","awsServicesAnalysis":"Amazon FSx for Windows File Server는 SMB 액세스와 Active Directory 통합을 제공하는 완전관리형 Windows 파일 시스템입니다. FSx File Gateway는 온프레미스에서 FSx for Windows File Server 데이터에 로컬 캐시와 SMB 인터페이스를 제공했습니다. 그러나 2024년 10월 28일부터 신규 고객은 FSx File Gateway를 생성할 수 없으며 기존 고객만 계속 사용할 수 있습니다. 현재 신규 고객은 네트워크 여건이 허용되면 온프레미스 클라이언트에서 FSx for Windows File Server에 직접 연결하고, 로컬 캐시가 필수이면 Amazon FSx for NetApp ONTAP의 캐시 기능 같은 대안을 검토해야 합니다. S3 File Gateway는 S3 객체를 파일 인터페이스로 제공하며 FSx 파일 시스템용 캐시 게이트웨이가 아닙니다.","choicesAnalysis":"출제 당시에는 클라우드 워크로드가 FSx for Windows File Server에 직접 연결하고 온프레미스 워크로드가 FSx File Gateway의 로컬 캐시를 통해 같은 파일에 접근하는 D가 지연 시간과 기존 SMB 접근 방식을 가장 잘 충족했습니다. 따라서 출제 맥락에서는 D가 정답입니다. 현재 신규 고객은 FSx File Gateway를 생성할 수 없으므로 직접 FSx 접속 또는 FSx for NetApp ONTAP 기반 캐시 같은 현행 대안으로 다시 설계해야 합니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"AWS 워크로드를 FSx for Windows File Server로 옮길 수 있지만 온프레미스 사용자를 위한 로컬 캐시가 없어 출제 당시의 최소 지연 시간 요구를 충분히 충족하지 못합니다. 다만 현재 신규 고객에게는 네트워크 성능이 충분한 경우 온프레미스에서 FSx에 직접 연결하는 방식이 권장될 수 있습니다."},"B":{"isCorrect":false,"explanation":"S3 File Gateway는 S3 객체를 SMB 또는 NFS로 제공하며 FSx for Windows File Server 데이터를 캐시하는 서비스가 아닙니다. 클라우드와 온프레미스 Windows 워크로드가 같은 FSx 파일 시스템을 사용하는 요구에 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"S3 중심으로 워크로드를 재구성해야 하므로 기존 Windows 파일 액세스 패턴이 크게 바뀝니다. 온프레미스와 클라우드가 같은 관리형 Windows 파일 시스템을 사용하는 구성도 아니므로 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"출제 당시에는 FSx for Windows File Server와 온프레미스 FSx File Gateway를 결합해 클라우드의 직접 접근과 온프레미스의 로컬 캐시 접근을 제공하므로 가장 적합했습니다. 현재는 신규 고객이 FSx File Gateway를 생성할 수 없고 기존 고객에게만 적용 가능합니다."}}},{"id":"Q0065","question_number":65,"question":"병원은 최근 Amazon API Gateway 및 AWS Lambda 와 함께 RESTful API 를 배포했습니다. 병원은 API Gateway 및 Lambda 를 사용하여 PDF 형식 및 JPEG 형식의 보고서를 업로드합니다. 병원은 보고서에서 보호되는 건강 정보(PHI)를 식별하기 위해 Lambda 코드를 수정해야 합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"기존 Python 라이브러리를 사용하여 보고서에서 텍스트를 추출하고 추출된 텍스트에서 PHI 를 식별합니다.","B":"Amazon Textract 를 사용하여 보고서에서 텍스트를 추출합니다. Amazon SageMaker 를 사용하여 추출된 텍스트에서 PHI 를 식별합니다.","C":"Amazon Textract 를 사용하여 보고서에서 텍스트를 추출합니다. Amazon Comprehend Medical 을 사용하여 추출된 텍스트에서 PHI 를 식별합니다.","D":"Amazon Rekognition 을 사용하여 보고서에서 텍스트를 추출합니다. Amazon Comprehend Medical 을 사용하여 추출된 텍스트에서 PHI 를 식별합니다."},"answers":["C"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["Amazon Textract","Amazon Comprehend"],"explanation":{"requirementsAnalysis":"병원은 API Gateway와 Lambda로 업로드되는 PDF 및 JPEG 보고서에서 보호되는 건강 정보(PHI)를 식별해야 합니다. 문서와 이미지에서 먼저 텍스트를 추출하고, 의료 맥락의 PHI를 인식해야 합니다. 최소 운영 오버헤드를 위해 자체 OCR 라이브러리나 맞춤형 머신러닝 모델을 구축하기보다 관리형 문서 분석 및 의료 자연어 처리 서비스를 사용해야 합니다.","awsServicesAnalysis":"Amazon Textract는 PDF와 이미지 문서에서 텍스트와 구조화된 정보를 추출하는 관리형 OCR 서비스입니다. Amazon Comprehend Medical은 의료 텍스트에서 의료 정보와 PHI를 식별하는 관리형 자연어 처리 서비스입니다. Amazon SageMaker는 맞춤형 모델을 개발, 학습, 배포할 수 있지만 추가적인 모델 운영이 필요합니다. Amazon Rekognition은 이미지 분석 서비스이지만 문서 OCR의 주된 서비스는 Textract입니다.","choicesAnalysis":"Lambda에서 Textract로 문서 텍스트를 추출한 뒤 Comprehend Medical의 PHI 감지 기능으로 분석하면 두 처리 단계를 모두 관리형 서비스로 수행할 수 있습니다. 자체 라이브러리에는 정확도와 유지보수 부담이 있고, SageMaker는 필요한 기능을 직접 구축해야 합니다. Rekognition은 이 문서 텍스트 추출 시나리오의 적절한 선택이 아닙니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 기존 Python 라이브러리로 OCR과 PHI 식별을 직접 구현하거나 유지해야 합니다. 관리형 서비스 조합보다 운영 부담이 크므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 Textract로 텍스트를 추출할 수 있지만 SageMaker에서 PHI 식별 모델을 개발하고 운영해야 합니다. Comprehend Medical의 관리형 PHI 감지 기능보다 운영 오버헤드가 크므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 Amazon Textract로 PDF/JPEG에서 텍스트를 추출하고 Amazon Comprehend Medical로 의료 PHI를 식별합니다. 두 서비스 모두 관리형이므로 최소 운영 오버헤드 요구사항에 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 Amazon Rekognition을 문서 텍스트 추출에 사용하려 하지만, 이 용도에는 Amazon Textract가 적합합니다. 따라서 관리형 PHI 감지 서비스를 함께 사용하더라도 적합하지 않습니다."}}},{"id":"Q0066","question_number":66,"question":"회사에 각각 크기가 약 5MB 인 많은 수의 파일을 생성하는 응용 프로그램이 있습니다. 파일은 Amazon S3 에 저장됩니다. 회사 정책에 따라 파일을 삭제하려면 4 년 동안 보관해야 합니다. 파일에는 재생산하기 쉽지 않은 중요한 비즈니스 데이터가 포함되어 있으므로 즉각적인 액세스가 항상 필요합니다. 파일은 객체 생성 후 처음 30 일 동안 자주 액세스되지만 처음 30 일 후에는 거의 액세스되지 않습니다. 가장 비용 효율적인 스토리지 솔루션은 무엇입니까?","choices":{"A":"객체 생성 후 30 일 동안 S3 Standard 에서 S3 Glacier 로 파일을 이동하는 S3 버킷 수명 주기 정책을 생성합니다. 객체 생성 후 4 년이 지나면 파일을 삭제합니다.","B":"객체 생성 후 30 일 동안 S3 Standard 에서 S3 One Zone-Infrequent Access(S3 One Zone-IA)로 파일을 이동하는 S3 버킷 수명 주기 정책을 생성합니다. 객체 생성 후 4 년이 지나면 파일을 삭제합니다.","C":"객체 생성 후 30 일 동안 S3 Standard 에서 S3 Standard-Infrequent Access(S3 Standard-IA)로 파일을 이동하는 S3 버킷 수명 주기 정책을 생성합니다. 객체 생성 후 4 년이 지나면 파일을 삭제합니다.","D":"객체 생성 후 30 일 동안 S3 Standard 에서 S3 Standard-Infrequent Access(S3 Standard-IA)로 파일을 이동하는 S3 버킷 수명 주기 정책을 생성합니다. 객체 생성 4 년 후 파일을 S3 Glacier 로 이동합니다."},"answers":["C"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 스토리지 솔루션 설계","aws_services":["Amazon S3"],"explanation":{"requirementsAnalysis":"파일은 생성 후 처음 30일에는 자주 접근되지만 이후에는 거의 접근되지 않으며, 삭제 전까지 4년간 보관해야 합니다. 중요한 비즈니스 데이터이므로 언제든 즉시 액세스할 수 있고 높은 내구성과 가용성을 유지해야 합니다. 따라서 자주 접근하는 기간에는 S3 Standard를 사용하고 이후에는 다중 가용 영역에 저장되면서 밀리초 단위 액세스를 제공하는 저비용 스토리지 클래스로 전환해야 합니다.","awsServicesAnalysis":"S3 Standard는 자주 접근하는 데이터를 위한 스토리지 클래스입니다. S3 Standard-Infrequent Access는 여러 가용 영역에 데이터를 저장하고 즉시 액세스할 수 있어, 접근 빈도가 낮지만 높은 가용성이 필요한 데이터에 적합합니다. S3 One Zone-IA는 하나의 가용 영역에만 저장합니다. S3 Glacier 계열은 아카이브 스토리지 클래스로, 복원 또는 검색 지연이 발생할 수 있어 항상 즉시 접근해야 하는 데이터에 맞지 않습니다. S3 Lifecycle은 객체 전환 및 만료를 자동화합니다.","choicesAnalysis":"30일 후 S3 Standard-IA로 전환하고 4년 후 만료하는 수명 주기 정책은 접근 패턴과 보존 기간을 모두 충족합니다. One Zone-IA는 가용 영역 장애 내성이 부족하고 Glacier는 즉시 액세스 조건을 위반할 수 있습니다. 4년 시점에 Glacier로 전환하면 삭제 요구사항 대신 보존을 계속하므로 맞지 않습니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 30일 후 S3 Glacier로 전환하므로 보관 비용은 낮출 수 있지만, Glacier 객체는 항상 즉시 액세스할 수 있다고 보장할 수 없습니다. 즉시 액세스 요구사항에 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B의 S3 One Zone-IA는 즉시 액세스를 제공하지만 데이터를 단일 가용 영역에 저장합니다. 재생산하기 어려운 중요 데이터에 요구되는 가용성과 복원력에 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 처음 30일은 S3 Standard에 저장하고 이후 S3 Standard-IA로 전환하여 비용을 절감합니다. Standard-IA는 다중 가용 영역 내구성과 즉시 액세스를 제공하며 4년 후 삭제도 자동화하므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 4년이 지난 파일을 삭제하지 않고 S3 Glacier로 이동합니다. 명시된 4년 보존 후 삭제 정책을 충족하지 못하므로 적합하지 않습니다."}}},{"id":"Q0067","question_number":67,"question":"회사는 여러 Amazon EC2 인스턴스에서 애플리케이션을 호스팅합니다. 애플리케이션은 Amazon SQS 대기열의 메시지를 처리하고 Amazon RDS 테이블에 쓰고 대기열에서 메시지를 삭제합니다. RDS 테이블에서 가끔 중복 레코드가 발견됩니다. SQS 대기열에는 중복 메시지가 없습니다. 메시지가 한 번만 처리되도록 솔루션 설계자는 무엇을 해야 합니까?","choices":{"A":"CreateQueue API 호출을 사용하여 새 대기열을 만듭니다.","B":"AddPermission API 호출을 사용하여 적절한 권한을 추가합니다.","C":"ReceiveMessage API 호출을 사용하여 적절한 대기 시간을 설정합니다.","D":"ChangeMessageVisibility API 호출을 사용하여 가시성 시간 초과를 늘립니다."},"answers":["D"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon SQS"],"explanation":{"requirementsAnalysis":"여러 EC2 인스턴스가 SQS 메시지를 처리한 뒤 RDS에 기록하고 메시지를 삭제합니다. 대기열에 중복 메시지가 없는데도 중복 레코드가 발생한다면 처리 완료 전에 가시성 제한 시간이 끝나 같은 메시지가 다른 소비자에게 다시 전달될 수 있습니다. 처리 중 동시 재전달을 줄이려면 작업 시간에 맞게 가시성 제한 시간을 조정해야 합니다. 다만 정확히 한 번의 데이터베이스 반영에는 소비자 측 멱등성도 필요합니다.","awsServicesAnalysis":"Amazon SQS에서 수신한 메시지는 가시성 제한 시간 동안 다른 소비자에게 보이지 않습니다. ChangeMessageVisibility API는 처리 중인 메시지의 가시성 제한 시간을 변경할 수 있습니다. 처리 시간이 이 제한을 넘으면 메시지가 다시 표시되어 다른 소비자가 처리할 수 있습니다. 그러나 SQS 표준 대기열은 적어도 한 번 전달을 제공하므로 가시성 제한 시간 안에도 드물게 중복 전달될 수 있습니다. 정확히 한 번의 RDS 반영을 보장하려면 고유 메시지 ID, 데이터베이스 고유 제약 또는 멱등 쓰기와 같은 애플리케이션 제어가 추가로 필요합니다.","choicesAnalysis":"제시된 선택지 중 관찰된 중복의 직접적인 원인인 처리 중 가시성 제한 시간 만료를 해결하는 방법은 ChangeMessageVisibility로 제한 시간을 늘리는 D입니다. 대기열 생성, 권한 부여, 수신 대기 시간은 처리 중 재전달을 막지 않습니다. 따라서 D가 정답입니다. 다만 D는 중복 가능성을 줄일 뿐 SQS 표준 대기열에서 정확히 한 번 처리를 보장하지 않으므로 실제 설계에는 RDS 쓰기의 멱등성이 필요합니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"CreateQueue는 새 SQS 대기열을 생성하는 API입니다. 기존 메시지의 처리 시간과 가시성 제한 시간 문제를 해결하지 못하므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"AddPermission은 SQS 리소스 정책에 권한을 추가하는 API입니다. 메시지의 재전달과 중복 처리 원인에 영향을 주지 않으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"ReceiveMessage의 대기 시간은 긴 폴링을 제어하며 처리 중인 메시지의 가시성 제한 시간을 연장하지 않습니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"ChangeMessageVisibility로 처리 중인 메시지의 가시성 제한 시간을 작업 시간보다 길게 연장하면 처리 완료 전 다른 소비자에게 다시 표시되는 문제를 줄일 수 있으므로 선택지 중 적합합니다. 정확히 한 번의 RDS 기록을 보장하려면 별도의 멱등성 제어도 필요합니다."}}},{"id":"Q0068","question_number":68,"question":"솔루션 설계자는 회사의 온프레미스 인프라를 AWS 로 확장하기 위해 새로운 하이브리드 아키텍처를 설계하고 있습니다. 이 회사는 AWS 리전에 대해 일관되게 짧은 지연 시간과 고가용성 연결이 필요합니다. 회사는 비용을 최소화해야 하며 기본 연결이 실패할 경우 더 느린 트래픽을 기꺼이 받아들입니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"리전에 대한 AWS Direct Connect 연결을 프로비저닝합니다. 기본 Direct Connect 연결이 실패하는 경우 백업으로 VPN 연결을 프로비저닝합니다.","B":"개인 연결을 위해 지역에 VPN 터널 연결을 프로비저닝합니다. 기본 VPN 연결이 실패할 경우 개인 연결 및 백업으로 두 번째 VPN 터널을 프로비저닝합니다.","C":"리전에 대한 AWS Direct Connect 연결을 프로비저닝합니다. 기본 Direct Connect 연결이 실패하는 경우 백업과 동일한 지역에 두 번째 Direct Connect 연결을 프로비저닝합니다.","D":"리전에 대한 AWS Direct Connect 연결을 프로비저닝합니다. AWS CLI 에서 Direct Connect 장애 조치 속성을 사용하여 기본 Direct Connect 연결이 실패할 경우 백업 연결을 자동으로 생성합니다."},"answers":["A"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 네트워크 아키텍처 결정","aws_services":["AWS Direct Connect","AWS Site-to-Site VPN"],"explanation":{"requirementsAnalysis":"회사는 온프레미스와 AWS 리전 사이에 일관되게 낮은 지연 시간과 고가용성을 제공하는 연결을 원하지만 비용도 최소화해야 합니다. 기본 연결 장애 시에는 성능이 낮아져도 되는 백업 경로를 허용합니다. 따라서 정상 시에는 전용 네트워크 연결을 사용하고, 장애 시에는 더 저렴한 인터넷 기반 암호화 연결로 전환하는 구성이 필요합니다.","awsServicesAnalysis":"AWS Direct Connect는 온프레미스 환경과 AWS 사이의 전용 연결을 제공하여 인터넷 경로보다 일관된 네트워크 성능을 지원합니다. AWS Site-to-Site VPN은 인터넷을 통해 IPsec 터널을 구성하며 Direct Connect의 백업 연결로 사용할 수 있습니다. 두 개의 Direct Connect 연결은 더 높은 전용 연결 복원력을 제공하지만 비용이 증가합니다. AWS CLI에는 Direct Connect 장애 시 새 백업 연결을 자동 생성하는 속성이 없습니다.","choicesAnalysis":"Direct Connect를 기본 연결로 두고 Site-to-Site VPN을 백업으로 구성하면 정상 상태의 지연 시간 요구사항과 장애 시 연결 지속성을 모두 충족합니다. 백업 경로 성능 저하를 수용하므로 두 번째 Direct Connect의 비용은 필요하지 않습니다. VPN만으로는 일관된 저지연 기본 연결을 제공하기 어렵습니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 AWS Direct Connect를 기본 경로로 사용하고 장애 시 Site-to-Site VPN으로 전환합니다. 비용이 더 낮은 VPN 백업을 사용하면서 정상 상태의 일관된 저지연 연결을 제공하므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 VPN 터널만으로 기본 및 백업 연결을 구성합니다. 고가용성은 높일 수 있지만, 기본 연결에 요구되는 일관된 짧은 지연 시간을 보장하는 전용 연결을 제공하지 않으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 두 번째 Direct Connect로 높은 복원력을 제공하지만, 성능이 낮은 백업을 허용하는 조건에서는 비용이 과도합니다. 비용 최소화 요구사항에 가장 적합한 선택이 아닙니다."},"D":{"isCorrect":false,"explanation":"D는 AWS CLI로 장애 시 Direct Connect 백업 연결을 자동 생성할 수 있다는 전제가 올바르지 않습니다. 또한 새 물리적 연결은 즉시 장애 조치 경로로 사용할 수 없으므로 적합하지 않습니다."}}},{"id":"Q0069","question_number":69,"question":"회사는 Application Load Balancer 뒤의 Amazon EC2 인스턴스에서 비즈니스 크리티컬 웹 애플리케이션을 실행하고 있습니다. EC2 인스턴스는 Auto Scaling 그룹에 있습니다. 애플리케이션은 단일 가용 영역에 배포된 Amazon Aurora PostgreSQL 데이터베이스를 사용합니다. 회사는 다운타임과 데이터 손실을 최소화하면서 애플리케이션의 고가용성을 원합니다. 최소한의 운영 노력으로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"EC2 인스턴스를 다른 AWS 리전에 배치합니다. Amazon Route 53 상태 확인을 사용하여 트래픽을 리디렉션합니다. Aurora PostgreSQL 교차 리전 복제를 사용합니다.","B":"여러 가용 영역을 사용하도록 Auto Scaling 그룹을 구성합니다. 데이터베이스를 다중 AZ 로 구성합니다. 데이터베이스에 대한 Amazon RDS 프록시 인스턴스를 구성합니다.","C":"하나의 가용 영역을 사용하도록 Auto Scaling 그룹을 구성합니다. 데이터베이스의 시간별 스냅샷을 생성합니다. 장애가 발생한 경우 스냅샷에서 데이터베이스를 복구합니다.","D":"여러 AWS 리전을 사용하도록 Auto Scaling 그룹을 구성합니다. 애플리케이션의 데이터를 Amazon S3 에 씁니다. S3 이벤트 알림을 사용하여 AWS Lambda 함수를 시작하여 데이터베이스에 데이터를 씁니다."},"answers":["B"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"고가용성 및/또는 내결함성 아키텍처 설계","aws_services":["Amazon EC2 Auto Scaling","Amazon Aurora","Amazon RDS"],"explanation":{"requirementsAnalysis":"웹 계층은 Auto Scaling 그룹에 있지만 단일 가용 영역에 배포된 Aurora PostgreSQL 데이터베이스가 단일 장애 지점입니다. 회사는 다운타임과 데이터 손실을 최소화하는 고가용성을 원하며 운영 노력도 낮춰야 합니다. 따라서 웹 계층과 데이터베이스 계층 모두 여러 가용 영역에 걸쳐 장애 내성을 갖추고, 데이터베이스 장애 조치를 관리형으로 처리해야 합니다.","awsServicesAnalysis":"Amazon EC2 Auto Scaling 그룹은 여러 가용 영역에 인스턴스를 배치할 수 있어 가용 영역 장애에 대비합니다. Amazon Aurora는 다중 가용 영역 구성과 복제본을 통해 고가용성 및 관리형 장애 조치를 지원합니다. Amazon RDS Proxy는 데이터베이스 연결을 풀링하고 장애 조치 시 애플리케이션 연결 복구를 지원할 수 있습니다. 교차 리전 배포는 재해 복구에 유용하지만 이 요구사항에는 더 큰 복잡성을 추가합니다.","choicesAnalysis":"여러 가용 영역으로 확장한 Auto Scaling 그룹과 다중 AZ 데이터베이스 구성은 웹 및 데이터 계층의 단일 가용 영역 장애를 제거합니다. RDS Proxy는 연결을 관리하여 데이터베이스 장애 조치가 애플리케이션에 미치는 영향을 줄일 수 있습니다. 단일 AZ 스냅샷 복구는 복구 시간과 데이터 손실 면에서 부족하며, 여러 리전 구성은 필요한 범위보다 복잡합니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 다른 리전과 교차 리전 복제를 추가하므로 재해 복구에는 도움이 될 수 있지만, 다중 리전 트래픽 전환과 복제를 운영해야 합니다. 동일 리전 고가용성을 최소 운영 노력으로 구현하는 최적의 선택이 아닙니다."},"B":{"isCorrect":true,"explanation":"B는 Auto Scaling 그룹을 여러 가용 영역에 배치하고 데이터베이스를 다중 AZ로 구성합니다. RDS Proxy까지 사용해 연결 장애 영향을 줄일 수 있으므로 다운타임과 데이터 손실을 최소화하는 데 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 웹 계층과 데이터베이스를 단일 가용 영역에 유지하며, 장애 후 스냅샷에서 복구해야 합니다. 복구 시간이 길고 마지막 스냅샷 이후 데이터가 손실될 수 있으므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 Auto Scaling 그룹을 여러 리전에 걸쳐 직접 구성할 수 없으며, S3 이벤트와 Lambda로 데이터베이스 쓰기 경로를 바꾸어도 Aurora의 고가용성을 제공하지 않습니다. 요구사항에 적합하지 않습니다."}}},{"id":"Q0070","question_number":70,"question":"회사의 HTTP 애플리케이션은 NLB(Network Load Balancer) 뒤에 있습니다. NLB 의 대상 그룹은 웹 서비스를 실행하는 여러 EC2 인스턴스와 함께 Amazon EC2 Auto Scaling 그룹을 사용하도록 구성됩니다. 회사는 NLB 가 애플리케이션에 대한 HTTP 오류를 감지하지 못한다는 것을 알게 되었습니다. 이러한 오류는 웹 서비스를 실행하는 EC2 인스턴스를 수동으로 다시 시작해야 합니다. 회사는 사용자 정의 스크립트나 코드를 작성하지 않고 애플리케이션의 가용성을 개선해야 합니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"NLB 에서 HTTP 상태 확인을 활성화하고 회사 응용 프로그램의 URL 을 제공합니다.","B":"EC2 인스턴스에 cron 작업을 추가하여 1 분에 한 번씩 로컬 애플리케이션의 로그를 확인합니다. HTTP 오류가 감지된 경우. 응용 프로그램이 다시 시작됩니다.","C":"NLB 를 Application Load Balancer 로 교체합니다. 회사 애플리케이션의 URL 을 제공하여 HTTP 상태 확인을 활성화합니다. 비정상 인스턴스를 교체하도록 Auto Scaling 작업을 구성합니다.","D":"NLB 에 대한 UnhealthyHostCount 지표를 모니터링하는 Amazon Cloud Watch 경보를 생성합니다. 경보가 ALARM 상태일 때 비정상 인스턴스를 교체하도록 Auto Scaling 작업을 구성합니다."},"answers":["C"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"고가용성 및/또는 내결함성 아키텍처 설계","aws_services":["Elastic Load Balancing(ELB)","Amazon EC2 Auto Scaling"],"explanation":{"requirementsAnalysis":"HTTP 애플리케이션은 NLB 뒤의 Auto Scaling 그룹에서 실행되지만, 현재 상태 확인이 애플리케이션 수준 HTTP 오류를 감지하지 못해 수동 재시작이 필요합니다. 사용자 정의 스크립트나 코드를 쓰지 않고 가용성을 높이려면 HTTP 경로 기반 상태 확인으로 비정상 인스턴스를 판별하고, Auto Scaling이 해당 인스턴스를 자동 교체하도록 구성해야 합니다. 계층 7 상태 확인과 로드 밸런서 상태 기반 인스턴스 교체를 함께 충족해야 합니다.","awsServicesAnalysis":"Application Load Balancer는 HTTP/HTTPS 애플리케이션을 위한 계층 7 로드 밸런서이며, 대상 그룹에서 HTTP 상태 확인 경로와 성공 코드를 설정할 수 있습니다. EC2 Auto Scaling은 Elastic Load Balancing 상태 확인을 사용해 비정상 인스턴스를 종료하고 교체할 수 있습니다. Network Load Balancer도 대상 그룹 HTTP/HTTPS 상태 확인을 지원할 수 있지만, 단순히 상태 확인을 설정하는 것만으로는 Auto Scaling의 인스턴스 교체 구성이 포함되지 않습니다. Amazon CloudWatch 경보는 관측과 알림에 사용되지만 대상별 애플리케이션 오류에 대한 직접적인 교체 체계를 완성하지는 않습니다.","choicesAnalysis":"요구사항은 HTTP 오류 감지뿐 아니라 비정상 인스턴스의 자동 교체입니다. ALB의 HTTP 상태 확인과 Auto Scaling의 ELB 상태 확인을 함께 구성하면 경로 기반으로 비정상 대상을 판별하고 인스턴스를 교체할 수 있습니다. cron 기반 방식은 사용자 정의 코드가 필요하며, 지표 경보만으로는 애플리케이션 상태 확인과 교체를 포괄적으로 구성하지 못합니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 NLB 대상 그룹에 HTTP 상태 확인을 설정할 수 있지만, 비정상 EC2 인스턴스를 Auto Scaling 그룹이 자동 교체하도록 구성하는 내용이 없습니다. 수동 재시작을 없애는 전체 요구사항을 충족하지 못하므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 로컬 로그를 검사하고 재시작하는 사용자 정의 cron 작업을 추가해야 합니다. 사용자 정의 스크립트나 코드를 작성하지 않아야 하는 요구사항에 맞지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 ALB의 HTTP 상태 확인으로 애플리케이션 URL을 검사하고, Auto Scaling이 비정상 인스턴스를 교체하도록 구성합니다. 관리형 상태 확인과 자동 교체를 함께 제공하므로 요구사항에 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 UnhealthyHostCount 경보를 만들 수 있지만, 지표 경보만으로 대상의 HTTP 오류를 검사하고 비정상 인스턴스를 신뢰성 있게 교체하는 구성이 완성되지는 않습니다. ALB 상태 확인과 Auto Scaling 통합보다 적합하지 않습니다."}}},{"id":"Q0071","question_number":71,"question":"한 회사는 Amazon DynamoDB 를 사용하여 고객 정보를 저장하는 쇼핑 애플리케이션을 실행합니다. 데이터 손상의 경우 솔루션 설계자는 15 분의 RPO(복구 시점 목표)와 1 시간의 RTO(복구 시간 목표)를 충족하는 솔루션을 설계해야 합니다. 이러한 요구 사항을 충족하기 위해 솔루션 설계자는 무엇을 권장해야 합니까?","choices":{"A":"DynamoDB 전역 테이블을 구성합니다. RPO 복구의 경우 애플리케이션이 다른 AWS 리전을 가리키도록 합니다.","B":"DynamoDB 지정 시간 복구를 구성합니다. RPO 복구의 경우 원하는 시점으로 복원합니다.","C":"DynamoDB 데이터를 매일 Amazon S3 Glacier 로 내보냅니다. RPO 복구의 경우 S3 Glacier 에서 DynamoDB 로 데이터를 가져옵니다.","D":"DynamoDB 테이블에 대한 Amazon Elastic Block Store(Amazon EBS) 스냅샷을 15 분마다 예약합니다. RPO 복구의 경우 EBS 스냅샷을 사용하여 DynamoDB 테이블을 복원합니다."},"answers":["B"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"고가용성 및/또는 내결함성 아키텍처 설계","aws_services":["Amazon DynamoDB"],"explanation":{"requirementsAnalysis":"회사는 고객 데이터 손상 발생 시 데이터 손실을 최대 15분으로 제한하고 1시간 안에 서비스를 복구해야 합니다. 따라서 최근 시점의 테이블 상태로 복원할 수 있어야 하며, 수동 백업 작업이나 장기 보관 계층의 검색 시간을 복구 절차에 의존하지 않아야 합니다.","awsServicesAnalysis":"Amazon DynamoDB 지정 시간 복구는 테이블 데이터를 연속적으로 백업하고 보존 기간 내 임의의 초 단위 시점으로 새 테이블을 복원할 수 있게 합니다. DynamoDB 전역 테이블은 여러 리전에 복제본을 유지하지만 논리적 데이터 손상도 복제될 수 있습니다. Amazon S3 Glacier는 장기 아카이브 스토리지이며, DynamoDB 테이블의 빠른 복구를 위한 백업 메커니즘이 아닙니다. Amazon EBS 스냅샷은 EBS 볼륨용 기능으로 DynamoDB 테이블에는 적용되지 않습니다.","choicesAnalysis":"15분 RPO를 만족하려면 백업 간격이 하루인 방식보다 연속 백업과 세밀한 복구 시점이 필요합니다. 지정 시간 복구는 별도 백업 스케줄 관리 없이 원하는 손상 이전 시점으로 테이블을 복원할 수 있으므로 1시간 RTO 목표에도 가장 적합합니다. 전역 복제는 가용성에는 도움이 되지만 데이터 손상 복구 대책으로는 충분하지 않습니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 리전 장애에 대한 가용성을 높일 수 있지만, 데이터 손상이 다른 리전 복제본에도 전파될 수 있습니다. 손상 이전 시점으로 복원하는 방법을 제공하지 않으므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 DynamoDB 지정 시간 복구를 사용하여 보존 기간 내 원하는 손상 이전 시점으로 테이블을 복원할 수 있습니다. 연속 백업을 기반으로 하므로 15분 RPO와 1시간 RTO 요구 사항에 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 데이터를 하루에 한 번만 내보내므로 15분 RPO를 충족하지 못합니다. 또한 S3 Glacier의 아카이브 복원과 DynamoDB 가져오기 절차는 신속한 복구에 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 DynamoDB 테이블에 Amazon EBS 스냅샷을 생성할 수 없으므로 구현할 수 없습니다. DynamoDB는 EBS 볼륨을 직접 관리하는 서비스가 아닙니다."}}},{"id":"Q0072","question_number":72,"question":"회사는 동일한 AWS 리전에 있는 Amazon S3 버킷에서 사진을 자주 업로드 및 다운로드해야 하는 사진 처리 애플리케이션을 실행합니다. 솔루션 설계자는 데이터 전송 비용이 증가한다는 사실을 알게 되었고 이러한 비용을 줄이기 위한 솔루션을 구현해야 합니다. 솔루션 설계자는 이 요구 사항을 어떻게 충족할 수 있습니까?","choices":{"A":"Amazon API Gateway 를 퍼블릭 서브넷에 배포하고 이를 통해 S3 호출을 라우팅하도록 라우팅 테이블을 조정합니다.","B":"NAT 게이트웨이를 퍼블릭 서브넷에 배포하고 S3 버킷에 대한 액세스를 허용하는 엔드포인트 정책을 연결합니다.","C":"애플리케이션을 퍼블릭 서브넷에 배포하고 S3 버킷에 액세스하기 위해 인터넷 게이트웨이를 통해 라우팅하도록 허용합니다.","D":"S3 VPC 게이트웨이 엔드포인트를 VPC 에 배포하고 S3 버킷에 대한 액세스를 허용하는 엔드포인트 정책을 연결합니다."},"answers":["D"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 네트워크 아키텍처 설계","aws_services":["Amazon S3","Amazon VPC"],"explanation":{"requirementsAnalysis":"애플리케이션은 동일 리전의 Amazon S3 버킷에 사진을 자주 업로드하고 다운로드하며, 데이터 전송 비용을 줄여야 합니다. 그러므로 인터넷 또는 NAT 게이트웨이를 경유하지 않고 VPC 내부에서 S3로 비공개 연결되는 경로가 필요합니다.","awsServicesAnalysis":"Amazon S3용 VPC 게이트웨이 엔드포인트는 VPC와 S3 사이의 비공개 연결을 제공하며 시간당 또는 처리량당 엔드포인트 비용이 없습니다. 엔드포인트 정책으로 액세스할 S3 버킷과 작업을 제한할 수 있습니다. NAT 게이트웨이는 프라이빗 서브넷의 인터넷 송신을 제공하지만 시간당 및 데이터 처리 요금이 발생합니다. 인터넷 게이트웨이와 API Gateway는 VPC에서 S3로 비공개 연결을 제공하는 수단이 아닙니다.","choicesAnalysis":"S3 VPC 게이트웨이 엔드포인트를 사용하면 동일 리전 S3 액세스가 인터넷/NAT 경로를 거치지 않으며, 보안 정책으로 대상 버킷 접근도 제한할 수 있습니다. 다른 선택지는 불필요한 중계 계층을 추가하거나 인터넷 경로를 사용하므로 비용 절감 목적에 맞지 않습니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 Amazon API Gateway는 S3 액세스를 위한 VPC 네트워크 경로가 아니며, 퍼블릭 서브넷에 배포하는 서비스도 아닙니다. 비용 절감 요구 사항에 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B의 NAT 게이트웨이는 인터넷 송신을 위한 서비스이며 데이터 처리 요금이 발생합니다. S3용 게이트웨이 엔드포인트 정책을 NAT 게이트웨이에 연결할 수도 없으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 S3 액세스를 인터넷 게이트웨이로 라우팅하므로 비공개 S3 연결을 사용하지 않습니다. 퍼블릭 서브넷 배치도 전송 비용 절감의 직접적인 해결책이 아닙니다."},"D":{"isCorrect":true,"explanation":"D는 S3 VPC 게이트웨이 엔드포인트를 통해 VPC에서 S3로 비공개 연결을 제공하고, 엔드포인트 정책으로 대상 버킷 접근을 제한할 수 있습니다. NAT 게이트웨이 데이터 처리 비용을 피할 수 있으므로 적합합니다."}}},{"id":"Q0073","question_number":73,"question":"한 회사는 최근 프라이빗 서브넷의 Amazon EC2 에서 Linux 기반 애플리케이션 인스턴스를 시작하고 VPC 의 퍼블릭 서브넷에 있는 Amazon EC2 인스턴스에서 Linux 기반 배스천 호스트를 시작했습니다. 솔루션 설계자는 사내 네트워크에서 회사의 인터넷 연결을 통해 배스천 호스트 및 애플리케이션 서버에 연결해야 합니다. 솔루션 설계자는 모든 EC2 인스턴스의 보안 그룹이 해당 액세스를 허용하는지 확인해야 합니다. 솔루션 설계자는 이러한 요구 사항을 충족하기 위해 어떤 단계 조합을 취해야 합니까? (2 개를 선택하세요.)","choices":{"A":"배스천 호스트의 현재 보안 그룹을 애플리케이션 인스턴스의 인바운드 액세스만 허용하는 보안 그룹으로 교체합니다.","B":"배스천 호스트의 현재 보안 그룹을 회사의 내부 IP 범위에서만 인바운드 액세스를 허용하는 보안 그룹으로 교체합니다.","C":"배스천 호스트의 현재 보안 그룹을 회사의 외부 IP 범위에서만 인바운드 액세스를 허용하는 보안 그룹으로 교체합니다.","D":"애플리케이션 인스턴스의 현재 보안 그룹을 배스천 호스트의 개인 IP 주소에서만 인바운드 SSH 액세스를 허용하는 보안 그룹으로 교체합니다.","E":"애플리케이션 인스턴스의 현재 보안 그룹을 배스천 호스트의 공용 IP 주소에서만 인바운드 SSH 액세스를 허용하는 보안 그룹으로 교체합니다."},"answers":["C","D"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["Amazon EC2","Amazon VPC"],"explanation":{"requirementsAnalysis":"관리자는 사내 네트워크에서 인터넷을 통해 퍼블릭 서브넷의 배스천 호스트에 접속한 뒤 프라이빗 서브넷의 애플리케이션 인스턴스로 SSH 연결해야 합니다. 따라서 배스천 호스트는 회사 인터넷 연결의 공인 송신 IP 범위에서만 인바운드를 허용해야 하며, 애플리케이션 인스턴스는 배스천 호스트에서 오는 프라이빗 IP 기반 SSH 연결만 허용해야 합니다.","awsServicesAnalysis":"Amazon EC2 보안 그룹은 인바운드 및 아웃바운드 트래픽을 제어하는 상태 저장 방화벽입니다. 인터넷을 통해 배스천 호스트에 접속할 때 소스는 회사 네트워크의 공인 또는 외부 IP 주소 범위입니다. 같은 VPC 안에서 배스천 호스트가 프라이빗 인스턴스에 연결하면 소스는 배스천 호스트의 프라이빗 IP 주소입니다. 보안 그룹은 보안 그룹 참조도 지원하지만, 이 문제의 선택지에서는 해당 프라이빗 IP 주소를 허용하는 방식이 제시됩니다.","choicesAnalysis":"접속 흐름은 회사 네트워크에서 배스천 호스트로 들어온 뒤 배스천 호스트에서 애플리케이션 인스턴스로 이동합니다. 그러므로 첫 번째 홉에는 회사의 외부 IP 범위를, 두 번째 홉에는 배스천 호스트의 프라이빗 IP 주소를 허용해야 합니다. 배스천의 공인 IP는 VPC 내부 SSH 패킷의 소스가 아니며, 회사의 내부 사설 IP는 인터넷을 통한 배스천 접속의 소스가 아닙니다. 따라서 C와 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 배스천 호스트에서 애플리케이션 인스턴스로의 트래픽만 고려하며, 회사 네트워크에서 배스천 호스트로 들어오는 SSH 접속을 허용하지 않습니다. 요구 사항을 충족하지 못합니다."},"B":{"isCorrect":false,"explanation":"B는 인터넷을 통해 배스천 호스트에 접속할 때 실제 소스로 보이는 회사 네트워크의 공인 송신 IP 범위가 아니라 내부 사설 IP 범위를 허용합니다. 따라서 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 회사 네트워크가 인터넷으로 나갈 때 사용하는 외부 또는 공인 IP 범위에서 배스천 호스트로의 인바운드 접속을 제한합니다. 관리자의 배스천 접근에 적합합니다."},"D":{"isCorrect":true,"explanation":"D는 VPC 내부에서 배스천 호스트가 애플리케이션 인스턴스에 SSH 연결할 때 사용하는 배스천 호스트의 프라이빗 IP 주소만 허용합니다. 프라이빗 애플리케이션 인스턴스 접근에 적합합니다."},"E":{"isCorrect":false,"explanation":"E는 배스천 호스트의 공용 IP 주소를 허용하지만, VPC 내부에서 애플리케이션 인스턴스로 전송되는 SSH 트래픽의 소스는 배스천 호스트의 프라이빗 IP 주소입니다. 따라서 적합하지 않습니다."}}},{"id":"Q0074","question_number":74,"question":"솔루션 설계자는 2 계층 웹 애플리케이션을 설계하고 있습니다. 애플리케이션은 퍼블릭 서브넷의 Amazon EC2 에서 호스팅되는 퍼블릭 웹 티어로 구성됩니다. 데이터베이스 계층은 프라이빗 서브넷의 Amazon EC2 에서 실행되는 Microsoft SQL Server 로 구성됩니다. 보안은 회사의 최우선 과제입니다. 이 상황에서 보안 그룹을 어떻게 구성해야 합니까? (2 개를 선택하세요.)","choices":{"A":"0.0.0.0/0 에서 포트 443 의 인바운드 트래픽을 허용하도록 웹 계층에 대한 보안 그룹을 구성합니다.","B":"0.0.0.0/0 에서 포트 443 의 아웃바운드 트래픽을 허용하도록 웹 계층에 대한 보안 그룹을 구성합니다.","C":"웹 계층에 대한 보안 그룹에서 포트 1433 의 인바운드 트래픽을 허용하도록 데이터베이스 계층에 대한 보안 그룹을 구성합니다.","D":"데이터베이스 계층의 보안 그룹을 구성하여 포트 443 및 1433 의 아웃바운드 트래픽을 웹 계층의 보안 그룹으로 보냅니다.","E":"웹 계층에 대한 보안 그룹의 포트 443 및 1433 에서 인바운드 트래픽을 허용하도록 데이터베이스 계층에 대한 보안 그룹을 구성합니다."},"answers":["A","C"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["Amazon EC2","Amazon VPC"],"explanation":{"requirementsAnalysis":"애플리케이션은 인터넷에 공개되는 웹 계층과 프라이빗 서브넷의 SQL Server 데이터베이스 계층으로 구성됩니다. 보안을 우선하면 웹 계층에는 필요한 HTTPS만 공개하고, 데이터베이스에는 웹 계층에서 필요한 SQL Server 포트만 허용해야 합니다. 데이터베이스를 인터넷에 직접 노출하거나 불필요한 포트를 열어서는 안 됩니다.","awsServicesAnalysis":"Amazon EC2 보안 그룹은 상태 저장 방식으로 인바운드 허용 규칙에 대한 응답 트래픽을 자동으로 허용합니다. HTTPS의 기본 포트는 443이고 Microsoft SQL Server의 기본 수신 포트는 1433입니다. 보안 그룹 규칙의 소스로 다른 보안 그룹을 지정하면 해당 계층의 인스턴스에서 오는 트래픽만 허용할 수 있습니다.","choicesAnalysis":"웹 계층은 공용 서비스이므로 인터넷 사용자의 HTTPS 요청을 포트 443에서 수신해야 합니다. 데이터베이스 계층은 웹 계층 보안 그룹을 소스로 지정한 포트 1433 인바운드 규칙만 필요합니다. 광범위한 아웃바운드 규칙이나 데이터베이스 포트 443 허용은 요구된 최소 권한 구성과 맞지 않습니다. 따라서 A와 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 인터넷 사용자의 HTTPS 요청을 웹 계층의 포트 443에서 수신하도록 허용합니다. 공개 웹 계층에 필요한 인바운드 규칙이므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 웹 계층의 포트 443 아웃바운드 트래픽을 0.0.0.0/0에 허용하지만, 클라이언트의 HTTPS 요청을 수신하는 데 필요한 규칙은 인바운드 규칙입니다. 요구 사항에 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 데이터베이스 계층의 포트 1433 인바운드를 웹 계층 보안 그룹에만 허용합니다. SQL Server 접근을 웹 계층으로 제한하므로 최소 권한 원칙에 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 데이터베이스 계층에서 웹 계층으로 향하는 아웃바운드 트래픽을 설정합니다. 필요한 흐름은 웹 계층에서 데이터베이스 계층으로의 인바운드 SQL 연결이므로 적합하지 않습니다."},"E":{"isCorrect":false,"explanation":"E는 데이터베이스 계층에 포트 443과 1433을 모두 허용합니다. SQL Server에는 포트 1433만 필요하므로 포트 443까지 여는 것은 최소 권한 원칙에 맞지 않습니다."}}},{"id":"Q0075","question_number":75,"question":"한 회사에서 애플리케이션의 성능을 개선하기 위해 다계층 애플리케이션을 온프레미스에서 AWS 클라우드로 이동하려고 합니다. 애플리케이션은 RESTful 서비스를 통해 서로 통신하는 애플리케이션 계층으로 구성됩니다. 한 계층이 오버로드되면 트랜잭션이 삭제됩니다. 솔루션 설계자는 이러한 문제를 해결하고 애플리케이션을 현대화하는 솔루션을 설계해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족하고 운영상 가장 효율적입니까?","choices":{"A":"Amazon API Gateway 를 사용하고 애플리케이션 계층으로 AWS Lambda 함수에 트랜잭션을 전달합니다. Amazon Simple Queue Service(Amazon SQS)를 애플리케이션 서비스 간의 통신 계층으로 사용합니다.","B":"Amazon CloudWatch 지표를 사용하여 애플리케이션 성능 기록을 분석하여 성능 장애 동안 서버의 최대 사용률을 결정합니다. 최대 요구 사항을 충족하도록 애플리케이션 서버의 Amazon EC2 인스턴스 크기를 늘립니다.","C":"Amazon Simple Notification Service(Amazon SNS)를 사용하여 Auto Scaling 그룹의 Amazon EC2 에서 실행되는 애플리케이션 서버 간의 메시징을 처리합니다. Amazon CloudWatch 를 사용하여 SNS 대기열 길이를 모니터링하고 필요에 따라 확장 및 축소합니다.","D":"Amazon Simple Queue Service(Amazon SQS)를 사용하여 Auto Scaling 그룹의 Amazon EC2 에서 실행되는 애플리케이션 서버 간의 메시징을 처리합니다. Amazon CloudWatch 를 사용하여 SQS 대기열 길이를 모니터링하고 통신 오류가 감지되면 확장합니다."},"answers":["A"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon API Gateway","AWS Lambda","Amazon SQS"],"explanation":{"requirementsAnalysis":"다계층 애플리케이션은 RESTful 서비스 간에 동기적으로 통신하며, 한 계층이 과부하되면 트랜잭션이 삭제됩니다. 솔루션은 요청을 완충해 계층을 느슨하게 결합하고, 급격한 부하에도 처리 능력을 독립적으로 확장해야 합니다. 또한 현대화와 운영 효율성이 요구되므로 서버 관리 부담이 적은 서비스가 적합합니다.","awsServicesAnalysis":"Amazon API Gateway는 API 요청을 수신하고 백엔드 서비스에 통합할 수 있는 관리형 서비스입니다. AWS Lambda는 서버 관리 없이 코드 실행을 자동 확장합니다. Amazon SQS는 내구성 있는 메시지 대기열로 생산자와 소비자를 분리하고 일시적 과부하 시 메시지를 보존합니다. Amazon SNS는 게시/구독 알림 서비스이며 대기열 길이 지표를 제공하지 않습니다. Amazon EC2 Auto Scaling은 인스턴스 용량을 조정하지만 서버 운영이 필요합니다.","choicesAnalysis":"과부하 시 트랜잭션 삭제를 막으려면 계층 사이에 내구성 있는 대기열을 두어 비동기 처리해야 합니다. API Gateway, Lambda, SQS 조합은 요청 수신·컴퓨팅·완충을 관리형 서비스로 제공하여 운영 부담도 낮춥니다. EC2 기반 대안은 서버 운영이 필요하고, SNS는 대기열 길이를 기반으로 한 소비자 확장 구조가 아닙니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 API Gateway와 Lambda로 서버리스 애플리케이션 계층을 구성하고 SQS로 서비스 간 트랜잭션을 내구성 있게 버퍼링합니다. 과부하 시 메시지 손실을 줄이고 운영 부담도 낮추므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 과거 사용률에 맞춰 EC2 인스턴스 크기를 늘리는 방식입니다. 계층 간 결합과 과부하 시 트랜잭션 삭제 문제를 해결하지 못하며, 예측할 수 없는 부하에도 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 SNS를 메시징에 사용하지만 SNS는 메시지 소비 속도를 조절하는 대기열이 아니며 SNS 대기열 길이를 모니터링할 수 없습니다. 요구된 내구성 있는 완충 구조에 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 SQS로 비동기 메시징을 제공하지만 EC2 서버와 Auto Scaling 그룹을 운영해야 합니다. 또한 통신 오류 감지는 대기열 적체에 따른 확장 기준이 아니므로 가장 운영 효율적인 해법이 아닙니다."}}},{"id":"Q0076","question_number":76,"question":"회사는 단일 공장에 있는 여러 기계에서 매일 10TB 의 계측 데이터를 수신합니다. 데이터는 공장 내에 위치한 온프레미스 데이터 센터의 SAN(Storage Area Network)에 저장된 JSON 파일로 구성됩니다. 회사는 이 데이터를 Amazon S3 로 전송하여 중요한 실시간에 가까운 분석을 제공하는 여러 추가 시스템에서 액세스할 수 있기를 원합니다. 데이터가 민감한 것으로 간주되기 때문에 안전한 전송이 중요합니다. 가장 안정적인 데이터 전송을 제공하는 솔루션은 무엇입니까?","choices":{"A":"공용 인터넷을 통한 AWS DataSync","B":"AWS Direct Connect 를 통한 AWS DataSync","C":"공용 인터넷을 통한 AWS Database Migration Service(AWS DMS)","D":"AWS Direct Connect 를 통한 AWS Database Migration Service(AWS DMS)"},"answers":["B"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 네트워크 아키텍처 결정","aws_services":["AWS DataSync","AWS Direct Connect","Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 단일 공장에서 매일 10TB의 JSON 파일을 온프레미스 SAN에서 Amazon S3로 전송하고, 여러 시스템이 실시간에 가깝게 이를 분석할 수 있어야 합니다. 데이터가 민감하므로 보안 전송이 필요하며, 대규모 정기 전송을 안정적으로 제공하는 네트워크 경로가 핵심입니다.","awsServicesAnalysis":"AWS DataSync는 NFS, SMB 등 온프레미스 스토리지 시스템과 AWS 스토리지 서비스 사이에서 대용량 파일 데이터를 전송하는 관리형 서비스입니다. AWS Direct Connect는 온프레미스와 AWS 사이에 전용 네트워크 연결을 제공하여 공용 인터넷보다 일관되고 예측 가능한 연결을 지원합니다. AWS Database Migration Service는 데이터베이스를 마이그레이션하고 복제하는 서비스로 SAN의 JSON 파일 전송용 서비스가 아닙니다.","choicesAnalysis":"소스 데이터는 데이터베이스가 아니라 SAN에 저장된 파일이므로 DataSync가 적합합니다. 매일 10TB의 민감한 데이터를 안정적으로 전송하려면 공용 인터넷보다 전용 연결인 Direct Connect를 DataSync 전송 경로로 사용하는 것이 적절합니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 DataSync로 파일 전송을 수행할 수 있지만 공용 인터넷 경로를 사용합니다. 대용량의 민감한 데이터를 가장 안정적으로 전송해야 하는 요구 사항에는 Direct Connect 방식보다 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 DataSync로 SAN의 JSON 파일을 Amazon S3로 전송하고 Direct Connect로 일관된 전용 네트워크 연결을 사용합니다. 대규모 민감 데이터의 안정적 전송 요구 사항에 적합합니다."},"C":{"isCorrect":false,"explanation":"C의 AWS DMS는 데이터베이스 마이그레이션과 복제를 위한 서비스입니다. SAN에 저장된 JSON 파일을 Amazon S3로 전송하는 요구 사항에 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 Direct Connect를 사용하더라도 AWS DMS가 파일 기반 SAN 데이터를 전송하는 서비스가 아닙니다. 따라서 구현 목적에 적합하지 않습니다."}}},{"id":"Q0077","question_number":77,"question":"회사는 애플리케이션에 대한 실시간 데이터 수집 아키텍처를 구성해야 합니다. 회사에는 데이터가 스트리밍될 때 데이터를 변환하는 프로세스인 API 와 데이터를 위한 스토리지 솔루션이 필요합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"Amazon EC2 인스턴스를 배포하여 Amazon Kinesis 데이터 스트림으로 데이터를 전송하는 API 를 호스팅합니다. Kinesis 데이터 스트림을 데이터 원본으로 사용하는 Amazon Kinesis Data Firehose 전송 스트림을 생성합니다. AWS Lambda 함수를 사용하여 데이터를 변환합니다. Kinesis Data Firehose 전송 스트림을 사용하여 데이터를 Amazon S3 로 보냅니다.","B":"Amazon EC2 인스턴스를 배포하여 AWS Glue 에 데이터를 전송하는 API 를 호스팅합니다. EC2 인스턴스에서 소스/대상 확인을 중지합니다. AWS Glue 를 사용하여 데이터를 변환하고 데이터를 Amazon S3 로 보냅니다.","C":"Amazon Kinesis 데이터 스트림으로 데이터를 보내도록 Amazon API Gateway API 를 구성합니다. Kinesis 데이터 스트림을 데이터 원본으로 사용하는 Amazon Kinesis Data Firehose 전송 스트림을 생성합니다. AWS Lambda 함수를 사용하여 데이터를 변환합니다. Kinesis Data Firehose 전송 스트림을 사용하여 데이터를 Amazon S3 로 보냅니다.","D":"데이터를 AWS Glue 로 보내도록 Amazon API Gateway API 를 구성합니다. AWS Lambda 함수를 사용하여 데이터를 변환합니다. AWS Glue 를 사용하여 데이터를 Amazon S3 로 보냅니다."},"answers":["C"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터 수집 및 변환 솔루션 결정","aws_services":["Amazon API Gateway","Amazon Kinesis","Amazon Data Firehose","AWS Lambda","Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 실시간으로 수집되는 데이터를 받아 변환한 뒤 저장해야 합니다. 수집용 API, 스트리밍 변환, 저장소가 모두 필요하며 운영 오버헤드는 최소화해야 합니다. 따라서 서버를 직접 운영하지 않고 관리형 API·스트리밍·전달 서비스를 조합하는 구성이 필요합니다.","awsServicesAnalysis":"Amazon API Gateway는 관리형 API 엔드포인트를 제공하고 Amazon Kinesis Data Streams와 통합할 수 있습니다. Kinesis Data Streams는 실시간 스트리밍 데이터를 수집합니다. Amazon Data Firehose는 스트림 데이터를 대상 저장소로 전달하며 AWS Lambda를 호출해 전달 전에 데이터를 변환할 수 있습니다. Amazon S3는 대용량 데이터를 내구성 있게 저장합니다. AWS Glue는 주로 ETL 및 데이터 카탈로그 작업에 사용되며 API 기반 실시간 수집 흐름의 대체 수단이 아닙니다.","choicesAnalysis":"API Gateway에서 Kinesis Data Streams로 데이터를 수집하고, Data Firehose와 Lambda로 변환 후 S3로 전달하면 모든 구성 요소가 관리형 서비스입니다. EC2에서 API를 호스팅하면 서버 운영 부담이 추가되며, Glue 중심 선택지는 실시간 스트리밍 API 수집 구조에 맞지 않습니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 Kinesis, Data Firehose, Lambda, S3를 적절히 사용하지만 API를 EC2 인스턴스에서 직접 호스팅합니다. 관리형 API Gateway를 사용하는 구성보다 운영 오버헤드가 크므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 API를 EC2에서 호스팅하고 AWS Glue로 데이터를 보내며, EC2의 소스/대상 확인 해제도 이 흐름에 필요하지 않습니다. 실시간 스트리밍 수집과 최소 운영 요구 사항에 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 API Gateway로 수집 API를 제공하고 Kinesis Data Streams, Data Firehose, Lambda로 실시간 데이터 수집·변환·전달을 수행한 뒤 S3에 저장합니다. 서버 관리가 필요하지 않으므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 API Gateway와 Lambda를 사용하지만 AWS Glue는 이 실시간 스트리밍 수집 및 전달 흐름의 적절한 대상 서비스가 아닙니다. Kinesis와 Data Firehose 기반 구성보다 요구 사항에 적합하지 않습니다."}}},{"id":"Q0078","question_number":78,"question":"회사는 사용자 트랜잭션 데이터를 Amazon DynamoDB 테이블에 보관해야 합니다. 회사는 데이터를 7 년간 보관해야 합니다. 이러한 요구 사항을 충족하는 가장 운영 효율성이 높은 솔루션은 무엇입니까?","choices":{"A":"DynamoDB 지정 시간 복구를 사용하여 테이블을 지속적으로 백업합니다.","B":"AWS Backup 을 사용하여 테이블에 대한 백업 일정 및 보존 정책을 생성합니다.","C":"DynamoDB 콘솔을 사용하여 테이블의 주문형 백업을 생성합니다. 백업을 Amazon S3 버킷에 저장합니다. S3 버킷에 대한 S3 수명 주기 구성을 설정합니다.","D":"AWS Lambda 함수를 호출하는 Amazon EventBridge(Amazon CloudWatch Events) 규칙을 생성합니다. 테이블을 백업하고 Amazon S3 버킷에 백업을 저장하도록 Lambda 함수를 구성합니다. S3 버킷에 대한 S3 수명 주기 구성을 설정합니다."},"answers":["B"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 스토리지 솔루션 설계","aws_services":["AWS Backup","Amazon DynamoDB"],"explanation":{"requirementsAnalysis":"회사는 DynamoDB 사용자 트랜잭션 데이터를 7년 동안 보관해야 하며, 운영 효율성이 가장 높은 백업 및 보존 방식을 원합니다. 그러므로 장기 보존 기간을 적용하는 일정 기반 백업을 관리형으로 구성할 수 있어야 합니다.","awsServicesAnalysis":"AWS Backup은 DynamoDB를 포함한 AWS 리소스의 백업 계획, 일정 및 보존 수명 주기를 중앙에서 관리합니다. DynamoDB 지정 시간 복구는 연속 백업으로 임의 시점 복원을 제공하지만 보존 기간은 최대 35일입니다. DynamoDB의 주문형 백업은 관리형 DynamoDB 백업으로 유지되며 콘솔에서 백업을 S3 버킷에 직접 저장하는 기능은 제공하지 않습니다. Lambda와 EventBridge로 백업을 직접 자동화하면 코드와 운영 작업이 추가됩니다.","choicesAnalysis":"7년 보관은 지정 시간 복구의 최대 보존 기간을 초과합니다. AWS Backup으로 DynamoDB 백업 일정과 7년 보존 정책을 정의하면 맞춤 코드 없이 장기 보존을 관리할 수 있습니다. S3로 직접 저장하거나 Lambda로 자동화하는 방식은 지원되지 않거나 불필요한 운영 복잡성을 만듭니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 DynamoDB 지정 시간 복구 보존 기간은 최대 35일입니다. 7년 보관 요구 사항을 충족하지 못하므로 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 AWS Backup에서 DynamoDB 테이블의 백업 일정과 7년 보존 정책을 관리형으로 설정할 수 있습니다. 장기 보관과 운영 효율성 요구 사항에 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 DynamoDB 주문형 백업을 Amazon S3 버킷에 직접 저장할 수 없으며, 수동 백업 생성도 운영 효율성이 낮습니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 사용자 지정 Lambda 코드와 EventBridge 규칙을 개발·운영해야 합니다. AWS Backup의 기본 일정 및 보존 정책보다 복잡하므로 가장 운영 효율적인 해법이 아닙니다."}}},{"id":"Q0079","question_number":79,"question":"회사에서 데이터 저장을 위해 Amazon DynamoDB 테이블을 사용할 계획입니다. 회사는 비용 최적화에 대해 우려하고 있습니다. 대부분의 아침에는 테이블을 사용하지 않습니다. 저녁에는 읽기 및 쓰기 트래픽이 예측할 수 없는 경우가 많습니다. 트래픽 급증이 발생하면 매우 빠르게 발생합니다. 솔루션 아키텍트는 무엇을 추천해야 합니까?","choices":{"A":"온디맨드 용량 모드에서 DynamoDB 테이블을 생성합니다.","B":"글로벌 보조 인덱스가 있는 DynamoDB 테이블을 생성합니다.","C":"프로비저닝된 용량 및 Auto Scaling 을 사용하여 DynamoDB 테이블을 생성합니다.","D":"프로비저닝된 용량 모드에서 DynamoDB 테이블을 생성하고 전역 테이블로 구성합니다."},"answers":["A"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 데이터베이스 솔루션 설계","aws_services":["Amazon DynamoDB"],"explanation":{"requirementsAnalysis":"DynamoDB 테이블은 아침에는 거의 사용되지 않고 저녁에는 예측하기 어려운 읽기 및 쓰기 트래픽이 갑자기 급증합니다. 회사는 비용을 최적화해야 하므로 유휴 시간의 사전 프로비저닝 비용을 낮추면서 급격한 수요를 처리할 수 있는 용량 모드가 필요합니다.","awsServicesAnalysis":"DynamoDB 온디맨드 용량 모드는 읽기와 쓰기 요청량에 따라 자동으로 확장되며 실제 요청에 대해 비용을 지불합니다. 프로비저닝된 용량 모드는 읽기/쓰기 용량을 미리 설정하고 Auto Scaling으로 조정할 수 있지만 최소 용량과 조정 정책을 관리해야 합니다. 글로벌 보조 인덱스는 다른 속성의 쿼리를 지원하고, 전역 테이블은 여러 리전 복제를 제공하며 둘 다 변동 트래픽에 대한 비용 최적화 수단이 아닙니다.","choicesAnalysis":"트래픽이 장시간 유휴 상태였다가 예측 없이 빠르게 증가하므로 요청 기반 과금과 자동 확장을 제공하는 온디맨드 모드가 적합합니다. 프로비저닝된 용량의 Auto Scaling은 용량 계획과 조정이 필요하며 급격한 예측 불가능한 변동에는 운영 부담이 더 큽니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 DynamoDB 온디맨드 용량 모드를 사용하여 유휴 시간에는 사전 프로비저닝 비용 없이 실제 요청에 따라 과금하고, 갑작스러운 트래픽 증가도 처리합니다. 요구 사항에 적합합니다."},"B":{"isCorrect":false,"explanation":"B의 글로벌 보조 인덱스는 대체 키로 데이터를 조회하기 위한 기능입니다. 예측 불가능한 읽기/쓰기 트래픽의 비용 최적화 요구 사항을 해결하지 못합니다."},"C":{"isCorrect":false,"explanation":"C는 용량을 제어할 수 있지만 프로비저닝된 용량과 Auto Scaling 정책을 관리해야 합니다. 장시간 유휴 상태와 급격한 예측 불가능한 트래픽에는 온디맨드 모드보다 운영 효율성과 비용 예측 측면에서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D의 전역 테이블은 다중 리전 복제를 위한 기능이며 프로비저닝된 용량 비용도 발생합니다. 비용 최적화와 예측 불가능한 단일 테이블 트래픽 요구 사항에 적합하지 않습니다."}}},{"id":"Q0080","question_number":80,"question":"한 회사는 최근 애플리케이션 마이그레이션 이니셔티브에 대한 지원을 위해 AWS 관리형 서비스 공급자(MSP) 파트너와 계약을 체결했습니다. 솔루션 설계자는 기존 AWS 계정의 Amazon 머신 이미지(AMI)를 MSP 파트너의 AWS 계정과 공유해야 합니다. AMI 는 Amazon Elastic Block Store(Amazon EBS)의 지원을 받으며 AWS Key Management Service(AWS KMS) 고객 관리형 키를 사용하여 EBS 볼륨 스냅샷을 암호화합니다. 솔루션 설계자가 MSP 파트너의 AWS 계정과 AMI 를 공유하는 가장 안전한 방법은 무엇입니까?","choices":{"A":"암호화된 AMI 및 스냅샷을 공개적으로 사용할 수 있도록 합니다. MSP 파트너의 AWS 계정이 키를 사용할 수 있도록 키 정책을 수정합니다.","B":"AMI 의 launchPermission 속성을 수정합니다. MSP 파트너의 AWS 계정과만 AMI 를 공유하십시오. MSP 파트너의 AWS 계정이 키를 사용할 수 있도록 키 정책을 수정합니다.","C":"AMI 의 launchPermission 속성을 수정합니다. MSP 파트너의 AWS 계정과만 AMI 를 공유하십시오. 암호화를 위해 MSP 파트너가 소유한 새 KMS 키를 신뢰하도록 키 정책을 수정합니다.","D":"원본 계정에서 MSP 파트너의 AWS 계정에 있는 Amazon S3 버킷으로 AMI 를 내보내고 MSP 파트너가 소유한 새 KMS 키로 S3 버킷을 암호화합니다. MSP 파트너의 AWS 계정에서 AMI 를 복사하고 시작합니다."},"answers":["B"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["Amazon EC2","Amazon EBS","AWS KMS"],"explanation":{"requirementsAnalysis":"솔루션 설계자는 원본 AWS 계정의 EBS 지원 AMI를 MSP 파트너 계정과만 안전하게 공유해야 합니다. 연결된 EBS 스냅샷은 고객 관리형 KMS 키로 암호화되어 있으므로 AMI 사용 권한뿐 아니라 파트너 계정의 암호 해독 권한도 최소 범위로 부여해야 합니다. 공개 공유나 불필요한 데이터 내보내기는 보안 요구 사항에 맞지 않습니다.","awsServicesAnalysis":"Amazon EC2 AMI의 launchPermission 속성으로 특정 AWS 계정에만 프라이빗 AMI 시작 권한을 부여할 수 있습니다. 암호화된 EBS 지원 AMI를 공유하려면 관련 암호화 스냅샷에 접근할 수 있어야 하며, AWS KMS 고객 관리형 키 정책 또는 권한 부여를 통해 대상 계정에 필요한 키 사용 권한을 제공해야 합니다. KMS 키 정책은 다른 계정의 키를 신뢰하도록 변경해 기존 스냅샷의 암호화를 이전하는 기능이 아닙니다. AMI를 S3로 내보내는 절차는 이 계정 간 공유 방식에 필요하지 않습니다.","choicesAnalysis":"최소 권한을 만족하려면 AMI 시작 권한을 MSP 계정으로만 제한하고, 해당 계정이 기존 고객 관리형 KMS 키를 사용하도록 키 정책을 수정해야 합니다. 공개 AMI는 권한 범위가 지나치게 넓고, 파트너 소유 키를 신뢰하도록 변경해도 기존 암호화 스냅샷을 공유할 수 없습니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 암호화된 AMI와 스냅샷을 공개로 만들어 모든 계정에 노출합니다. MSP 파트너에게만 공유해야 하는 최소 권한 및 보안 요구 사항에 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 launchPermission으로 AMI 시작 권한을 MSP 파트너 계정으로만 제한하고, 키 정책으로 해당 계정에 고객 관리형 KMS 키 사용 권한을 부여합니다. 암호화된 EBS 지원 AMI를 안전하게 공유하는 방식이므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 MSP 파트너가 소유한 새 KMS 키를 신뢰하도록 원본 키 정책을 변경하지만, 이는 기존 EBS 스냅샷의 암호화를 새 키로 변경하거나 공유 권한을 부여하는 방법이 아닙니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 AMI를 S3로 내보내고 다시 복사하는 불필요한 절차를 추가합니다. 기존 AMI의 계정 간 공유와 KMS 권한 부여보다 복잡하며 가장 안전한 방법이 아닙니다."}}},{"id":"Q0081","question_number":81,"question":"솔루션 설계자는 AWS 에 배포되는 새 애플리케이션을 위한 클라우드 아키텍처를 설계하고 있습니다. 처리할 작업 수에 따라 필요에 따라 애플리케이션 노드를 추가 및 제거하면서 프로세스가 병렬로 실행되어야 합니다. 프로세서 응용 프로그램은 상태 비저장입니다. 솔루션 설계자는 응용 프로그램이 느슨하게 연결되어 있고 작업 항목이 영구적으로 저장되어 있는지 확인해야 합니다. 솔루션 설계자는 어떤 디자인을 사용해야 합니까?","choices":{"A":"처리해야 하는 작업을 보낼 Amazon SNS 주제를 생성합니다. 프로세서 애플리케이션으로 구성된 Amazon 머신 이미지(AMI)를 생성합니다. AMI 를 사용하는 시작 구성을 생성합니다. 시작 구성을 사용하여 Auto Scaling 그룹을 생성합니다. CPU 사용량에 따라 노드를 추가 및 제거하도록 Auto Scaling 그룹에 대한 조정 정책을 설정합니다.","B":"처리해야 하는 작업을 보관할 Amazon SQS 대기열을 생성합니다. 프로세서 애플리케이션으로 구성된 Amazon 머신 이미지(AMI)를 생성합니다. AMI 를 사용하는 시작 구성을 생성합니다. 시작 구성을 사용하여 Auto Scaling 그룹을 생성합니다. Auto Scaling 그룹의 조정 정책을 설정하여 네트워크 사용량에 따라 노드를 추가 및 제거합니다.","C":"처리해야 하는 작업을 보관할 Amazon SQS 대기열을 생성합니다. 프로세서 애플리케이션으로 구성된 Amazon 머신 이미지(AMI)를 생성합니다. AMI 를 사용하는 시작 템플릿을 생성합니다. 시작 템플릿을 사용하여 Auto Scaling 그룹을 생성합니다. SQS 대기열의 항목 수에 따라 노드를 추가 및 제거하도록 Auto Scaling 그룹에 대한 조정 정책을 설정합니다.","D":"처리해야 하는 작업을 보낼 Amazon SNS 주제를 생성합니다. 프로세서 애플리케이션으로 구성된 Amazon 머신 이미지(AMI)를 생성합니다. AMI 를 사용하는 시작 템플릿을 생성합니다. 시작 템플릿을 사용하여 Auto Scaling 그룹을 생성합니다. SNS 주제에 게시된 메시지 수에 따라 노드를 추가 및 제거하도록 Auto Scaling 그룹에 대한 조정 정책을 설정합니다."},"answers":["C"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon SQS","Amazon EC2","Amazon EC2 Auto Scaling"],"explanation":{"requirementsAnalysis":"애플리케이션은 상태 비저장 프로세서를 작업량에 맞춰 수평 확장 또는 축소하면서 병렬로 실행해야 합니다. 또한 처리 구성 요소를 느슨하게 결합하고, 작업 항목은 소비 전까지 내구성 있게 보존해야 합니다. 따라서 작업을 영속 대기열에 분리하고, 대기 중인 작업량을 기준으로 처리 노드 수를 조정하는 설계가 필요합니다.","awsServicesAnalysis":"Amazon SQS는 생산자와 소비자를 분리하는 완전관리형 메시지 대기열이며, 메시지를 내구성 있게 보관하고 소비자가 폴링할 수 있습니다. Amazon EC2 Auto Scaling은 시작 템플릿을 사용해 EC2 인스턴스 수를 자동 조정할 수 있으며, SQS의 ApproximateNumberOfMessagesVisible 같은 대기열 지표를 조정 기준으로 사용할 수 있습니다. Amazon SNS는 메시지를 구독자에게 팬아웃하는 알림 서비스로, SQS와 달리 작업을 소비할 때까지 보관하는 처리 대기열의 역할에 적합하지 않습니다.","choicesAnalysis":"작업을 영구 보관하려면 SQS를 사용해야 하며, 처리 용량은 CPU나 네트워크 사용량보다 실제 대기 작업 수에 따라 조정해야 합니다. 시작 템플릿 기반 Auto Scaling 그룹은 이러한 EC2 처리 노드 확장에 적합합니다. SNS는 영속 작업 대기열이 아니고, 노드 자체의 사용률은 남은 작업량을 직접 나타내지 못합니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 SNS는 처리할 작업을 소비 전까지 보관하는 대기열이 아닙니다. 또한 CPU 사용률은 대기 중인 작업 수를 직접 반영하지 않으므로 요구사항에 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 SQS를 사용해 느슨한 결합과 작업 보관을 제공하지만, 네트워크 사용량으로 확장하면 대기열의 누적 작업량에 맞춰 처리 용량을 조정할 수 없습니다. 따라서 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 SQS에 작업을 내구성 있게 보관하고 시작 템플릿 기반 Auto Scaling 그룹이 대기열 항목 수에 따라 상태 비저장 프로세서를 조정합니다. 병렬 처리, 느슨한 결합 및 작업 보존 요구사항을 모두 충족하므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D의 SNS는 작업 항목을 처리 대기열로 보관하지 않으며, SNS 게시 수는 소비되지 않은 작업의 누적량을 나타내지 않습니다. 따라서 적합하지 않습니다."}}},{"id":"Q0082","question_number":82,"question":"회사는 AWS 클라우드에서 웹 애플리케이션을 호스팅합니다. 회사는 AWS Certificate Manager(ACM)로 가져온 인증서를 사용하도록 Elastic Load Balancer 를 구성합니다. 각 인증서가 만료되기 30 일 전에 회사 보안팀에 알려야 합니다. 솔루션 설계자는 이 요구 사항을 충족하기 위해 무엇을 권장해야 합니까?","choices":{"A":"ACM 에 규칙을 추가하여 인증서가 만료되기 30 일 전부터 매일 Amazon Simple Notification Service(Amazon SNS) 주제에 사용자 지정 메시지를 게시합니다.","B":"30 일 이내에 만료되는 인증서를 확인하는 AWS Config 규칙을 생성합니다. AWS Config 가 비준수 리소스를 보고할 때 Amazon Simple Notification Service(Amazon SNS)를 통해 사용자 지정 알림을 호출하도록 Amazon EventBridge(Amazon CloudWatch Events)를 구성합니다.","C":"AWS Trusted Advisor 를 사용하여 30 일 이내에 만료되는 인증서를 확인합니다. 상태 변경 확인에 대한 Trusted Advisor 지표를 기반으로 하는 Amazon CloudWatch 경보를 생성합니다. Amazon Simple Notification Service(Amazon SNS)를 통해 사용자 지정 알림을 보내도록 경보를 구성합니다.","D":"30 일 이내에 만료되는 모든 인증서를 감지하는 Amazon EventBridge(Amazon CloudWatch Events) 규칙을 생성합니다. AWS Lambda 함수를 호출하도록 규칙을 구성합니다. Amazon Simple Notification Service(Amazon SNS)를 통해 사용자 지정 알림을 보내도록 Lambda 함수를 구성합니다."},"answers":["B"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["AWS Certificate Manager(ACM)","AWS Config","Amazon EventBridge","Amazon SNS"],"explanation":{"requirementsAnalysis":"Elastic Load Balancer에 연결된 ACM 가져온 인증서의 만료 30일 전에 보안팀에 알림을 보내야 합니다. 인증서 상태를 지속적으로 평가하고, 기준을 충족하지 않는 리소스가 발견되면 알림 흐름을 자동으로 시작해야 합니다. 따라서 관리형 규정 준수 평가와 이벤트 기반 알림을 결합하는 구성이 필요합니다.","awsServicesAnalysis":"AWS Config 관리형 규칙 acm-certificate-expiration-check는 ACM 인증서의 만료 기간을 평가하며, 최소 일수 임계값을 설정할 수 있습니다. Amazon EventBridge는 AWS Config의 규정 준수 상태 변경 이벤트를 수신해 대상 서비스를 호출할 수 있고, Amazon SNS는 보안팀 구독자에게 알림을 전송할 수 있습니다. ACM은 가져온 인증서의 갱신을 자동으로 관리하지 않으므로 만료 모니터링이 필요합니다.","choicesAnalysis":"만료 임계값을 직접 평가하는 AWS Config 규칙을 사용하면 인증서 상태를 관리형 방식으로 확인할 수 있습니다. 비준수 상태 변경을 EventBridge가 감지하여 SNS 알림으로 연결하면 별도 코드 없이 요구된 통지를 자동화할 수 있습니다. EventBridge 단독은 인증서 만료일을 계산하는 규칙 세부 구현이 필요하고, ACM에는 이러한 사용자 지정 알림 규칙을 만드는 기능이 없습니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 ACM에 사용자 지정 만료 알림 규칙을 추가하는 기능을 전제로 하지만, ACM은 해당 방식의 규칙과 SNS 게시 기능을 제공하지 않습니다. 따라서 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 AWS Config의 ACM 인증서 만료 확인 규칙으로 30일 임계값을 평가하고, 비준수 상태 변경을 EventBridge와 SNS로 전달합니다. 관리형 서비스로 만료 전 보안팀 알림을 자동화하므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C의 Trusted Advisor 상태 변경 지표는 ACM 가져온 인증서별 만료 30일 전 알림을 구성하는 직접적인 규정 준수 평가 수단이 아닙니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 EventBridge 규칙과 Lambda 코드로 만료일을 감지하고 알림을 구현해야 합니다. AWS Config 관리형 규칙을 사용하는 방식보다 운영 오버헤드가 크므로 최선의 선택이 아닙니다."}}},{"id":"Q0083","question_number":83,"question":"회사의 동적 웹 사이트는 미국의 온프레미스 서버를 사용하여 호스팅됩니다. 이 회사는 유럽에서 제품을 출시하고 있으며 새로운 유럽 사용자를 위해 사이트 로딩 시간을 최적화하려고 합니다. 사이트의 백엔드는 미국에 있어야 합니다. 제품이 며칠 안에 출시되며 즉각적인 솔루션이 필요합니다. 솔루션 설계자는 무엇을 권장해야 합니까?","choices":{"A":"us-east-1 에서 Amazon EC2 인스턴스를 시작하고 사이트를 마이그레이션합니다.","B":"웹사이트를 Amazon S3 로 이동합니다. 지역 간 교차 지역 복제를 사용합니다.","C":"온프레미스 서버를 가리키는 사용자 지정 오리진과 함께 Amazon CloudFront 를 사용합니다.","D":"온프레미스 서버를 가리키는 Amazon Route 53 지리 근접 라우팅 정책을 사용합니다."},"answers":["C"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 네트워크 아키텍처 결정","aws_services":["Amazon CloudFront"],"explanation":{"requirementsAnalysis":"동적 웹 사이트의 백엔드는 미국 온프레미스에 그대로 두어야 하며, 유럽 사용자의 로딩 시간을 며칠 안에 개선해야 합니다. 애플리케이션 이전이나 정적 웹 사이트로의 재구축에는 시간이 부족합니다. 따라서 기존 온프레미스 오리진을 유지하면서 유럽의 엣지에서 콘텐츠 전송을 최적화하는 즉시 적용 가능한 서비스가 필요합니다.","awsServicesAnalysis":"Amazon CloudFront는 전 세계 엣지 로케이션에서 콘텐츠를 제공하는 CDN이며, 사용자 지정 오리진으로 온프레미스 HTTP 서버를 지정할 수 있습니다. 캐시 가능한 콘텐츠는 사용자와 가까운 엣지에서 제공되고, 동적 요청도 CloudFront의 글로벌 네트워크를 통해 오리진으로 전달할 수 있습니다. Amazon Route 53 지리 근접 라우팅은 사용자 위치에 따라 DNS 응답을 조정하지만 콘텐츠 캐싱이나 전송 경로 가속 기능을 제공하지 않습니다.","choicesAnalysis":"백엔드를 미국에 유지하면서 유럽 사용자 경험을 빠르게 개선하려면 온프레미스 오리진 앞에 CDN을 배치해야 합니다. CloudFront는 애플리케이션 마이그레이션 없이 구성할 수 있고, 정적 자산 캐싱 및 글로벌 전송 경로 최적화를 제공합니다. S3 이전은 동적 웹 사이트에 적합하지 않고, Route 53만으로는 로딩 시간을 충분히 개선할 수 없습니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 사이트를 EC2로 마이그레이션해야 하며, 제안된 us-east-1은 기존 미국 온프레미스 백엔드를 유지해야 하는 요구사항에도 부합하지 않습니다. 따라서 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 동적 웹 사이트를 S3로 이전해야 하며, 애플리케이션 백엔드 기능을 대체하지 못합니다. 즉각적인 성능 개선 방안으로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 온프레미스 서버를 CloudFront의 사용자 지정 오리진으로 유지하면서 유럽 엣지 로케이션에서 캐시 가능한 콘텐츠를 제공하고 전송을 최적화합니다. 빠르게 적용할 수 있으므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D의 지리 근접 라우팅은 DNS 수준에서 트래픽을 배분할 뿐 온프레미스 오리진 콘텐츠를 유럽에서 캐시하거나 가속하지 않습니다. 따라서 적합하지 않습니다."}}},{"id":"Q0084","question_number":84,"question":"회사는 기존 3 계층 웹 아키텍처의 비용을 절감하려고 합니다. 웹, 애플리케이션 및 데이터베이스 서버는 개발, 테스트 및 프로덕션 환경을 위한 Amazon EC2 인스턴스에서 실행됩니다. EC2 인스턴스의 평균 CPU 사용률은 사용량이 많은 시간에는 30%이고 사용량이 많지 않은 시간에는 10%입니다. 프로덕션 EC2 인스턴스는 하루 24 시간 실행됩니다. 개발 및 테스트 EC2 인스턴스는 매일 최소 8 시간 동안 실행됩니다. 회사는 개발을 중지하고 사용하지 않을 때 EC2 인스턴스를 테스트하는 자동화를 구현할 계획입니다. 어떤 EC2 인스턴스 구매 솔루션이 가장 비용 효율적으로 회사의 요구 사항을 충족합니까?","choices":{"A":"프로덕션 EC2 인스턴스에 스팟 인스턴스를 사용합니다. EC2 인스턴스 개발 및 테스트에 예약 인스턴스를 사용합니다.","B":"프로덕션 EC2 인스턴스에 예약 인스턴스를 사용합니다. 개발 및 테스트 EC2 인스턴스에 온디맨드 인스턴스를 사용합니다.","C":"프로덕션 EC2 인스턴스에 스팟 블록을 사용합니다. EC2 인스턴스 개발 및 테스트에 예약 인스턴스를 사용합니다.","D":"프로덕션 EC2 인스턴스에 온디맨드 인스턴스를 사용합니다. 개발 및 테스트 EC2 인스턴스에 스팟 블록을 사용합니다."},"answers":["B"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 컴퓨팅 솔루션 설계","aws_services":["Amazon EC2"],"explanation":{"requirementsAnalysis":"프로덕션 인스턴스는 하루 24시간 지속 실행되지만 개발 및 테스트 인스턴스는 자동 중지로 하루 최소 8시간만 실행됩니다. 비용을 낮추면서도 각 환경의 가용성 요구사항에 맞는 구매 옵션을 선택해야 합니다. 따라서 안정적이고 지속적인 프로덕션 사용량에는 장기 약정을 적용하고, 가변적인 개발/테스트 사용량에는 약정 없는 옵션을 적용하는 것이 필요합니다.","awsServicesAnalysis":"Amazon EC2 예약 인스턴스는 일정한 장기 사용량에 대해 온디맨드 요금보다 할인된 요금을 제공하며, 중단 없이 실행해야 하는 워크로드에 적합합니다. 온디맨드 인스턴스는 약정 없이 필요할 때 실행하고 중지할 수 있어 가변적인 사용량에 적합합니다. 스팟 인스턴스는 EC2 용량 상황에 따라 중단될 수 있으며, 스팟 블록은 더 이상 제공되지 않는 구매 옵션입니다.","choicesAnalysis":"상시 실행되는 프로덕션 환경은 예측 가능한 사용량이므로 예약 인스턴스로 비용을 절감할 수 있습니다. 자동 중지되는 개발/테스트 환경은 실행 시간이 변동하므로 온디맨드가 적합합니다. 프로덕션에 스팟을 사용하면 중단 위험이 있고, 스팟 블록은 현재 사용할 수 없습니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 중단될 수 있는 스팟 인스턴스를 상시 프로덕션 서버에 사용하므로 가용성 요구사항에 적합하지 않습니다. 개발/테스트의 변동 사용량에 예약 인스턴스를 적용하는 것도 비효율적입니다."},"B":{"isCorrect":true,"explanation":"B는 예측 가능하고 상시 실행되는 프로덕션에는 예약 인스턴스를, 자동 중지로 사용량이 변동하는 개발/테스트에는 온디맨드 인스턴스를 사용합니다. 비용과 운영 요구사항에 가장 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 프로덕션에 스팟 블록을 사용하도록 제안하지만 스팟 블록은 더 이상 제공되지 않습니다. 또한 개발/테스트의 변동 사용량에 예약 인스턴스를 적용하므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 프로덕션의 지속적이고 예측 가능한 사용량에 온디맨드를 사용해 할인 기회를 활용하지 못합니다. 또한 스팟 블록은 사용할 수 없으므로 적합하지 않습니다."}}},{"id":"Q0085","question_number":85,"question":"회사에 사용자가 웹 인터페이스 또는 모바일 앱을 통해 문서를 업로드하는 프로덕션 웹 애플리케이션이 있습니다. 새로운 규제 요구 사항에 따라. 새 문서는 저장 후에 수정하거나 삭제할 수 없습니다. 솔루션 설계자는 이 요구 사항을 충족하기 위해 무엇을 해야 합니까?","choices":{"A":"업로드된 문서를 S3 버전 관리 및 S3 객체 잠금이 활성화된 Amazon S3 버킷에 저장합니다.","B":"업로드된 문서를 Amazon S3 버킷에 저장합니다. 문서를 주기적으로 보관하도록 S3 수명 주기 정책을 구성합니다.","C":"업로드된 문서를 S3 버전 관리가 활성화된 Amazon S3 버킷에 저장합니다. 모든 액세스를 읽기 전용으로 제한하도록 ACL 을 구성합니다.","D":"업로드된 문서를 Amazon Elastic File System(Amazon EFS) 볼륨에 저장합니다. 읽기 전용 모드에서 볼륨을 마운트하여 데이터에 액세스합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["Amazon S3"],"explanation":{"requirementsAnalysis":"업로드된 새 문서는 저장된 뒤 수정하거나 삭제할 수 없어야 하므로 규제상 변경 불가능한 보관이 필요합니다. 단순한 접근 제어만으로는 권한 변경이나 관리자 작업에 따른 수정 및 삭제를 방지하기 어렵습니다. 따라서 객체 버전과 보존 기간 또는 법적 보류를 강제할 수 있는 WORM 방식의 저장 구성이 필요합니다.","awsServicesAnalysis":"Amazon S3 Object Lock은 S3 버전 관리가 활성화된 버킷에서 객체 버전을 WORM 방식으로 보존하는 기능입니다. 보존 기간 또는 법적 보류를 사용하면 보호된 객체 버전을 덮어쓰거나 삭제할 수 없게 할 수 있습니다. S3 Lifecycle은 객체 전환과 만료를 자동화하며 변경 불가능성을 제공하지 않습니다. ACL은 권한을 제어하지만 권한이 있는 주체의 삭제를 불변하게 차단하지 않습니다.","choicesAnalysis":"규제 요구사항은 문서의 수정과 삭제를 모두 방지하는 것입니다. 버전 관리와 S3 Object Lock을 함께 사용하면 특정 객체 버전에 대한 보존을 강제할 수 있습니다. 수명 주기, ACL 또는 EFS 읽기 전용 마운트는 업로드 후 객체 자체의 변경 및 삭제를 보장하는 WORM 제어가 아닙니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 S3 버전 관리가 필요한 S3 Object Lock을 활성화하여 문서 객체 버전을 WORM 방식으로 보존할 수 있습니다. 보존 설정을 적용하면 수정 및 삭제 방지 요구사항을 충족하므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B의 S3 Lifecycle은 객체를 전환하거나 만료할 수 있지만, 저장 직후 문서의 수정과 삭제를 차단하지 않습니다. 따라서 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C의 버전 관리와 읽기 전용 ACL은 접근 권한을 제한할 수 있지만, 권한을 변경하거나 적절한 권한을 가진 주체의 삭제를 불변하게 막지 않습니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D의 클라이언트 측 읽기 전용 마운트는 EFS에 대한 다른 쓰기 경로나 권한 있는 작업을 차단하지 않으며 WORM 보존을 제공하지 않습니다. 따라서 적합하지 않습니다."}}},{"id":"Q0086","question_number":86,"question":"회사에는 공통 Amazon RDS MySQL 다중 AZ DB 인스턴스에 자주 액세스해야 하는 여러 웹 서버가 있습니다. 회사는 사용자 자격 증명을 자주 교체해야 하는 보안 요구 사항을 충족하면서 웹 서버가 데이터베이스에 연결할 수 있는 안전한 방법을 원합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"AWS Secrets Manager 에 데이터베이스 사용자 자격 증명을 저장합니다. 웹 서버가 AWS Secrets Manager 에 액세스할 수 있도록 필요한 IAM 권한을 부여합니다.","B":"AWS Systems Manager OpsCenter 에 데이터베이스 사용자 자격 증명을 저장합니다. 웹 서버가 OpsCenter 에 액세스할 수 있도록 필요한 IAM 권한을 부여합니다.","C":"안전한 Amazon S3 버킷에 데이터베이스 사용자 자격 증명을 저장합니다. 웹 서버가 자격 증명을 검색하고 데이터베이스에 액세스할 수 있도록 필요한 IAM 권한을 부여합니다.","D":"웹 서버 파일 시스템의 AWS Key Management Service(AWS KMS)로 암호화된 파일에 데이터베이스 사용자 자격 증명을 저장합니다. 웹 서버는 파일을 해독하고 데이터베이스에 액세스할 수 있어야 합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["AWS Secrets Manager","IAM","Amazon RDS"],"explanation":{"requirementsAnalysis":"여러 웹 서버가 다중 AZ Amazon RDS for MySQL DB 인스턴스에 안전하게 연결해야 하고, 데이터베이스 자격 증명은 자주 교체해야 합니다. 자격 증명을 코드나 서버 파일 시스템에 고정하지 않고 중앙에서 보호하며, 회전 후 애플리케이션이 최신 값을 검색할 수 있어야 합니다. 따라서 데이터베이스 자격 증명 저장과 자동 교체를 지원하는 관리형 비밀 관리 서비스가 필요합니다.","awsServicesAnalysis":"AWS Secrets Manager는 데이터베이스 자격 증명 같은 비밀을 암호화하여 저장하고 IAM 정책으로 접근을 제어합니다. Amazon RDS와 통합하여 지원되는 데이터베이스 자격 증명의 자동 교체를 구성할 수 있으며, 애플리케이션은 API로 현재 비밀 값을 검색할 수 있습니다. AWS Systems Manager OpsCenter는 운영 문제를 관리하는 서비스이며 비밀 저장소가 아닙니다. Amazon S3 또는 서버 파일 시스템은 자격 증명 회전과 안전한 배포를 위한 전용 비밀 관리 기능을 제공하지 않습니다.","choicesAnalysis":"자주 교체되는 데이터베이스 자격 증명은 중앙 비밀 저장소에 보관하고 웹 서버 IAM 역할에 필요한 읽기 권한만 부여해야 합니다. Secrets Manager는 RDS 자격 증명 회전과 안전한 검색을 지원하므로 이 요구사항에 직접 부합합니다. 다른 선택지는 비밀 관리 또는 자동 회전 기능이 없고 자격 증명 노출 및 운영 부담을 늘립니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 Secrets Manager에 데이터베이스 자격 증명을 저장하고 IAM으로 웹 서버의 접근을 제한할 수 있습니다. RDS 자격 증명 회전도 지원하므로 안전한 연결과 빈번한 교체 요구사항에 적합합니다."},"B":{"isCorrect":false,"explanation":"B의 Systems Manager OpsCenter는 운영 항목을 조사하고 관리하는 서비스이며 데이터베이스 자격 증명을 저장하거나 회전하는 비밀 관리 서비스가 아닙니다. 따라서 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 S3에 자격 증명을 저장해도 전용 비밀 관리 및 RDS 자격 증명 자동 교체 기능을 제공하지 않습니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 자격 증명을 각 웹 서버 파일에 배포하고 회전 시 파일을 갱신해야 합니다. 중앙 관리와 자동 교체가 어려우므로 적합하지 않습니다."}}},{"id":"Q0087","question_number":87,"question":"회사는 Amazon API Gateway API 에 의해 호출되는 AWS Lambda 함수에서 애플리케이션을 호스팅합니다. Lambda 함수는 고객 데이터를 Amazon Aurora MySQL 데이터베이스에 저장합니다. 회사에서 데이터베이스를 업그레이드할 때마다 Lambda 함수는 업그레이드가 완료될 때까지 데이터베이스 연결을 설정하지 못합니다. 그 결과 일부 이벤트에 대한 고객 데이터가 기록되지 않습니다. 솔루션 설계자는 데이터베이스 업그레이드 중에 생성되는 고객 데이터를 저장하는 솔루션을 설계해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"Lambda 함수와 데이터베이스 사이에 위치하도록 Amazon RDS 프록시를 프로비저닝합니다. RDS 프록시에 연결하도록 Lambda 함수를 구성합니다.","B":"Lambda 함수의 실행 시간을 최대로 늘립니다. 데이터베이스에 고객 데이터를 저장하는 코드에서 재시도 메커니즘을 만듭니다.","C":"고객 데이터를 Lambda 로컬 스토리지에 유지합니다. 고객 데이터를 데이터베이스에 저장하기 위해 로컬 스토리지를 스캔하도록 새로운 Lambda 함수를 구성합니다.","D":"Amazon Simple Queue Service(Amazon SQS) FIFO 대기열에 고객 데이터를 저장합니다. 대기열을 폴링하고 고객 데이터를 데이터베이스에 저장하는 새 Lambda 함수를 생성합니다."},"answers":["D"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon API Gateway","AWS Lambda","Amazon Aurora","Amazon SQS"],"explanation":{"requirementsAnalysis":"Amazon Aurora 업그레이드 동안 Lambda가 데이터베이스 연결을 만들지 못해 고객 데이터가 손실되고 있습니다. 업그레이드 기간에도 수신 데이터를 내구성 있게 보존하고, 데이터베이스가 다시 사용 가능해지면 처리해야 합니다. 따라서 API 수신과 데이터베이스 쓰기를 분리하고 재시도 가능한 버퍼를 두는 비동기 설계가 필요합니다.","awsServicesAnalysis":"Amazon SQS FIFO 대기열은 메시지를 내구성 있게 보관하고 메시지 그룹 내 순서를 유지할 수 있습니다. Lambda는 SQS를 이벤트 소스로 사용해 대기열 메시지를 처리할 수 있으며, 데이터베이스 오류가 발생하면 성공 처리될 때까지 메시지를 다시 처리할 수 있습니다. Amazon RDS Proxy는 연결 풀링과 장애 조치 관리를 개선하지만, 데이터베이스가 업그레이드로 쓰기를 받을 수 없는 동안 고객 데이터를 영구 버퍼에 저장하지는 않습니다. Lambda의 로컬 스토리지는 실행 환경에 종속되므로 내구성 있는 데이터 저장소가 아닙니다.","choicesAnalysis":"데이터베이스가 일시적으로 사용할 수 없을 때도 데이터를 보존하려면 Lambda와 Aurora 사이에 내구성 있는 대기열을 배치해야 합니다. 새 Lambda가 SQS에서 데이터를 읽어 Aurora에 기록하면, 실패한 메시지는 이후에 재시도됩니다. 연결 프록시나 실행 시간 증가만으로는 데이터베이스 비가용 중 이벤트 손실을 방지할 수 없습니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 RDS Proxy는 Lambda 연결 관리에 도움을 주지만, 데이터베이스 업그레이드로 쓰기 연결이 불가능한 동안 고객 이벤트를 저장하지 않습니다. 따라서 데이터 손실 방지 요구사항에 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 재시도를 추가할 수 있지만 데이터베이스 업그레이드 시간이 Lambda 최대 실행 시간을 넘으면 이벤트가 실패할 수 있습니다. 내구성 있는 버퍼가 없으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C의 Lambda 로컬 스토리지는 실행 환경이 종료되면 사라질 수 있고 다른 실행에서 공유되지 않습니다. 고객 데이터를 보존하는 저장소로 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"D는 고객 데이터를 SQS FIFO 대기열에 내구성 있게 보관하고, 별도 Lambda가 데이터베이스를 사용할 수 있을 때 메시지를 처리하도록 합니다. 업그레이드 중에도 이벤트를 보존하고 이후 재시도할 수 있으므로 적합합니다."}}},{"id":"Q0088","question_number":88,"question":"설문 조사 회사는 미국 지역에서 수년 동안 데이터를 수집했습니다. 이 회사는 크기가 3TB 이고 계속 증가하는 Amazon S3 버킷에 데이터를 호스팅합니다. 이 회사는 S3 버킷이 있는 유럽 마케팅 회사와 데이터를 공유하기 시작했습니다. 회사는 데이터 전송 비용이 가능한 한 낮게 유지되기를 원합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"회사의 S3 버킷에서 요청자 지불 기능을 구성합니다.","B":"회사의 S3 버킷에서 마케팅 회사의 S3 버킷 중 하나로 S3 교차 리전 복제를 구성합니다.","C":"마케팅 회사가 회사의 S3 버킷에 액세스할 수 있도록 마케팅 회사에 대한 교차 계정 액세스를 구성합니다.","D":"S3 Intelligent-Tiering 을 사용하도록 회사의 S3 버킷을 구성합니다. S3 버킷을 마케팅 회사의 S3 버킷 중 하나와 동기화합니다."},"answers":["A"],"content_domain":"비용에 최적화된 아키텍처 설계","content_task":"비용에 최적화된 스토리지 솔루션 설계","aws_services":["Amazon S3"],"explanation":{"requirementsAnalysis":"미국 리전의 3TB 이상 S3 데이터를 유럽의 다른 회사와 공유하면서 데이터 전송 비용을 가능한 낮게 유지해야 합니다. 데이터 복제나 동기화는 추가 전송과 저장 비용을 만들 수 있으므로 피해야 합니다. 따라서 데이터 접근으로 발생하는 S3 요청 및 전송 비용을 데이터를 받는 회사에 부담시키는 공유 방식이 필요합니다.","awsServicesAnalysis":"S3 Requester Pays를 활성화한 버킷에서는 객체 요청과 데이터 전송 요금을 요청자가 부담하며, 버킷 소유자는 스토리지 요금과 일부 관리 비용을 부담합니다. S3 교차 리전 복제는 객체를 다른 리전 버킷으로 복사하므로 복제 전송과 대상 저장 비용이 발생합니다. 교차 계정 액세스는 권한을 부여할 수 있지만 비용 부담자를 요청자로 전환하지 않습니다. S3 Intelligent-Tiering은 액세스 패턴에 따라 스토리지 클래스를 최적화하는 기능입니다.","choicesAnalysis":"목표는 대용량 데이터 공유에 따른 회사의 데이터 전송 비용을 최소화하는 것입니다. Requester Pays는 마케팅 회사가 데이터에 접근할 때 발생하는 요청 및 전송 비용을 그 회사에 청구하도록 합니다. 리전 간 복제나 동기화는 대량 데이터 사본을 추가로 만들고, 교차 계정 접근만으로는 비용 부담이 바뀌지 않습니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 S3 Requester Pays를 활성화하여 마케팅 회사가 객체를 요청하고 받을 때 발생하는 요청 및 데이터 전송 요금을 부담하게 합니다. 공유자의 전송 비용을 낮추므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 유럽 리전 버킷으로 전체 데이터를 복제하므로 대량의 리전 간 전송과 추가 스토리지 비용이 발생합니다. 비용을 가능한 낮게 유지하는 방법으로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 마케팅 회사에 교차 계정 권한을 부여할 수 있지만, 버킷 소유자의 데이터 전송 비용을 요청자에게 이전하지 않습니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 Intelligent-Tiering으로 스토리지 비용을 일부 최적화할 수 있으나, 버킷 동기화는 데이터 사본과 전송 비용을 추가합니다. 공유 전송 비용 최소화 요구사항에 적합하지 않습니다."}}},{"id":"Q0089","question_number":89,"question":"회사는 Amazon S3 를 사용하여 기밀 감사 문서를 저장합니다. S3 버킷은 버킷 정책을 사용하여 최소 권한 원칙에 따라 감사 팀 IAM 사용자 자격 증명에 대한 액세스를 제한합니다. 회사 관리자는 S3 버킷에서 실수로 문서가 삭제되는 것을 걱정하고 더 안전한 솔루션을 원합니다. 솔루션 설계자는 감사 문서를 보호하기 위해 무엇을 해야 합니까?","choices":{"A":"S3 버킷에서 버전 관리 및 MFA 삭제 기능을 활성화합니다.","B":"각 감사 팀 IAM 사용자 계정의 IAM 사용자 자격 증명에 대해 다단계 인증(MFA)을 활성화합니다.","C":"감사 날짜 동안 s3:DeleteObject 작업을 거부하도록 감사 팀의 IAM 사용자 계정에 S3 수명 주기 정책을 추가합니다.","D":"AWS Key Management Service(AWS KMS)를 사용하여 S3 버킷을 암호화하고 감사 팀 IAM 사용자 계정이 KMS 키에 액세스하지 못하도록 제한합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["Amazon S3"],"explanation":{"requirementsAnalysis":"감사 문서는 최소 권한 버킷 정책으로 보호되지만, 허가된 사용자의 실수로 인한 삭제도 방지해야 합니다. 단순 사용자 MFA나 암호화는 삭제 요청 자체를 방지하지 못합니다. 따라서 객체의 이전 버전을 보존하고 삭제 작업에 추가 인증을 요구하는 S3 수준 보호가 필요합니다.","awsServicesAnalysis":"S3 버전 관리를 활성화하면 객체 삭제는 일반적으로 삭제 마커를 추가하며 이전 객체 버전은 보존됩니다. MFA Delete는 버킷의 버전 관리 상태 변경 및 객체 버전의 영구 삭제에 MFA를 요구하는 추가 보호 기능입니다. IAM 사용자에 MFA를 활성화하는 것은 로그인 보안을 강화하지만 S3 삭제 작업에 MFA를 강제하지 않습니다. S3 Lifecycle은 IAM 정책을 부착하는 기능이 아니며, AWS KMS 암호화는 데이터 기밀성을 보호합니다.","choicesAnalysis":"실수 삭제 후 문서를 복구할 수 있어야 하고, 영구 삭제를 더 어렵게 만들어야 합니다. S3 버전 관리와 MFA Delete를 함께 사용하면 이전 버전을 보존하고 영구 삭제에 추가 MFA 인증을 요구할 수 있습니다. 사용자 계정 MFA, 수명 주기 또는 KMS는 이 삭제 보호 조합을 제공하지 않습니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 S3 버전 관리로 이전 객체 버전을 보존하고 MFA Delete로 영구 삭제에 MFA를 요구합니다. 실수로 삭제된 감사 문서를 보호하고 복구할 수 있으므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 IAM 사용자 로그인에 대한 보안을 강화하지만, 해당 사용자가 수행하는 S3 객체 삭제 작업에 MFA를 별도로 요구하지 않습니다. 따라서 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 S3 수명 주기 정책으로 IAM 사용자 권한을 제어할 수 없으며, 수명 주기 기능은 DeleteObject 거부 정책을 설정하는 수단이 아닙니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D의 KMS 암호화와 키 접근 제한은 문서의 기밀성을 보호하지만, 허가된 사용자의 객체 삭제를 방지하거나 복구하지 못합니다. 따라서 적합하지 않습니다."}}},{"id":"Q0090","question_number":90,"question":"회사에서 SQL 데이터베이스를 사용하여 공개적으로 액세스할 수 있는 영화 데이터를 저장하고 있습니다. 데이터베이스는 Amazon RDS 단일 AZ DB 인스턴스에서 실행됩니다. 스크립트는 데이터베이스에 추가된 새로운 영화의 수를 기록하기 위해 매일 임의의 간격으로 쿼리를 실행합니다. 스크립트는 업무 시간 동안의 최종 합계를 보고해야 합니다. 회사의 개발 팀은 스크립트가 실행 중일 때 데이터베이스 성능이 개발 작업에 부적절하다는 것을 알아차렸습니다. 솔루션 설계자는 이 문제를 해결하기 위한 솔루션을 권장해야 합니다. 최소한의 운영 오버헤드로 이 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"DB 인스턴스를 다중 AZ 배포로 수정합니다.","B":"데이터베이스의 읽기 전용 복제본을 생성합니다. 읽기 전용 복제본만 쿼리하도록 스크립트를 구성합니다.","C":"개발 팀에게 매일 일과가 끝날 때 데이터베이스의 항목을 수동으로 내보내도록 지시합니다.","D":"Amazon ElastiCache 를 사용하여 스크립트가 데이터베이스에 대해 실행하는 일반적인 쿼리를 캐시합니다."},"answers":["B"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터베이스 솔루션 결정","aws_services":["Amazon RDS"],"explanation":{"requirementsAnalysis":"단일 AZ RDS DB 인스턴스에서 임의 시간에 실행되는 읽기 쿼리가 개발 작업의 데이터베이스 성능을 저하시킵니다. 스크립트의 집계 쿼리를 운영 DB와 분리하면서 매일 업무 시간 동안 최신 데이터를 조회해야 합니다. 별도 관리 부담을 최소화하려면 RDS가 관리하는 읽기 확장 기능을 사용하는 방식이 필요합니다.","awsServicesAnalysis":"Amazon RDS 읽기 전용 복제본은 원본 DB 인스턴스의 데이터를 비동기로 복제하고 읽기 전용 연결을 제공하여 읽기 트래픽을 오프로드할 수 있습니다. 다중 AZ 배포는 고가용성과 장애 조치를 위한 동기식 대기 인스턴스를 제공하며 일반적인 읽기 쿼리 대상으로 사용되지 않습니다. Amazon ElastiCache는 반복 조회의 지연 시간을 줄일 수 있지만 데이터 무효화와 캐시 관리가 필요하며 임의 집계 쿼리를 분리하는 직접적인 해결책이 아닙니다.","choicesAnalysis":"성능 문제는 스크립트의 읽기 쿼리가 원본 데이터베이스의 자원을 사용하는 데서 발생합니다. 읽기 전용 복제본을 만들고 스크립트가 그 엔드포인트에만 연결하도록 하면 읽기 부하를 분리할 수 있습니다. 다중 AZ는 읽기 확장 기능이 아니고, 수동 내보내기는 운영 오버헤드가 크며, 캐시는 임의 시간의 최신 집계 요구사항에 적합하지 않습니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 다중 AZ 배포는 장애 조치와 고가용성을 제공하지만 대기 인스턴스를 일반적인 읽기 쿼리 대상으로 사용할 수 없습니다. 따라서 스크립트 부하를 분리하는 해결책이 아닙니다."},"B":{"isCorrect":true,"explanation":"B는 RDS 읽기 전용 복제본으로 스크립트의 읽기 쿼리를 오프로드하여 원본 DB 인스턴스의 성능 영향을 줄입니다. RDS가 복제를 관리하므로 최소 운영 오버헤드 요구사항에 적합합니다."},"C":{"isCorrect":false,"explanation":"C는 매일 수동 내보내기를 수행해야 하고 임의 시간의 쿼리 결과를 제공하지 못할 수 있습니다. 운영 오버헤드가 크므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 일반적인 쿼리를 캐시하더라도 데이터 최신성 및 캐시 무효화를 관리해야 하며, 임의의 집계 쿼리 부하를 안정적으로 DB에서 분리하지 못합니다. 따라서 적합하지 않습니다."}}},{"id":"Q0091","question_number":91,"question":"회사에 VPC 의 Amazon EC2 인스턴스에서 실행되는 애플리케이션이 있습니다. 애플리케이션 중 하나는 Amazon S3 API 를 호출하여 객체를 저장하고 읽어야 합니다. 회사의 보안 규정에 따라 응용 프로그램의 트래픽은 인터넷을 통해 이동할 수 없습니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"S3 게이트웨이 엔드포인트를 구성합니다.","B":"프라이빗 서브넷에 S3 버킷을 생성합니다.","C":"EC2 인스턴스와 동일한 AWS 리전에 S3 버킷을 생성합니다.","D":"EC2 인스턴스와 동일한 서브넷에 NAT 게이트웨이를 구성합니다."},"answers":["A"],"content_domain":"보안 아키텍처 설계","content_task":"안전한 워크로드 및 애플리케이션 설계","aws_services":["Amazon VPC","Amazon S3"],"explanation":{"requirementsAnalysis":"애플리케이션은 VPC의 Amazon EC2 인스턴스에서 Amazon S3 API를 호출해 객체를 읽고 저장해야 합니다. 보안 규정상 이 트래픽은 인터넷을 경유할 수 없습니다. 따라서 S3에 대한 사설 네트워크 경로를 제공하면서 애플리케이션의 기존 API 호출을 유지하는 구성이 필요합니다.","awsServicesAnalysis":"Amazon VPC 게이트웨이 엔드포인트는 Amazon S3 및 Amazon DynamoDB에 VPC 내부의 비공개 연결 경로를 제공합니다. 게이트웨이 엔드포인트에는 비용이 없으며 라우팅 테이블을 통해 트래픽을 해당 엔드포인트로 보냅니다. Amazon S3 버킷은 서브넷 안에 배치되는 리소스가 아니며, NAT 게이트웨이는 프라이빗 서브넷의 인터넷 아웃바운드 연결에 사용됩니다.","choicesAnalysis":"S3 게이트웨이 엔드포인트를 구성하면 EC2 인스턴스의 S3 요청이 인터넷 게이트웨이나 NAT 디바이스를 통과하지 않고 AWS 네트워크 내에서 처리됩니다. 버킷의 리전 또는 NAT 게이트웨이 구성만으로는 인터넷 미경유 요구사항을 보장하지 못합니다. 따라서 A가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 S3 게이트웨이 엔드포인트를 통해 VPC와 Amazon S3 사이에 비공개 연결 경로를 제공하므로, 인터넷을 거치지 않는 S3 API 액세스 요구사항에 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 S3 버킷을 프라이빗 서브넷에 생성할 수 있다는 전제부터 성립하지 않습니다. S3 버킷은 VPC 서브넷에 배치되지 않으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 네트워크 지연을 줄일 수는 있지만 S3 트래픽의 인터넷 경유 여부를 제어하지는 않습니다. 비공개 연결을 위해서는 VPC 엔드포인트가 필요하므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D의 NAT 게이트웨이는 프라이빗 서브넷에서 인터넷으로 나가는 연결에 사용됩니다. 인터넷을 통과하지 않아야 하는 요구사항과 맞지 않으므로 적합하지 않습니다."}}},{"id":"Q0092","question_number":92,"question":"회사에서 Amazon S3 버킷에 민감한 사용자 정보를 저장하고 있습니다. 회사는 VPC 내부의 Amazon EC2 인스턴스에서 실행되는 애플리케이션 계층에서 이 버킷에 대한 보안 액세스를 제공하려고 합니다. 솔루션 설계자는 이를 달성하기 위해 어떤 단계 조합을 취해야 합니까? (2 개를 선택하세요.)","choices":{"A":"VPC 내에서 Amazon S3 용 VPC 게이트웨이 엔드포인트를 구성합니다.","B":"S3 버킷의 객체를 퍼블릭으로 만들기 위한 버킷 정책을 생성합니다.","C":"VPC 에서 실행되는 애플리케이션 계층으로만 액세스를 제한하는 버킷 정책을 생성합니다.","D":"S3 액세스 정책으로 IAM 사용자를 생성하고 IAM 자격 증명을 EC2 인스턴스에 복사합니다.","E":"NAT 인스턴스를 생성하고 EC2 인스턴스가 NAT 인스턴스를 사용하여 S3 버킷에 액세스하도록 합니다."},"answers":["A","C"],"content_domain":"보안 아키텍처 설계","content_task":"AWS 리소스에 대한 보안 액세스 설계","aws_services":["Amazon VPC","Amazon S3"],"explanation":{"requirementsAnalysis":"회사는 민감한 사용자 정보를 저장한 Amazon S3 버킷에 대해 VPC의 EC2 애플리케이션 계층만 안전하게 액세스하도록 해야 합니다. 문제는 두 가지 조치를 요구하므로, 인터넷을 우회하는 S3 연결 경로와 해당 접근 주체를 제한하는 권한 제어를 함께 구성해야 합니다.","awsServicesAnalysis":"Amazon S3용 VPC 게이트웨이 엔드포인트는 VPC에서 S3로 가는 트래픽을 비공개 AWS 네트워크 경로로 보냅니다. S3 버킷 정책은 `aws:SourceVpce` 같은 조건 키를 사용하여 특정 VPC 엔드포인트를 통한 요청만 허용할 수 있습니다. EC2 인스턴스에는 IAM 역할을 연결해 임시 자격 증명을 제공하는 방식이 권장되며, IAM 사용자 장기 자격 증명을 복사할 필요가 없습니다.","choicesAnalysis":"게이트웨이 엔드포인트는 애플리케이션 계층의 S3 연결을 인터넷에서 분리하고, 버킷 정책은 해당 비공개 경로를 사용하지 않는 접근을 차단할 수 있습니다. 퍼블릭 정책, 장기 IAM 자격 증명 복사, NAT 인스턴스는 민감한 데이터에 대한 최소 권한 및 비공개 액세스 요구사항에 맞지 않습니다. 따라서 A와 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":true,"explanation":"A는 VPC 내부 애플리케이션이 S3에 비공개로 연결할 수 있도록 게이트웨이 엔드포인트를 구성하므로 적합합니다."},"B":{"isCorrect":false,"explanation":"B는 객체를 공개하여 민감한 사용자 정보에 대한 접근 범위를 넓힙니다. 보안 액세스 요구사항에 정면으로 어긋나므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 버킷 정책으로 VPC 애플리케이션 계층의 접근만 허용하도록 제한할 수 있습니다. 게이트웨이 엔드포인트와 결합하면 요구사항에 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 IAM 사용자 장기 자격 증명을 EC2 인스턴스에 복사해야 하므로 노출과 교체 관리 위험이 있습니다. IAM 역할을 사용하는 방식보다 안전하지 않으므로 적합하지 않습니다."},"E":{"isCorrect":false,"explanation":"E는 NAT 인스턴스를 통한 인터넷 경로를 사용하며, S3 접근을 애플리케이션 계층으로 제한하지도 않습니다. 게이트웨이 엔드포인트보다 운영 부담도 크므로 적합하지 않습니다."}}},{"id":"Q0093","question_number":93,"question":"회사는 MySQL 데이터베이스로 구동되는 온프레미스 애플리케이션을 실행합니다. 이 회사는 애플리케이션의 탄력성과 가용성을 높이기 위해 애플리케이션을 AWS 로 마이그레이션하고 있습니다. 현재 아키텍처는 정상 작동 시간 동안 데이터베이스에서 많은 읽기 활동을 보여줍니다. 회사의 개발 팀은 4 시간마다 프로덕션 데이터베이스의 전체 내보내기를 가져와 준비 환경의 데이터베이스를 채웁니다. 이 기간 동안 사용자는 허용할 수 없는 애플리케이션 대기 시간을 경험합니다. 개발 팀은 절차가 완료될 때까지 스테이징 환경을 사용할 수 없습니다. 솔루션 설계자는 애플리케이션 지연 문제를 완화하는 대체 아키텍처를 권장해야 합니다. 또한 대체 아키텍처는 개발 팀이 지연 없이 스테이징 환경을 계속 사용할 수 있는 능력을 제공해야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"프로덕션용 다중 AZ Aurora 복제본과 함께 Amazon Aurora MySQL 을 사용합니다. mysqldump 유틸리티를 사용하는 백업 및 복원 프로세스를 구현하여 스테이징 데이터베이스를 채웁니다.","B":"프로덕션용 다중 AZ Aurora 복제본과 함께 Amazon Aurora MySQL 을 사용합니다. 데이터베이스 복제를 사용하여 요청 시 스테이징 데이터베이스를 생성합니다.","C":"다중 AZ 배포 및 프로덕션용 읽기 전용 복제본과 함께 MySQL 용 Amazon RDS 를 사용합니다. 스테이징 데이터베이스에 대해 대기 인스턴스를 사용합니다.","D":"다중 AZ 배포 및 프로덕션용 읽기 전용 복제본과 함께 MySQL 용 Amazon RDS 를 사용합니다. mysqldump 유틸리티를 사용하는 백업 및 복원 프로세스를 구현하여 스테이징 데이터베이스를 채웁니다."},"answers":["B"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터베이스 솔루션 결정","aws_services":["Amazon Aurora"],"explanation":{"requirementsAnalysis":"회사는 읽기 활동이 많은 MySQL 기반 애플리케이션을 AWS로 마이그레이션하면서 가용성과 탄력성을 높여야 합니다. 4시간마다 수행하는 전체 내보내기와 스테이징 복원은 프로덕션 지연을 유발하고, 작업 중에는 스테이징 환경을 사용할 수 없게 합니다. 따라서 읽기 부하를 분산하고 운영 중인 스테이징을 지연 없이 새 데이터로 갱신할 수 있는 데이터베이스 아키텍처가 필요합니다.","awsServicesAnalysis":"Amazon Aurora MySQL 호환 DB 클러스터는 여러 가용 영역에 걸친 내구성 있는 스토리지를 사용하고 Aurora Replica로 읽기 확장을 지원합니다. Aurora 클론은 Copy-on-Write 방식을 사용하여 기존 DB 클러스터 볼륨에서 빠르게 생성되며, 원본 데이터와 공통 스토리지를 공유한 뒤 변경된 데이터만 별도로 저장합니다. Amazon RDS for MySQL의 다중 AZ 대기 인스턴스는 장애 조치용이며 읽기 트래픽을 처리하지 않습니다.","choicesAnalysis":"Aurora Replica는 읽기 요청을 분산해 프로덕션의 읽기 병목을 완화합니다. 요청 시 생성한 Aurora 클론은 전체 내보내기와 복원 없이 스테이징용 사본을 빠르게 제공하므로 기존 스테이징을 장시간 중단시키지 않습니다. mysqldump 기반 방식과 RDS 다중 AZ 대기 인스턴스는 이 두 요구사항을 함께 충족하지 못합니다. 따라서 B가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 Aurora Replica를 사용할 수 있지만 mysqldump 기반 내보내기와 복원은 프로덕션 부하와 스테이징 중단 문제를 계속 유발합니다. 따라서 적합하지 않습니다."},"B":{"isCorrect":true,"explanation":"B는 Aurora Replica로 읽기 트래픽을 분산하고, 요청 시 Aurora 클론을 생성해 전체 내보내기 없이 스테이징 데이터를 제공할 수 있으므로 적합합니다."},"C":{"isCorrect":false,"explanation":"C의 RDS 다중 AZ 대기 인스턴스는 읽기 요청을 처리하는 복제본이 아닙니다. 또한 대기 인스턴스를 스테이징 DB로 사용할 수 없으므로 적합하지 않습니다."},"D":{"isCorrect":false,"explanation":"D는 읽기 전용 복제본을 제공할 수 있지만 mysqldump 내보내기와 복원 방식이 지연 및 스테이징 중단 원인을 해소하지 못하므로 적합하지 않습니다."}}},{"id":"Q0094","question_number":94,"question":"한 회사에서 사용자가 Amazon S3 에 작은 파일을 업로드하는 애플리케이션을 설계하고 있습니다. 사용자가 파일을 업로드한 후 데이터를 변환하고 나중에 분석할 수 있도록 데이터를 JSON 형식으로 저장하려면 파일에 일회성 단순 처리가 필요합니다. 각 파일은 업로드 후 최대한 빨리 처리해야 합니다. 수요는 다양할 것입니다. 어떤 날에는 사용자가 많은 수의 파일을 업로드합니다. 다른 날에는 사용자가 몇 개의 파일을 업로드하거나 파일을 업로드하지 않습니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"Amazon S3 에서 텍스트 파일을 읽도록 Amazon EMR 을 구성합니다. 처리 스크립트를 실행하여 데이터를 변환합니다. 결과 JSON 파일을 Amazon Aurora DB 클러스터에 저장합니다.","B":"Amazon SQS(Amazon Simple Queue Service) 대기열에 이벤트 알림을 보내도록 Amazon S3 를 구성합니다. Amazon EC2 인스턴스를 사용하여 대기열에서 읽고 데이터를 처리합니다. 결과 JSON 파일을 Amazon DynamoDB 에 저장합니다.","C":"이벤트 알림을 Amazon Simple Queue Service(Amazon SQS) 대기열로 보내도록 Amazon S3 를 구성합니다. AWS Lambda 함수를 사용하여 대기열에서 읽고 데이터를 처리합니다. 결과 JSON 파일을 Amazon DynamoDB 에 저장합니다.","D":"새 파일이 업로드될 때 Amazon Kinesis Data Streams 에 이벤트를 보내도록 Amazon EventBridge(Amazon CloudWatch Events)를 구성합니다. AWS Lambda 함수를 사용하여 스트림에서 이벤트를 소비하고 데이터를 처리합니다. 결과 JSON 파일을 Amazon Aurora DB 클러스터에 저장합니다."},"answers":["C"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터 수집 및 변환 솔루션 결정","aws_services":["Amazon S3","Amazon SQS","AWS Lambda","Amazon DynamoDB"],"explanation":{"requirementsAnalysis":"사용자가 S3에 업로드하는 작은 파일은 업로드 직후 일회성으로 변환되어 JSON 형식의 결과 데이터로 저장되어야 합니다. 업로드량은 크게 변동하므로 유휴 상태의 서버나 클러스터를 관리하지 않고도 급증하는 이벤트를 처리할 수 있어야 합니다. 따라서 이벤트 기반으로 자동 확장되며 운영 오버헤드가 낮은 처리 파이프라인이 필요합니다.","awsServicesAnalysis":"Amazon S3 이벤트 알림은 객체 생성 이벤트를 Amazon SQS 같은 대상으로 전송할 수 있습니다. Amazon SQS는 생산자와 소비자를 분리하고 처리 요청을 버퍼링합니다. AWS Lambda는 SQS를 이벤트 소스로 사용해 메시지를 처리하며, 서버 관리 없이 수요에 맞춰 확장됩니다. Amazon DynamoDB는 서버리스 NoSQL 데이터베이스로 변환 결과 데이터를 저장할 수 있습니다. Amazon EMR과 EC2는 클러스터 또는 인스턴스 운영이 필요합니다.","choicesAnalysis":"S3 이벤트를 SQS로 전달하고 Lambda가 이를 비동기로 처리하면 업로드 급증을 버퍼링하면서 서버를 운영하지 않아도 됩니다. 처리 결과는 DynamoDB에 저장할 수 있습니다. EMR/EC2 또는 Aurora를 추가하는 대안은 일회성 소규모 파일 처리에 불필요한 운영 부담을 만듭니다. 또한 제시된 EventBridge에서 Kinesis Data Streams로의 흐름은 S3 객체 생성 이벤트의 직접 대상 구성이 아닙니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 EMR 클러스터를 구성하고 Aurora DB 클러스터를 운영해야 합니다. 작은 파일의 가변적인 일회성 처리에는 운영 오버헤드가 크므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 SQS로 이벤트를 버퍼링할 수 있지만 EC2 인스턴스의 확장과 운영을 관리해야 합니다. Lambda를 사용하는 방식보다 운영 오버헤드가 크므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 S3 이벤트를 SQS로 전달하고 Lambda로 처리하여 수요에 따라 자동 확장할 수 있습니다. 별도 서버 관리 없이 결과 데이터를 DynamoDB에 저장할 수 있으므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 S3 객체 생성 이벤트를 Kinesis Data Streams로 직접 전송하는 제시된 구성이 적절하지 않습니다. 또한 Aurora DB 클러스터 운영은 최소 운영 오버헤드 요구사항에 맞지 않으므로 적합하지 않습니다."}}},{"id":"Q0095","question_number":95,"question":"응용 프로그램을 사용하면 회사 본사의 사용자가 제품 데이터에 액세스할 수 있습니다. 제품 데이터는 Amazon RDS MySQL DB 인스턴스에 저장됩니다. 운영 팀은 애플리케이션 성능 저하를 격리하고 쓰기 트래픽에서 읽기 트래픽을 분리하려고 합니다. 솔루션 설계자는 애플리케이션의 성능을 신속하게 최적화해야 합니다. 솔루션 설계자는 무엇을 권장해야 합니까?","choices":{"A":"기존 데이터베이스를 다중 AZ 배포로 변경합니다. 기본 가용 영역에서 읽기 요청을 제공합니다.","B":"기존 데이터베이스를 다중 AZ 배포로 변경합니다. 보조 가용 영역에서 읽기 요청을 제공합니다.","C":"데이터베이스에 대한 읽기 전용 복제본을 생성합니다. 컴퓨팅 및 스토리지 리소스의 절반을 원본 데이터베이스로 사용하여 읽기 전용 복제본을 구성합니다.","D":"데이터베이스에 대한 읽기 전용 복제본을 생성합니다. 원본 데이터베이스와 동일한 컴퓨팅 및 스토리지 리소스로 읽기 전용 복제본을 구성합니다."},"answers":["D"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 데이터베이스 솔루션 결정","aws_services":["Amazon RDS"],"explanation":{"requirementsAnalysis":"애플리케이션의 제품 데이터는 Amazon RDS for MySQL DB 인스턴스에 저장되어 있으며, 운영 팀은 성능 저하를 격리하고 읽기 트래픽을 쓰기 트래픽에서 분리하려고 합니다. 빠르게 성능을 최적화하려면 쓰기 작업을 원본 DB에 유지하면서 읽기 작업을 별도의 읽기 확장 대상에 보내야 합니다. 읽기 부하를 처리할 복제본은 원본과 동등한 용량을 가져야 합니다.","awsServicesAnalysis":"Amazon RDS for MySQL 읽기 전용 복제본은 비동기 복제를 사용하고 읽기 전용 연결 엔드포인트를 제공하여 읽기 트래픽을 원본 DB 인스턴스에서 분리합니다. RDS 다중 AZ 배포의 대기 인스턴스는 고가용성과 장애 조치를 위한 구성 요소이며 읽기 요청을 제공하지 않습니다. 복제본 인스턴스 클래스와 스토리지 구성은 예상되는 읽기 부하를 감당하도록 선택해야 합니다.","choicesAnalysis":"읽기 전용 복제본을 원본 DB와 동일한 컴퓨팅 및 스토리지 리소스로 구성하면 프로덕션의 읽기 트래픽을 분리하면서 동등한 처리 용량을 제공합니다. 다중 AZ의 기본 또는 대기 인스턴스는 읽기 확장 수단이 아니고, 절반 용량 복제본은 요구되는 성능을 보장하지 못합니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 다중 AZ 배포는 장애 조치용 대기 인스턴스를 제공하지만 읽기 트래픽을 쓰기 트래픽에서 분리하지 못합니다. 기본 인스턴스에서 계속 읽기를 처리하므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B의 다중 AZ 대기 인스턴스는 읽기 요청을 제공하지 않습니다. 고가용성 기능을 읽기 확장 기능으로 사용할 수 없으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 읽기 전용 복제본을 생성하지만 원본의 절반 컴퓨팅 및 스토리지 리소스는 기존 읽기 부하를 수용할 충분한 용량을 보장하지 못합니다. 신속한 성능 최적화 요구사항에 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"D는 원본과 동등한 리소스의 읽기 전용 복제본으로 읽기 요청을 분리하여 원본의 쓰기 작업과 성능 저하를 격리할 수 있으므로 적합합니다."}}},{"id":"Q0096","question_number":96,"question":"Amazon EC2 관리자는 여러 사용자가 포함된 IAM 그룹과 연결된 다음 정책을 생성했습니다.\n\n정책:\n{\n  \"Version\": \"2012-10-17\",\n  \"Statement\": [\n    {\n      \"Effect\": \"Allow\",\n      \"Action\": \"ec2:TerminateInstances\",\n      \"Resource\": \"*\",\n      \"Condition\": {\n        \"IpAddress\": {\n          \"aws:SourceIp\": \"10.100.100.0/24\"\n        }\n      }\n    },\n    {\n      \"Effect\": \"Deny\",\n      \"Action\": \"ec2:*\",\n      \"Resource\": \"*\",\n      \"Condition\": {\n        \"StringNotEquals\": {\n          \"ec2:Region\": \"us-east-1\"\n        }\n      }\n    }\n  ]\n} 이 정책의 효과는 무엇입니까?","choices":{"A":"사용자는 us-east-1 을 제외한 모든 AWS 리전에서 EC2 인스턴스를 종료할 수 있습니다.","B":"사용자는 us-east-1 리전에서 IP 주소가 10.100.100.1 인 EC2 인스턴스를 종료할 수 있습니다.","C":"사용자는 사용자의 소스 IP 가 10.100.100.254 일 때 us-east-1 리전에서 EC2 인스턴스를 종료할 수 있습니다.","D":"사용자의 소스 IP 가 10.100.100.254 인 경우 사용자는 us-east-1 리전에서 EC2 인스턴스를 종료할 수 없습니다."},"answers":["C"],"content_domain":"보안 아키텍처 설계","content_task":"AWS 리소스에 대한 보안 액세스 설계","aws_services":["IAM","Amazon EC2"],"explanation":{"requirementsAnalysis":"정책은 IAM 그룹 사용자에게 EC2 인스턴스 종료 권한을 조건부로 부여하고, 특정 리전 밖의 모든 EC2 작업은 명시적으로 거부합니다. 따라서 요청 리전과 요청을 보낸 소스 IP가 모두 조건을 충족하는지, 그리고 명시적 거부가 허용보다 우선하는지를 함께 판단해야 합니다.","awsServicesAnalysis":"IAM 정책에서 `IpAddress` 조건의 `aws:SourceIp`는 요청을 보낸 클라이언트의 IP 주소가 지정된 CIDR 범위에 속하는지를 검사합니다. `10.100.100.0/24`에는 10.100.100.1부터 10.100.100.254까지의 주소가 포함됩니다. `StringNotEquals` 조건으로 `ec2:Region`이 us-east-1이 아닌 모든 EC2 작업을 명시적으로 거부합니다. IAM 평가에서는 명시적 Deny가 Allow보다 우선합니다.","choicesAnalysis":"종료 작업은 us-east-1 외 리전에서는 두 번째 문장의 명시적 거부 때문에 허용되지 않습니다. us-east-1에서는 해당 거부 조건이 적용되지 않으며, 소스 IP가 10.100.100.0/24 범위이면 첫 번째 문장의 허용이 적용됩니다. 10.100.100.254는 그 범위에 포함되므로 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 us-east-1 이외 리전의 EC2 작업이 명시적으로 거부된다는 정책 효과와 반대입니다. 따라서 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 조건 키가 사용자 요청의 소스 IP를 검사한다는 점을 EC2 인스턴스의 IP 주소와 혼동합니다. 또한 허용 범위는 특정 .1 주소로 한정되지 않으므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C의 소스 IP 10.100.100.254는 10.100.100.0/24 범위에 포함되고, us-east-1에서는 리전 기반 명시적 거부가 적용되지 않습니다. 따라서 인스턴스 종료가 허용되어 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 소스 IP 10.100.100.254가 허용 CIDR에 포함된다는 점과 us-east-1에서 명시적 거부가 적용되지 않는다는 점을 반영하지 못합니다. 따라서 적합하지 않습니다."}}},{"id":"Q0097","question_number":97,"question":"회사에는 Microsoft Windows 공유 파일 저장소가 필요한 온프레미스에서 실행되는 대규모 Microsoft SharePoint 배포가 있습니다. 회사는 이 워크로드를 AWS 클라우드로 마이그레이션하기를 원하며 다양한 스토리지 옵션을 고려하고 있습니다. 저장소 솔루션은 액세스 제어를 위해 고가용성 및 Active Directory 와 통합되어야 합니다. 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"Amazon EFS 스토리지를 구성하고 인증을 위해 Active Directory 도메인을 설정합니다.","B":"두 가용 영역의 AWS Storage Gateway 파일 게이트웨이에 SMB 파일 공유를 생성합니다.","C":"Amazon S3 버킷을 생성하고 볼륨으로 탑재하도록 Microsoft Windows Server 를 구성합니다.","D":"AWS 에서 Windows 파일 서버용 Amazon FSx 파일 시스템을 생성하고 인증을 위해 Active Directory 도메인을 설정합니다."},"answers":["D"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"고가용성 및/또는 내결함성 아키텍처 설계","aws_services":["Amazon FSx(모든 유형)"],"explanation":{"requirementsAnalysis":"온프레미스의 대규모 Microsoft SharePoint 배포를 AWS로 마이그레이션하면서 Microsoft Windows 공유 파일 저장소가 필요합니다. 스토리지는 고가용성이어야 하고 액세스 제어를 위해 Microsoft Active Directory와 통합되어야 합니다. 따라서 Windows의 SMB 파일 공유 요구사항과 관리형 고가용성, Active Directory 인증을 함께 충족하는 서비스가 필요합니다.","awsServicesAnalysis":"Amazon FSx for Windows File Server는 완전관리형 Windows 파일 시스템으로 SMB 프로토콜, Windows NTFS 권한 및 Microsoft Active Directory 통합을 지원합니다. Multi-AZ 배포를 선택하면 여러 가용 영역에 걸쳐 고가용성을 제공할 수 있습니다. Amazon EFS는 NFS 기반 파일 시스템이며 Windows SMB 공유용 서비스가 아닙니다. AWS Storage Gateway File Gateway는 온프레미스 파일 액세스를 S3 객체 스토리지와 연결하는 하이브리드 서비스입니다.","choicesAnalysis":"FSx for Windows File Server는 SharePoint가 요구하는 Windows 파일 공유와 Active Directory 기반 인증/권한 제어를 지원하고 Multi-AZ 배포로 고가용성을 제공할 수 있습니다. EFS, S3 볼륨 탑재, File Gateway는 이 요구사항 조합에 직접 부합하지 않습니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 Amazon EFS는 NFS 파일 시스템이며 Windows SMB 공유 및 Windows NTFS 권한 요구사항을 직접 충족하지 못합니다. 따라서 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B의 File Gateway는 S3 기반 하이브리드 파일 액세스에 적합하지만, AWS에서 Windows 파일 서버용 관리형 고가용성 파일 시스템을 제공하는 해법은 아닙니다. 따라서 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C는 S3 버킷을 Windows 파일 공유처럼 탑재하는 방식이며, SharePoint용 SMB 파일 시스템과 Active Directory 통합 요구사항을 충족하지 못합니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"D는 Amazon FSx for Windows File Server에 Active Directory를 연결하여 Windows 공유 파일 저장소와 액세스 제어를 제공할 수 있습니다. Multi-AZ 배포를 사용하면 고가용성도 충족하므로 적합합니다."}}},{"id":"Q0098","question_number":98,"question":"이미지 처리 회사에는 사용자가 이미지를 업로드하는 데 사용하는 웹 응용 프로그램이 있습니다. 애플리케이션은 이미지를 Amazon S3 버킷에 업로드합니다. 회사는 객체 생성 이벤트를 Amazon Simple Queue Service(Amazon SQS) 표준 대기열에 게시하도록 S3 이벤트 알림을 설정했습니다. SQS 대기열은 이미지를 처리하고 결과를 이메일을 통해 사용자에게 보내는 AWS Lambda 함수의 이벤트 소스 역할을 합니다. 사용자는 업로드된 모든 이미지에 대해 여러 이메일 메시지를 수신하고 있다고 보고합니다. 솔루션 설계자는 SQS 메시지가 Lambda 함수를 두 번 이상 호출하여 여러 이메일 메시지를 생성한다고 판단합니다. 솔루션 설계자는 이 문제를 최소한의 운영 오버헤드로 해결하기 위해 무엇을 해야 합니까?","choices":{"A":"ReceiveMessage 대기 시간을 30 초로 늘려 SQS 대기열에서 긴 폴링을 설정합니다.","B":"SQS 표준 대기열을 SQS FIFO 대기열로 변경합니다. 메시지 중복 제거 ID 를 사용하여 중복 메시지를 버리십시오.","C":"SQS 대기열의 가시성 제한 시간을 함수 제한 시간과 일괄 처리 창 제한 시간의 합계보다 큰 값으로 늘립니다.","D":"처리 전에 메시지를 읽은 직후 SQS 대기열에서 각 메시지를 삭제하도록 Lambda 함수를 수정합니다."},"answers":["C"],"content_domain":"복원력을 갖춘 아키텍처 설계","content_task":"확장 가능하고 느슨하게 결합된 아키텍처 설계","aws_services":["Amazon S3","Amazon SQS","AWS Lambda"],"explanation":{"requirementsAnalysis":"S3 객체 생성 이벤트가 SQS 표준 대기열을 거쳐 Lambda를 호출하고 함수가 이메일을 전송합니다. 여러 이메일은 동일 메시지가 처리 완료 전에 다시 표시되어 Lambda가 재호출되는 상황에서 발생할 수 있습니다. 최소 변경으로 이 원인을 줄이려면 Lambda가 처리하는 동안 메시지가 다른 소비자에게 보이지 않도록 가시성 제한 시간을 충분히 설정해야 합니다. 또한 이메일 같은 부수 효과에는 중복 전달을 견디는 멱등성이 필요합니다.","awsServicesAnalysis":"SQS 가시성 제한 시간 동안 수신된 메시지는 다른 소비자에게 보이지 않으며, 처리 완료 전에 제한 시간이 끝나면 다시 전달될 수 있습니다. Lambda의 SQS 이벤트 소스 매핑에서는 함수 제한 시간과 배치 창 및 재시도 여유를 고려해 제한 시간을 설정해야 하며, AWS는 일반적으로 가시성 제한 시간을 함수 제한 시간의 6배에 최대 배치 창을 더한 값 이상으로 설정하도록 권장합니다. 그러나 SQS 표준 대기열과 Lambda 이벤트 소스 매핑은 적어도 한 번 처리를 사용하므로 적절한 제한 시간만으로 모든 중복을 제거할 수는 없습니다. 긴 폴링은 빈 응답을 줄이는 기능입니다.","choicesAnalysis":"가시성 제한 시간이 Lambda 실행과 배치 수집에 필요한 시간보다 짧다면 처리 중인 메시지가 다시 표시되어 중복 호출이 발생할 수 있습니다. 이를 충분히 늘리는 C는 대기열 유형이나 애플리케이션 구조를 바꾸지 않고 해당 원인을 줄이는 선택지입니다. 따라서 C가 정답입니다. 다만 표준 대기열의 적어도 한 번 전달 특성 때문에 이메일 발송 로직은 이벤트 ID를 기록하는 등 멱등성도 갖춰야 합니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"긴 폴링은 대기열이 비어 있을 때의 불필요한 폴링과 빈 응답을 줄입니다. 처리 중 가시성 제한 시간이 만료되는 문제는 해결하지 못하므로 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"FIFO 대기열로의 변경과 중복 제거 ID 관리는 더 큰 구조 변경이며, S3 이벤트 알림을 SQS FIFO 대기열로 직접 전송하는 구성에도 제약이 있습니다. 관찰된 가시성 제한 시간 문제를 최소 변경으로 해결하는 방법이 아니므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"가시성 제한 시간을 함수 제한 시간과 배치 창보다 충분히 길게 설정하면 처리 중인 메시지가 다시 표시되는 원인을 줄일 수 있으므로 적합합니다. 실제 설정에서는 재시도 여유까지 반영하고 이메일 발송 로직도 멱등하게 만들어야 합니다."},"D":{"isCorrect":false,"explanation":"처리 성공 전에 메시지를 삭제하면 함수 오류 시 재처리 기회를 잃고 데이터가 유실될 수 있습니다. Lambda의 SQS 통합이 정상 처리 후 메시지 삭제를 관리하므로 적합하지 않습니다."}}},{"id":"Q0099","question_number":99,"question":"회사는 온프레미스 데이터 센터에서 호스팅되는 게임 애플리케이션을 위한 공유 스토리지 솔루션을 구현하고 있습니다. 회사는 Lustre 클라이언트를 사용하여 데이터에 액세스할 수 있는 기능이 필요합니다. 솔루션은 완전히 관리되어야 합니다. 어떤 솔루션이 이러한 요구 사항을 충족합니까?","choices":{"A":"AWS Storage Gateway 파일 게이트웨이를 생성합니다. 필요한 클라이언트 프로토콜을 사용하는 파일 공유를 만듭니다. 응용 프로그램 서버를 파일 공유에 연결합니다.","B":"Amazon EC2 Windows 인스턴스를 생성합니다. 인스턴스에 Windows 파일 공유 역할을 설치하고 구성합니다. 응용 프로그램 서버를 파일 공유에 연결합니다.","C":"Amazon Elastic File System(Amazon EFS) 파일 시스템을 생성하고 Lustre 를 지원하도록 구성합니다. 파일 시스템을 원본 서버에 연결합니다. 응용 프로그램 서버를 파일 시스템에 연결합니다.","D":"Lustre 파일 시스템용 Amazon FSx 를 생성합니다. 파일 시스템을 원본 서버에 연결합니다. 응용 프로그램 서버를 파일 시스템에 연결합니다."},"answers":["D"],"content_domain":"고성능 아키텍처 설계","content_task":"고성능 및/또는 확장 가능한 스토리지 솔루션 결정","aws_services":["Amazon FSx(모든 유형)"],"explanation":{"requirementsAnalysis":"온프레미스 데이터 센터에서 호스팅되는 게임 애플리케이션에는 공유 스토리지가 필요하며, 애플리케이션이 Lustre 클라이언트로 데이터에 액세스할 수 있어야 합니다. 사용자는 스토리지 인프라를 직접 운영하지 않는 완전관리형 솔루션을 요구합니다. 따라서 Lustre 네이티브 파일 시스템을 관리형으로 제공하고 하이브리드 네트워크에서 연결할 수 있는 서비스가 필요합니다.","awsServicesAnalysis":"Amazon FSx for Lustre는 Lustre 파일 시스템을 완전관리형으로 제공하며, 표준 Lustre 클라이언트를 사용해 액세스할 수 있습니다. 온프레미스 클라이언트는 AWS Direct Connect 또는 Site-to-Site VPN 등으로 VPC에 연결한 뒤 FSx for Lustre 파일 시스템을 마운트할 수 있습니다. Amazon EFS는 NFS를 지원하며 Lustre 파일 시스템으로 구성할 수 없습니다. File Gateway는 SMB 또는 NFS 파일 공유를 S3에 연결합니다.","choicesAnalysis":"FSx for Lustre는 요구된 Lustre 프로토콜을 직접 지원하면서 관리형 파일 시스템을 제공합니다. 온프레미스 애플리케이션 서버도 사설 네트워크 연결을 통해 해당 파일 시스템에 접근할 수 있습니다. File Gateway, 자체 구축 Windows 파일 서버, EFS는 Lustre 클라이언트 요구사항을 충족하지 못합니다. 따라서 D가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A의 File Gateway는 SMB 또는 NFS 기반 파일 공유를 제공하지만 Lustre 클라이언트용 파일 시스템은 제공하지 않습니다. 따라서 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 EC2에서 Windows 파일 서버를 직접 설치하고 운영해야 하며 Lustre 파일 시스템도 아닙니다. 완전관리형 및 프로토콜 요구사항에 맞지 않으므로 적합하지 않습니다."},"C":{"isCorrect":false,"explanation":"C의 Amazon EFS는 NFS 파일 시스템이며 Lustre 지원으로 구성할 수 없습니다. 따라서 적합하지 않습니다."},"D":{"isCorrect":true,"explanation":"D는 Amazon FSx for Lustre를 사용하여 표준 Lustre 클라이언트가 액세스할 수 있는 완전관리형 공유 파일 시스템을 제공합니다. 온프레미스 서버도 사설 연결을 통해 마운트할 수 있으므로 적합합니다."}}},{"id":"Q0100","question_number":100,"question":"회사의 컨테이너화된 애플리케이션은 Amazon EC2 인스턴스에서 실행됩니다. 애플리케이션은 다른 비즈니스 애플리케이션과 통신하기 전에 보안 인증서를 다운로드해야 합니다. 회사는 거의 실시간으로 인증서를 암호화하고 해독할 수 있는 매우 안전한 솔루션을 원합니다. 또한 솔루션은 데이터가 암호화된 후 고가용성 스토리지에 데이터를 저장해야 합니다. 최소한의 운영 오버헤드로 이러한 요구 사항을 충족하는 솔루션은 무엇입니까?","choices":{"A":"암호화된 인증서에 대한 AWS Secrets Manager 암호를 생성합니다. 필요에 따라 인증서를 수동으로 업데이트합니다. 세분화된 IAM 액세스를 사용하여 데이터에 대한 액세스를 제어합니다.","B":"Python 암호화 라이브러리를 사용하여 암호화 작업을 수신하고 수행하는 AWS Lambda 함수를 생성합니다. 함수를 Amazon S3 버킷에 저장합니다.","C":"AWS Key Management Service(AWS KMS) 고객 관리형 키를 생성합니다. EC2 역할이 암호화 작업에 KMS 키를 사용하도록 허용합니다. 암호화된 데이터를 Amazon S3 에 저장합니다.","D":"AWS Key Management Service(AWS KMS) 고객 관리형 키를 생성합니다. EC2 역할이 암호화 작업에 KMS 키를 사용하도록 허용합니다. 암호화된 데이터를 Amazon Elastic Block Store(Amazon EBS) 볼륨에 저장합니다."},"answers":["C"],"content_domain":"보안 아키텍처 설계","content_task":"적합한 데이터 보안 제어 결정","aws_services":["AWS KMS","Amazon S3"],"explanation":{"requirementsAnalysis":"EC2에서 실행되는 컨테이너 애플리케이션은 다른 비즈니스 애플리케이션과 통신하기 전에 보안 인증서를 내려받아야 합니다. 인증서는 거의 실시간으로 암호화 및 복호화되어야 하며, 암호화된 뒤에는 고가용성 스토리지에 저장되어야 합니다. 최소 운영 오버헤드를 위해 관리형 암호화 서비스와 고내구성 객체 스토리지를 결합하는 방식이 필요합니다.","awsServicesAnalysis":"AWS Key Management Service는 고객 관리형 KMS 키를 사용한 관리형 암호화 및 복호화 API를 제공하며, IAM 역할 및 키 정책으로 키 사용 권한을 제어할 수 있습니다. Amazon S3는 여러 가용 영역에 걸쳐 설계된 고내구성 객체 스토리지이며 암호화된 데이터를 저장할 수 있습니다. Amazon EBS 볼륨은 특정 가용 영역에 속하는 블록 스토리지입니다. AWS Secrets Manager는 보안 인증 정보 저장과 회전에 적합하지만, 제시된 수동 갱신 방식은 거의 실시간 암호화/복호화 워크플로를 제공하지 않습니다.","choicesAnalysis":"KMS 고객 관리형 키를 EC2 역할에 사용하도록 허용하면 애플리케이션이 관리형 API로 인증서를 암호화하고 복호화할 수 있습니다. 암호화된 데이터는 S3에 저장하면 고가용성과 낮은 운영 부담을 함께 충족합니다. 직접 구현한 Lambda 암호화, 수동 Secrets Manager 갱신, 단일 AZ EBS 저장은 요구사항에 덜 적합합니다. 따라서 C가 정답입니다."},"choice_evaluations":{"A":{"isCorrect":false,"explanation":"A는 Secrets Manager에 암호를 저장할 수 있지만 인증서를 수동으로 갱신해야 하며, 거의 실시간 암호화 및 복호화 요구사항을 충족하는 구성은 아닙니다. 따라서 적합하지 않습니다."},"B":{"isCorrect":false,"explanation":"B는 암호화 로직을 직접 구현하고 관리해야 하며, Lambda 함수를 S3 버킷에 저장한다는 구성도 적절하지 않습니다. 관리형 KMS를 사용하는 방식보다 운영 오버헤드가 크므로 적합하지 않습니다."},"C":{"isCorrect":true,"explanation":"C는 KMS 고객 관리형 키와 EC2 IAM 역할로 암호화/복호화 권한을 안전하게 제어하고, 암호화된 데이터를 Amazon S3에 저장합니다. 관리형 서비스로 거의 실시간 처리와 고가용성 스토리지를 제공하므로 적합합니다."},"D":{"isCorrect":false,"explanation":"D는 KMS를 통한 암호화 권한 제어는 제공하지만 Amazon EBS 볼륨은 단일 가용 영역에 속합니다. 고가용성 스토리지 요구사항에는 Amazon S3보다 적합하지 않습니다."}}}]'::jsonb) as record(
  id text,
  question_number smallint,
  question text,
  choices jsonb,
  answers text[],
  content_domain text,
  content_task text,
  aws_services text[],
  explanation jsonb,
  choice_evaluations jsonb
)
on conflict (id) do update set
  question_number = excluded.question_number,
  question = excluded.question,
  choices = excluded.choices,
  answers = excluded.answers,
  content_domain = excluded.content_domain,
  content_task = excluded.content_task,
  aws_services = excluded.aws_services,
  explanation = excluded.explanation,
  choice_evaluations = excluded.choice_evaluations,
  updated_at = now();
